INSERT INTO `estrofas` VALUES (1,1,'Estrofa',1,'[Do]Cristo me a[Sol]yuda [Re]por Él a vivir, \nCristo me ayuda por Él a morir; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2,1,'Coro',2,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(3,1,'Estrofa',3,'Siento pesares, muy cerca Él está, \nSiento dolores, alivio me da; \nTengo aflicciones, me muestra su amor, \nCada momento, me cuidas Señor.'),(4,1,'Coro',4,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(5,1,'Estrofa',5,'Tengo amarguras o tengo temor, \nTengo tristezas, me inspiras valor; \nTengo conflictos o penas aquí, \nCada momento te acuerdas de mí.'),(6,1,'Coro',6,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(7,1,'Estrofa',7,'Tengo flaquezas o débil estoy \nCristo me dice: “Tu amparo yo soy”. \nCada momento en tinieblas o en luz, \nSiempre conmigo está mi Jesús.'),(8,1,'Coro',8,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(9,2,'Estrofa',1,'Por fe contemplo redención,\nLa fuente carmesí;\nJesús nos da la salvación,\nSu vida dió por mí.'),(10,2,'Coro',2,'La fuente sin igual hallé,\nDe vida y luz el manantial;\n¡Oh, gloria a Dios, me limpia a mí,\nMe limpia a mí, me limpia a mí.'),(11,2,'Estrofa',3,'Mi vida entrego a mi Jesús,\nLas dudas Él quitó;\nMi alma goza de su luz,\nMis deudas Él pagó.'),(12,2,'Coro',4,'La fuente sin igual hallé,\nDe vida y luz el manantial;\n¡Oh, gloria a Dios, me limpia a mí,\nMe limpia a mí, me limpia a mí.'),(13,2,'Estrofa',5,'Cuán inefable gozo es,\nSaber que salvo soy;\nMi Rey aquí es mi Jesús,\nAl reino sé que voy.'),(14,2,'Coro',6,'La fuente sin igual hallé,\nDe vida y luz el manantial;\n¡Oh, gloria a Dios, me limpia a mí,\nMe limpia a mí, me limpia a mí.'),(15,2,'Estrofa',7,'¡Oh, gracia excelsa de mi Dios,\nProfundo es el amor;\nDe mi Jesús vía de luz,\nCordero redentor.'),(16,2,'Coro',8,'La fuente sin igual hallé,\nDe vida y luz el manantial;\n¡Oh, gloria a Dios, me limpia a mí,\nMe limpia a mí, me limpia a mí.'),(17,3,'Estrofa',1,'Nunca desmayes en todo afán,\nTe cuidará el Señor;\nSus fuertes alas te cubrirán,\nTe cuidará el Señor.'),(18,3,'Coro',2,'Te cuidará el Señor,\nNo te verás solo jamás;\nVelando está su amor;\nTe cuidará el Señor.'),(19,3,'Estrofa',3,'Cuando flaqueare tu corazón,\nTe cuidará el Señor;\nEn tus conflictos y tentación,\nTe cuidará el Señor.'),(20,3,'Coro',4,'Te cuidará el Señor,\nNo te verás solo jamás;\nVelando está su amor;\nTe cuidará el Señor.'),(21,3,'Estrofa',5,'De sus riquezas te proveerá,\nTe cuidará el Señor;\nJamás sus bienes te negará,\nTe cuidará el Señor.'),(22,3,'Coro',6,'Te cuidará el Señor,\nNo te verás solo jamás;\nVelando está su amor;\nTe cuidará el Señor.'),(23,3,'Estrofa',7,'Que pruebas vengan no importa, no,\nTe cuidará el Señor;\nTus cargas todas en Cristo pon,\nTe cuidará el Señor.'),(24,3,'Coro',8,'Te cuidará el Señor,\nNo te verás solo jamás;\nVelando está su amor;\nTe cuidará el Señor.'),(25,4,'Estrofa',1,'No hay tristeza en el reino, ni llanto ni amargo dolor;\nNo hay corazón angustiado, do reina el Señor de amor;\nLas nubes de nuestro horizonte, jamás aparecen allí;\nEl sol en su gloria esplendente, derrama su luz celestial.'),(26,4,'Coro',2,'Yo voy a la patria del alma, do Cristo prepara mi hogar;\nDo todos los santificados, irán para siempre a morar;\nEl día feliz ya se acerca, en que el sol para mí se pondrá;\n¡Oh, qué gozo será, cuando mire al Señor,\nen aquella hermosa ciudad!'),(27,4,'Estrofa',3,'No hay aflicción en el reino, ni pruebas existen allá;\nEl alma que en Cristo reposa, segura en su seno estará.\nNo hay tentación en el reino, ni sombra de muerte atroz;\nEl árbol de vida florece, do fluye el río de Dios.'),(28,4,'Coro',4,'Yo voy a la patria del alma, do Cristo prepara mi hogar;\nDo todos los santificados, irán para siempre a morar;\nEl día feliz ya se acerca, en que el sol para mí se pondrá;\n¡Oh, qué gozo será, cuando mire al Señor,\nen aquella hermosa ciudad!'),(29,4,'Estrofa',5,'¡Cuán dulce será en el reino, pasadas las penas aquí;\nVolvernos a ver reunidos, con nuestros amados allí!.\n¡Por todos los siglos eternos, qué dicha inefable ha de ser;\nEstar en presencia de Cristo, gozando de eterno placer!'),(30,4,'Coro',6,'Yo voy a la patria del alma, do Cristo prepara mi hogar;\nDo todos los santificados, irán para siempre a morar;\nEl día feliz ya se acerca, en que el sol para mí se pondrá;\n¡Oh, qué gozo será, cuando mire al Señor,\nen aquella hermosa ciudad!'),(31,5,'Estrofa',1,'Hay un jardín memorable y hermoso,\nDonde flores exhalan su olor:\nDonde el Maestro pasaba las horas\nRespirando su dulce oración.'),(32,5,'Coro',2,'Al hermoso jardín , el jardín de oración\nAl hermoso jardín de oración:\nEl Señor está allí y la puerta abre Él,\nAl hermoso jardín de oración.'),(33,5,'Estrofa',3,'Aun las aves gorjeaban sus trinos,\nAl compás de tan dulce oración.\nCuando el Maestro imploraba a los cielos,\nPara el mundo la grán salvación.'),(34,5,'Coro',4,'Al hermoso jardín , el jardín de oración\nAl hermoso jardín de oración:\nEl Señor está allí y la puerta abre Él,\nAl hermoso jardín de oración.'),(35,5,'Estrofa',5,'La fragancia del óleo Divino,\nSe esparcía por todo el jardín,\nCuando Cristo del cielo fue ungido,\nPorque pronto ya Él iba a morir.'),(36,5,'Coro',6,'Al hermoso jardín , el jardín de oración\nAl hermoso jardín de oración:\nEl Señor está allí y la puerta abre Él,\nAl hermoso jardín de oración.'),(37,6,'Estrofa',1,'Crucificado por mí fue Jesús,\nDe tal manera me amó;\nSin murmurar fue llevado a la cruz,\nDe tal manera me amó.'),(38,6,'Coro',2,'De tal manera me amó,\nDe tal manera me amó;\nCristo en la cruz del calvario murió,\nDe tal manera me amó'),(39,6,'Estrofa',3,'El inocente Cordero de Dios,\nDe tal manera me amó;\nQue por salvarme sufrió muerte atroz,\nDe tal manera me amó.'),(40,6,'Coro',4,'De tal manera me amó,\nDe tal manera me amó;\nCristo en la cruz del calvario murió,\nDe tal manera me amó'),(41,6,'Estrofa',5,'En mi lugar padeció aflicción,\nDe tal manera me amó;\nYa consumó mi eternal salvación,\nDe tal manera me amó.'),(42,6,'Coro',6,'De tal manera me amó,\nDe tal manera me amó;\nCristo en la cruz del calvario murió,\nDe tal manera me amó'),(43,7,'Estrofa',1,'Nunca Dios mío cesará mi labio\nDe bendecirte, de cantar tu gloria;\nPorque conservo de tu amor inmenso,\nGrata memoria.'),(44,7,'Estrofa',2,'Cuando perdido en mundanal sendero,\nno me cercaba sino niebla oscura;\nTú me miraste y alumbrome un rayo\nDe tu luz pura.'),(45,7,'Estrofa',3,'Cuando inclinaba mi abatida frente,\nDe mal obrar el oneroso yugo;\nDulce reposo y eficaz alivio\nDarme te plugo.'),(46,7,'Estrofa',4,'Cuando los dones malgasté a porfía,\nCon que mi alma pródiga adornaste;\n“Padre, he pecado” con dolor te dije,\nY me abrazaste.'),(47,7,'Estrofa',5,'Cuando en mis propios méritos fiaba,\nNunca mi pecho con amor latía;\nHoy de tu amor late porque en tus bondades\nSólo confía.'),(48,7,'Estrofa',6,'¡Oh, nunca, nunca cesará mi labio,\nDe bendecirte, de cantar tu gloria;\nPorque conservo de tu amor inmenso,\nGrata memoria!'),(49,8,'Estrofa',1,'Cuando combatido por la adversidad,\nCreas ya perdida tu felicidad;\nMira lo que el cielo para tí guardó,\nCuenta las riquezas que el Señor te dio.'),(50,8,'Coro',2,'Bendiciones, cuántas tienes ya,\nBendiciones, Dios te manda más;\nBendiciones, te sorprenderás,\nCuando veas lo que Dios por tí hará.'),(51,8,'Estrofa',3,'¿Andas agobiado por algún pesar?\n¿Duro te parece amarga cruz llevar?\nCuenta las promesas del Señor Jesús,\nY de las tinieblas nacerá la luz.'),(52,8,'Coro',4,'Bendiciones, cuántas tienes ya,\nBendiciones, Dios te manda más;\nBendiciones, te sorprenderás,\nCuando veas lo que Dios por tí hará.'),(53,8,'Estrofa',5,'Cuando de otros veas la prosperidad,\nY tus pies claudiquen tras de su maldad;\nCuenta las riquezas que tendrás por fe,\nDonde el oro es polvo que hollará tu pie.'),(54,8,'Coro',6,'Bendiciones, cuántas tienes ya,\nBendiciones, Dios te manda más;\nBendiciones, te sorprenderás,\nCuando veas lo que Dios por tí hará.'),(55,9,'Estrofa',1,'Obediente a tu mandato,\nParticipa hoy tu grey;\nDe tu cena y con gozo,\nAcercamonos con fé,\nLo que hiciste en el calvario,\nPor el pobre pecador;\nAnunciamos en tu nombre,\nRecordando tu amor.'),(56,9,'Estrofa',2,'Recordamos tus angustias,\n¡Oh, Divino Redentor!\nY la copa de amargura,\nQue por todo pecador,\nEn el gólgota apuraste,\nDespreciando tu dolor;\nTe pedimos que constantes,\nTe sigamos von valor.'),(57,9,'Estrofa',3,'Gracias ¡Oh, Jesús te damos,\nLos unidos en tu amor;\nGracias mil, pues disfrutamos\nTu clemencia y tu favor!\nTuya fue la cruz, mas nuestra\nEs la dicha y es la paz;\nTuya sea la gloria toda,\nTuya por siempre jamás.'),(58,10,'Estrofa',1,'Que preciosa paz nos da, de la vida en el viajar,\nMientras vamos caminando en la luz de Dios\nDe hermosura sin igual, nuestra senda nos será,\nMientras vamos caminando en la luz de Dios'),(59,10,'Coro',2,'Vamos caminando en la luz de Dios,\nVamos Caminando en la luz de Dios;\nCon Jesús en comunión, fiando en la Biblia de Dios,\nMientras vamos caminando en la luz de Dios.'),(60,10,'Estrofa',3,'Cual la luz que da el Señor, así nos muestra su amor,\nMientras vamos caminando en la luz de Dios\nCon su santa redención, purifica el corazón,\nMientras vamos caminando en la luz de Dios.'),(61,10,'Coro',4,'Vamos caminando en la luz de Dios,\nVamos Caminando en la luz de Dios;\nCon Jesús en comunión, fiando en la Biblia de Dios,\nMientras vamos caminando en la luz de Dios.'),(62,10,'Estrofa',5,'Sostengamos con Jesús, comunión en plena luz,\nMientras vamos caminando en la luz de Dios;\nY en perfecta libertad, triunfaréis por su bondad,\nMientras vamos caminando en la luz de Dios.'),(63,10,'Coro',6,'Vamos caminando en la luz de Dios,\nVamos Caminando en la luz de Dios;\nCon Jesús en comunión, fiando en la Biblia de Dios,\nMientras vamos caminando en la luz de Dios.'),(64,10,'Estrofa',7,'A través del mundo cruel o del valle do no hay miel,\nMientras vamos caminando en la luz de Dios;\nCaminemos hacia Sión, donde está nuestra mansión,\nMientras vamos caminando en la luz de Dios.'),(65,10,'Coro',8,'Vamos caminando en la luz de Dios,\nVamos Caminando en la luz de Dios;\nCon Jesús en comunión, fiando en la Biblia de Dios,\nMientras vamos caminando en la luz de Dios.'),(66,11,'Estrofa',1,'A Jesucristo ven sin tardar,\nQue entre nosotros hoy Él está;\nY te convida con dulce afán,\nTierno diciendo “ven”.'),(67,11,'Coro',2,'¡Oh, cuán grande es nuestra reunión,\nCuando el reino establecido ya,\nContigo estemos en comunión,\nGozando eterno bien!'),(68,11,'Estrofa',3,'Piensa que Él solo puede colmar,\nTu triste pecho de gozo y paz;\nY porque anhela tu bienestar,\nVuelve a decirte “Ven”.'),(69,11,'Coro',4,'¡Oh, cuán grande es nuestra reunión,\nCuando el reino establecido ya,\nContigo estemos en comunión,\nGozando eterno bien!'),(70,11,'Estrofa',5,'Su voz escucha sin vacilar,\nY grato acepta lo que hoy te da;\nTalvez mañana no habrá lugar,\nNo te detengas ven.'),(71,11,'Coro',6,'¡Oh, cuán grande es nuestra reunión,\nCuando el reino establecido ya,\nContigo estemos en comunión,\nGozando eterno bien!'),(72,12,'Estrofa',1,'Hay muchos que nunca comprenden\nPor qué, estoy tan gozoso aquí;\nCruce el Jordán, llegue a Canaán,\n¡Oh, sí, es un Reino aquí!'),(73,12,'Coro',2,'Oh, sí, es un Reino aquí!\n¡Oh, sí, es un Reino aquí!\nCruce el Jordán, llegue a Canaán,\n¡Oh, sí, es un Reino aquí!'),(74,12,'Estrofa',3,'Cuando alegres cantan los santos asi,\nLa gente no sabe por qué;\nPues es el Espíritu santo de Dios\nQue Cristo ha mandado aquí'),(75,12,'Coro',4,'¡Oh, sí, es un Reino aquí!\n¡Oh, sí, es un Reino aquí!\nCruce el Jordán, llegue a Canaán,\n¡Oh, sí, es un Reino aquí!'),(76,12,'Estrofa',5,'Tonadas celestes oímos cantar,\nPor tierra, el aire y el mar;\nResuena el mensaje de Cristo, el Señor\nQue en nubes pronto ha de llegar.'),(77,12,'Coro',6,'¡Oh, sí, es un Reino aquí!\n¡Oh, sí, es un Reino aquí!\nCruce el Jordán, llegue a Canaán,\n¡Oh, sí, es un Reino aquí!'),(78,12,'Estrofa',7,'Veremos a Cristo que en gloria vendrá,\nEl mismo que en la cruz murió;\nCon todos los ángeles pronto vendrá\nReinara con los que compró.'),(79,12,'Coro',8,'Y ese un Reino será, Y ese un Reino será;\nJesús con sus ángeles pronto vendrá\nY ese un Reino será'),(80,13,'Estrofa',1,'Del Santo amor de Cristo, que no tendrá su igual;\nDe su divina gracia, sublime y eternal.\nDe su misericordia, inmensa como el mar,\nY cual los cielos alta, con gozo he de cantar.'),(81,13,'Coro',2,'El amor de mi Señor, grande, dulce es más y más.\nRico e inefable, nada es comparable,\nAl amor de mi Jesús.'),(82,13,'Estrofa',3,'Cuando Él vivió en el mundo, la gente lo siguió,\nY todas sus angustias, en Él depositó.\nEntonces bondadoso, su amor brotó a raudal,\nIncontenible inmenso, sanando todo mal.'),(83,13,'Coro',4,'El amor de mi Señor, grande, dulce es más y más.\nRico e inefable, nada es comparable,\nAl amor de mi Jesús.'),(84,13,'Estrofa',5,'El puso en las pupilas, del ciego nueva luz;\nLa eterna luz de vida, que centella en la cruz.\nY dio a las almas todas, la gloria de su ser;\nAl impartir su gracia, su Espíritu y poder.'),(85,13,'Coro',6,'El amor de mi Señor, grande, dulce es más y más.\nRico e inefable, nada es comparable,\nAl amor de mi Jesús.'),(86,13,'Estrofa',7,'Su amor por las edades, del mundo es el fanal,\nQue marca esplendoroso, la senda del ideal.\nY al paso de los años, lo hará mas dulce y más\nPrecioso, al darle al alma su incomparable paz.'),(87,13,'Coro',8,'El amor de mi Señor, grande, dulce es más y más.\nRico e inefable, nada es comparable,\nAl amor de mi Jesús.'),(88,14,'Estrofa',1,'Cristo tan sólo pudo amarme,\nNada podrá de Él separarme,\nPues con su sangre me redimió;\nAhora soy de Él.'),(89,14,'Coro',2,'Ahora soy de Cristo.\nMío también, es Él;\nPuedo gozar en su amistad\nPor la eternidad.'),(90,14,'Estrofa',3,'Antes vivía en el pecado,\nMi corazón de Dios alejado;\nMas mi vergüenza Él me quitó:\nYa pertenezco a Él.'),(91,14,'Coro',4,'Ahora soy de Cristo.\nMío también, es Él;\nPuedo gozar en su amistad\nPor la eternidad.'),(92,14,'Estrofa',5,'Mi ser rebosa de pleno gozo,\nDios me liberta, dióme reposo,\nPues con su sangre me redimió;\nAhora soy de Él.'),(93,14,'Coro',6,'Ahora soy de Cristo.\nMío también, es Él;\nPuedo gozar en su amistad\nPor la eternidad.'),(94,15,'Estrofa',1,'La cruz no será más pesada,\nQue la gracia que El me da;\nY si la tormenta me espanta,\nNo podrá esconder su faz'),(95,15,'Coro',2,'La gracia de Dios me bastara,\nSu ayuda jamás me faltara\nConsolado por su amor\nQue echa fuera mi temor,\nConfiare en mi Señor.'),(96,15,'Estrofa',3,'Mi cáliz nunca es tan amargo,\nComo el de Getsemaní;\nEn mis días más apurados,\nNo se aparta Dios de mí.'),(97,15,'Coro',4,'La gracia de Dios me bastara,\nSu ayuda jamás me faltara\nConsolado por su amor\nQue echa fuera mi temor,\nConfiare en mi Señor.'),(98,15,'Estrofa',5,'La luz de su rostro me alumbra,\nEn el tiempo de aflicción;\nY mi alma gozosa vislumbra,\nA Jesús que reina en Sión.'),(99,15,'Coro',6,'La gracia de Dios me bastara,\nSu ayuda jamás me faltara\nConsolado por su amor\nQue echa fuera mi temor,\nConfiare en mi Señor.'),(100,16,'Estrofa',1,'Maravillado estoy que Dios me amara,\nTan pecador, cubierto de maldad;\nQue me hiciera andar en su presencia,\nPurificado con su santidad.'),(101,16,'Coro',2,'Maravillado estoy que Dios me amara,\nSolo Jesús mi culpa borrará;\nPor fe en Jesús obtengo vida eterna,\nPor siempre moraré con ÉL en Sión.'),(102,16,'Estrofa',3,'Maravillado estoy que me acogiera,\nPara vivir con Él en santidad;\nParticipar de su divina gloria,\nQue me reserva en el reino allá.'),(103,16,'Coro',4,'Maravillado estoy que Dios me amara,\nSolo Jesús mi culpa borrará;\nPor fe en Jesús obtengo vida eterna,\nPor siempre moraré con ÉL en Sión.'),(104,16,'Estrofa',5,'Maravillado estoy que Dios salvara,\nA todos los que siguen su mandar;\nDe aceptar a su Hijo Jesucristo,\nY en su sendero siempre caminar.'),(105,16,'Coro',6,'Maravillado estoy que Dios me amara,\nSolo Jesús mi culpa borrará;\nPor fe en Jesús obtengo vida eterna,\nPor siempre moraré con ÉL en Sión.'),(106,17,'Estrofa',1,'Tan dulce el nombre de Jesús,\nSus bellas notas al cantar;\nQue mi alma llena al proclamar,\nEl nombre de Jesús.'),(107,17,'Coro',2,'¡Cristo, oh, que dulce es!\n¡Cristo, para siempre es!\n¡Cristo, yo te aclamaré!\nPor siempre, ¡oh, mi Cristo!'),(108,17,'Estrofa',3,'Adoro el nombre de Jesús,\nJamás me faltará su amor\nY pone aparte mi dolor,\nEl nombre de Jesús.'),(109,17,'Coro',4,'¡Cristo, oh, que dulce es!\n¡Cristo, para siempre es!\n¡Cristo, yo te aclamaré!\nPor siempre, ¡oh, mi Cristo!'),(110,17,'Estrofa',5,'¡Tan puro el nombre de Jesús!\nQue mi pesar pudo quitar;\nY grata paz a mi alma dar.\nEl nombre de Jesús.'),(111,17,'Coro',6,'¡Cristo, oh, que dulce es!\n¡Cristo, para siempre es!\n¡Cristo, yo te aclamaré!\nPor siempre, ¡oh, mi Cristo!'),(112,17,'Estrofa',7,'El dulce nombre de Jesús,\nPor siempre quiero alabar;\nY todos deben ensalzar,\nEl nombre de Jesús.'),(113,17,'Coro',8,'¡Cristo, oh, que dulce es!\n¡Cristo, para siempre es!\n¡Cristo, yo te aclamaré!\nPor siempre, ¡oh, mi Cristo!'),(114,18,'Estrofa',1,'Cuando andemos con Dios,\nEscuchando su voz,\nNuestra senda florida será;\nSi acatamos su ley,\nÉl será nuestro Rey,\nY con Él reinaremos allá.'),(115,18,'Coro',2,'O...be...de...cer\nCumple a nuestro deber;\nSi queréis ser felices,\nDebéis obedecer.'),(116,18,'Estrofa',3,'Cuando Cristo murió,\nNuestro llanto enjugó;\nProclamarle debemos doquier;\nGozarás del amor\nDe tu Rey y Señor\nSi obediente le quieres tú ser.'),(117,18,'Coro',4,'O...be...de...cer\nCumple a nuestro deber;\nSi queréis ser felices,\nDebéis obedecer.'),(118,18,'Estrofa',5,'No podemos probar,\nLas delicias sin par;\nSi seguimos mundano el placer;\nObtendremos su amor,\nY el divino favor,\nSi sus leyes queremos hacer.'),(119,18,'Coro',6,'O...be...de...cer\nCumple a nuestro deber;\nSi queréis ser felices,\nDebéis obedecer.'),(120,19,'Estrofa',1,'Hay un lugar do quiero estar,\nEn el corazón de Dios;\nLugar do pueda descansar,\nEn el corazón de Dios.'),(121,19,'Coro',2,'Jesús, tu fuiste enviado,\nDel corazón de Dios;\nMantenme fiel y firme,\nEn el corazón de Dios.'),(122,19,'Estrofa',3,'Hay un lugar de gozo y paz,\nEn el corazón de Dios;\nLugar de celestial solaz,\nEn el corazón de Dios.'),(123,19,'Coro',4,'Jesús, tu fuiste enviado,\nDel corazón de Dios;\nMantenme fiel y firme,\nEn el corazón de Dios.'),(124,19,'Estrofa',5,'Hay un lugar de adoración,\nEn el corazón de Dios;\nLugar de eterna bendición,\nEn el corazón de Dios.'),(125,19,'Coro',6,'Jesús, tu fuiste enviado,\nDel corazón de Dios;\nMantenme fiel y firme,\nEn el corazón de Dios.'),(126,20,'Estrofa',1,'¡Padre a tus pies me postro!\nRompe mis prisiones duras;\n¡Oh, responde mientras llamo!\n¡Pon tu Espíritu en mí!'),(127,20,'Coro',2,'¡Pon tu Espíritu en mi alma!\nHazme lo que se debiera;\nHazme puro en todo, libre de pecado,\n¡Pon tu Espíritu en mí!'),(128,20,'Estrofa',3,'Mientras Cristo intercede,\nMientras oro yo humilde,\nLo que necesito dame,\n¡Pon tu Espíritu en mí!'),(129,20,'Coro',4,'¡Pon tu Espíritu en mi alma!\nHazme lo que se debiera;\nHazme puro en todo, libre de pecado,\n¡Pon tu Espíritu en mí!'),(130,20,'Estrofa',5,'No deseo yo ofenderte,\nViviré para agradarte,\nY en mi corazón guardarte,\n¡Pon tu Espíritu en mí!'),(131,20,'Coro',6,'¡Pon tu Espíritu en mi alma!\nHazme lo que se debiera;\nHazme puro en todo, libre de pecado,\n¡Pon tu Espíritu en mí!'),(132,21,'Estrofa',1,'Incansables compañeros, seamos fieles a Jesús\nDe Jesús somos guerreros, con sus armas y su luz,\nVenceremos a Satán'),(133,21,'Coro',2,'Yo voy a Jesús llevando su cruz\nYo dejo este mundo exento de luz'),(134,21,'Estrofa',3,'Vamos pronto cual viajeros, vamos siempre, sin cesar;\nAquí somos peregrinos, de Dios somos mensajeros,\n¡No hay descanso hasta el llegar!'),(135,21,'Coro',4,'Yo voy a Jesús llevando su cruz\nYo dejo este mundo exento de luz'),(136,21,'Estrofa',5,'Si cansados del camino, nos sentamos a pensar;\nOtros cogen nuestro asiento, y al llegar no habrá lugar,\n¡No hay descanso hasta el llegar!'),(137,21,'Coro',6,'Yo voy a Jesús llevando su cruz\nYo dejo este mundo exento de luz'),(138,21,'Estrofa',7,'No dejemos el camino, es nutrido el batallar;\nTodos somos peregrinos, Triunfaremos al final;\n¡No hay descanso hasta el llegar!'),(139,21,'Coro',8,'Yo voy a Jesús llevando su cruz\nYo dejo este mundo exento de luz'),(140,21,'Estrofa',9,'Al finalizar el viaje, desde aquí a la eternidad;\nDios dará blanco ropaje, al que ha de perseverar,\n¡No hay descanso hasta el llegar!'),(141,21,'Coro',10,'Yo voy a Jesús llevando su cruz\nYo dejo este mundo exento de luz'),(142,21,'Estrofa',11,'Si en el mundo de tinieblas, nos queremos detener;\nNos veremos por doquiera, a punto de perecer;\n¡No hay descanso hasta el llegar!'),(143,21,'Coro',12,'Yo voy a Jesús llevando su cruz\nYo dejo este mundo exento de luz'),(144,22,'Estrofa',1,'Por la mañana ¡oh, Señor!\nYo con alegre voz,\nA tu buen nombre doy loor,\nCon gratitud mi Dios.'),(145,22,'Estrofa',2,'El sol brillante ya salió,\nandamos en su luz;\nDel Salvador es símbolo,\nDe nuestro Rey Jesús.'),(146,22,'Estrofa',3,'Los cielos cuentan al que cree,\nLa gloria del Señor;\nSalvados somos por la fe,\nEn su eterno amor.'),(147,22,'Estrofa',4,'En la mañana eterna pues,\nContigo cuando esté;\nYo del Cordero y de Moisés,\nEl himno entonaré.'),(148,23,'Estrofa',1,'Dulce oración, dulce oración,\nDe toda influencia mundanal,\nElevas tú mi corazón,\nAl tierno Padre Celestial.\n¡Oh, cuántas veces tuve en ti,\nAuxilio en ruda tentación,\nY cuántos bienes recibí,\nMediante ti dulce oración!'),(149,23,'Estrofa',2,'Dulce oración, dulce oración,\nAl trono excelso de bondad,\nTú llevarás mi petición,\nA Dios que escucha con piedad.\nPor fe espero recibir,\nLa gran Divina bendición;\nY siempre a mi Señor servir,\nPor tu virtud, dulce oración.'),(150,23,'Estrofa',3,'Dulce oración, dulce oración,\nQue aliento y gozo al alma das;\nEn esta tierra de aflicción,\nConsuelo siempre me serás.\nHasta el momento en que veré,\nFrancas las puertas de Sión;\nEntonces me despediré,\nFeliz de ti, dulce oración.'),(151,24,'Estrofa',1,'Ved la fuente sanadora,\nLa que abrió el Salvador,\nCuyas aguas refrescantes,\nSon de perennal valor.'),(152,24,'Coro',2,'¡Oh, preciosa, fuente sanadora!\nPara todos fluye libre;\n¡Oh, preciosa fuente sanadora!\n¡Gloria a Dios, me sana a mí!'),(153,24,'Estrofa',3,'En la fuente que nos sana,\nHe hallado el perdón,\nY lavado toda mancha,\nDe mi pobre corazón.'),(154,24,'Coro',4,'¡Oh, preciosa, fuente sanadora!\nPara todos fluye libre;\n¡Oh, preciosa fuente sanadora!\n¡Gloria a Dios, me sana a mí!'),(155,24,'Estrofa',5,'En la fuente que nos sana,\nHe hallado el perdón,\nY lavado toda mancha,\nDe mi pobre corazón.'),(156,24,'Coro',6,'¡Oh, preciosa, fuente sanadora!\nPara todos fluye libre;\n¡Oh, preciosa fuente sanadora!\n¡Gloria a Dios, me sana a mí!'),(157,24,'Estrofa',7,'En la fuente que nos sana,\nCristo ofrece la salud;\nPues venid enfermos todos,\nProbaréis su gran virtud.'),(158,24,'Coro',8,'¡Oh, preciosa, fuente sanadora!\nPara todos fluye libre;\n¡Oh, preciosa fuente sanadora!\n¡Gloria a Dios, me sana a mí!'),(159,24,'Estrofa',9,'Esta fuente que nos sana,\nAun hoy día es eficaz;\nVen, sumérgete en ella,\nCree y sano quedarás'),(160,24,'Coro',10,'¡Oh, preciosa, fuente sanadora!\nPara todos fluye libre;\n¡Oh, preciosa fuente sanadora!\n¡Gloria a Dios, me sana a mí!'),(161,25,'Estrofa',1,'Hay una Iglesia preciosa,\nEsta es la Iglesia de Dios;\nQue esparce su luz por doquiera,\nPara dar al mundo salvación.'),(162,25,'Coro',2,'¡Oh, ven, ven, ven,\nVen a la Iglesia de Dios;\nDonde podrás descansar;\nOtro sitio igual nunca encuentras,\nCual la Iglesia de Dios sin igual.'),(163,25,'Estrofa',3,'Ve a la Iglesia de Dios,\nY conocerás verdad;\nY serás para siempre dichoso,\nGozando de libertad.'),(164,25,'Coro',4,'¡Oh, ven, ven, ven,\nVen a la Iglesia de Dios;\nDonde podrás descansar;\nOtro sitio igual nunca encuentras,\nCual la Iglesia de Dios sin igual.'),(165,25,'Estrofa',5,'Ven, pecador a Jesús,\nTus pecados lavarás;\nY estando tu alma ya limpia,\nEsta noche con Él cenarás.'),(166,25,'Coro',6,'¡Oh, ven, ven, ven,\nVen a la Iglesia de Dios;\nDonde podrás descansar;\nOtro sitio igual nunca encuentras,\nCual la Iglesia de Dios sin igual.'),(167,25,'Estrofa',7,'¡Oh, libertad tan preciosa,\nQue en Jesús pude hallar,\nEn su sangre, oh, fuente hermosa,\nQue lavó para siempre mi mal.'),(168,25,'Coro',8,'¡Oh, ven, ven, ven,\nVen a la Iglesia de Dios;\nDonde podrás descansar;\nOtro sitio igual nunca encuentras,\nCual la Iglesia de Dios sin igual.'),(169,26,'Estrofa',1,'¡Hermosa tierra Sión, de Cristo, el Señor,\nEn alta roca estás para pendón de Paz;\nDonde el dolor huirá y la gloria será,\nDe Dios, el Padre y de Cristo, nuestro Señor!'),(170,26,'Coro',2,'¡Bendita tierra hermosa, tú eres Sión!\nLa señalada por el infinito Dios;\nPara que el pueblo, salvado por su amor,\nGoce en ti una eterna bendición.'),(171,26,'Estrofa',3,'¡Hermosa tierra Sión, de Cristo, el Señor,\nSólo en ti habrá nueva canción de amor;\nCon que los ángeles, huestes de redención!\n¡Aleluya, entonarán al Redentor!'),(172,26,'Coro',4,'¡Bendita tierra hermosa, tú eres Sión!\nLa señalada por el infinito Dios;\nPara que el pueblo, salvado por su amor,\nGoce en ti una eterna bendición.'),(173,26,'Estrofa',5,'¡Hermosa tierra Sión, de Cristo, el Señor,\nHermosura de Dios, en Cristo la salud,\nEnsalzamiento en ti todos entonarán,\nCuando sus grillos quebrados sean de\nesclavitud!'),(174,26,'Coro',6,'¡Bendita tierra hermosa, tú eres Sión!\nLa señalada por el infinito Dios;\nPara que el pueblo, salvado por su amor,\nGoce en ti una eterna bendición.'),(175,26,'Estrofa',7,'¡Hermosa tierra Sión, de Cristo, el Señor,\nAlégrate en tu Rey, gózate en tu hacedor;\nLoando su nombre en santa oración,\nSe gozarán todos los fieles hijos de Sión!'),(176,26,'Coro',8,'¡Bendita tierra hermosa, tú eres Sión!\nLa señalada por el infinito Dios;\nPara que el pueblo, salvado por su amor,\nGoce en ti una eterna bendición.'),(177,27,'Estrofa',1,'A tu siervo Moisés le dijiste,\nQue tus hijos harían siempre así;\nCelebrando por pacto perpetuo,\nEl recuerdo del Gethsemaní.'),(178,27,'Coro',2,'Cristo es Alfa, Omega,\ny principio, es fin , es fin;\nPor sus sendas debemos de ir,\nEsperar la corona de gloria,\nQue los salvos han de recibir.'),(179,27,'Estrofa',3,'El pimpollo que ha aparecido,\nDe las doce tribus de Israel;\nAdmirable y gran consejero,\nEl primado de Jerusalem.'),(180,27,'Coro',4,'Cristo es Alfa, Omega,\ny principio, es fin , es fin;\nPor sus sendas debemos de ir,\nEsperar la corona de gloria,\nQue los salvos han de recibir.'),(181,27,'Estrofa',5,'Mandamientos y leyes les diste,\nDescendiste sobre el Sinaí;\nLes dijiste: “Yo soy el Camino,\nPocos son los que han de ir por aquí”.'),(182,27,'Coro',6,'Cristo es Alfa, Omega,\ny principio, es fin , es fin;\nPor sus sendas debemos de ir,\nEsperar la corona de gloria,\nQue los salvos han de recibir.'),(183,27,'Estrofa',7,'En el árbol de la gran oliva,\nfué ingerida La Iglesia de Dios;\nY al que toca las siete trompetas,\nSi en verdad escuchamos su voz.'),(184,27,'Coro',8,'Cristo es Alfa, Omega,\ny principio, es fin , es fin;\nPor sus sendas debemos de ir,\nEsperar la corona de gloria,\nQue los salvos han de recibir.'),(185,27,'Estrofa',9,'Te rogamos Señor infinito,\nTe pedimos tus santos también;\nQue nos lleves con mano potente,\nA tu reino de Jerusalem.'),(186,27,'Coro',10,'Cristo es Alfa, Omega,\ny principio, es fin , es fin;\nPor sus sendas debemos de ir,\nEsperar la corona de gloria,\nQue los salvos han de recibir.'),(187,28,'Estrofa',1,'Cantaré la bella historia,\nDe Jesús, mi Salvador;\nPara mí dejó la gloria,\nEn la cruz por mí expiró.'),(188,28,'Coro',2,'Cantaré la maravilla,\nDe Jesús, mi Salvador;\nCon los santos en el reino,\nCantaré con grande amor.'),(189,28,'Estrofa',3,'Me salvó con gracia eterna,\nCuando herrado y vil me vió;\nCon su mano fiel y tierna,\nAl camino ÉL me guió.'),(190,28,'Coro',4,'Cantaré la maravilla,\nDe Jesús, mi Salvador;\nCon los santos en el reino,\nCantaré con grande amor.'),(191,28,'Estrofa',5,'Oprimido y angustiado,\nCristo vino y me libró;\nLastimado del pecado,\nCristo vino y me salvó.'),(192,28,'Coro',6,'Cantaré la maravilla,\nDe Jesús, mi Salvador;\nCon los santos en el reino,\nCantaré con grande amor.'),(193,28,'Estrofa',7,'Con su brazo fiel y fuerte,\nYo el río cruzaré;\nMás allá, con Cristo siempre,\nMis amados yo veré.'),(194,28,'Coro',8,'Cantaré la maravilla,\nDe Jesús, mi Salvador;\nCon los santos en el reino,\nCantaré con grande amor.'),(195,29,'Estrofa',1,'Pronto la noche viene, tiempo es de trabajar;\nLos que lucháis por Cristo, no hay que descansar.\nCuando la vida es sueño, gozo, vigor, salud;\nEs la mañana hermosa, de la juventud.'),(196,29,'Estrofa',2,'Pronto la noche viene, tiempo es de trabajar;\nPara salvar al mundo, hay que batallar;\nCuando la vida alcanza, toda su esplendidez,\nCuando es el medio día de la madurez.'),(197,29,'Estrofa',3,'Pronto la noche viene, tiempo es de trabajar;\nSi el pecador perece, idlo a rescatar.\nAun a la edad provecta, débil y sin salud;\nAun en la misma tarde, de la senectud.'),(198,29,'Estrofa',4,'Pronto la noche viene, ¡Listos a trabajar!\n¡Listos que muchas almas, hay que rescatar!\nQuién de la vida el día, puede desperdiciar;\nViene la noche cuando, nadie puede obrar.'),(199,30,'Estrofa',1,'Juventud que a Jesús te consagras,\nNo desmayes ni mires atrás;\nSigue en pos de corona de triunfo,\nQue obtendrás cuando venga Jesús.'),(200,30,'Coro',2,'¡Despertad y velad juventud,\nDe la Iglesia de Dios,\nNo durmáis; no durmáis,\nQue Jesús a las puertas ya está!.'),(201,30,'Estrofa',3,'Alzad siempre muy alta la insignia,\nDel glorioso evangelio de Dios;\nAnunciad a la nación maligna,\nQue el Señor deja oir hoy su voz.'),(202,30,'Coro',4,'¡Despertad y velad juventud,\nDe la Iglesia de Dios,\nNo durmáis; no durmáis,\nQue Jesús a las puertas ya está!.'),(203,30,'Estrofa',5,'Levantaos del sueño profundo,\nE inhiestos tomad con valor;\nLa armadura de Dios que en el mundo,\nha dejado a su pueblo el Señor.'),(204,30,'Coro',6,'¡Despertad y velad juventud,\nDe la Iglesia de Dios,\nNo durmáis; no durmáis,\nQue Jesús a las puertas ya está!.'),(205,30,'Estrofa',7,'Si luchamos por Cristo obtendremos,\nLa corona sublime del bien;\nese gran galardón esperamos,\nSi con Cristo sufrimos también.'),(206,30,'Coro',8,'¡Despertad y velad juventud,\nDe la Iglesia de Dios,\nNo durmáis; no durmáis,\nQue Jesús a las puertas ya está!.'),(207,31,'Estrofa',1,'¡Oh, Señor, recíbeme cual soy,\nYa no más, ya no quiero pecar;\nDel pecado me quiero apartar,\nJustifica mi ser, dame tu dulce paz,\nY tu gran bendición!'),(208,31,'Estrofa',2,'¡Oh, Señor, toma mi corazón,\nY hazlo tuyo por la eternidad;\nLléname de tu santa bondad,\nY en mi alma Tú pon una nueva canción,\nDe paz y dulce amor!'),(209,31,'Estrofa',3,'Pecador, tú que vagas sin Dios,\nVen ahora y acepta al Señor;\nÉl te quiere impartir su perdón,\nÉl te quiere salvar,\nÉl te quiere ayudar; hoy acepta el perdón.'),(210,32,'Estrofa',1,'Quiero seguir a mi Jesús,\nEn pos de aquella real mansión;\nAquella excelsa y bella Sión,\nPor eso cargo yo la cruz.'),(211,32,'Coro',2,'¡Venid, venid, pueblo de Dios,\nVamos cumpliendo con su ley;\nGlorifiquemos nuestro Rey,\nAlcemos todos bien la voz!'),(212,32,'Estrofa',3,'Digamos todos: ¡Gran Señor!\nEres antorcha que da luz;\nEres la vida, ¡oh, mi Jesús!\nEres alivio en mi dolor.'),(213,32,'Coro',4,'¡Venid, venid, pueblo de Dios,\nVamos cumpliendo con su ley;\nGlorifiquemos nuestro Rey,\nAlcemos todos bien la voz!'),(214,32,'Estrofa',5,'Hagamos todos con valor,\nResplandecer la fiel verdad,\nY sea en nosotros la bondad\nDe Cristo, nuestro Salvador.'),(215,32,'Coro',6,'¡Venid, venid, pueblo de Dios,\nVamos cumpliendo con su ley;\nGlorifiquemos nuestro Rey,\nAlcemos todos bien la voz!'),(216,32,'Estrofa',7,'Días venturosos para nos,\nCuando allá en Sión estemos ya;\nLa dicha eterna allí será,\nY ensalzaremos nuestro Dios'),(217,32,'Coro',8,'¡Venid, venid, pueblo de Dios,\nVamos cumpliendo con su ley;\nGlorifiquemos nuestro Rey,\nAlcemos todos bien la voz!'),(218,33,'Estrofa',1,'Manos cariñosas, manos de Jesús,\nManos que llevaron el dolor por mí;\nManos que supieron sólo hacer el bien,\n¡Gloria a esas manos! ¡Aleluya, amén!'),(219,33,'Estrofa',2,'Blancas azucenas, lirios del amor,\nFueron esas manos de mi Redentor;\nManos que a los ciegos dieron la visión,\nCon el real consuelo de su gran perdón.'),(220,33,'Estrofa',3,'Manos que supieron calmar el dolor,\n¡Oh, manos divinas de mi Redentor!\nQue multiplicaron los peces y el pan\nManos milagrosas que la vida dan.'),(221,33,'Estrofa',4,'Manos que sufrieron el clavo y la cruz,\nManos redentoras de mi buen Jesús;\nDe esas manos bellas yo confiado estoy,\nEllas van guiando, pues al Reino voy.'),(222,34,'Estrofa',1,'Cantaré, a Jesús, de mi alma rey,\nAl Rey de gloria ensalzaré;\nTrajo al mundo paz,\nY al mortal buena voluntad;\nAlegres nuevas doquiera proclamad.'),(223,34,'Coro',2,'Yo soy feliz con mi Cristo,\nporque Él mi alma salvó;\nÁngeles cantan alegres,\nPor cuantos Él redimió.\n¡Oh, cuán hermosa es la vida!\nDulce, serena de fe;\nSoy peregrino en la tierra,\nMas ando con Cristo, de mi alma Rey.'),(224,34,'Estrofa',3,'En la cruz del Calvario por mi sufrió,\nAsí la amarga copa bebió,\nY al expirar, el sol de luto se cubrió,\nMas vencedor el Señor resucitó.'),(225,34,'Coro',4,'Yo soy feliz con mi Cristo,\nporque Él mi alma salvó;\nÁngeles cantan alegres,\nPor cuantos Él redimió.\n¡Oh, cuán hermosa es la vida!\nDulce, serena de fe;\nSoy peregrino en la tierra,\nMas ando con Cristo, de mi alma Rey.'),(226,34,'Estrofa',5,'Ascendió a los cielos, mi buen Señor,\nPor mí intercede, con tierno amor;\nPronto volverá con sus santos para reinar,\nDicha indecible será con Él morar.'),(227,34,'Coro',6,'Yo soy feliz con mi Cristo,\nporque Él mi alma salvó;\nÁngeles cantan alegres,\nPor cuantos Él redimió.\n¡Oh, cuán hermosa es la vida!\nDulce, serena de fe;\nSoy peregrino en la tierra,\nMas ando con Cristo, de mi alma Rey.'),(228,35,'Estrofa',1,'Viviendo aquí, en mundo de maldad,\nNunca podréme confortar;\nDuro es luchar con toda tentación...\n¿A dónde iré sin ti Señor?'),(229,35,'Coro',2,'Oh!, ¿A dónde iré,?\n¿A dónde iré, Señor?\n¿Dónde encontrar asilo y paz?\nYo necesito un gran amigo fiel...\n¿A dónde iré sin Ti Señor?'),(230,35,'Estrofa',3,'Hay quienes son muy llenos de bondad,\nY a los que tanto amo yo;\nMas cuando anhelo el celestial maná,\n¿A dónde iré sino al Señor?'),(231,35,'Coro',4,'Oh!, ¿A dónde iré,?\n¿A dónde iré, Señor?\n¿Dónde encontrar asilo y paz?\nYo necesito un gran amigo fiel...\n¿A dónde iré sin Ti Señor?'),(232,35,'Estrofa',5,'Aunque rodeado estoy, de amigos mil,\nBusco palabra de mi Dios;\nY cuando llegué de mi vida el fin,\n¿A dónde iré sino al Señor?'),(233,35,'Coro',6,'Oh!, ¿A dónde iré,?\n¿A dónde iré, Señor?\n¿Dónde encontrar asilo y paz?\nYo necesito un gran amigo fiel...\n¿A dónde iré sin Ti Señor?'),(234,36,'Estrofa',1,'Una vez perdido vivía yo\nLejos y vagante en error\nMas la voz de Cristo me alcanzó,\nMe llamó con tierno amor.'),(235,36,'Coro',2,'Hay un nombre nuevo en la gloria,\nMío es, si, mío es;\nY los ángeles cantan la historia,\n\\\"Salvo es el pecador\\\".\nOh, hay un nombre nuevo en la gloria!\nMío es, si, mío es;\nTodos mis pecados ya son perdonados,\n¡Gloria al Señor!'),(236,36,'Estrofa',3,'Cantos de alegría elevo hoy\nA mi Rey, y buen Salvador;\nYa por fe en su nombre al Reino voy,\nDesde que me rescató.'),(237,36,'Coro',4,'Hay un nombre nuevo en la gloria,\nMío es, si, mío es;\nY los ángeles cantan la historia,\n\\\"Salvo es el pecador\\\".\nOh, hay un nombre nuevo en la gloria!\nMío es, si, mío es;\nTodos mis pecados ya son perdonados,\n¡Gloria al Señor!'),(238,36,'Estrofa',5,'Cantos de alegría elevo hoy a mi Rey,\nY buen Salvador;\nEs porque mis dones a Cristo doy,\nQue me use por su amor.'),(239,36,'Coro',6,'Hay un nombre nuevo en la gloria,\nMío es, si, mío es;\nY los ángeles cantan la historia,\n\\\"Salvo es el pecador\\\".\nOh, hay un nombre nuevo en la gloria!\nMío es, si, mío es;\nTodos mis pecados ya son perdonados,\n¡Gloria al Señor!'),(240,37,'Estrofa',1,'Estoy admirado del amor de mi Jesús,\nDe su rica gracia, su bondad y clara luz;\nSe agita mi alma al saber que sólo por mí,\nJesús en la cruz vertió su sangre carmesí.'),(241,37,'Coro',2,'¡Que maravilla es, que me amara así!\n¡Hasta morir por mí!\n¡Que maravilla es!\n¡El murió por mí!'),(242,37,'Estrofa',3,'No sé cómo fue que su trono dejara Él,\nA fin de salvarme, cuando era yo tan infiel,\nIndigno, rebelde, viviendo en perdición,\nCon su sangre me lavó, dándome salvación.'),(243,37,'Coro',4,'¡Que maravilla es, que me amara así!\n¡Hasta morir por mí!\n¡Que maravilla es!\n¡El murió por mí!'),(244,37,'Estrofa',5,'Mi deuda a Él es tan grande, pues Él sufrió\nLos clavos, azotes, la cuenta así pagó;\n¿Podré olvidar tal amor, sí, tal devoción?\n¡Jamás, hoy te rindo mi vida, mi corazón!'),(245,37,'Coro',6,'¡Que maravilla es, que me amara así!\n¡Hasta morir por mí!\n¡Que maravilla es!\n¡El murió por mí!'),(246,38,'Estrofa',1,'Si al cruel enemigo temes combatir,\nSi la duda agobia siempre tu existir;\nQue la hermosa luz de Dios fulgure en ti,\nY serás feliz así.'),(247,38,'Coro',2,'Deja penetrar la luz, deja penetrar la luz;\nQue la hermosa luz de Dios fulgure en ti,\nY serás feliz así.'),(248,38,'Estrofa',3,'Si tu fe en Jesús muy flaca y débil es,\nSi Dios no contesta tu ferviente prez;\nQue la hermosa luz de Dios fulgure en ti,\nY serás feliz así.'),(249,38,'Coro',4,'Deja penetrar la luz, deja penetrar la luz;\nQue la hermosa luz de Dios fulgure en ti,\nY serás feliz así.'),(250,38,'Estrofa',5,'Si feliz el Reino anhelas alcanzar,\nY del mal y las tinieblas escapar;\nQue la hermosa luz de Dios fulgure en ti,\nY serás feliz así.'),(251,38,'Coro',6,'Deja penetrar la luz, deja penetrar la luz;\nQue la hermosa luz de Dios fulgure en ti,\nY serás feliz así.'),(252,38,'Estrofa',7,'Si anduviéremos en luz, divina luz,\nLimpios nos hará la sangre de Jesús;\nClaridad tendremos en el corazón,\nSi vivimos en su luz.'),(253,38,'Coro',8,'Deja penetrar la luz, deja penetrar la luz;\nQue la hermosa luz de Dios fulgure en ti,\nY serás feliz así.'),(254,38,'Estrofa',9,'Si el espíritu de Dios consolador,\nLuz del cielo trae, divino resplandor;\nCuando tenga entrada en tu corazón,\nEl será tu eterna luz.'),(255,38,'Coro',10,'Deja penetrar la luz, deja penetrar la luz;\nQue la hermosa luz de Dios fulgure en ti,\nY serás feliz así.'),(256,39,'Estrofa',1,'Hay un lugar en la tierra,\nLejos, más allá del mar;\nTierra de Dios escogida,\nTierra de Dios sin igual.'),(257,39,'Coro',2,'Jerusalem, Jerusalem, que desolada fuiste,\nporque Jehová te dijo: ven, y no quisiste ir.\nHoy restaurada serás, por el Omnipotente,\nY tus hijos en ti morarán para siempre.'),(258,39,'Estrofa',3,'Salid de allí, pueblo mío,\nDice el Señor Jehová;\nSalid, dejad al impío,\nPues a éste Él destruirá.'),(259,39,'Coro',4,'Jerusalem, Jerusalem, que desolada fuiste,\nporque Jehová te dijo: ven, y no quisiste ir.\nHoy restaurada serás, por el Omnipotente,\nY tus hijos en ti morarán para siempre.'),(260,39,'Estrofa',5,'Reunios hermanos en Sión,\nJuntaos en Jerusalem,\nY allí entonaremos canción,\nAl que viene a ser Rey de Israel.'),(261,39,'Coro',6,'Jerusalem, Jerusalem, que desolada fuiste,\nporque Jehová te dijo: ven, y no quisiste ir.\nHoy restaurada serás, por el Omnipotente,\nY tus hijos en ti morarán para siempre.'),(262,39,'Estrofa',7,'Se oye una voz que nos grita,\nY nos dice con afán:\nVenid, mi pueblo israelita,\nQue el tiempo cumplido está.'),(263,39,'Coro',8,'Jerusalem, Jerusalem, que desolada fuiste,\nporque Jehová te dijo: ven, y no quisiste ir.\nHoy restaurada serás, por el Omnipotente,\nY tus hijos en ti morarán para siempre.'),(264,39,'Estrofa',9,'Mas no salvéis vuestras vidas,\nSin antes esto hacer:\nBuscad las ovejas perdidas,\nDe la casa de Israel.'),(265,39,'Coro',10,'Jerusalem, Jerusalem, que desolada fuiste,\nporque Jehová te dijo: ven, y no quisiste ir.\nHoy restaurada serás, por el Omnipotente,\nY tus hijos en ti morarán para siempre.'),(266,40,'Estrofa',1,'Ven, oh pródigo, ven, sin tardar, te llama Dios!\nÓyele llamando, llamándote a ti;\nTú que vagas errante, escucha su tierna voz,\nEscucha su voz de amor.'),(267,40,'Coro',2,'Llamando por ti,\nPerdido, pródigo, ven;\nLlamando por ti,\nPerdido, pródigo, ven.'),(268,40,'Estrofa',3,'Con paciencia y ternura te llama, ven a El,\nÓyele llamando, llamándote a ti;\nMientras Cristo te llama, ven, no seas infiel,\nEscucha su voz de amor.'),(269,40,'Coro',4,'Llamando por ti,\nPerdido, pródigo, ven;\nLlamando por ti,\nPerdido, pródigo, ven.'),(270,40,'Estrofa',5,'De tu padre en la casa, abundancia hay de pan,\nÓyele llamando, llamándote a ti;\nYa le mesa está lista, la bienvenida da,\nEscucha su voz de amor.'),(271,40,'Coro',6,'Llamando por ti,\nPerdido, pródigo, ven;\nLlamando por ti,\nPerdido, pródigo, ven.'),(272,41,'Estrofa',1,'Hay una senda que el mundo no conoce,\nHay una senda que yo pude encontrar;\nEn Cristo tengo la salvación de mi alma,\nCristo es la senda que me puede salvar;\nEn Cristo tengo la salvación de mi alma,\nCristo es la senda que me puede salvar.'),(273,41,'Estrofa',2,'Las amistades y todos mis parientes,\nFueron las gentes que yo relacioné;\nMe aborrecieron por causa de su nombre,\nCuando supieron que a Cristo me entregué;\nMe aborrecieron por causa de su nombre,\nCuando supieron que a Cristo me entregué.'),(274,41,'Estrofa',3,'Y aquel camino de tantos sufrimientos,\nAquel camino que al mundo me llevó,\nFue transformado en aquel feliz momento,\nCuando mi Cristo al Reino me llamó;\nFue transformado en aquel feliz momento,\nCuando mi Cristo al Reino me llamó.'),(275,42,'Estrofa',1,'Vivir en el pecado, yo no quiero ya más,\nPrefiero santidad y salvación y luz y paz;\nVivir en el pecado, pues, es cosa tan atroz,\nQue viene y nos separa de la comunión con Dios;\nQuiero triunfar, no quiero más pecar.'),(276,42,'Estrofa',2,'Oír la voz que viene de mi Padre Celestial,\nEs algo como un manso y cristalino manantial;\nAndar por sus senderos, es andar en plena luz,\nLa luz que nos fue dada en la persona de Jesús,\nEterno Dios, quiero escuchar tu voz.'),(277,42,'Estrofa',3,'Salir de las tinieblas, es lo más trascendental,\nPues ellas nos conducen solamente a hacer el mal;\nLa vida con Jesús es tan sublime en realidad,\nPues Él es vida eterna, salvación y santidad;\nEs la verdad, es vida y santidad.'),(278,42,'Estrofa',4,'Digamos, pues hermanos: \\\"Yo no quiero más pecar\\\",\nPrefiero con mi Cristo, por su senda caminar;\nDejemos las envidias y los celos y el rencor,\nUnámonos en uno, con un mismo y santo amor;\nNo más rencor, andemos en amor.'),(279,43,'Estrofa',1,'Maestro, se encrespan las aguas, y ruge la tempestad;\nLos grandes abismos del cielo, se cubren de oscuridad.\n¿No ves que aquí perecemos? ¿Puedes dormir así,\nCuando el mar agitado nos abre profundo sepulcro aquí?'),(280,43,'Coro',2,'Los vientos, las ondas oirán tu voz,\n¡Sea la paz! ¡Sea la paz!\nCalma las iras del negro mar,\nLas luchas del alma las haces cesar.\nAsí la barquilla do va el Señor,\nHundirse no puede en el mar traidor;\nDoquier se cumple su voluntad,\n¡Sea la paz! ¡Sea la paz!\nTu voz resuena en la inmensidad,\n¡Sea la paz!'),(281,43,'Estrofa',3,'Maestro, mi ser angustiado, te busca con ansiedad;\nDe mi alma en los antros profundos, se libra cruel tempestad.\nPasa el pecado a torrentes, sobre mi frágil ser,\nY perezco, perezco, Maestro ¡oh, quiéreme socorrer!'),(282,43,'Coro',4,'Los vientos, las ondas oirán tu voz,\n¡Sea la paz! ¡Sea la paz!\nCalma las iras del negro mar,\nLas luchas del alma las haces cesar.\nAsí la barquilla do va el Señor,\nHundirse no puede en el mar traidor;\nDoquier se cumple su voluntad,\n¡Sea la paz! ¡Sea la paz!\nTu voz resuena en la inmensidad,\n¡Sea la paz!'),(283,43,'Estrofa',5,'Maestro, pasó la tormenta, los vientos no rugen ya,\nY sobre el cristal de las aguas, el sol resplandecerá.\nMaestro, prolonga esta calma, no me abandones más;\nCruzaré, los abismos contigo, al puerto de eterna paz.'),(284,43,'Coro',6,'Los vientos, las ondas oirán tu voz,\n¡Sea la paz! ¡Sea la paz!\nCalma las iras del negro mar,\nLas luchas del alma las haces cesar.\nAsí la barquilla do va el Señor,\nHundirse no puede en el mar traidor;\nDoquier se cumple su voluntad,\n¡Sea la paz! ¡Sea la paz!\nTu voz resuena en la inmensidad,\n¡Sea la paz!'),(285,44,'Estrofa',1,'Yo quisiera hablarte del amor de Cristo,\nPues en Él hallé un Amigo fuerte y fiel;\nPor su gracia transformó mi vida entera,\nLo que en esta vida soy lo debo a Él.'),(286,44,'Coro',2,'Nadie pudo amarme como Cristo,\nEs incomparable su amistad;\nSolo Él pudo redimirme del pecado,\nPor su amor y su bondad.'),(287,44,'Estrofa',3,'Mi alma estaba llena de ayes y tristezas,\nLlena estaba de miserias y dolor;\nCon ternura Cristo me tendió la mano,\nY me guió por el sendero del amor.'),(288,44,'Coro',4,'Nadie pudo amarme como Cristo,\nEs incomparable su amistad;\nSolo Él pudo redimirme del pecado,\nPor su amor y su bondad.'),(289,44,'Estrofa',5,'Cada día viene a darme nuevo aliento,\nA mi corazón infunde dulce paz;\nNo comprenderé por que, vino a salvarme,\nHasta que en el Reino pueda ver su faz.'),(290,44,'Coro',6,'Nadie pudo amarme como Cristo,\nEs incomparable su amistad;\nSolo Él pudo redimirme del pecado,\nPor su amor y su bondad.'),(291,45,'Estrofa',1,'Salid de Egipto ya,\nManda el Señor Jehová,\nAl pueblo de Israel,\nQue subyugado está.'),(292,45,'Coro',2,'¡Ven oh Señor, libertador!\nLibra a tu pueblo de Faraón;\nTú nos guiarás y llevarás,\nA esa tierra bendita, Sión.'),(293,45,'Estrofa',3,'Mira la aflicción,\nDe tu pueblo Israel;\nTú eres compasión,\nTendrás piedad de él.'),(294,45,'Coro',4,'¡Ven oh Señor, libertador!\nLibra a tu pueblo de Faraón;\nTú nos guiarás y llevarás,\nA esa tierra bendita, Sión.'),(295,45,'Estrofa',5,'Me voy de Egipto ya,\nNo quiero en ti vivir;\nEl castigo de Dios,\nYa viene sobre ti.'),(296,45,'Coro',6,'¡Ven oh Señor, libertador!\nLibra a tu pueblo de Faraón;\nTú nos guiarás y llevarás,\nA esa tierra bendita, Sión.'),(297,45,'Estrofa',7,'No temas, Israel,\nQue el viento sopla ya,\nPara partir la mar,\nY tú puedas pasar.'),(298,45,'Coro',8,'¡Ven oh Señor, libertador!\nLibra a tu pueblo de Faraón;\nTú nos guiarás y llevarás,\nA esa tierra bendita, Sión.'),(299,45,'Estrofa',9,'Cuando allí estés,\nNo habrá ya más dolor;\nDescansarán tus pies,\nDespués de la labor.'),(300,45,'Coro',10,'¡Ven oh Señor, libertador!\nLibra a tu pueblo de Faraón;\nTú nos guiarás y llevarás,\nA esa tierra bendita, Sión.'),(301,46,'Estrofa',1,'Somos un cuerpo en Cristo, con diferente don;\nDiáconos y Ministros, y la congregación.\nY si de acuerdo vamos, crece la caridad,\nSolos no nos quedamos, Jehová nos ayudará.'),(302,46,'Coro',2,'Todos en uno, amados, Todos en comunión,\nSiendo regocijados, por esta salvación.'),(303,46,'Estrofa',3,'Aunque este cuerpo tiene miembros en distinción;\nEmpero, todos juntos, con diferente acción.\nUno se ayuda al otro, para poder obrar;\nPara que uno al otro, se pueda evangelizar.'),(304,46,'Coro',4,'Todos en uno, amados, Todos en comunión,\nSiendo regocijados, por esta salvación.'),(305,46,'Estrofa',5,'Este cuerpo en Cristo, tiene alimentación;\nEl es el Gran Pontífice de la congregación.\nEl es el Gran Arquitecto, que vida al hombre da;\nCon su palabra salvos, por toda la eternidad.'),(306,46,'Coro',6,'Todos en uno, amados, Todos en comunión,\nSiendo regocijados, por esta salvación.'),(307,46,'Estrofa',7,'Cristo es la cabeza, Él es el buen Pastor;\nDe Él vino la promesa Cristo, el Redentor.\nDe toda esta Iglesia, que sirve con verdad,\nQue ha amado su palabra; hoy goza de libertad.'),(308,46,'Coro',8,'Todos en uno, amados, Todos en comunión,\nSiendo regocijados, por esta salvación.'),(309,46,'Estrofa',9,'Somos un solo cuerpo, en el Señor Jesús;\nConforme al mundo, muertos, viviendo en su luz.\nSomos participantes, de la resurrección:\nEntraremos triunfantes cantando a Cristo en Sión.'),(310,46,'Coro',10,'Todos en uno, amados, Todos en comunión,\nSiendo regocijados, por esta salvación.'),(311,47,'Estrofa',1,'Pies divinos, pies divinos, pies divinos,\nPies divinos, pies divinos, de Jesús;\nQue en la cumbre del Calvario\nLos clavaron en la cruz,\nQue en la cumbre del Calvario\nlos clavaron en la cruz.'),(312,47,'Estrofa',2,'Pies divinos, pies divinos, pies divinos,\nPies divinos, pies divinos, del Señor,\nQue anduvieron por Judea derramando paz y amor.\nQue anduvieron por Judea derramando paz y amor.'),(313,47,'Estrofa',3,'Vedles fríos y desnudos por los campos,\nCaminando, caminando sin cesar;\nPor las cumbres, por los valles,\nPor la orilla de la mar;\nPor las cumbres, por los valles,\nPor la orilla de la mar.'),(314,47,'Estrofa',4,'Van llevando por Judea la semilla,\nDel bendito Evangelio del amor;\nY calmando del enfermo las tristezas y el dolor,\nY calmando del enfermo las tristezas y el dolor.'),(315,47,'Estrofa',5,'¡Cuán hermosos y cuán santos, cuán benditos,\nDe Jesús, el Nazareno, son los pies!\nOh, yo quiero que a la tierra venga pronto otra vez!\nOh, yo quiero que a la tierra venga pronto otra vez!'),(316,48,'Estrofa',1,'¡Loor a Ti, Señor, loor a Ti!\nLo grande de tu amor es para mí;\nMe diste un Salvador, Cristo Jesús,\n¡Loor a Ti, Señor, loor a Ti!'),(317,48,'Estrofa',2,'¡Gloria a mi Salvador, Cristo Jesús!\nEl es el Pan de Vida para mí;\nSu vida dio por mí, allá en la cruz,\n¡Loor a Ti, Señor; loor a Ti!'),(318,48,'Estrofa',3,'Hazme vivir, Señor, cerca de Ti,\nLa deuda de tu amor la siento en mí;\nTe entrego a ti mi ser, mi corazón,\n¡Loor a Ti, Señor, loor a Ti!'),(319,48,'Estrofa',4,'Quiero ser limpio, hoy de mi maldad,\nAcudo a Ti, Jesús, tal como soy;\nVenid, me dices Tú, con tierno amor,\n¡Loor a Ti, Señor; loor a Ti!'),(320,49,'Estrofa',1,'A tu puerta Cristo está. ¡Ábrele!\nSi le abres entrará. ¡Ábrele!\nTu pecado quitará,\nLuz y paz derramará;\nDía glorioso te será. ¡Ábrele!'),(321,49,'Estrofa',2,'¡Ábrele, oh pecador! ¡Ábrele!\nAl amante Salvador. ¡Ábrele!\nHoy te ofrece salvación,\nDel pecado y del perdón;\nSaciará tu corazón.\n¡Ábrele!'),(322,49,'Estrofa',3,'No le hagas esperar. ¡Ábrele!\nNo le obligues a marchar. ¡Ábrele!\n¡Que dolor después tendrás,\nCuando en vano clamarás\nY perdido te hallarás! ¡Ábrele!'),(323,50,'Estrofa',1,'Oh, Cristo mío! Eres Tú mi amigo fiel;\nSeguro amparo, sólo en Ti tendré.\nEn mis aflicciones, buen Jesús, iré a Ti;\nY consuelo y dicha, me darás allí.'),(324,50,'Coro',2,'Cristo, ven más cerca,\nDame gozo, paz y perdón;\nCerca, si, más cerca,\nDe mi corazón.'),(325,50,'Estrofa',3,'Cuando en la noche, vea yo estrellas mil;\nTu voz divina, pueda mi alma oír.\nHaz que yo medite, en tu tierno y dulce amor,\nY que así te alabe, lleno de fervor.'),(326,50,'Coro',4,'Cristo, ven más cerca,\nDame gozo, paz y perdón;\nCerca, si, más cerca,\nDe mi corazón.'),(327,50,'Estrofa',5,'Cuando esta vida, tenga yo que abandonar;\nCorona hermosa, tu me ceñirás,\nY con dulce canto, tu bondad alabaré,\nY al venir tu Reino, me transformaré.'),(328,50,'Coro',6,'Cristo, ven más cerca,\nDame gozo, paz y perdón;\nCerca, si, más cerca,\nDe mi corazón.'),(329,51,'Estrofa',1,'¡Oh, jóvenes, venid! Su brillante pabellón,\nCristo ha desplegado ante la nación;\nA todos en sus filas os quiere recibir,\nY con Él a la pelea os hará salir.'),(330,51,'Coro',2,'¡Vamos a Jesús, alistados sin temor!\n¡Vamos a la lid inflamados de valor!\n¡Jóvenes, luchemos todos contra el mal,\nen Jesús llevamos nuestro General!'),(331,51,'Estrofa',3,'¡Oh jóvenes, venid, el Caudillo Salvador,\nQuiere recibiros en su derredor;\nCon Él a la batalla, salid sin vacilar,\nVamos pronto compañeros, vamos a luchar!'),(332,51,'Coro',4,'¡Vamos a Jesús, alistados sin temor!\n¡Vamos a la lid inflamados de valor!\n¡Jóvenes, luchemos todos contra el mal,\nen Jesús llevamos nuestro General!'),(333,51,'Estrofa',5,'Las armas invencibles, del jefe guiador,\nSon el Evangelio y su grande amor;\nCon ellas revestidos y llenos de valor,\nCompañeros acudamos, vamos a vencer.'),(334,51,'Coro',6,'¡Vamos a Jesús, alistados sin temor!\n¡Vamos a la lid inflamados de valor!\n¡Jóvenes, luchemos todos contra el mal,\nen Jesús llevamos nuestro General!'),(335,51,'Estrofa',7,'Los fieros enemigos, engendros de Satán,\nSe hallan sostenidos por su capitán;\n¡Oh, jóvenes vosotros, poneos sin temor,\nA la diestra del Caudillo, nuestro Salvador!'),(336,51,'Coro',8,'¡Vamos a Jesús, alistados sin temor!\n¡Vamos a la lid inflamados de valor!\n¡Jóvenes, luchemos todos contra el mal,\nen Jesús llevamos nuestro General!'),(337,51,'Estrofa',9,'Quien venga a la pelea, su voz escuchará,\nCristo la victoria nos concederá;\nSalgamos compañeros, luchemos bien por Él,\nCon Jesús conquistaremos inmortal laurel.'),(338,51,'Coro',10,'¡Vamos a Jesús, alistados sin temor!\n¡Vamos a la lid inflamados de valor!\n¡Jóvenes, luchemos todos contra el mal,\nen Jesús llevamos nuestro General!'),(339,52,'Estrofa',1,'Sal a sembrar, sembrador de paz,\nSigue las huellas del buen Jesús;\nMuy ricos frutos tendrás si fiel,\nSigues la senda de paz y luz.'),(340,52,'Coro',2,'Ve, ve, ve, sembrador\nVe, ve, siembra la paz;\nHabla doquiera del Señor,\nY de su santa paz.'),(341,52,'Estrofa',3,'Vasto es el campo, sal a sembrar,\nSiembra el terreno que Dios te da;\nSi siembras siempre confiando en Dios,\nEl tus esfuerzos coronará.'),(342,52,'Coro',4,'Ve, ve, ve, sembrador\nVe, ve, siembra la paz;\nHabla doquiera del Señor,\nY de su santa paz.'),(343,52,'Estrofa',5,'No desperdicies el tiempo, ve,\nSiembra palabras de vida y paz;\nSemilla eterna que dé su mies,\nRica semilla que no es fugaz.'),(344,52,'Coro',6,'Ve, ve, ve, sembrador\nVe, ve, siembra la paz;\nHabla doquiera del Señor,\nY de su santa paz.'),(345,52,'Estrofa',7,'Dios lo ha mandado, sal a decir,\nNuevas de vida, de amor, de paz;\nTal vez te cueste dolores mil,\nMas en el Reino tendrás solaz.'),(346,52,'Coro',8,'Voy, voy, voy, Salvador,\nVoy, voy, siembro la paz;\nHablando siempre del Señor,\nY de su santa paz.'),(347,53,'Estrofa',1,'Yo escucho, buen Jesús,\nTu dulce voz de amor,\nQue desde el árbol de la cruz,\nInvita al pecador.\nYo soy pecador,\nNada hay bueno en mí;\nSer objeto de tu amor,\nDeseo y vengo a Ti.'),(348,53,'Estrofa',2,'Tú ofreces el perdón,\nDe toda iniquidad;\nSi el llanto inunda el corazón,\nQue acude a tu piedad.\nYo soy pecador,\nTen de mí piedad;\nDame llanto de dolor,\nY borra mi maldad.'),(349,53,'Estrofa',3,'Tú ofreces aumentar,\nLa fe del que creyó;\nY gracia sobre gracia dar,\nA quien en Ti esperó.\nCreo en Ti, Señor,\nSólo espero en Ti,\nDame tu infinito amor,\nPues basta para mí.'),(350,54,'Estrofa',1,'Rostro divino ensangrentado,\nCuerpo llagado por nuestro bien;\nCalma benigno justos enojos,\nLloren los ojos que así te ven.'),(351,54,'Estrofa',2,'Manos preciosas, tan lastimadas,\nPor mí clavadas en una cruz;\nEn este valle sean mi guía,\nY mi alegría. mi norte y luz.'),(352,54,'Estrofa',3,'Bello costado, en cuya herida,\nHalla su vida la humanidad;\nFuente amorosa de un Dios clemente,\nVoz elocuente de caridad.'),(353,54,'Estrofa',4,'Tus pies heridos, Cristo paciente,\nYo indiferente los taladré;\nY arrepentido, hoy que te adoro,\nTu gracia imploro, Señor, pequé.'),(354,54,'Estrofa',5,'Crucificado en un madero,\nManso cordero, mueres por mí;\nPor eso el alma triste y llorosa,\nSuspira ansiosa, Señor, por Ti.'),(355,55,'Estrofa',1,'Allá la puerta franca está,\nSu luz es refulgente;\nLa cruz se mira más allá,\nSeñal de amor ferviente.'),(356,55,'Coro',2,'¡Oh, cuánto me ama Dios a mí!\nLa puerta franca está por mí;\nPor mí, por mí,\nSi quiero entrar así.'),(357,55,'Estrofa',3,'Si tienes fe, avanza tú,\nLa puerta es franca ahora;\nSi quieres calma, ten la cruz,\nSeñal de eterna gloria.'),(358,55,'Coro',4,'¡Oh, cuánto me ama Dios a mí!\nLa puerta franca está por mí;\nPor mí, por mí,\nSi quiero entrar así.'),(359,55,'Estrofa',5,'Pasando presto el Jordán,\nLa patria redentora;\nSe mira sin dolor ni afán,\nCiudad de Dios, de gloria.'),(360,55,'Coro',6,'¡Oh, cuánto me ama Dios a mí!\nLa puerta franca está por mí;\nPor mí, por mí,\nSi quiero entrar así.'),(361,56,'Estrofa',1,'¡Oh, cuán dulce es fiar en Cristo!\nY entregarle todo a Él;\nEsperar en sus promesas,\nY en sus sendas serle fiel.'),(362,56,'Coro',2,'Jesucristo, Jesucristo,\nYa tu amor probaste en mí;\nJesucristo, Jesucristo,\nSiempre quiero fiar en Ti.'),(363,56,'Estrofa',3,'Es muy dulce fiar en Cristo,\nY cumplir su voluntad;\nNo dudando en su palabra,\nQue es la luz y la verdad.'),(364,56,'Coro',4,'Jesucristo, Jesucristo,\nYa tu amor probaste en mí;\nJesucristo, Jesucristo,\nSiempre quiero fiar en Ti.'),(365,56,'Estrofa',5,'Siempre es grato fiar en Cristo,\nCuando busca el corazón;\nLos tesoros infinitos,\nDe la paz y del perdón.'),(366,56,'Coro',6,'Jesucristo, Jesucristo,\nYa tu amor probaste en mí;\nJesucristo, Jesucristo,\nSiempre quiero fiar en Ti.'),(367,56,'Estrofa',7,'Siempre en Ti confiar yo quiero,\nMi precioso Salvador;\nEn la vida y en la muerte,\nProtección me dé tu amor.'),(368,56,'Coro',8,'Jesucristo, Jesucristo,\nYa tu amor probaste en mí;\nJesucristo, Jesucristo,\nSiempre quiero fiar en Ti.'),(369,57,'Estrofa',1,'De pesar estás rodeado,\n¿Tienes pruebas en verdad?\nDe sufrir estás cansado,\n¿Ves que viene tempestad?'),(370,57,'Coro',2,'Sigue orando, sigue orando,\nAunque ruja la tempestad;\nEl Señor está velando,\nTe dará tranquilidad.'),(371,57,'Estrofa',3,'En las penas, en el duelo,\nQue tu alma sufrirá;\nEn Jesús tendrás consuelo,\n¡El tus penas calmará !'),(372,57,'Coro',4,'Sigue orando, sigue orando,\nAunque ruja la tempestad;\nEl Señor está velando,\nTe dará tranquilidad.'),(373,57,'Estrofa',5,'Al Señor tu voz eleva,\nVe a Dios con gran fervor;\nEl de penas te releva,\n¡Y mitiga tu dolor!'),(374,57,'Coro',6,'Sigue orando, sigue orando,\nAunque ruja la tempestad;\nEl Señor está velando,\nTe dará tranquilidad.'),(375,57,'Estrofa',7,'¿Tarda Dios en contestarte?\nSigue orando sin cesar;\nPronto ayuda puede darte,\nTu oración al contestar.'),(376,57,'Coro',8,'Sigue orando, sigue orando,\nAunque ruja la tempestad;\nEl Señor está velando,\nTe dará tranquilidad.'),(377,58,'Estrofa',1,'Piensa bien lo que hoy vas a hacer,\nSi tu vida anhelas salvar;\nPues desde hoy tendrás que ser,\nSólo siervo del Señor,\nY soldado de mucho valor.'),(378,58,'Coro',2,'Si, bautízate, es lo mejor,\nQue en la vida tú puedes hacer;\nPero fiel tendrás que ser,\nEn las filas de Israel.\nQue es el único pueblo de Dios.'),(379,58,'Estrofa',3,'Piensa bien lo que hoy vas a hacer,\nQue el bautismo no es para jugar;\nSi eres fiel premio tendrás,\nCuando venga el Salvador,\nAllá en Sión tú con Él estarás.'),(380,58,'Coro',4,'Si, bautízate, es lo mejor,\nQue en la vida tú puedes hacer;\nPero fiel tendrás que ser,\nEn las filas de Israel.\nQue es el único pueblo de Dios.'),(381,58,'Estrofa',5,'Piensa bien lo que hoy vas a hacer,\nQue harás pacto con el Señor;\nTe tendrás que despedir,\nDe este mundo de maldad,\nY a Dios entregarte a servir.'),(382,58,'Coro',6,'Si, bautízate, es lo mejor,\nQue en la vida tú puedes hacer;\nPero fiel tendrás que ser,\nEn las filas de Israel.\nQue es el único pueblo de Dios.'),(383,58,'Estrofa',7,'Piensa bien lo que hoy vas a hacer,\nSi te apartas tendrás que llorar;\nLlora, si, haciendo bien,\nSufre como Él sufrió,\nPues ejemplo Cristo nos dejó.'),(384,58,'Coro',8,'Si, bautízate, es lo mejor,\nQue en la vida tú puedes hacer;\nPero fiel tendrás que ser,\nEn las filas de Israel.\nQue es el único pueblo de Dios.'),(385,59,'Estrofa',1,'Buen Salvador, a Ti yo acudo,\nLlegando aquí tal como soy;\nMi rebelión y mal depongo,\n¡Y ante tus pies postrado estoy!'),(386,59,'Coro',2,'Toma mi vida, oh buen Jesús,\nQue deposito sobre tu altar;\nTú el alfarero eres, Señor,\nYo vil arcilla que habrás de usar.'),(387,59,'Estrofa',3,'Tu bendición ansioso imploro,\nCansado estoy de batallar;\nMi voluntad completa rindo,\nEn Ti yo quiero descansar.'),(388,59,'Coro',4,'Toma mi vida, oh buen Jesús,\nQue deposito sobre tu altar;\nTú el alfarero eres, Señor,\nYo vil arcilla que habrás de usar.'),(389,59,'Estrofa',5,'Venciste, al fin, oh Galileo,\nRendiste tú mi corazón;\nDuda y temor de él arrancaste,\nEres mi Rey, mi Salvador.'),(390,59,'Coro',6,'Toma mi vida, oh buen Jesús,\nQue deposito sobre tu altar;\nTú el alfarero eres, Señor,\nYo vil arcilla que habrás de usar.'),(391,60,'Estrofa',1,'Sobre el tumultuoso ruido mundanal,\nSe oye el llamamiento de Cristo a \\\"trabajar\\\"\nDe Cristo oíd la voz.'),(392,60,'Coro',2,'La voz de Cristo os ordena: \\\"Las nuevas llevad\\\",\nCon el glorioso Evangelio al mundo alumbrad;\nEntre nosotros, doquier estemos,\nserá nuestro Rey;\nMarchemos, pues, resueltos con valor y fe.'),(393,60,'Estrofa',3,'De lejanas tierras nos llaman sin cesar,\nAlmas oprimidas su yugo a destrozar;\nDe Cristo oíd la voz.'),(394,60,'Coro',4,'La voz de Cristo os ordena: \\\"Las nuevas llevad\\\",\nCon el glorioso Evangelio al mundo alumbrad;\nEntre nosotros, doquier estemos,\nserá nuestro Rey;\nMarchemos, pues, resueltos con valor y fe.'),(395,60,'Estrofa',5,'Es la mies muy grande, obreros faltan ya\n¿Quién al llamamiento de Cristo acudirá?\nDe Cristo oíd la voz.'),(396,60,'Coro',6,'La voz de Cristo os ordena: \\\"Las nuevas llevad\\\",\nCon el glorioso Evangelio al mundo alumbrad;\nEntre nosotros, doquier estemos,\nserá nuestro Rey;\nMarchemos, pues, resueltos con valor y fe.'),(397,60,'Estrofa',7,'\\\"Id por todo el mundo\\\", la orden Cristo da,\nId y el Evangelio a todos anunciad;\nDe Cristo oíd la voz.'),(398,60,'Coro',8,'La voz de Cristo os ordena: \\\"Las nuevas llevad\\\",\nCon el glorioso Evangelio al mundo alumbrad;\nEntre nosotros, doquier estemos,\nserá nuestro Rey;\nMarchemos, pues, resueltos con valor y fe.'),(399,61,'Estrofa',1,'Padre, tu Palabra es\nMi delicia y mi solaz;\nGuíe siempre aquí mis pies,\nY a mi pecho traiga paz.'),(400,61,'Coro',2,'Es tu Ley, Señor,\nFaro Celestial,\nQue en perenne resplandor,\nNorte y guía da al mortal.'),(401,61,'Estrofa',3,'Si obediente oí tu voz,\nEn tu gracia fuerza hallé;\nY con firme pie y veloz,\nPor sus sendas caminé.'),(402,61,'Coro',4,'Es tu Ley, Señor,\nFaro Celestial,\nQue en perenne resplandor,\nNorte y guía da al mortal.'),(403,61,'Estrofa',5,'Tu verdad es mi sostén,\nContra duda y tentación;\nY destila calma y bien,\nCuando asalta la aflicción.'),(404,61,'Coro',6,'Es tu Ley, Señor,\nFaro Celestial,\nQue en perenne resplandor,\nNorte y guía da al mortal.'),(405,61,'Estrofa',7,'Son tus dichos para mí,\nPrendas fieles de salud;\nDame pues que te oiga a Ti,\nCon filial solicitud,'),(406,61,'Coro',8,'Es tu Ley, Señor,\nFaro Celestial,\nQue en perenne resplandor,\nNorte y guía da al mortal.'),(407,62,'Estrofa',1,'Miembros todos de la escuela del Señor,\nElevad vuestra conducta y vuestra acción;\nDelirantes de entusiasmo y de fervor,\nCumplid vuestra obligación.'),(408,62,'Coro',2,'Escuela Sabática: Es la escuela del Señor;\nCon anhelo a la escuela sabática,\nCada sábado iré.'),(409,62,'Estrofa',3,'La primera cosa que hay que practicar,\nComo la más bella y grata distracción,\nEs tomar el tiempo para estudiar,\nDiariamente la lección.'),(410,62,'Coro',4,'Escuela Sabática: Es la escuela del Señor;\nCon anhelo a la escuela sabática,\nCada sábado iré.'),(411,62,'Estrofa',5,'Muy temprano, en la mañana del Señor,\nPreparado cada miembro debe estar;\nAsistir puntual al sabio preceptor,\nQue una clase ha de enseñar.'),(412,62,'Coro',6,'Escuela Sabática: Es la escuela del Señor;\nCon anhelo a la escuela sabática,\nCada sábado iré.'),(413,62,'Estrofa',7,'Como parte de grata cooperación,\nCada quien se debe siempre deleitar;\nEn llevar a otros una invitación,\nQue quizá le ha de salvar.'),(414,62,'Coro',8,'Escuela Sabática: Es la escuela del Señor;\nCon anhelo a la escuela sabática,\nCada sábado iré.'),(415,62,'Estrofa',9,'Si tú en verdad quieres con Dios andar,\nAtiende su buen consejo que hoy te da;\nPensamientos tú debes perfeccionar,\nEn la escuela de Jehová.'),(416,62,'Coro',10,'Escuela Sabática: Es la escuela del Señor;\nCon anhelo a la escuela sabática,\nCada sábado iré.'),(417,63,'Estrofa',1,'Brille o no el sol, verano o invierno sea,\nRecorre la montaña, el soto, el llano;\nCual Cristo la palabra en Galilea,\nSembrar es tu misión, si eres cristiano.'),(418,63,'Estrofa',2,'Siembra doquiera la verdad divina,\nSiémbrala con afanes, con dolores;\nQue al soplo del Espíritu germina,\nPlanta que al cielo da frutos y flores.'),(419,63,'Estrofa',3,'Quizás alguna vez tu planta herida,\nSientas por las espinas del sendero;\n¿No ves con ellas de Jesús ceñida,\nLa frente augusta en el fatal madero?'),(420,63,'Estrofa',4,'Siembra, no temas, en la peña dura,\nDeja en la roca estéril caer el grano;\nQue suele hallar la gracia una hendidura\nEn el granito del orgullo humano.'),(421,63,'Estrofa',5,'En las arenas siembra, en el desierto,\nDonde el rocío suave no descienda;\nTú animarás el corazón ya muerto,\nCon esa vida que tu amor encienda.'),(422,63,'Estrofa',6,'En la región de dudas y de penas,\nDonde del sol jamás llegó la llama;\nEsparce la semilla a manos llenas,\nY fe y virtud y caridad derrama.'),(423,63,'Estrofa',7,'Siembra, que no te arredre el egoísmo,\nSiembra, do la impiedad blasfemias lanza,\nEn el camino, el fango, en el abismo,\nHarás brotar la flor de la esperanza.'),(424,63,'Estrofa',8,'No importa, no, que el labrador sucumba,\nAntes que la simiente rompa el suelo;\nQue al despertar del sueño de la tumba,\nSu mies guardada ha de ser su anhelo.'),(425,64,'Estrofa',1,'Salid valientes batallones de Israel,\nCantad el triunfo y la victoria por la fe;\n¡Oh, juventud que tu simiente está en Jesús,\nEterna piedra de los siglos firme es!\nA grandes voces pregonemos con fervor;\nEl Evangelio de justicia y santo amor;\nQue este mensaje por el mundo has de llevar,\nLas almas gimen por el yugo de Satán.'),(426,64,'Coro',2,'Las huestes del Señor salen triunfantes,\nA luchar contra Satán;\nPues valientes se apresuran los soldados,\nSus espadas a empuñar.\nY aunque sangre de los mártires nos cueste,\nPues regada ha sido ya,\nEn los campos por do quiera ya anunciado,\nSiempre el Evangelio quedará.'),(427,64,'Estrofa',3,'Legión Celeste de los Ángeles de Luz,\nSerán ayuda a los soldados de Jesús;\nY en la lucha magna, gloria de Jehová,\nIrá hasta el frente resguardando sin cesar.\nY manifiesta luz del alba se verá,\nDe retaguardia irá la gloria de Jehová;\nCuando invocares a Jesús presto será,\nA responderte Jesús irá.'),(428,64,'Coro',4,'Las huestes del Señor salen triunfantes,\nA luchar contra Satán;\nPues valientes se apresuran los soldados,\nSus espadas a empuñar.\nY aunque sangre de los mártires nos cueste,\nPues regada ha sido ya,\nEn los campos por do quiera ya anunciado,\nSiempre el Evangelio quedará.'),(429,64,'Estrofa',5,'Marchad valientes a luchar contra Satán,\nOh, juventud sin vacilar avanza ya;\nLa voz guerrera que resuene por doquier,\nQue pelees por Jesús es tu deber.\nSe imitador de aquellos hombres del ayer,\nY el enemigo humillado quedará,\nComo Josué, por la gracia y por la fe,\nA su mandato el Sol obedeció.'),(430,64,'Coro',6,'Las huestes del Señor salen triunfantes,\nA luchar contra Satán;\nPues valientes se apresuran los soldados,\nSus espadas a empuñar.\nY aunque sangre de los mártires nos cueste,\nPues regada ha sido ya,\nEn los campos por do quiera ya anunciado,\nSiempre el Evangelio quedará.'),(431,65,'Estrofa',1,'En oscuridad, sin Jesús me vi,\nCon mil penas y gran dolor;\nMas Jesús llamó: \\\"Ven, si, ven a mí,\nQuiero ser tu Salvador\\\".'),(432,65,'Coro',2,'En mi alma hay dulce paz,\nDesde que vine a Jesús;\nNo hay noche nunca, sino paz y gozo,\nDesde que vivo en la luz.'),(433,65,'Estrofa',3,'Por las grandes olas de la maldad,\nYo llevado fui más y más;\nSin tener piloto en la tempestad,\nHasta ver al buen Jesús.'),(434,65,'Coro',4,'En mi alma hay dulce paz,\nDesde que vine a Jesús;\nNo hay noche nunca, sino paz y gozo,\nDesde que vivo en la luz.'),(435,65,'Estrofa',5,'¿En la ruda lid combatiendo estás,\nSin amigo y sin solaz?\n¡Oh, no llores más! Si no ve la faz,\nDe tu amigo, el buen Jesús.'),(436,65,'Coro',6,'En mi alma hay dulce paz,\nDesde que vine a Jesús;\nNo hay noche nunca, sino paz y gozo,\nDesde que vivo en la luz.'),(437,66,'Estrofa',1,'Del culto el tiempo llega,\nComienza la oración;\nEl alma a Dios se entrega,\n¡Silencio y atención!\nSi al Santo Dios la mente,\nQueremos elevar;\nSilencio reverente,\nHabremos de guardar.'),(438,66,'Estrofa',2,'Mil coros celestiales,\nA Dios cantando están;\nA ellos los mortales,\nSus voces unirán.\nAlcemos pues el alma,\nEn santa devoción;\nGozando en dulce calma,\nDe Dios la comunión.'),(439,66,'Estrofa',3,'La Biblia bendecida,\nDe Dios revelación;\nA meditar convida,\nEn nuestra condición.\n¡Silencio que ha llegado,\nDel culto la ocasión;\nDios se halla a nuestro lado,\nSilencio y devoción!'),(440,67,'Estrofa',1,'Señor, reposamos en tu santo día,\nCumpliendo el mandato legado por Ti;\nReposo buscamos, Dios nuestro, en tu seno,\nQue así ordenaste en el Sinaí,\nQue así ordenaste en el Sinaí.'),(441,67,'Estrofa',2,'Tus hijos se acercan, oh Dios, a tu trono,\nEn santa, ferviente y sincera oración;\nPidiéndote escuches su humilde plegaria,\nY gocen por siempre de tu protección,\nY gocen por siempre de tu protección.'),(442,67,'Estrofa',3,'Alienta a tus hijos, que tengan victoria,\nQue puedan fielmente, tus Leyes cumplir;\nQue cuando Tú vengas, Señor, en tu gloria,\nPodamos por siempre contigo vivir,\nPodamos por siempre contigo vivir.'),(443,68,'Estrofa',1,'Roca de la eternidad,\nFuiste abierta para mí;\nSe mi escondedero fiel,\nSolo encuentro paz en Ti,\nRico, limpio manantial,\nEn el cual lavado fui.'),(444,68,'Estrofa',2,'Aunque fuese siempre fiel,\nY llorase sin cesar;\nDel pecado no podré,\nJustificación lograr;\nSolo en Ti teniendo fe,\nDeuda tal podré pagar.'),(445,68,'Estrofa',3,'Mientras deba aquí vivir,\nMi postrer suspiro al dar;\nCuando vaya a responder,\nAnte tu alto tribunal,\nSe mi escondedero fiel,\nRoca de la Eternidad.'),(446,69,'Estrofa',1,'Embajadores de Jesucristo,\nMarchad al frente, Jesús os ve;\nCon la armadura del Dios Eterno,\nCon el escudo de vuestra fe.\nEmbajadores de Jesucristo,\nTomad el yelmo de la salud;\nY del Espíritu alzad la espada,\nBlandid las armas con prontitud.'),(447,69,'Estrofa',2,'Embajadores de Jesucristo,\nLuchad valientes contra Satán;\nCeñid los lomos, usad la cota\nDe la justicia, porque vendrán\nDardos de fuego para destruiros,\nPara obligaros a desmayar,\nPero si fuereis siempre valientes,\nVuestras victorias podréis cantar.'),(448,69,'Estrofa',3,'¡A la victoria fieles soldados,\nEmbajadores de Cristo el Rey;\nLlevad las nuevas a los perdidos,\nDe que no estamos bajo la ley!\nQue ahora estamos bajo la gracia,\nPorque ya Cristo nos redimió;\nYa que en el cuerpo llevó las culpas,\nDe todo aquel que le recibió.'),(449,70,'Estrofa',1,'Sembraré, la simiente preciosa,\nDel glorioso Evangelio de amor;\nSembraré, sembraré, mientras viva,\nDejaré, el resultado al Señor.'),(450,70,'Coro',2,'¡Sembraré, sembraré,\nMientras viva, simiente de amor;\nSegaré, segaré,\nCuando venga a su Reino el Señor!'),(451,70,'Estrofa',3,'Sembraré, en corazones sensibles,\nLa doctrina del Dios de perdón;\nSembraré, sembraré, mientras viva,\nDejaré, el resultado al Señor.'),(452,70,'Coro',4,'¡Sembraré, sembraré,\nMientras viva, simiente de amor;\nSegaré, segaré,\nCuando venga a su Reino el Señor!'),(453,70,'Estrofa',5,'Sembraré, en corazones de mármol,\nLa bendita Palabra de Dios;\nSembraré, sembraré, mientras viva,\nDejaré, el resultado al Señor.'),(454,70,'Coro',6,'¡Sembraré, sembraré,\nMientras viva, simiente de amor;\nSegaré, segaré,\nCuando venga a su Reino el Señor!'),(455,71,'Estrofa',1,'¡Oh, qué, amigo nos es Cristo,\nEl llevó nuestro dolor;\nY nos manda que llevemos,\nTodo a Dios en oración!\n¿Vive el hombre desprovisto,\nDe paz, gozo y santo amor?\nEsto es porque no llevamos,\nTodo a Dios en oración.'),(456,71,'Estrofa',2,'¿Vives débil y cargado,\nDe cuidados y temor?\nA Jehová refugio eterno,\nDile todo en oración;\n¿Te desprecian tus amigos?\nCuéntaselo en oración;\nEn sus brazos de amor tierno,\nPaz tendrá tu corazón.'),(457,71,'Estrofa',3,'Jesucristo es nuestro amigo,\nDe esto prueba Él nos dio;\nAl sufrir el cruel castigo,\nQue el culpable mereció,\nY su pueblo redimido,\nHallará seguridad;\nFiando en este amigo eterno,\nY esperando en su bondad.'),(458,72,'Estrofa',1,'Firmes y adelante, huestes de la fe,\nSin temor alguno, que Jesús nos ve;\nJefe soberano, Cristo al frente va,\nY la regia enseña tremolando está.'),(459,72,'Coro',2,'¡Firmes y adelante, huestes de la fe,\nSin temor alguno, que Jesús nos ve!'),(460,72,'Estrofa',3,'Al sagrado nombre de nuestro adalid,\nTiembla el enemigo y huye de la lid;\nNuestra es la victoria, dad a Dios loor,\nY óigalo el averno lleno de pavor.'),(461,72,'Coro',4,'¡Firmes y adelante, huestes de la fe,\nSin temor alguno, que Jesús nos ve!'),(462,72,'Estrofa',5,'Muévase potente la Iglesia de Dios,\nDe los victoriosos marchemos en pos;\nSomos sólo un cuerpo, y uno es el Señor,\nUna la esperanza, y uno nuestro amor.'),(463,72,'Coro',6,'¡Firmes y adelante, huestes de la fe,\nSin temor alguno, que Jesús nos ve!'),(464,72,'Estrofa',7,'Tronos y coronas pueden perecer,\nDe Jesús la Iglesia fiel habrá de ser;\nNada en contra suya prevalecerá,\nPorque la promesa nunca faltará.'),(465,72,'Coro',8,'¡Firmes y adelante, huestes de la fe,\nSin temor alguno, que Jesús nos ve!'),(466,73,'Estrofa',1,'Cerca de Ti, Señor, quiero morar;\nTu grande y tierno amor, quiero gozar.\nLlena mi pobre ser, limpia mi corazón;\nHazme tu rostro ver, en comunión.'),(467,73,'Estrofa',2,'Pasos inciertos doy, el sol se va;\nMas si contigo estoy, no temo ya.\nHimnos de gratitud, ferviente cantaré;\nY fiel a Ti, Jesús, siempre seré.'),(468,73,'Estrofa',3,'Día feliz veré, creyendo en Ti;\nEn que yo habitaré, cerca de Ti.\nMi voz alabará, tu dulce nombre allí;\nY mi alma gozará, cerca de Ti.'),(469,74,'Estrofa',1,'Dulce comunión la que gozo ya,\nEn los brazos de mi Salvador;\n¡Qué, gran bendición en su paz me da!\n¡Oh, yo siento en mí su tierno amor!'),(470,74,'Coro',2,'Libre, salvo, del pecado y del temor,\nLibre, salvo, en los brazos de mi Salvador.'),(471,74,'Estrofa',3,'¡Cuán dulce es vivir, cuán dulce es gozar!\nEn los brazos de mi Salvador;\nAllí quiero ir y con Él morar,\nSiendo objeto de su tierno amor.'),(472,74,'Coro',4,'Libre, salvo, del pecado y del temor,\nLibre, salvo, en los brazos de mi Salvador.'),(473,74,'Estrofa',5,'No hay que temer, ni que desconfiar,\nEn los brazos de mi Salvador;\nPor su gran poder Él me guardará,\nDe los lazos del engañador.'),(474,74,'Coro',6,'Libre, salvo, del pecado y del temor,\nLibre, salvo, en los brazos de mi Salvador.'),(475,75,'Estrofa',1,'En el seno de mi alma una dulce quietud,\nSe difunde embargando mi ser;\nUna calma infinita que sólo podrán\nLos amados de Dios comprender.'),(476,75,'Coro',2,'¡Paz! ¡Paz! ¡Cuán dulce paz!\nEs aquella que el Padre me da;\nYo le ruego que inunde por siempre mi ser,\nEn sus ondas de amor celestial.'),(477,75,'Estrofa',3,'¡Qué tesoro yo tengo en la paz que me da!\nQue en el fondo del alma ha de estar;\nTan seguro, que nadie quitarlo podrá,\nMientras miro los años pasar.'),(478,75,'Coro',4,'¡Paz! ¡Paz! ¡Cuán dulce paz!\nEs aquella que el Padre me da;\nYo le ruego que inunde por siempre mi ser,\nEn sus ondas de amor celestial.'),(479,75,'Estrofa',5,'Esta paz inefable, consuelo me da,\nDescansando tan sólo en Jesús;\nY ningunos peligros mi vida tendrá,\nSi me siento inundado en su luz.'),(480,75,'Coro',6,'¡Paz! ¡Paz! ¡Cuán dulce paz!\nEs aquella que el Padre me da;\nYo le ruego que inunde por siempre mi ser,\nEn sus ondas de amor celestial.'),(481,75,'Estrofa',7,'Sin cesar yo medito en aquella Ciudad,\nDo el autor de la paz he de ver;\nY en que el himno más dulce que allí he de cantar,\nAl estar con Jesús, ha de ser.'),(482,75,'Coro',8,'¡Paz! ¡Paz! ¡Cuán dulce paz!\nEs aquella que el Padre me da;\nYo le ruego que inunde por siempre mi ser,\nEn sus ondas de amor celestial.'),(483,75,'Estrofa',9,'Alma triste que en rudo conflicto te ves,\nSola y débil tu senda al seguir;\nHaz de Cristo el amigo, que fiel siempre es,\n¡Y su paz tú podrás recibir!'),(484,75,'Coro',10,'¡Paz! ¡Paz! ¡Cuán dulce paz!\nEs aquella que el Padre me da;\nYo le ruego que inunde por siempre mi ser,\nEn sus ondas de amor celestial.'),(485,76,'Estrofa',1,'Cristo es mi dulce Salvador,\nMi bien, mi paz, mi luz;\nMostróme su infinito amor,\nMuriendo en dura cruz.\nCuando estoy triste encuentro en Él,\nConsolador y amigo fiel,\nConsolador, amigo fiel, es Jesús.'),(486,76,'Estrofa',2,'Cristo es mi dulce Salvador,\nSu sangre me compró;\nCon sus heridas y dolor,\nPerfecta paz me dio.\nDicha inmortal allá tendré,\nCon Cristo siempre reinaré,\nDicha inmortal allá tendré, con Jesús.'),(487,76,'Estrofa',3,'Cristo es mi dulce Salvador,\nMi eterno redentor;\n¡Oh, nunca yo podré, pagar,\nLa deuda de su amor!\nLe seguiré, pues, en la luz,\nNo temeré, llevar su cruz,\nNo temeré, llevar la cruz de Jesús.'),(488,76,'Estrofa',4,'Cristo es mi dulce Salvador,\nPor Él ya salvo soy;\nÉl es la Piedra angular,\nEn quien seguro estoy.\nGloria inmortal allá tendré,\nCon Cristo siempre Reinaré,\n¡Gloria inmortal, allá tendré, con Jesús!'),(489,77,'Estrofa',1,'Grande gozo hay en mi alma hoy,\nPues Jesús conmigo está;\nY su paz que ya gozando estoy,\n¡Por siempre durará!'),(490,77,'Coro',2,'Grande gozo, ¡Cuán hermoso!\nPaso todo el tiempo bien feliz;\nPorque veo de Cristo la sonriente faz\n¡Grande gozo siento en mí!'),(491,77,'Estrofa',3,'Hay un canto en mi alma hoy,\nMelodías a mi Rey;\nEn su amor feliz y libre soy,\n¡Y salvo por la fe!'),(492,77,'Coro',4,'Grande gozo, ¡Cuán hermoso!\nPaso todo el tiempo bien feliz;\nPorque veo de Cristo la sonriente faz\n¡Grande gozo siento en mí!'),(493,77,'Estrofa',5,'Paz divina hay en mi alma hoy,\nPorque Cristo me salvó;\nLas cadenas rotas ya están,\nJesús me libertó.'),(494,77,'Coro',6,'Grande gozo, ¡Cuán hermoso!\nPaso todo el tiempo bien feliz;\nPorque veo de Cristo la sonriente faz\n¡Grande gozo siento en mí!'),(495,77,'Estrofa',7,'Gratitud hay en mi alma hoy,\nY alabanzas a Jesús;\nPor su gracia a su Reino voy,\n¡Gozándome en su luz!'),(496,77,'Coro',8,'Grande gozo, ¡Cuán hermoso!\nPaso todo el tiempo bien feliz;\nPorque veo de Cristo la sonriente faz\n¡Grande gozo siento en mí!'),(497,78,'Estrofa',1,'Un hombre de noche llegose a Jesús,\nBuscando la senda de vida y de luz;\nY Cristo le dijo: \\\"Si a Dios quieres ver,\nTendrás que renacer\\\".'),(498,78,'Coro',2,'Tendrás que renacer, tendrás que renacer,\nDe cierto, de cierto te digo a ti:\nTendrás que renacer.'),(499,78,'Estrofa',3,'Si acaso al Reino tú quieres entrar,\nY allí con los santos poder descansar;\nSi quieres la vida eternal obtener,\nTendrás que renacer.'),(500,78,'Coro',4,'Tendrás que renacer, tendrás que renacer,\nDe cierto, de cierto te digo a ti:\nTendrás que renacer.'),(501,78,'Estrofa',5,'Amigo, no debes jamás desechar,\nPalabras que Cristo dignose hablar;\nSi tu alma no quieres llegar a perder,\nTendrás que renacer.'),(502,78,'Coro',6,'Tendrás que renacer, tendrás que renacer,\nDe cierto, de cierto te digo a ti:\nTendrás que renacer.'),(503,78,'Estrofa',7,'Si quieres con Cristo un día Reinar,\nGozar las delicias de su Reino aquí;\nPues esta proclama hoy debes creer,\nTendrás que renacer.'),(504,78,'Coro',8,'Tendrás que renacer, tendrás que renacer,\nDe cierto, de cierto te digo a ti:\nTendrás que renacer.'),(505,79,'Estrofa',1,'Que mi vida entera esté,\nConsagrada a Ti, Señor;\nQue a mis manos pueda guiar,\nEl impulso de tu amor.'),(506,79,'Coro',2,'¡Lávame en tu sangre Salvador!\n¡Límpiame de toda mi maldad!\nTraigo a Ti mi vida, para ser, Señor,\n¡Tuya por la eternidad!'),(507,79,'Estrofa',3,'Que mis pies tan sólo en pos,\nDe lo santo puedan ir;\nY que a Ti, Señor, mi voz,\nSe complazca en bendecir.'),(508,79,'Coro',4,'¡Lávame en tu sangre Salvador!\n¡Límpiame de toda mi maldad!\nTraigo a Ti mi vida, para ser, Señor,\n¡Tuya por la eternidad!'),(509,79,'Estrofa',5,'Que mi tiempo todo esté,\nConsagrado a tu loor;\nQue mis labios al hablar,\nHablen sólo de tu amor.'),(510,79,'Coro',6,'¡Lávame en tu sangre Salvador!\n¡Límpiame de toda mi maldad!\nTraigo a Ti mi vida, para ser, Señor,\n¡Tuya por la eternidad!'),(511,79,'Estrofa',7,'Toma ¡Oh Dios! mi voluntad,\nY hazla tuya nada más;\nToma, sí, mi corazón,\nPor morada lo tendrás.'),(512,79,'Coro',8,'¡Lávame en tu sangre Salvador!\n¡Límpiame de toda mi maldad!\nTraigo a Ti mi vida, para ser, Señor,\n¡Tuya por la eternidad!'),(513,79,'Estrofa',9,'Toma Tú mi amor que hoy,\nA tus pies vengo a poner;\n¡Toma todo lo que soy!\n¡Todo tuyo quiero ser!'),(514,79,'Coro',10,'¡Lávame en tu sangre Salvador!\n¡Límpiame de toda mi maldad!\nTraigo a Ti mi vida, para ser, Señor,\n¡Tuya por la eternidad!'),(515,80,'Estrofa',1,'Santa Biblia para mí,\nEres un tesoro aquí;\nTú contienes con verdad,\nLa divina voluntad;\nTú me dices lo que soy,\nDe quién vine y a quién voy.'),(516,80,'Estrofa',2,'Tú reprendes mi dudar,\nTú me exhortas sin cesar;\nEres faro que a mi pie,\nVa guiando por la fe,\nA las fuentes del amor,\nDel Bendito Salvador.'),(517,80,'Estrofa',3,'Eres infalible voz,\nDel Espíritu de Dios;\nQue vigor al alma da,\nCuando en aflicción está;\nTú me enseñas a triunfar,\nDe la muerte y el pecar.'),(518,80,'Estrofa',4,'Por tu santa letra sé,\nQue con Cristo reinaré;\nYo que tan indigno soy,\nPor tu Luz al Reino voy;\n¡Santa Biblia para mí,\nEres un tesoro aquí'),(519,81,'Estrofa',1,'Hay un precioso manantial, manantial, manantial,\nHay un precioso manantial, de sangre de Emmanuel;\nQue purifica a cada cual, a cada cual, a cada cual,\nQue purifica a cada cual, que se sumerja en él.'),(520,81,'Coro',2,'¡Oh, sí, rica fuente, fuente carmesí!\nRecuerdo que un día yo lavado fui.'),(521,81,'Estrofa',3,'El malhechor se convirtió, se convirtió, se convirtió,\nEl malhechor se convirtió, pendiente de una cruz;\nEl vio la fuente y se lavó, y se lavó, y se lavó,\nEl vio la fuente y se lavó, creyendo en Jesús.'),(522,81,'Coro',4,'¡Oh, sí, rica fuente, fuente carmesí!\nRecuerdo que un día yo lavado fui.'),(523,81,'Estrofa',5,'Y yo también mi pobre ser, mi pobre ser, mi pobre ser,\nY yo también mi pobre ser, allí logré, lavar;\nLa gloria de su gran poder, su gran poder, su gran poder,\nLa gloria de su gran poder, me gozo en ensalzar.'),(524,81,'Coro',6,'¡Oh, sí, rica fuente, fuente carmesí!\nRecuerdo que un día yo lavado fui.'),(525,81,'Estrofa',7,'Eterna fuente carmesí, carmesí, carmesí\nEterna fuente carmesí, raudal de puro amor.\nSe lavará por siempre en Ti,\npor siempre en Ti, por siempre en Ti,\nSe lavará por siempre en Ti, el pueblo del Señor.'),(526,81,'Coro',8,'¡Oh, sí, rica fuente, fuente carmesí!\nRecuerdo que un día yo lavado fui.'),(527,82,'Estrofa',1,'Somos obreros del Señor,\nLa mies segamos con amor;\nLas nuevas damos de la salvación,\nDe Cristo al pecador.\nHoy trabajamos por amor,\nA Cristo nuestro Salvador;\nQue por nosotros vida dio,\nEn el Calvario do murió.'),(528,82,'Coro',2,'A la siega acudid, el Maestro os llama,\nTodos deben trabajar tarde y mañana;\nCorre el tiempo y jamás,\nNunca, hermanos, volverá,\nVamos, todos, hoy a trabajar.'),(529,82,'Estrofa',3,'El evangelio predicad,\nA todo el mundo sin cesar;\nY sin temor y con lealtad,\nHoy su bandera levantad.\nEn nuestras manos Él confió,\nEsta gran comisión de amor;\nLas nuevas dad, no vaciléis,\nQue la victoria obtendréis.'),(530,82,'Coro',4,'A la siega acudid, el Maestro os llama,\nTodos deben trabajar tarde y mañana;\nCorre el tiempo y jamás,\nNunca, hermanos, volverá,\nVamos, todos, hoy a trabajar.'),(531,82,'Estrofa',5,'Horas y días pasarán,\nEl tiempo nunca volverá;\nSi no predicas a Jesús,\nTal vez no habrá oportunidad.\nHoy es el día de salvación,\nEl mundo pereciendo está;\n¡Oh!, no desprecies el honor,\nQue Cristo hoy te da.'),(532,82,'Coro',6,'A la siega acudid, el Maestro os llama,\nTodos deben trabajar tarde y mañana;\nCorre el tiempo y jamás,\nNunca, hermanos, volverá,\nVamos, todos, hoy a trabajar.'),(533,83,'Estrofa',1,'Tan triste y tan lejos de Dios me sentí,\nY sin el perdón de Jesús;\nMas, cuando su voz amorosa oí,\nQue dijo: \\\"Oh, ven a la luz\\\".'),(534,83,'Coro',2,'Ya todo dejé para andar en la luz,\nNo vivo en tinieblas ya más;\nYa todo dejé, por seguir a Jesús,\n¡Y vivo en la luz de su faz!'),(535,83,'Estrofa',3,'De mi alma el anhelo por siempre será,\nMás cerca vivir de Jesús;\nDo santo poder y pureza me da,\n¡La sangre de Cristo Jesús!'),(536,83,'Coro',4,'Ya todo dejé para andar en la luz,\nNo vivo en tinieblas ya más;\nYa todo dejé, por seguir a Jesús,\n¡Y vivo en la luz de su faz!'),(537,83,'Estrofa',5,'¡Qué, amigo tan dulce es el tierno Jesús!\nTan lleno de paz y de amor;\nDe todo este mundo la fúlgida luz,\n¡El nombre del buen Salvador!'),(538,83,'Coro',6,'Ya todo dejé para andar en la luz,\nNo vivo en tinieblas ya más;\nYa todo dejé, por seguir a Jesús,\n¡Y vivo en la luz de su faz!'),(539,83,'Estrofa',7,'¡Oh! Ven a Jesús, infeliz pecador,\nNo vagues a ciegas ya más;\nSí, ven a Jesús nuestro gran Salvador,\n¡Pues en Él salvación hallarás!'),(540,83,'Coro',8,'Ya todo dejé para andar en la luz,\nNo vivo en tinieblas ya más;\nYa todo dejé, por seguir a Jesús,\n¡Y vivo en la luz de su faz!'),(541,84,'Estrofa',1,'¡Oh, amor de Dios! su inmensidad,\nEl hombre no podría contar;\nNi comprender la gran verdad,\nQue Dios al hombre supo amar.\nCuando el pecar entró al hogar,\nDe Adán y Eva en Edén; Dios les sacó,\nMas prometió un Salvador también.'),(542,84,'Coro',2,'¡Oh, amor de Dios! brotando está,\nInmensurable eternal;\nPor las edades durará,\nInagotable raudal.'),(543,84,'Estrofa',3,'Si fuera tinta todo el mar,\nY todo el cielo un gran papel;\nY todo hombre un escritor,\nY cada hoja un pincel,\nPara escribir de su existir,\nNo bastarían jamás;\nEl me lavó y me salvó,\nY me da el Reino además.'),(544,84,'Coro',4,'¡Oh, amor de Dios! brotando está,\nInmensurable eternal;\nPor las edades durará,\nInagotable raudal.'),(545,85,'Estrofa',1,'¡Oh, yo Quiero andar con Cristo!\nQuiero oír su tierna voz;\nMeditar en su palabra,\nSiempre andar de Él en pos.\nConsagrar a Él mi vida,\nCumplir fiel su voluntad;\nY un día con mi Cristo,\nGozaré, la eternidad.'),(546,85,'Coro',2,'¡Oh, sí, yo quiero andar con Cristo!\n¡Oh, sí, yo quiero vivir con Cristo!\n¡Oh, si, yo quiero morir con Cristo!\nQuiero serle un testigo fiel.'),(547,85,'Estrofa',3,'¡Oh, yo quiero andar con Cristo,\nEl vivió en santidad;\nEn la Biblia yo lo leo,\nY yo sé que es la verdad!\nCristo era santo en todo,\nEl cordero de la cruz;\nY yo anhelo ser cristiano,\nSeguidor de mi Jesús.'),(548,85,'Coro',4,'¡Oh, sí, yo quiero andar con Cristo!\n¡Oh, sí, yo quiero vivir con Cristo!\n¡Oh, si, yo quiero morir con Cristo!\nQuiero serle un testigo fiel.'),(549,85,'Estrofa',5,'¡Oh, yo quiero andar, con Cristo!\nEn la senda de la luz,\nDejaré el perverso mundo,\nCargaré aquí su Cruz.\nEste mundo nada ofrece,\nCristo ofrece Salvación;\nY es mi única esperanza,\nGozar vida eterna en Sión'),(550,85,'Coro',6,'¡Oh, sí, yo quiero andar con Cristo!\n¡Oh, sí, yo quiero vivir con Cristo!\n¡Oh, si, yo quiero morir con Cristo!\nQuiero serle un testigo fiel.'),(551,86,'Estrofa',1,'Hallé un buen amigo, mi amado salvador,\nContaré, lo que Él ha hecho para mí;\nHallándome perdido e indigno pecador,\nMe salvó y hoy me guarda para sí.\nMe salva del pecado, me guarda de Satán,\nPromete estar conmigo hasta el fin;\nEl consuela mi tristeza, me quita todo afán.\nGrandes cosas Cristo ha hecho para mí.'),(552,86,'Estrofa',2,'Jesús jamás me falta, jamás me dejará,\nEs mi fuerte y poderoso protector;\nDel mundo me separo, y de la vanidad,\nPara consagrar mi vida al Señor.\nSi el mundo me persigue, si sufro tentación,\nConfiando en Cristo puedo resistir;\nLa victoria me es segura, elevo mi canción,\nGrandes cosas Cristo ha hecho para mí.'),(553,86,'Estrofa',3,'Yo sé que Jesucristo muy pronto volverá,\nEntretanto en su servicio quiero estar;\nConfiando en su palabra haré su voluntad,\nY anhelo serle fiel hasta el llegar.\nAnhelo en su Reino, estar en su fulgor,\nY contemplar su esplendorosa faz;\nY entonces con los santos unido cantaré,\nGrandes cosas Cristo ha hecho para mí.'),(554,87,'Estrofa',1,'Cuando estás cansado y abatido,\nPiensa en Cristo, piensa en Cristo;\nSi te sientes débil, confundido,\nPiensa en Cristo el Señor.'),(555,87,'Coro',2,'Piensa en Cristo, piensa en Cristo,\nEl es tu amigo más fiel;\nNo hay otro amigo como Cristo,\nPiensa tan sólo en Él.'),(556,87,'Estrofa',3,'Cuando estés de tentación cercado,\nMira a Cristo, mira a Cristo;\nCuando rujan huestes de pecado,\nMira a Cristo, el Señor.'),(557,87,'Coro',4,'Mira a Cristo, mira a Cristo,\nEl es tu amigo más fiel;\nNo hay otro amigo como Cristo,\nMira tan sólo en Él.'),(558,87,'Estrofa',5,'Si se apartan otros de la senda,\nSigue a Cristo, sigue a Cristo;\nSi acrecienta en torno la contienda,\nSigue a Cristo, el Señor.'),(559,87,'Coro',6,'Sigue a Cristo, sigue a Cristo,\nEl es tu amigo más fiel;\nNo hay otro amigo como Cristo,\nSigue tan sólo en Él.'),(560,87,'Estrofa',7,'Cuando llegue la final jornada,\nFía en Cristo, fía en Cristo;\nTe dará en el Reino franca entrada,\nFía en Cristo, el Señor.'),(561,87,'Coro',8,'Fía en Cristo, fía en Cristo,\nEl es tu amigo más fiel;\nNo hay otro amigo como Cristo,\nFía tan sólo en Él.'),(562,88,'Estrofa',1,'Dios os guarde en su santo amor,\nHasta el día en que lleguemos,\nA la patria do estaremos,\nPara siempre con el Salvador,'),(563,88,'Coro',2,'Al venir Jesús nos veremos,\nA los pies de nuestro Salvador;\nReunidos todos seremos,\nUn redil con nuestro buen Pastor.'),(564,88,'Estrofa',3,'Dios os guarde en su santo amor,\nDe la senda peligrosa;\nDe esta vida tormentosa,\nY os conserve en paz y sin temor.'),(565,88,'Coro',4,'Al venir Jesús nos veremos,\nA los pies de nuestro Salvador;\nReunidos todos seremos,\nUn redil con nuestro buen Pastor.'),(566,88,'Estrofa',5,'Dios os guarde en su santo amor,\nOs conduzca su bandera;\nY os esfuerce en gran manera,\nCon su Espíritu Consolador.'),(567,88,'Coro',6,'Al venir Jesús nos veremos,\nA los pies de nuestro Salvador;\nReunidos todos seremos,\nUn redil con nuestro buen Pastor.'),(568,88,'Estrofa',7,'Dios os guarde en su santo amor,\nCon su gracia Él os sostenga;\nHasta que el Maestro venga,\nA fundar su Reino en esplendor.'),(569,88,'Coro',8,'Al venir Jesús nos veremos,\nA los pies de nuestro Salvador;\nReunidos todos seremos,\nUn redil con nuestro buen Pastor.'),(570,89,'Estrofa',1,'Doquier el hombre esté, la nueva proclamad,\nDoquier haya aflicción, miserias y dolor;\nCristianos, anunciad que el Padre nos envió,\nAl fiel consolador.'),(571,89,'Coro',2,'El fiel consolador, el fiel consolador\nQue Dios nos prometió, al mundo descendió;\nDoquier el hombre esté, decid que vino ya,\nEl fiel consolador.'),(572,89,'Estrofa',3,'La noche ya pasó, y al fin brilló la luz,\nQue vino a disipar las sombras del terror;\nAsí del alma fue aurora celestial,\nEl fiel Consolador.'),(573,89,'Coro',4,'El fiel consolador, el fiel consolador\nQue Dios nos prometió, al mundo descendió;\nDoquier el hombre esté, decid que vino ya,\nEl fiel consolador.'),(574,89,'Estrofa',5,'Él es quien da la luz y plena libertad,\nA los que encadenó el fiero destructor;\nLos rotos hierros hoy dirán que vino ya,\nEl fiel Consolador.'),(575,89,'Coro',6,'El fiel consolador, el fiel consolador\nQue Dios nos prometió, al mundo descendió;\nDoquier el hombre esté, decid que vino ya,\nEl fiel consolador.'),(576,90,'Estrofa',1,'Puedo oír la voz de Cristo,\nTiernamente está llamando;\nPuedo oír el llamamiento:\n\\\"Trae tu cruz y ven en pos de mí\\\"'),(577,90,'Coro',2,'Seguiré do Tú me guíes,\nSeguiré do Tú me guíes;\nSalvador, seguirte quiero,\nDondequiera fiel te seguiré.'),(578,90,'Estrofa',3,'Seguiré aún con sufrimiento,\nPor la vía dolorosa;\nY con mi alma tan gozosa,\nSufriré contigo, mi Jesús.'),(579,90,'Coro',4,'Seguiré do Tú me guíes,\nSeguiré do Tú me guíes;\nSalvador, seguirte quiero,\nDondequiera fiel te seguiré.'),(580,90,'Estrofa',5,'Sufriré por Ti, Maestro,\nNo me faltará tu mano;\nY si Tú irás conmigo,\nMoriré contigo, mi Jesús.'),(581,90,'Coro',6,'Seguiré do Tú me guíes,\nSeguiré do Tú me guíes;\nSalvador, seguirte quiero,\nDondequiera fiel te seguiré.'),(582,90,'Estrofa',7,'Me darás tu plena gracia,\nYo veré tu eterna gloria;\nContaré la antigua historia,\nY por siempre Tú me guiarás.'),(583,90,'Coro',8,'Seguiré do Tú me guíes,\nSeguiré do Tú me guíes;\nSalvador, seguirte quiero,\nDondequiera fiel te seguiré.'),(584,91,'Estrofa',1,'Solo o a Ti, Dios y Señor,\nAdoramos, adoramos;\nY la gloria y el honor,\nTributamos, tributamos.\nSólo a Cristo, nuestra luz,\nAcudimos, acudimos;\nPor su muerte en la cruz,\nRevivimos, revivimos.'),(585,91,'Estrofa',2,'Un Espíritu, no más,\nNos gobierna, nos gobierna;\nY con Él, Señor, nos das,\nPaz eterna, paz eterna.\nÉl es fuego celestial,\nCuya llama, cuya llama;\nEn amor angelical,\nNos inflama, nos inflama.'),(586,91,'Estrofa',3,'Disfrutamos tu favor,\nSolamente, solamente;\nPor Jesús, fuente de amor,\nPermanente, permanente.\nSólo Él nos libertó,\nDe la muerte, de la muerte;\nSólo Él se declaró,\nNuestro fuerte, nuestro fuerte.'),(587,91,'Estrofa',4,'Sólo Tú, ¡Oh, Creador!\nDios eterno, Dios eterno;\nNos libraste del furor,\nDel pecado, del pecado.\nY por esto con placer,\nProclamamos, proclamamos;\nQue sólo en tu gran poder,\nConfiamos, confiamos.'),(588,92,'Estrofa',1,'Cerca, más cerca, ¡Oh, Dios de Ti!\nCerca yo quiero mi vida llevar;\nCerca, más cerca, ¡Oh, Dios de Ti!\n//Cerca a tu gracia que puede salvar.//'),(589,92,'Estrofa',2,'Cerca, más cerca, cual pobre soy,\nNada Señor, yo te puedo ofrecer;\nSolo mi ser contrito te doy,\n//Pueda contigo la paz obtener.//'),(590,92,'Estrofa',3,'Cerca, más cerca, Señor de Ti,\nQuiero ser tuyo, dejando el pecar;\nGoces y pompas vanas aquí,\n//Todo, Señor, pronto quiero dejar.//'),(591,92,'Estrofa',4,'Cerca, más cerca, mientras el ser,\nAliente vida y busque tu faz;\nY cuando el Reino pueda obtener,\n//Ya para siempre conmigo estarás.//'),(592,93,'Estrofa',1,'¡Santo! ¡Santo! ¡Santo! Señor Omnipotente,\nSiempre el labio mío loores te dará;\n¡Santo! ¡Santo! ¡Santo! Te adoro reverente,\n¡Dios Eterno y Santo recibe mi cantar!'),(593,93,'Estrofa',2,'¡Santo! ¡Santo! ¡Santo! en numeroso coro,\nSantos escogidos te adoran con fervor;\nDe alegría llenos, y sus coronas de oro,\nRinden ante el trono glorioso del Señor.'),(594,93,'Estrofa',3,'¡Santo! ¡Santo! ¡Santo! la inmensa muchedumbre\nDe ángeles que cumplen tu santa voluntad;\nAnte Ti se postra bañada con tu lumbre,\nAnte Ti que has sido, que eres y serás.'),(595,93,'Estrofa',4,'¡Santo! ¡Santo! ¡Santo! por más que estés velado\nE imposible sea tu gloria contemplar;\nSanto Tú, eres solo y nada hay a tu lado,\nEn poder perfecto, pureza y caridad.'),(596,93,'Estrofa',5,'¡Santo! ¡Santo! ¡Santo! la gloria de tu nombre.\nVemos en tus obras, en cielo, tierra y mar;\n¡Santo! ¡Santo! ¡Santo! te adorará todo hombre,\nDios que siempre has sido, que eres y serás.'),(597,94,'Estrofa',1,'¡Cuán glorioso es el cambio operado en mi ser,\nViniendo a mi vida el Señor!\nHay en mi alma una paz que yo ansiaba tener,\nLa paz que me trajo su amor.'),(598,94,'Coro',2,'¡El vino a mi corazón! ¡El vino a mi corazón!\nSoy feliz con la vida que Cristo me dio,\nCuando Él vino a mi corazón.'),(599,94,'Estrofa',3,'Ya no voy por la senda que el mal me trazó,\nDo sólo encontré, confusión;\nMis errores pasados Jesús los borró,\nCuando Él vino a mi corazón.'),(600,94,'Coro',4,'¡El vino a mi corazón! ¡El vino a mi corazón!\nSoy feliz con la vida que Cristo me dio,\nCuando Él vino a mi corazón.'),(601,94,'Estrofa',5,'Ni una sombra de duda obscurece su amor,\nAmor que me trajo el perdón;\nLa esperanza que aliento la debo al Señor,\nCuando Él vino a mi corazón.'),(602,94,'Coro',6,'¡El vino a mi corazón! ¡El vino a mi corazón!\nSoy feliz con la vida que Cristo me dio,\nCuando Él vino a mi corazón.'),(603,95,'Estrofa',1,'¡Guíame, oh, Salvador!\nPor la vía de salud;\nA tu lado no hay temor,\nSólo hay gozo, paz, quietud.'),(604,95,'Coro',2,'¡Cristo! ¡Cristo!\nNo me dejes, ¡Oh, Señor!\nSiendo Tú mi guía fiel,\nSeré, más que vencedor.'),(605,95,'Estrofa',3,'No me dejes, ¡Oh, Señor!\nMientras en el mundo esté,\nY haz que arribe sin temor,\nDo feliz por fin seré.'),(606,95,'Coro',4,'¡Cristo! ¡Cristo!\nNo me dejes, ¡Oh, Señor!\nSiendo Tú mi guía fiel,\nSeré, más que vencedor.'),(607,95,'Estrofa',5,'Tú, de mi alma salvación,\nEn la ruda tempestad;\nAl venir la tentación,\nDame ayuda, ¡Por piedad!'),(608,95,'Coro',6,'¡Cristo! ¡Cristo!\nNo me dejes, ¡Oh, Señor!\nSiendo Tú mi guía fiel,\nSeré, más que vencedor.'),(609,96,'Estrofa',1,'Hubo quien por mis culpas muriera en la cruz,\nAún indigno y vil como soy;\nSoy feliz, pues su sangre vertió mi Jesús,\nY con ella mis culpas borró'),(610,96,'Coro',2,'Mis pecados llevó en la cruz do murió,\nEl sublime, el tierno Jesús;\nLos desprecios sufrió y mi alma salvó,\nEl cambió mis tinieblas en luz.'),(611,96,'Estrofa',3,'El es tierno y amante, cual nadie lo fue,\nPues convierte al infiel corazón;\nY por esa paciencia y ternura, yo sé,\nQue soy libre de condenación.'),(612,96,'Coro',4,'Mis pecados llevó en la cruz do murió,\nEl sublime, el tierno Jesús;\nLos desprecios sufrió y mi alma salvó,\nEl cambió mis tinieblas en luz.'),(613,96,'Estrofa',5,'Es mi anhelo constante a Cristo seguir,\nMi camino su ejemplo marcó;\nY por darme la vida Él quiso morir,\nEn su cruz mi pecado clavó.'),(614,96,'Coro',6,'Mis pecados llevó en la cruz do murió,\nEl sublime, el tierno Jesús;\nLos desprecios sufrió y mi alma salvó,\nEl cambió mis tinieblas en luz.'),(615,97,'Estrofa',1,'Un día Cristo volverá,\nPromesa fiel. ¿Faltar? ¡Jamás!\nComo se fue, así vendrá,\nY su pueblo ha de ver al Rey Jesús.'),(616,97,'Coro',2,'Muy pronto, sí, Jesús vendrá,\nY alegre le verá su pueblo;\n¡Velad!, ¡orad!, el Rey vendrá,\nY con los suyos Reinará.'),(617,97,'Estrofa',3,'Los mensajeros del Señor,\nAfirman que vendrá Jesús;\nY el buen y fiel Consolador,\nLas promesas ya sacó a plena luz.'),(618,97,'Coro',4,'Muy pronto, sí, Jesús vendrá,\nY alegre le verá su pueblo;\n¡Velad!, ¡orad!, el Rey vendrá,\nY con los suyos Reinará.'),(619,97,'Estrofa',5,'¡Oh, gloria sin comparación,\nSerá mirar a nuestro Rey!\nReciben todos bendición,\nEsperando ese día: con tu grey.'),(620,97,'Coro',6,'Muy pronto, sí, Jesús vendrá,\nY alegre le verá su pueblo;\n¡Velad!, ¡orad!, el Rey vendrá,\nY con los suyos Reinará.'),(621,97,'Estrofa',7,'¡Oh, bienvenido Rey Jesús!\nTu Iglesia te espera, sí;\nMuy pronto ha de ver tu faz,\nY gozar de tus laureles siempre aquí.'),(622,97,'Coro',8,'Muy pronto, sí, Jesús vendrá,\nY alegre le verá su pueblo;\n¡Velad!, ¡orad!, el Rey vendrá,\nY con los suyos Reinará.'),(623,98,'Estrofa',1,'La senda ancha dejaré,\nYo quiero por la angosta andar;\nY muchos no sabrán por qué,\nCon Cristo en Sión voy a Reinar.'),(624,98,'Coro',2,'No puede el mundo ser mi hogar,\nNo puede el mundo ser mi hogar,\nPues sólo peregrino soy,\nNo puede el mundo ser mi hogar.'),(625,98,'Estrofa',3,'Algunos quieren verme ir,\nPor el sendero de maldad;\nOír no puedo su llamar,\nPues voy con Cristo a Reinar.'),(626,98,'Coro',4,'No puede el mundo ser mi hogar,\nNo puede el mundo ser mi hogar,\nPues sólo peregrino soy,\nNo puede el mundo ser mi hogar.'),(627,98,'Estrofa',5,'¡Oh, ven conmigo pecador,\nY sigue en pos de el Salvador!\n¿Porqué, no quieres tu buscar\nLa hermosa tierra más allá ?'),(628,98,'Coro',6,'No puede el mundo ser mi hogar,\nNo puede el mundo ser mi hogar,\nPues sólo peregrino soy,\nNo puede el mundo ser mi hogar.'),(629,99,'Estrofa',1,'Señor Jesús, dirige\nTú mis pasos a Jehová,\nY haz que humilde guarde siempre,\nLos mandatos de su amor.'),(630,99,'Coro',2,'Dime, dime, cómo consagrar,\nTodo al Padre Celestial,\nDime, dime, cómo hacer su voluntad.'),(631,99,'Estrofa',3,'Dime como ser sumiso,\nY entregar mi entero ser;\nGozos y tesoros vanos,\nTodo siempre aborrecer.'),(632,99,'Coro',4,'Dime, dime, cómo consagrar,\nTodo al Padre Celestial,\nDime, dime, cómo hacer su voluntad.'),(633,99,'Estrofa',5,'Dime cómo al ser probado,\nDebo siempre en Él confiar;\nY aunque sufra en agonía,\nNunca de Él desesperar.'),(634,99,'Coro',6,'Dime, dime, cómo consagrar,\nTodo al Padre Celestial,\nDime, dime, cómo hacer su voluntad.'),(635,99,'Estrofa',7,'Dime cómo obedecerle,\nAunque a veces mi razón,\nNo comprenda sus designios,\nNi halle pronto explicación.'),(636,99,'Coro',8,'Dime, dime, cómo consagrar,\nTodo al Padre Celestial,\nDime, dime, cómo hacer su voluntad.'),(637,99,'Estrofa',9,'Dime cómo he de agradarle,\nNunca fiando en mi saber;\nEntregado a su servicio,\nY confiando en su poder.'),(638,99,'Coro',10,'Dime, dime, cómo consagrar,\nTodo al Padre Celestial,\nDime, dime, cómo hacer su voluntad.'),(639,100,'Estrofa',1,'A Cristo doy mi canto,\nÉl salva el alma mía;\nMe libra del quebranto,\nY con amor me guía.'),(640,100,'Coro',2,'Ensalce nuestro canto,\nTu sacrosanta historia;\nEs nuestro anhelo, santo,\nMirar, Jesús, tu gloria.'),(641,100,'Estrofa',3,'Jamás dolor ni agravios,\nEnlutarán la mente;\nSi a Cristo nuestros labios,\nBendicen dulcemente.'),(642,100,'Coro',4,'Ensalce nuestro canto,\nTu sacrosanta historia;\nEs nuestro anhelo, santo,\nMirar, Jesús, tu gloria.'),(643,100,'Estrofa',5,'Tu nombre bendecido,\nAlegra el alma mía;\nTu nombre es en mi oído,\nDulcísima armonía.'),(644,100,'Coro',6,'Ensalce nuestro canto,\nTu sacrosanta historia;\nEs nuestro anhelo, santo,\nMirar, Jesús, tu gloria.'),(645,101,'Estrofa',1,'Cristo está buscando obreros hoy,\nQue quieran ir con Él;\n¿Quién dirá: “Señor, contigo voy,\nYo quiero serte fiel”?'),(646,101,'Coro',2,'¡Oh, Señor, es mucha la labor,\nY obreros faltan ya;\nDanos luz, ardiente fe y valor,\nY obreros siempre habrá!'),(647,101,'Estrofa',3,'Cristo quiere mensajeros hoy,\nQue anuncien su verdad;\n¿Quién dirá: “Señor, yo listo estoy,\nHaré tu voluntad”?'),(648,101,'Coro',4,'¡Oh, Señor, es mucha la labor,\nY obreros faltan ya;\nDanos luz, ardiente fe y valor,\nY obreros siempre habrá!'),(649,101,'Estrofa',5,'Hay lugar si quieres trabajar,\nDe Cristo en la labor;\nPuedes de su gracia al mundo hablar,\nDe su bondad y amor.'),(650,101,'Coro',6,'¡Oh, Señor, es mucha la labor,\nY obreros faltan ya;\nDanos luz, ardiente fe y valor,\nY obreros siempre habrá!'),(651,101,'Estrofa',7,'¿Vives ya salvado por Jesús?\n¿Su amor conoces ya?\n¡Habla, pues, anuncia que en la luz,\nDe Cristo vives ya!'),(652,101,'Coro',8,'¡Oh, Señor, es mucha la labor,\nY obreros faltan ya;\nDanos luz, ardiente fe y valor,\nY obreros siempre habrá!'),(653,102,'Estrofa',1,'Todo a Cristo yo me rindo,\nCon el fin de serle fiel;\nPara siempre quiero amarle,\nY agradarle sólo a Él.'),(654,102,'Coro',2,'Yo me rindo a Él,\nYo me rindo a Él;\nTodo a Cristo yo me entrego,\nQuiero serle fiel.'),(655,102,'Estrofa',3,'Todo a Cristo yo me rindo,\nY a sus pies postrado estoy;\nLos placeres he dejado,\nY le sigo desde hoy.'),(656,102,'Coro',4,'Yo me rindo a Él,\nYo me rindo a Él;\nTodo a Cristo yo me entrego,\nQuiero serle fiel.'),(657,102,'Estrofa',5,'Todo a Cristo yo me rindo,\nSí, de todo corazón;\nYo le entrego alma y cuerpo,\nBusco hoy su santa unción.'),(658,102,'Coro',6,'Yo me rindo a Él,\nYo me rindo a Él;\nTodo a Cristo yo me entrego,\nQuiero serle fiel.'),(659,102,'Estrofa',7,'Todo a Cristo yo me rindo,\nSiento el fuego de su amor;\n¡Oh, qué‚ gozo hay en mi alma!\n¡Gloria, gloria a mi Señor!'),(660,102,'Coro',8,'Yo me rindo a Él,\nYo me rindo a Él;\nTodo a Cristo yo me entrego,\nQuiero serle fiel.'),(661,103,'Estrofa',1,'Canten los ángeles con dulce voz,\nCanten los hombres con sonora voz;\nCristo vendrá, nuestro Rey vencedor,\nCristo vendrá otra vez.'),(662,103,'Coro',2,'¡Viene otra vez, viene otra vez!\nEn gloria viene al mundo otra vez;\n¡Viene otra vez, viene otra vez!\n¡El viene pronto a Reinar!'),(663,103,'Estrofa',3,'Ved en la tierra, los aires y el mar,\nGrandes Señales cumpliéndose ya;\nTodo indicando que pronto vendrá,\nNuestro glorioso Señor.'),(664,103,'Coro',4,'¡Viene otra vez, viene otra vez!\nEn gloria viene al mundo otra vez;\n¡Viene otra vez, viene otra vez!\n¡El viene pronto a Reinar!'),(665,103,'Estrofa',5,'Todos los muertos en Cristo, saldrán,\nDe los sepulcros, y alegres irán;\nPara encontrar a su Rey subirán,\n¡Cristo vendrá otra vez!'),(666,103,'Coro',6,'¡Viene otra vez, viene otra vez!\nEn gloria viene al mundo otra vez;\n¡Viene otra vez, viene otra vez!\n¡El viene pronto a Reinar!'),(667,103,'Estrofa',7,'¡Ven en las nubes, ¡Oh buen Salvador!\n¡Ven a tierra, te ruego Señor!\n¡Ven, que tu Iglesia te espera, Jesús!\n¡Cristo vendrá otra vez!'),(668,103,'Coro',8,'¡Viene otra vez, viene otra vez!\nEn gloria viene al mundo otra vez;\n¡Viene otra vez, viene otra vez!\n¡El viene pronto a Reinar!'),(669,104,'Estrofa',1,'¡Ve, ve, oh, Sión, tu gran destino cumple,\nQue Dios es luz, al mundo proclamad;\nQue el Hacedor de las naciones quiere,\nQue nadie muera en densa oscuridad!'),(670,104,'Coro',2,'¡Alegres nuevas al mundo dad!\nNuevas de redención, de amor y libertad.'),(671,104,'Estrofa',3,'Ve cuántos miles yacen todavía,\nEn la obscuras cárceles del mal;\nIgnoran que de Cristo la agonía,\nFue para darles vida y libertad.'),(672,104,'Coro',4,'¡Alegres nuevas al mundo dad!\nNuevas de redención, de amor y libertad.'),(673,104,'Estrofa',5,'Es tu deber que salves de la muerte,\nLas almas por las cuales Él murió;\nSe fiel, si no tendrás que ser culpable,\nDe que se pierda lo que Dios ganó.'),(674,104,'Coro',6,'¡Alegres nuevas al mundo dad!\nNuevas de redención, de amor y libertad.'),(675,104,'Estrofa',7,'Ve, di a toda tribu, pueblo y lengua,\nQue el Dios en quien vivimos es amor;\nQue su Hijo a muerto porque tenga,\nTodo mortal la vida en el Señor.'),(676,104,'Coro',8,'¡Alegres nuevas al mundo dad!\nNuevas de redención, de amor y libertad.'),(677,104,'Estrofa',9,'Tus hijos manda con el gran mensaje,\nCon tu dinero, impulso a ellos da;\nEn oración sustenta fiel sus almas,\nY cuanto gastes Cristo pagará.'),(678,104,'Coro',10,'¡Alegres nuevas al mundo dad!\nNuevas de redención, de amor y libertad.'),(679,105,'Estrofa',1,'En las aguas de la muerte,\nSumergido fue Jesús;\nMas su amor no fue apagado,\nPor sus penas en la cruz.\nLevantose de la tumba,\nSus cadenas quebrantó;\nY triunfante y victorioso,\nA los cielos ascendió.'),(680,105,'Estrofa',2,'En las aguas del bautismo,\nHoy confieso yo mi fe;\nJesucristo me ha salvado,\nY en su amor me gozaré\nEn las aguas humillantes,\nA Jesús siguiendo estoy;\nDesde ahora para el mundo,\nY al pecado muerto soy.'),(681,105,'Estrofa',3,'Yo que estoy Crucificado,\n¿Cómo más podré‚ pecar?\nYa que estoy resucitado,\nSanta vida, he de llevar.\nSon las aguas del bautismo,\nMi Señal de salvación;\nY yo quiero consagrarme,\nAl que obró mi redención.'),(682,106,'Estrofa',1,'¿Cómo podré‚ estar triste?\n¿Cómo entre sombras ir?\n¿Cómo sentirme solo?\n¿Y en el dolor vivir?\nSi Cristo es mi consuelo,\nMi amigo siempre fiel;\n//Si aún las aves tienen,\nSeguro asilo en Él.//'),(683,106,'Coro',2,'Feliz, cantando alegre,\nYo vivo siempre aquí;\n¡Si Él cuida de las aves,\nCuidará también de mí!'),(684,106,'Estrofa',3,'“Nunca te desalientes”,\nOigo al Señor decir;\nY en su Palabra fiado,\nHago al dolor huir.\nA Cristo, paso a paso,\nYo sigo sin cesar;\n//Y todas sus bondades,\nMe da sin limitar.//'),(685,106,'Coro',4,'Feliz, cantando alegre,\nYo vivo siempre aquí;\n¡Si Él cuida de las aves,\nCuidará también de mí!'),(686,106,'Estrofa',5,'Siempre que soy tentado,\nO en la sombra estoy;\nMás cerca de Él, camino,\nY protegido voy.\nSi en mí la fe desmaya,\nY caigo en la ansiedad;\n//¡Tan sólo Él me levanta,\nMe da seguridad!//'),(687,106,'Coro',6,'Feliz, cantando alegre,\nYo vivo siempre aquí;\n¡Si Él cuida de las aves,\nCuidará también de mí!'),(688,107,'Estrofa',1,'¡Ama el Pastor sus ovejas con un amor paternal!\n¡Ama el Pastor su rebaño, con un amor sin igual!\n¡Ama el Pastor a las otras, que descarriadas están,\nY conmovido las busca, por dondequiera que van!'),(689,107,'Coro',2,'Por el desierto errabundas, vense sufrir penas mil,\nY al encontrarlas en hombros, llévalas, tierno, al redil.'),(690,107,'Estrofa',3,'Ama el Pastor sus corderos, ámalos tierno El Pastor!\nA los que a veces perdidos, se oyen gemir de dolor.\nVed al Pastor conmovido, por los collados vagar;\nY los corderos en hombros, vedlo llevando al hogar.'),(691,107,'Coro',4,'Por el desierto errabundas, vense sufrir penas mil,\nY al encontrarlas en hombros, llévalas, tierno, al redil.'),(692,107,'Estrofa',5,'¡Ama las noventa y nueve, que en el aprisco guardó!\n!Ama las que descarriadas, por el desierto dejó!\n¡Oh, mis ovejas perdidas, clama doliente el Pastor!\n¿Quiénesvendrán en mi ayuda, para salvarlas, Señor?'),(693,107,'Coro',6,'Por el desierto errabundas, vense sufrir penas mil,\nY al encontrarlas en hombros, llévalas, tierno, al redil.'),(694,107,'Estrofa',7,'Son delicados tus pastos, y quietas tus aguas son;\nHenos aquí, ¡Oh, Maestro! danos hoy tu comisión.\nHaznos obreros fervientes, llénanos de un santo amor;\nPor las ovejas perdidas, de tu redil, buen Señor.'),(695,107,'Coro',8,'Por el desierto errabundas, vense sufrir penas mil,\nY al encontrarlas en hombros, llévalas, tierno, al redil.'),(696,108,'Estrofa',1,'Pecador, ven al dulce Jesús,\nY feliz para siempre serás;\nSi en verdad le quisieras tener,\nAl divino Señor hallarás.'),(697,108,'Coro',2,'//Ven a Él, ven a Él,\nQue te espera tu buen Salvador.//'),(698,108,'Estrofa',3,'Si cual hijo que necio pecó,\nVas buscando a sus pies compasión,\nTierno Padre en Jesús hallarás,\nY tendrás en sus brazos perdón.'),(699,108,'Coro',4,'//Ven a Él, ven a Él,\nQue te espera tu buen Salvador.//'),(700,108,'Estrofa',5,'Si enfermo te sientes morir,\nEl será tu Doctor Celestial;\nY hallarás en su sangre también,\nMedicina que cure tu mal.'),(701,108,'Coro',6,'//Ven a Él, ven a Él,\nQue te espera tu buen Salvador.//'),(702,108,'Estrofa',7,'Ovejuela que huyó del redil,\n¡He aquí tu benigno Señor!\nEn los hombros llevada serás,\nDe tan dulce y amante Pastor.'),(703,108,'Coro',8,'//Ven a Él, ven a Él,\nQue te espera tu buen Salvador.//'),(704,109,'Estrofa',1,'Yo quiero trabajar por el Señor,\nConfiando en su Palabra y en su amor;\nQuiero yo cantar y orar,\nY ocupado siempre estar,\nEn la viña del Señor.'),(705,109,'Coro',2,'Trabajad y orad,\nEn la viña, en la viña del Señor;\nSi, mi anhelo es orar,\nY ocupado siempre estar,\nEn la viña del Señor.'),(706,109,'Estrofa',3,'Yo quiero día por día trabajar,\nY esclavos del pecado libertar;\nConducirlos a Jesús,\nNuestro guía y nuestra luz,\nEn la viña del Señor.'),(707,109,'Coro',4,'Trabajad y orad,\nEn la viña, en la viña del Señor;\nSi, mi anhelo es orar,\nY ocupado siempre estar,\nEn la viña del Señor.'),(708,109,'Estrofa',5,'Yo quiero ser obrero de valor,\nConfiando en el poder de el Salvador;\nY el que quiera trabajar,\nHallar también lugar,\nEn la viña del Señor.'),(709,109,'Coro',6,'Trabajad y orad,\nEn la viña, en la viña del Señor;\nSi, mi anhelo es orar,\nY ocupado siempre estar,\nEn la viña del Señor.'),(710,110,'Estrofa',1,'La palabra hoy sembrada,\nHazla, Cristo, en mí nacer;\nPara darle crecimiento,\nSólo tienes Tú poder\n//Ricos frutos Tú nos puedes conceder.//'),(711,110,'Estrofa',2,'La semilla que tu siervo,\nHa sembrado con saber;\nNo permitas que las aves,\nSe la vengan a comer.\n//Ricos frutos Tú nos puedes conceder.//'),(712,110,'Estrofa',3,'Haz que crezca con tu gracia,\nY tu rica bendición;\nNo la ahoguen las espinas,\nDe congojas y aflicción,\n//Ricos frutos Tú nos puedes conceder.//'),(713,110,'Estrofa',4,'Que su efecto muy profundo,\nEn la mente y corazón;\nConvencer consigo al mundo:\nQue les das la salvación.\n//Ricos frutos Tú nos puedes conceder.//'),(714,110,'Estrofa',5,'Sembraremos la palabra,\nCon amor y profusión;\nEsperando la cosecha,\nEstaremos allá en Sión.\n//Ricos frutos Tú nos puedes conceder.//'),(715,111,'Estrofa',1,'Voy feliz al dulce hogar, por fe en Jesús,\nY luchando a traer almas a la luz;\nDardos encendidos mil vienen contra mí,\nMas yo sé, por la fe, venceré aquí.'),(716,111,'Coro',2,'¡Oh, sí, quiero verle, ver al Salvador!\nQuiero ver su rostro lleno de amor;\nEn aquel gran día yo he de cantar,\nYa pasó todo afán, todo mi pesar.'),(717,111,'Estrofa',3,'En las olas del turbión Cristo guardará,\nMi barquilla y guiará hasta el puerto allá;\nYo tranquilo puedo estar, mi Piloto es Él,\nEs mi Rey, tengo fe, sé‚ que Él es fiel.'),(718,111,'Coro',4,'¡Oh, sí, quiero verle, ver al Salvador!\nQuiero ver su rostro lleno de amor;\nEn aquel gran día yo he de cantar,\nYa pasó todo afán, todo mi pesar.'),(719,111,'Estrofa',5,'En servir al Salvador por los valles voy,\nDonde muchas sombras hay, más seguro Estoy;\nMuchos triunfos obtendré, nunca faltará,\nMi Jesús, es la Luz, Él me sostendrá.'),(720,111,'Coro',6,'¡Oh, sí, quiero verle, ver al Salvador!\nQuiero ver su rostro lleno de amor;\nEn aquel gran día yo he de cantar,\nYa pasó todo afán, todo mi pesar.'),(721,112,'Estrofa',1,'A solas al huerto yo voy,\nCuando duerme aún la floresta;\nY en quietud y paz con Jesús estoy,\nOyendo absorto allí su voz.'),(722,112,'Coro',2,'¡El conmigo está, puedo oír su voz!\nY que suyo, dice, seré;\nY el encanto que hallo en Él allí,\nCon nadie tener podré.'),(723,112,'Estrofa',3,'Tan dulce es la voz del Señor,\nQue las aves guardan silencio;\nY tan sólo se oye esa voz de amor,\nQue inmensa paz al alma da.'),(724,112,'Coro',4,'¡El conmigo está, puedo oír su voz!\nY que suyo, dice, seré;\nY el encanto que hallo en Él allí,\nCon nadie tener podré.'),(725,112,'Estrofa',5,'Con Él encantado yo estoy,\nAunque en torno lleguen las sombras;\nMás me ordena a ir, que a escuchar yo voy\nSu voz doquier la pena esté.'),(726,112,'Coro',6,'¡El conmigo está, puedo oír su voz!\nY que suyo, dice, seré;\nY el encanto que hallo en Él allí,\nCon nadie tener podré.'),(727,113,'Estrofa',1,'Oh, Señor Omnipotente,\nOye ya mi petición;\nQue tu Espíritu Bendito,\nLlene hoy mi corazón.'),(728,113,'Coro',2,'Llene hoy, llene hoy,\nLlene hoy mi corazón;\nQue tu Espíritu Bendito\nHaga en él su habitación.'),(729,113,'Estrofa',3,'De tu gracia puedes darme,\nInundado el corazón;\nVen que mucho necesito;\nDame hoy tu bendición.'),(730,113,'Coro',4,'Llene hoy, llene hoy,\nLlene hoy mi corazón;\nQue tu Espíritu Bendito\nHaga en él su habitación.'),(731,113,'Estrofa',5,'Débil soy, oh sí, muy débil.\nY a tus pies postrado estoy;\nEsperando que tu gracia,\nCon poder me llene hoy.'),(732,113,'Coro',6,'Llene hoy, llene hoy,\nLlene hoy mi corazón;\nQue tu Espíritu Bendito\nHaga en él su habitación.'),(733,113,'Estrofa',7,'Dame paz, consuelo y gozo,\nCúbreme hoy con tu perdón;\nTú confortas y redimes,\nTú das grande salvación'),(734,113,'Coro',8,'Llene hoy, llene hoy,\nLlene hoy mi corazón;\nQue tu Espíritu Bendito\nHaga en él su habitación.'),(735,114,'Estrofa',1,'¡Oh, Padre, Eterno Dios!\nAlzamos nuestra voz\nEn gratitud,\nDe cuanto Tú nos das,\nCon sin igual amor,\nHallando nuestra paz, en Ti, Señor.'),(736,114,'Estrofa',2,'¡Bendito Salvador!\nTe damos con amor\nEl corazón,\nY aquí nos puedes ver,\nQue humildes a tu altar,\nVenimos a ofrecer, precioso don.'),(737,114,'Estrofa',3,'¡Oh, Padre, Eterno Dios!\nEscucha nuestra voz,\nY tu verdad,\nDerrama en nuestro ser,\nDivina claridad,\nPara poder vivir, en santidad.'),(738,115,'Estrofa',1,'¡No te dé temor hablar por Cristo!\nHaz que brille en ti su luz;\nAl que te salvó confiesa siempre,\nTodo debes a Jesús.'),(739,115,'Coro',2,'¡No te dé temor, no te dé temor!\n¡Nunca, nunca, nunca!\nEs tu amante Salvador,\n¡Nunca pues, te dé temor!'),(740,115,'Estrofa',3,'¡No te dé temor hacer por Cristo,\nCuando de tu parte esté;\nObra con amor, con fe y constancia,\nTus trabajos premiará.'),(741,115,'Coro',4,'¡No te dé temor, no te dé temor!\n¡Nunca, nunca, nunca!\nEs tu amante Salvador,\n¡Nunca pues, te dé temor!'),(742,115,'Estrofa',5,'¡No te dé temor, sufrir por Cristo,\nLos reproches o el dolor;\nSufre con amor tus pruebas todas,\nCual sufrió tu Salvador!'),(743,115,'Coro',6,'¡No te dé temor, no te dé temor!\n¡Nunca, nunca, nunca!\nEs tu amante Salvador,\n¡Nunca pues, te dé temor!'),(744,115,'Estrofa',7,'¡No te dé temor vivir por Cristo,\nEsa vida que te da!\nSi tan sólo en Él por siempre fiares,\nEl con bien te sacará.'),(745,115,'Coro',8,'¡No te dé temor, no te dé temor!\n¡Nunca, nunca, nunca!\nEs tu amante Salvador,\n¡Nunca pues, te dé temor!'),(746,115,'Estrofa',9,'¡No te dé temor morir por Cristo,\nVía, verdad y vida es El!\nÉl te llevará con su ternura,\nA su Reino magno y fiel'),(747,115,'Coro',10,'¡No te dé temor, no te dé temor!\n¡Nunca, nunca, nunca!\nEs tu amante Salvador,\n¡Nunca pues, te dé temor!'),(748,116,'Estrofa',1,'¡Trabajad! ¡Trabajad! somos siervos de Dios,\nSeguiremos la senda que el Maestro trazó;\nRenovando las fuerzas con bienes que da,\nEl deber que nos toca cumplido será.'),(749,116,'Coro',2,'¡Trabajad, Trabajad!\n¡Esperad y velad!\n¡Confiad! ¡Siempre orad!\n¡Que el Maestro pronto volverá!'),(750,116,'Estrofa',3,'¡Trabajad! ¡Trabajad! Hay que dar de comer,\nAl que pan de la vida quisiere tener;\nHay enfermos que irán a los pies de Señor,\nAl saber que de balde los sana su amor.'),(751,116,'Coro',4,'¡Trabajad, Trabajad!\n¡Esperad y velad!\n¡Confiad! ¡Siempre orad!\n¡Que el Maestro pronto volverá!'),(752,116,'Estrofa',5,'¡Trabajad! ¡Trabajad! fortaleza pedid,\nEl reinado del mal, con valor combatid;\nConducid los cautivos al Libertador,\ny decid que de balde redime su amor.'),(753,116,'Coro',6,'¡Trabajad, Trabajad!\n¡Esperad y velad!\n¡Confiad! ¡Siempre orad!\n¡Que el Maestro pronto volverá!'),(754,117,'Estrofa',1,'Señor, nos recordamos, de tu pasión aquí;\nCual sustituto Santo, sufriendo tu alma así.\nEl cáliz de amargura, con plena sumisión;\nTú mismo lo agotaste, Señor, ¡Qué redención!.'),(755,117,'Estrofa',2,'Las olas vengadoras, de cólera penal;\nPor sobre Ti pasaron, con peso judicial.\nY tu alma sumergida, probó la maldición,\nDebida a los perdidos, por nuestra salvación.'),(756,117,'Estrofa',3,'Sabemos que tu muerte, quitó la acusación;\nPor causa del pecado, ¡Qué grande expiación!\nMas, ¿cuál no fue el tormento, que tu alma allá sufrió;\nCuando el divino rostro, de Ti Dios apartó?'),(757,117,'Estrofa',4,'¿Y Quién dirá qué gozo, el Padre en ti sintió;\nEn ese mismo instante, en que Dios te dejó?\nMas a su diestra ahora, sentado en gloria estás;\nDo esperas el momento, en que Tú volverás.'),(758,118,'Estrofa',1,'Lejos de mi Padre Dios,\nPor Jesús fui hallado;\nPor su gracia y por su amor,\nSólo fui salvado.'),(759,118,'Coro',2,'¡En Jesús, mi Señor,\nSea mi gloria eterna;\nEl me amó y me salvó,\nEn su gracia tierna!'),(760,118,'Estrofa',3,'En Jesús, mi Salvador,\nPongo mi confianza;\nToda mi necesidad,\nSuple en abundancia.'),(761,118,'Coro',4,'¡En Jesús, mi Señor,\nSea mi gloria eterna;\nEl me amó y me salvó,\nEn su gracia tierna!'),(762,118,'Estrofa',5,'Cerca de mi buen Pastor,\nVivo cada día;\nToda gracia en su Señor,\nHalla el alma mía.'),(763,118,'Coro',6,'¡En Jesús, mi Señor,\nSea mi gloria eterna;\nEl me amó y me salvó,\nEn su gracia tierna!'),(764,118,'Estrofa',7,'Guárdame, Señor Jesús,\nPara que no caiga;\nComo un sarmiento en la vid,\nVida de Ti traiga.'),(765,118,'Coro',8,'¡En Jesús, mi Señor,\nSea mi gloria eterna;\nEl me amó y me salvó,\nEn su gracia tierna!'),(766,119,'Estrofa',1,'¡Oh, bondad tan infinita,\nHacia el mundo pecador,\nDios en Cristo revelando,\nSu eternal y santo amor!'),(767,119,'Coro',2,'¡Es Jesús para mí,\nLa esperanza de salud;\nSólo en Él hallaré,\nLa divina plenitud!'),(768,119,'Estrofa',3,'Como el vasto firmamento,\nComo el insondable mar,\nEs la gracia salvadora,\nQue Jesús al alma da.'),(769,119,'Coro',4,'¡Es Jesús para mí,\nLa esperanza de salud;\nSólo en Él hallaré,\nLa divina plenitud!'),(770,119,'Estrofa',5,'Aunque fueren tus pecados,\nrojos como el carmesí;\nEn el río del Calvario,\nHay limpieza para ti'),(771,119,'Coro',6,'¡Es Jesús para mí,\nLa esperanza de salud;\nSólo en Él hallaré,\nLa divina plenitud!'),(772,120,'Estrofa',1,'Yo guiaré al peregrino extraviado,\nBondadoso hasta el faro de luz;\nLe diré al corazón angustiado:\n“Hallarás tu consuelo en Jesús”.'),(773,120,'Coro',2,'Yo guiaré, yo guiaré,\nAl sediento de vida y de luz;\nYo guiaré, yo guiaré,\nAl perdido a los pies de Jesús.'),(774,120,'Estrofa',3,'Yo diré‚ al que buscare la calma,\nQue se llegue al amante Jesús;\nLe diré‚ con placer a aquella alma,\n¡Que te inunden sus ondas de luz!'),(775,120,'Coro',4,'Yo guiaré, yo guiaré,\nAl sediento de vida y de luz;\nYo guiaré, yo guiaré,\nAl perdido a los pies de Jesús.'),(776,120,'Estrofa',5,'Al que vague buscando una fuente,\nDo apagar de su sed el ardor;\nLo guiaré‚ con amor diligente,\nA Jesús, la gran fuente de amor.'),(777,120,'Coro',6,'Yo guiaré, yo guiaré,\nAl sediento de vida y de luz;\nYo guiaré, yo guiaré,\nAl perdido a los pies de Jesús.'),(778,120,'Estrofa',7,'Al cansado que busque reposo,\nSin hallarlo en su duro penar;\nLe diré‚ que reciba al que dice:\n“Ven a mí, y te haré‚ descansar”'),(779,120,'Coro',8,'Yo guiaré, yo guiaré,\nAl sediento de vida y de luz;\nYo guiaré, yo guiaré,\nAl perdido a los pies de Jesús.'),(780,121,'Estrofa',1,'¡Oh, cantádmelas otra vez,\nBellas palabras de vida,\nHallo en ellas mi gozo y luz,\nBellas palabras de vida!'),(781,121,'Coro',2,'Sí, de luz y vida,\nSon sostén y guía;\n//¡Qué bellas son, Qué bellas son,\nBellas palabras de vida!//'),(782,121,'Estrofa',3,'Jesucristo a todos da,\nBellas palabras de vida;\nHoy escúchalas pecador,\nBellas palabras de vida.\nBondadoso te salva,\nY al Reino te llama;'),(783,121,'Coro',4,'//¡Qué bellas son, Qué bellas son,\nBellas palabras de vida!//'),(784,121,'Estrofa',5,'Grato el cántico sonará,\nBellas palabras de vida;\nTus pecados perdonará,\nBellas palabras de vida.\nSi, de luz y vida,\nSon sostén y guía;'),(785,121,'Coro',6,'//¡Qué bellas son, Qué bellas son,\nBellas palabras de vida!//'),(786,122,'Estrofa',1,'A nuestro Padre Dios,\nAlcemos nuestra voz;\n¡Gloria a Él!\nTal fue su amor que dio,\nAl Hijo que murió;\nEn quien confío yo,\n¡Gloria a Él!'),(787,122,'Estrofa',2,'A nuestro Salvador,\nDemos con fe loor,\n¡Gloria a Él!\nSu sangre derramó,\nCon ella me lavó;\nY un Reino me prometió,\n¡Gloria a Él!'),(788,122,'Estrofa',3,'Santísimo Señor,\nElevo a Ti mi voz;\n¡Gloria a Ti!\nCon celestial fulgor,\nMe muestras el amor,\nDe Cristo mi Señor,\n¡Gloria a Ti!'),(789,123,'Estrofa',1,'Nítido rayo por Cristo,\nYo quiero siempre ser;\nEn todo quiero agradarle,\nY hacerlo con placer.'),(790,123,'Coro',2,'Un nítido rayo,\nNítido rayo por Cristo;\nUn nítido rayo,\nNítido rayo seré.'),(791,123,'Estrofa',3,'A Cristo quiero llegarme,\nEn mi temprana edad;\nPor siempre quiero amarle,\nY hacer su voluntad.'),(792,123,'Coro',4,'Un nítido rayo,\nNítido rayo por Cristo;\nUn nítido rayo,\nNítido rayo seré.'),(793,123,'Estrofa',5,'Nítido rayo, en tinieblas,\nDeseo resplandecer;\nAlmas perdidas a Cristo,\nAnhelo conducir.'),(794,123,'Coro',6,'Un nítido rayo,\nNítido rayo por Cristo;\nUn nítido rayo,\nNítido rayo seré.'),(795,123,'Estrofa',7,'Una heredad en su Reino,\nMi alma gozará;\nSi desde niño soy bueno,\nY hago su voluntad.'),(796,123,'Coro',8,'Un nítido rayo,\nNítido rayo por Cristo;\nUn nítido rayo,\nNítido rayo seré.'),(797,124,'Estrofa',1,'Cristo me ama, bien lo sé,\nSu palabra me hace ver;\nQue los niños son de aquel,\nQue es nuestro amigo fiel;'),(798,124,'Coro',2,'Cristo me ama, Cristo me ama,\nCristo me ama, la Biblia dice así.'),(799,124,'Estrofa',3,'Cristo me ama, pues murió,\nY el camino me mostró;\nEl mis culpas quitará,\nY su gracia me dará.'),(800,124,'Coro',4,'Cristo me ama, Cristo me ama,\nCristo me ama, la Biblia dice así.'),(801,124,'Estrofa',5,'Cristo me ama, es verdad,\nY me cuida en su bondad;\nCuando Él venga, si soy fiel,\nEn Sión gozaré con Él.'),(802,124,'Coro',6,'Cristo me ama, Cristo me ama,\nCristo me ama, la Biblia dice así.'),(803,125,'Estrofa',1,'Aunque ruda la tormenta,\nSe desata en derredor,\nAl amparo de Roca salvo estoy:\nAunque el cielo esté sombrío,\nNo me invadirá el temor,\nQue al amparo de la Roca salvo estoy.'),(804,125,'Coro',2,'Al amparo de la Roca salvo estoy,\nAl amparo de la Roca salvo estoy:\nSi a mi lado está el Señor,\nNo tendré ningún temor,\nQue al amparo de la Roca salvo estoy.'),(805,125,'Estrofa',3,'Cuando ruja el mar furioso,\nY agitado esté el turbión,\nAl amparo de la Roca salvo estoy;\nEn el puerto de reposo,\nY velando en oración,\nQue al amparo de la Roca salvo estoy.'),(806,125,'Coro',4,'Al amparo de la Roca salvo estoy,\nAl amparo de la Roca salvo estoy:\nSi a mi lado está el Señor,\nNo tendré ningún temor,\nQue al amparo de la Roca salvo estoy.'),(807,125,'Estrofa',5,'Con ternura Dios me cuida,\nDel peligro y del dolor,\nAl amparo de roca salvo estoy;\nÉl mis penas dulcifica,\nSoy objeto de su amor,\nQue al amparo de la Roca salvo Estoy.'),(808,125,'Coro',6,'Al amparo de la Roca salvo estoy,\nAl amparo de la Roca salvo estoy:\nSi a mi lado está el Señor,\nNo tendré ningún temor,\nQue al amparo de la Roca salvo estoy.'),(809,126,'Estrofa',1,'Dios bendiga las almas unidas,\nPor los lazos de amor sacrosanto;\nY los guarde de todo quebranto,\nEn el mundo de espinas erial.\nQue el hogar que a formarse comienza,\nCon la unión de estos dos corazones,\nGoce siempre, de mil bendiciones,\nAl amparo del Dios de Israel.'),(810,126,'Estrofa',2,'Que el Señor, con su dulce presencia,\nCariñoso estas bodas presida;\nY conduzca por sendas de vida,\nA los que hoy se han jurado lealtad.\nLes recuerde que nada en el mundo,\nEs eterno, que todo termina;\nY por tanto, con gracia divina,\nCifrar deben la dicha en su Dios.'),(811,126,'Estrofa',3,'Que a los dos que al altar se aproximan,\nA jurarse su fe mutuamente;\nBusquen siempre de Dios en la fuente,\nEl secreto de dicha inmortal.\nY si acaso de duelo y tristeza,\nSe empañasen sus sendas un día;\nEn Jesús hallarán dulce guía.\nQue otra senda les muestre mejor'),(812,127,'Estrofa',1,'En el valle florece la rosa,\nLa más bella del valle Sarón,\nY la vida en Cristo es hermosa,\nSi se acepta con el corazón.'),(813,127,'Coro',2,'Yo estaré con Jesús en el Reino,\nY por siempre su rostro veré;\nCon los santos en sus alabanzas,\nCon mi canto también me uniré.'),(814,127,'Estrofa',3,'En el valle florece la rosa,\nEs hermosa y trasciende su olor;\nY el alma que en Cristo reposa,\nHa encontrado la fuente de amor.'),(815,127,'Coro',4,'Yo estaré con Jesús en el Reino,\nY por siempre su rostro veré;\nCon los santos en sus alabanzas,\nCon mi canto también me uniré.'),(816,127,'Estrofa',5,'Es Jesús la promesa divina,\nEs la rosa más bella que el sol;\nEs la rosa de toda la Iglesia,\nQue le sirve con el corazón.'),(817,127,'Coro',6,'Yo estaré con Jesús en el Reino,\nY por siempre su rostro veré;\nCon los santos en sus alabanzas,\nCon mi canto también me uniré.'),(818,128,'Estrofa',1,'¡Cristianos Israelitas, hermanos del Señor!\nLlevad en vuestras manos la Biblia con valor,\ny en todos los hogares entremos a enseñar;\nDe las doctrinas santas para evangelizar\nA todos los gentiles que guarden con amor,\nLos mandamientos todos, de Dios Nuestro Señor.'),(819,128,'Estrofa',2,'Ceñid en vuestros lomos la Ley de la verdad,\nY en cota de justicia tendréis seguridad;\nLa paz del Evangelio calcemos sin cesar,\nY de salud el yelmo, debemos de llevar;\nTomemos el escudo con poderosa fe,\nY del Señor la espada, venced, como Josué.'),(820,128,'Estrofa',3,'¡Valientes Israelitas! Crucemos el Jordán,\nY en todas las naciones del reino de Satán;\nSerán vencidas todas como lo habló Jehová,\nLos reyes y señores en nada quedarán;\nMas Cristo en la batalla que pronto volverá,\nLos santos le veremos que en breve triunfará.'),(821,128,'Estrofa',4,'En el valle de los valles será la decisión,\nSigamos adelante hasta llegar a Sión;\nY en esta Sión gloriosa los santos reinarán,\nPor los siglos de siglos se regocijarán;\nLos cielos de los cielos, cantad a Dios cantad,\nCantad todos los mares, cantad a Dios cantad.'),(822,128,'Estrofa',5,'Entonces las naciones tendrán que respetar,\nQue Cristo es Rey de Reyes que viene a reinar,\nCaerá la Babilonia, caerá toda legión,\nSalid, ¡Oh pueblo santo!, de toda confusión;\nSeñor de los Señores es Cristo nuestro Rey\nEs Cristo el Rey de Reyes y en la Iglesia de Dios.'),(823,129,'Estrofa',1,'Alguna vez ya no estaré,\nEn mi lugar, en esta grey;\nMas ¡Cuán feliz despertaré,\nAl venir mi Señor y Rey!'),(824,129,'Coro',2,'Yo le veré y en dulce amor,\nHabré de estar con Él allí;\nY le diré: “Mi buen Señor,\nPor gracia yo salvado fui”.'),(825,129,'Estrofa',3,'Alguna vez la muerte atroz,\nVendrá, mas ¿Cuando? no lo sé,\nPero esto sé: Con mi buen Dios,\nFeliz por siempre yo seré.'),(826,129,'Coro',4,'Yo le veré y en dulce amor,\nHabré de estar con Él allí;\nY le diré: “Mi buen Señor,\nPor gracia yo salvado fui”.'),(827,129,'Estrofa',5,'Alguna vez yo, como el sol,\nMi ocaso y fin tendré también;\nPero al venir mi buen Señor,\nHe de gozar de dicha y bien.'),(828,129,'Coro',6,'Yo le veré y en dulce amor,\nHabré de estar con Él allí;\nY le diré: “Mi buen Señor,\nPor gracia yo salvado fui”.'),(829,129,'Estrofa',7,'El día feliz que espero yo,\nObedeciendo aquí su Ley;\nEl Reino me abrirá el Señor,\nEn la ciudad de Dios mi Rey.'),(830,129,'Coro',8,'Yo le veré y en dulce amor,\nHabré de estar con Él allí;\nY le diré: “Mi buen Señor,\nPor gracia yo salvado fui”.'),(831,130,'Estrofa',1,'Hoy es día de reposo,\nEl gran día de solaz;\nEs el día venturoso,\nQue nos trae dulce paz.\nEs el día Señalado,\nCon el sello del amor;\nNuestro Dios lo ha designado,\nEs el día del Señor.'),(832,130,'Estrofa',2,'Celebremos a porfía,\nAl autor de aquel gran don;\nQue nos da el festivo día,\nY se goza en el perdón.\nAceptemos hoy con gusto,\nEl descanso semanal;\nEsperando el día augusto,\nDel reposo eternal.'),(833,130,'Estrofa',3,'Trabajar es la sentencia,\nDe la antigua creación;\nY morir, la consecuencia,\nDe la prevaricación.\nMás reposo y vida estable,\nDios nos da quitando el mal;\nY su amor inescrutable,\nDe la gracia es el raudal.'),(834,130,'Estrofa',4,'Los que a Ti nos acercamos,\nPor Jesús, Dios de verdad;\nHoy alegres proclamamos,\nTu justicia y tu bondad.\nEn los fastos de la historia,\nSiempre se celebrará;\nY en tu pueblo tu memoria,\nPor los siglos durará.'),(835,131,'Estrofa',1,'Feliz momento en que escogí,\nServirte, mi Señor y Dios;\nPreciso es que mi gozo en Ti,\nLo muestre hoy con obra y voz.'),(836,131,'Coro',2,'¡Soy feliz! ¡Soy feliz!\nY en su favor me gozaré,\nEn libertad y luz me vi,\nCuando triunfó en mí la fe;\nY el raudal carmesí,\nSalud de mi alma, enferma fue.'),(837,131,'Estrofa',3,'¡Pasó! Mi gran deber cumplí,\nDe Cristo soy, y mío es Él;\nMe atrajo, con placer seguí,\nSu voz conoce todo fiel.'),(838,131,'Coro',4,'¡Soy feliz! ¡Soy feliz!\nY en su favor me gozaré,\nEn libertad y luz me vi,\nCuando triunfó en mí la fe;\nY el raudal carmesí,\nSalud de mi alma, enferma fue.'),(839,131,'Estrofa',5,'Reposa, débil corazón,\nA tus contiendas por ya fin;\nHallé más noble posesión,\nY parte en superior festín.'),(840,131,'Coro',6,'¡Soy feliz! ¡Soy feliz!\nY en su favor me gozaré,\nEn libertad y luz me vi,\nCuando triunfó en mí la fe;\nY el raudal carmesí,\nSalud de mi alma, enferma fue.'),(841,132,'Estrofa',1,'De Jesús el nombre, mi labio nunca calle,\nEl lirio es del valle, estrella del albor;\nEs el Rey de gloria, y en mi corazón,\nDe su amor la historia, por siempre es mi canción.'),(842,132,'Coro',2,'Es un canto de libertad, y su melodía resuena;\nEs un canto de libertad, que de paz el alma llena.\nEs un canto de libertad, proclamarlo Él me ordena;\n¡Aleluya! ¡Aleluya! Es un canto de libertad.'),(843,132,'Estrofa',3,'Redimióme Cristo de mi pecar funesto,\nY en mi boca ha puesto un canto de loor;\nÉl es mi Maestro, mi dueño y mi Señor,\nMi Salvador, y el vuestro, por su divino amor.'),(844,132,'Coro',4,'Es un canto de libertad, y su melodía resuena;\nEs un canto de libertad, que de paz el alma llena.\nEs un canto de libertad, proclamarlo Él me ordena;\n¡Aleluya! ¡Aleluya! Es un canto de libertad.'),(845,132,'Estrofa',5,'Ángeles entonan de salvación el canto,\nEl canto es por el santo, el salvó por su amor;\nAntes al pecado servía en oscuridad,\nMas ahora he hallado en Él la libertad.'),(846,132,'Coro',6,'Es un canto de libertad, y su melodía resuena;\nEs un canto de libertad, que de paz el alma llena.\nEs un canto de libertad, proclamarlo Él me ordena;\n¡Aleluya! ¡Aleluya! Es un canto de libertad.'),(847,133,'Estrofa',1,'Jesús es mi Rey soberano,\nMi gozo es cantar su loor;\nEs Rey y me ve cual hermano,\nEs Rey y me imparte su amor.\nDejando su trono de gloria,\nMe vino a sacar de escoria.\n¡Y yo soy feliz, y yo soy feliz por Él!'),(848,133,'Estrofa',2,'Jesús es mi Amigo anhelado,\nEn sombras o en luz siempre va;\nPaciente y humilde a mi lado,\nAyuda y consuelo me da.\nPor eso constante le sigo,\nporque Él es mi Rey y mi Amigo.\n¡Y yo soy feliz, y yo soy feliz por Él!'),(849,133,'Estrofa',3,'Señor, ¿Que‚ pudiera yo darte,\nPor tanta bondad para mí?\n¿Te basta serviste y amarte?\nEs todo entregarme yo a Ti?\n¡Entonces acepta mi vida,\nQue a Ti solo queda rendida!\n¡Y yo soy feliz, y yo soy feliz por Él!'),(850,134,'Estrofa',1,'En presencia estar de Cristo,\nVer su rostro, ¿Qué será;\nCuando al fin, en pleno gozo,\nMi alma le contemplará?'),(851,134,'Coro',2,'Cara a cara espero verle,\nCuando venga en gloria y luz;\nYa muy pronto cara a cara,\nHe de ver a mi Jesús.'),(852,134,'Estrofa',3,'Sólo tras oscuro velo,\nHoy lo puedo contemplar;\nMas al descender del cielo,\nÉl su gloria ha de mostrar.'),(853,134,'Coro',4,'Cara a cara espero verle,\nCuando venga en gloria y luz;\nYa muy pronto cara a cara,\nHe de ver a mi Jesús.'),(854,134,'Estrofa',5,'¡Cuánto gozo habrá con Cristo,\nCuando no haya más dolor;\nCuando cesen los peligros,\nAl abrigo de su amor!'),(855,134,'Coro',6,'Cara a cara espero verle,\nCuando venga en gloria y luz;\nYa muy pronto cara a cara,\nHe de ver a mi Jesús.'),(856,134,'Estrofa',7,'Cara a cara ¡Cuán glorioso,\nHa de ser con Él vivir!\nVer el rostro de quien quiso,\nNuestra almas redimir.'),(857,134,'Coro',8,'Cara a cara espero verle,\nCuando venga en gloria y luz;\nYa muy pronto cara a cara,\nHe de ver a mi Jesús.'),(858,135,'Estrofa',1,'¡Piedad, oh, Santo Dios, piedad!\nPiedad te implora el corazón;\n¡Oh, lávame de mi maldad,\nY dame gozo, paz, perdón!'),(859,135,'Estrofa',2,'Mis rebeliones graves son,\nSon todas sólo contra Ti;\nMas crea un nuevo corazón,\nY un nuevo espíritu en mí.'),(860,135,'Estrofa',3,'No quieres sacrificio, más\nQue el humillado corazón,\nMi ofrenda no despreciarás,\nYa que eres todo compasión.'),(861,135,'Estrofa',4,'Oh, sálvame con tu poder,\nQue mi esperanza es sólo en Ti,\nTemblando aguardo tu perdón,\n¡Sé compasivo hacia mí!'),(862,136,'Estrofa',1,'Loor a Ti, mi Dios, en esta noche,\nPor todas tus bondades de este día;\n//¡Oh, guárdame! Y que tus potentes alas,\nSean por siempre la defensa mía.//'),(863,136,'Estrofa',2,'De cuantas faltas hoy he cometido,\nPerdóname, Señor, por tu hijo amado;\n//Contigo, con el prójimo conmigo,\nQuede antes de dormir, reconciliado.//'),(864,136,'Estrofa',3,'Enséñame a vivir, que no me espante,\nLa tumba más que el lecho de reposo;\n//Enséñame a morir, para que pueda,\nEl día postrero, despertar glorioso.//'),(865,136,'Estrofa',4,'¡Oh, logre reposar en Ti mi alma!\nMis párpados los cierre dulce sueño;\n//Sueño que pueda más vigor prestarme,\nPara servirte, al despertar, mi dueño.//'),(866,137,'Estrofa',1,'“De tu cántaro dame, dame tú de deber”,\nA la samaritana, dijo un día Jesús;\n“¿Por qué‚ siendo Judío me diriges la voz?”\nRespondió con vehemencia la mujer que\nIgnoraba la grandeza de Dios.'),(867,137,'Estrofa',2,'“!Oh!, si tú conocieses este don que es de Dios\nY quien viene a rogarte que le des de deber,\nQuizás tú pedirías y Él podríate dar,\nAgua más deleitosa que en los pozos terrenos\nNo podrás encontrar”.'),(868,137,'Estrofa',3,'“Quien bebiere de esta agua volver a tener sed,\nMas aquel que bebiere de la que le daré,\nPara siempre, declaro que más sed no tendrá;\nMas será en él la fuente que para vida\nEterna con poder saltará.”'),(869,138,'Estrofa',1,'De mi tierno Salvador, cantaré el inmenso amor;\nGloriaréme en el favor de Jesús;\nDe tinieblas me llamó, de cadenas me libró,\n¡De la muerte me salvó mi Jesús!'),(870,138,'Coro',2,'¡Mi Jesús! ¡Mi Jesús!\n¡Cuán precioso es el nombre de Jesús!\nCon su sangre me limpió, De su gozo me llenó,\nDe su vida me dotó, mi Jesús.'),(871,138,'Estrofa',3,'¡Oh, que‚ triste condición, del impío corazón!\nMe salvó de perdición mi Jesús;\nDel pecado el perdón, de la ruina salvación,\nPor tristeza, bendición, dio Jesús.'),(872,138,'Coro',4,'¡Mi Jesús! ¡Mi Jesús!\n¡Cuán precioso es el nombre de Jesús!\nCon su sangre me limpió, De su gozo me llenó,\nDe su vida me dotó, mi Jesús.'),(873,138,'Estrofa',5,'En el mundo al vagar, solitario, sin hogar,\nNo sabía que dulce paz da Jesús,\nMas las lágrimas de ayer han pasado y placer\nYa comienzo a tener en Jesús.'),(874,138,'Coro',6,'¡Mi Jesús! ¡Mi Jesús!\n¡Cuán precioso es el nombre de Jesús!\nCon su sangre me limpió, De su gozo me llenó,\nDe su vida me dotó, mi Jesús.'),(875,138,'Estrofa',7,'De lo falso, a su verdad, de lo inmundo, a santidad;\nYa me trajo la bondad de Jesús;\nHechos fuertes en virtud de su perennal salud, Himnos dad de gratitud a Jesús.'),(876,138,'Coro',8,'¡Mi Jesús! ¡Mi Jesús!\n¡Cuán precioso es el nombre de Jesús!\nCon su sangre me limpió, De su gozo me llenó,\nDe su vida me dotó, mi Jesús.'),(877,139,'Estrofa',1,'Cuando la trompeta suene en aquel día final;\nY que el alba eterna rompa en claridad,\nCuando las naciones salvas a su patria lleguen ya,\nY que sea pasada lista, allí he de estar.'),(878,139,'Coro',2,'Cuando allá se pase lista,\nCuando allá se pase lista;\nCuando allá se pase lista,\nA mi nombre yo feliz responderé.'),(879,139,'Estrofa',3,'En aquel día sin nieblas en que muerte ya no habrá;\nY su gloria el Salvador impartirá;\nCuando los llamados entren de Jesús al Reino ya,\nY que sea pasada lista, allí he de estar.'),(880,139,'Coro',4,'Cuando allá se pase lista,\nCuando allá se pase lista;\nCuando allá se pase lista,\nA mi nombre yo feliz responderé.'),(881,139,'Estrofa',5,'Trabajemos por el Maestro desde el alba al vislumbrar;\nSiempre hablemos de su amor y fiel bondad.\nCuando todo aquí fenezca, y nuestra obra cese ya,\nY que sea pasada lista, allí he de estar.'),(882,139,'Coro',6,'Cuando allá se pase lista,\nCuando allá se pase lista;\nCuando allá se pase lista,\nA mi nombre yo feliz responderé.'),(883,140,'Estrofa',1,'Por fe en Cristo, el Redentor,\nSe salva hoy el pecador;\nAunque sin merecer perdón,\nRecibe plena salvación.'),(884,140,'Coro',2,'¡Oh, gracia excelsa del amor!\nQue Dios perdone al pecador;\nSi quieres presto confesar,\nTus culpas y en Jesús confiar,\nEn cuyo nombre hay salvación,\nPues Él obró la redención.'),(885,140,'Estrofa',3,'La vida antigua ya pasó,\nY todo en nuevo se tornó;\nY aunque nada tenga aquí,\nGozar con Él podré‚ allí.'),(886,140,'Coro',4,'¡Oh, gracia excelsa del amor!\nQue Dios perdone al pecador;\nSi quieres presto confesar,\nTus culpas y en Jesús confiar,\nEn cuyo nombre hay salvación,\nPues Él obró la redención.'),(887,140,'Estrofa',5,'Aquí cual peregrino es,\nUn Reino al fin tendré‚ después;\nAllí en Sión con mi Jesús,\nGozar podré‚ de paz y luz.'),(888,140,'Coro',6,'¡Oh, gracia excelsa del amor!\nQue Dios perdone al pecador;\nSi quieres presto confesar,\nTus culpas y en Jesús confiar,\nEn cuyo nombre hay salvación,\nPues Él obró la redención.'),(889,141,'Estrofa',1,'Da lo mejor al Maestro,\nTu fuerza, tu juventud;\nTodo el fervor de tu alma,\nTu exuberante salud.\nDueño sea Él de tu vida,\nSírvele con fe y amor;\nTodo a su gracia lo debes,\n¡Dale a Jesús lo mejor!'),(890,141,'Coro',2,'¡Da lo mejor al Maestro,\nA combatir por Él ven:\nSé‚ paladín decidido,\nDe la verdad y del bien!'),(891,141,'Estrofa',3,'Da lo mejor al Maestro,\nDale la flor de tu edad;\nY haz de tus años maduros,\nFruto de santa piedad.\nDale una noble obediencia,\nDale un ardiente fervor;\nDale una limpia conciencia,\nDale tu heroico valor.'),(892,141,'Coro',4,'¡Da lo mejor al Maestro,\nA combatir por Él ven:\nSé‚ paladín decidido,\nDe la verdad y del bien!'),(893,141,'Estrofa',5,'Da lo mejor al Maestro,\nEntrégale el corazón;\nNadie como Él te ha amado,\nDigno es de tu devoción.\nRico y feliz quiere hacerte,\nEs gran tesoro su amor;\nDeja que llene tu alma,\nDale a Jesús lo mejor.'),(894,141,'Coro',6,'¡Da lo mejor al Maestro,\nA combatir por Él ven:\nSé‚ paladín decidido,\nDe la verdad y del bien!'),(895,142,'Estrofa',1,'Ya la noche con sus sombras se alejó,\nLa mañana vino ya;\nY viviendo en plena luz me encuentro yo,\nLa mañana vino ya.'),(896,142,'Coro',2,'La mañana vino ya en mi corazón,\nToda sombra ha disipado mi Señor;\nY cantando alegre voy,\nPorque con Jesús estoy,\nLa mañana vino ya en mi corazón.'),(897,142,'Estrofa',3,'Hace Cristo en mundo nuevo para mí,\nLa mañana vino ya;\nY por Él y en Él la vida es grande aquí,\nLa mañana vino ya.'),(898,142,'Coro',4,'La mañana vino ya en mi corazón,\nToda sombra ha disipado mi Señor;\nY cantando alegre voy,\nPorque con Jesús estoy,\nLa mañana vino ya en mi corazón.'),(899,142,'Estrofa',5,'Una vida esplendorosa viviré,\nLa mañana vino ya;\nPorque en Cristo, mi Señor, me apoyaré,\nLa mañana vino ya.'),(900,142,'Coro',6,'La mañana vino ya en mi corazón,\nToda sombra ha disipado mi Señor;\nY cantando alegre voy,\nPorque con Jesús estoy,\nLa mañana vino ya en mi corazón.'),(901,143,'Estrofa',1,'¿De Jesús no escuchas tierno llamamiento?\n“Ven a mí, pecador”;\nQuiere darte tu perdón, paz y contento,\nVen a Él, pecador.'),(902,143,'Coro',2,'Te llama con un tierno acento,\nTu vida quiere redimir;\nOye del Señor el tierno llamamiento:\n“Ven a mí, ven a mí”.'),(903,143,'Estrofa',3,'De tus penas pronto puedes olvidarte,\nVen a Él, ven a Él;\nPorque de ellas Cristo alivio puede darte,\nVen a Él, ven a Él.'),(904,143,'Coro',4,'Te llama con un tierno acento,\nTu vida quiere redimir;\nOye del Señor el tierno llamamiento:\n“Ven a mí, ven a mí”.'),(905,143,'Estrofa',5,'Solo Él puede pleno gozo concederte,\nVen a Él, ven a Él;\nEn la dura cruz por ello vio la muerte,\nVen a Él, ven a Él.'),(906,143,'Coro',6,'Te llama con un tierno acento,\nTu vida quiere redimir;\nOye del Señor el tierno llamamiento:\n“Ven a mí, ven a mí”.'),(907,143,'Estrofa',7,'No su voz de amor escuches con desprecio,\nVen a Él, ven a Él;\nPor tu salvación pagó divino precio,\nVen a Él, ven a Él.'),(908,143,'Coro',8,'Te llama con un tierno acento,\nTu vida quiere redimir;\nOye del Señor el tierno llamamiento:\n“Ven a mí, ven a mí”.'),(909,144,'Estrofa',1,'No hay satisfacción en riqueza mundanal,\nSi se niega al Salvador;\nEsta vida es sólo un sueño terrenal,\nCuando andamos sin su amor.'),(910,144,'Coro',2,'Treinta piezas de plata dieron por Jesús,\nTreinta piezas de plata, por Él quien es la luz;\nYo también tengo culpa de su muerte cruel,\nY te ruego, oh Dios, me perdones por ser tan infiel.'),(911,144,'Estrofa',3,'Su mansión de gloria dejó mi Redentor,\nPor salvar al hombre vil;\nMas yo despreciaba su incomparable amor,\nFui hundido en males mil.'),(912,144,'Coro',4,'Treinta piezas de plata dieron por Jesús,\nTreinta piezas de plata, por Él quien es la luz;\nYo también tengo culpa de su muerte cruel,\nY te ruego, oh Dios, me perdones por ser tan infiel.'),(913,145,'Estrofa',1,'En Jesucristo, mártir de paz,\nEn horas negras de tempestad;\nHallan las almas dulce solaz,\nGrato consuelo, felicidad.'),(914,145,'Coro',2,'¡Gloria cantemos al Redentor!\nQue por nosotros quiso morir;\nLa santa gracia de el Salvador,\nSiempre dirija nuestro vivir.'),(915,145,'Estrofa',3,'En los peligros, en el dolor,\nA cada paso su protección;\nCalma le infunde, santo vigor,\nNuevos alientos al corazón.'),(916,145,'Coro',4,'¡Gloria cantemos al Redentor!\nQue por nosotros quiso morir;\nLa santa gracia de el Salvador,\nSiempre dirija nuestro vivir.'),(917,145,'Estrofa',5,'Cuando en la lucha falta la fe,\nY el alma siente desfallecer;\nCristo nos dice: “Yo os colmaré,\nDe rica gracia, santo poder”.'),(918,145,'Coro',6,'¡Gloria cantemos al Redentor!\nQue por nosotros quiso morir;\nLa santa gracia de el Salvador,\nSiempre dirija nuestro vivir.'),(919,146,'Estrofa',1,'Hay un huerto do Cristo me espera,\nHay un sitio de consolación;\n¡Cuán radiante es la luz de su presencia!\nEn el huerto de dulce oración'),(920,146,'Coro',2,'¡Oh qué hermoso es el huerto de oración!\nCuando a solas estoy con mi Señor;\nY se alienta en mí la fe, en presencia de mi Rey,\n¡Oh qué hermoso es el huerto de oración!'),(921,146,'Estrofa',3,'Hay un huerto do Cristo me acoge,\nJunto a Él a gozar comunión;\nSiempre escucho su voz tan amorosa,\nEn el huerto de dulce oración.'),(922,146,'Coro',4,'¡Oh qué hermoso es el huerto de oración!\nCuando a solas estoy con mi Señor;\nY se alienta en mí la fe, en presencia de mi Rey,\n¡Oh qué hermoso es el huerto de oración!'),(923,146,'Estrofa',5,'Hay un huerto do Cristo te invita,\nPara darte pureza y perdón;\nVen a Él, y a sus plantas pon tus cargas,\nEn el huerto de dulce oración.'),(924,146,'Coro',6,'¡Oh qué hermoso es el huerto de oración!\nCuando a solas estoy con mi Señor;\nY se alienta en mí la fe, en presencia de mi Rey,\n¡Oh qué hermoso es el huerto de oración!'),(925,147,'Estrofa',1,'Es el tiempo de la siega y tú sin vacilar,\nDeclarando con holgura: “No hay que trabajar”;\nMientras tanto que el Maestro te vuelve a llamar,\n¡Joven, joven, ven, trabaja ya!'),(926,147,'Coro',2,'Ven, y ve los campos blancos, como están,\nAguardando manos que lo segarán;\n¡Joven, despierta! Hazlo pronto y alerta,\nSé el primero en decirle: “Heme aquí Señor”,\nPor doquier se inclina la madura mies,\nQue las auras mueven, y ¡qué‚ bella es!;\n¡Joven despierta! Hazlo pronto y alerta,\nPocos días hay que restan para el segador.'),(927,147,'Estrofa',3,'Las gavillas que recojas, joyas de esplendor,\nBrillarán en la corona que dará el Señor,\nBusca pronto eternas joyas, Dios es premiador,\n¡Joven, joven, ven, trabaja ya!'),(928,147,'Coro',4,'Ven, y ve los campos blancos, como están,\nAguardando manos que lo segarán;\n¡Joven, despierta! Hazlo pronto y alerta,\nSé el primero en decirle: “Heme aquí Señor”,\nPor doquier se inclina la madura mies,\nQue las auras mueven, y ¡qué‚ bella es!;\n¡Joven despierta! Hazlo pronto y alerta,\nPocos días hay que restan para el segador.'),(929,147,'Estrofa',5,'Va pasando la mañana, y nunca volverá,\nPronto el tiempo de la siega aquí terminará;\nTe hallarás al fin vacío ante tu Creador,\n¡Joven, joven, ven, trabaja ya!'),(930,147,'Coro',6,'Ven, y ve los campos blancos, como están,\nAguardando manos que lo segarán;\n¡Joven, despierta! Hazlo pronto y alerta,\nSé el primero en decirle: “Heme aquí Señor”,\nPor doquier se inclina la madura mies,\nQue las auras mueven, y ¡qué‚ bella es!;\n¡Joven despierta! Hazlo pronto y alerta,\nPocos días hay que restan para el segador.'),(931,148,'Estrofa',1,'Es Jesucristo mi todo, grato es cantar su loor,\n¡Oh, cuán sublime e infinito es su divino amor!\nCuando me vio errabundo, cual hijo pródigo\nVino a buscar y a salvarme, a su redil me llevó.'),(932,148,'Coro',2,'¡Cristo! ¡Cristo! Tú eres mi Salvador,\n¡Cristo! ¡Cristo! tuyo seré, Señor;\nTe seguiré‚ por doquiera, si Tú guiando vas,\nY al terminar mi carrera en gloria veré tu faz.'),(933,148,'Estrofa',3,'Cristo es el Lirio del valle, la Rosa es de Sarón,\nCristo es el astro esplendente, la Roca de Salvación;\nÉl es la fuente de vida y gozo eternal,\nYa satisface mi alma con el maná celestial.'),(934,148,'Coro',4,'¡Cristo! ¡Cristo! Tú eres mi Salvador,\n¡Cristo! ¡Cristo! tuyo seré, Señor;\nTe seguiré‚ por doquiera, si Tú guiando vas,\nY al terminar mi carrera en gloria veré tu faz.'),(935,148,'Estrofa',5,'Cristo fue puesto en pesebre, la amarga copa bebió,\nCual inocente Cordero, en el Calvario murió;\nResucitó de la tumba, y al cielo ascendió,\nMas pronto viene en gloria, esta promesa nos dio'),(936,148,'Coro',6,'¡Cristo! ¡Cristo! Tú eres mi Salvador,\n¡Cristo! ¡Cristo! tuyo seré, Señor;\nTe seguiré‚ por doquiera, si Tú guiando vas,\nY al terminar mi carrera en gloria veré tu faz.'),(937,149,'Estrofa',1,'En los días de prueba y de lucha cruel,\nMi alma auxilio jamás halló;\nPero vino presto el amigo fiel,\nCon su diestra la mía estrechó.'),(938,149,'Coro',2,'Con su diestra la mía estrechó,\nCon su diestra la mía estrechó;\nEn los días de prueba y de oscuridad,\nCon su diestra la mía estrechó.'),(939,149,'Estrofa',3,'Si cansado y triste en el mundo estoy,\nY me siento desfallecer;\nÉl se acerca luego doquier yo voy,\nCon su diestra la mía estrechó.'),(940,149,'Coro',4,'Con su diestra la mía estrechó,\nCon su diestra la mía estrechó;\nEn los días de prueba y de oscuridad,\nCon su diestra la mía estrechó.'),(941,149,'Estrofa',5,'Y al pasar el valle de sombra cruel,\nPor la senda que Él cruzó;\nPuedo yo exclamar con acento fiel,\nCon su diestra la mía estrechó.'),(942,149,'Coro',6,'Con su diestra la mía estrechó,\nCon su diestra la mía estrechó;\nEn los días de prueba y de oscuridad,\nCon su diestra la mía estrechó.'),(943,150,'Estrofa',1,'Fuente de la vida eterna\nY de toda bendición,\nEnsalzar tu gracia tierna\nDebe todo corazón\nTu piedad inagotable\nAbundante en perdonar\nÚnico ser adorable\nGloria a Ti debemos dar.'),(944,150,'Estrofa',2,'De los cánticos celestes,\nTe quisiéramos cantar;\nEntonados por las huestes,\nQue lograste rescatar\nAlmas que a buscar viniste,\nPorque les tuviste amor;\nDe ellas te compadeciste,\nCon tiernísimo favor.'),(945,150,'Estrofa',3,'Toma nuestros corazones,\nLlénalos de tu verdad;\nDe tu Espíritu los dones\nY de toda santidad.\nGuiamos en obediencia\nHumildad, amor y fe;\nNos ampare tu clemencia\nSalvador, propicio sé.'),(946,151,'Estrofa',1,'Dad al Padre toda gloria,\nDad al Hijo todo honor;\nTributando a lo Divino.\nAlabanzas de loor.'),(947,151,'Coro',2,'¡Adoradle, adoradle\nAdorad al Salvador;\nTributable toda gloria,\nPueblo suyo por su grande amor!'),(948,151,'Estrofa',3,'Adoradle, ¡Oh Iglesia!\nPor Jesús tu Redentor;\nRescatada por su gracia,\nLibre por su grande amor.'),(949,151,'Coro',4,'¡Adoradle, adoradle\nAdorad al Salvador;\nTributable toda gloria,\nPueblo suyo por su grande amor!'),(950,151,'Estrofa',5,'Entonadle un canto nuevo.\nToda la “Iglesia de Dios”;\nCielos, tierra, mar y luna,\nTodos digan al Señor.'),(951,151,'Coro',6,'Yo te adoro, yo te adoro\nYo te adoro, buen Jesús\nYo te adoro reverente.\n¡Oh, Cordero Santo de mi Dios!'),(952,152,'Estrofa',1,'Siempre Orad, muy pronto viene Cristo.\nGuarda bien tu corazón;\nRetén firme todo lo que tienes,\nTú tendrás tu galardón'),(953,152,'Coro',2,'Siempre Orad, nos manda Cristo\ny velad en oración;\nPronto vendrá Él en las nubes\nTraerá nuestro galardón.'),(954,152,'Estrofa',3,'Siempre Orad, que si hoy viniera Cristo,\nÉl te halle en la lid:\nCon la espada suya bien templada,\nFiel por nuestro Adalid.'),(955,152,'Coro',4,'Siempre Orad, nos manda Cristo\ny velad en oración;\nPronto vendrá Él en las nubes\nTraerá nuestro galardón.'),(956,152,'Estrofa',5,'Siempre Orad. Si vive aquí velando\nEs mandato del Señor\nSin demora toma la promesa.\nDel gran fiel consolador.'),(957,152,'Coro',6,'Siempre Orad, nos manda Cristo\ny velad en oración;\nPronto vendrá Él en las nubes\nTraerá nuestro galardón.'),(958,152,'Estrofa',7,'Siempre Orad, constante y con celo,\nEjercítate en la fe\nTen el ánimo de Jesucristo\ny sus huellas sigue fiel.'),(959,152,'Coro',8,'Siempre Orad, nos manda Cristo\ny velad en oración;\nPronto vendrá Él en las nubes\nTraerá nuestro galardón.'),(960,153,'Estrofa',1,'Hoy venimos, cual hermanos\nA la cena del Señor;\ncongreguémonos, cristianos,\nRespirando tierno amor.'),(961,153,'Estrofa',2,'En memoria de su muerte,\nY la sangre que vertió;\nCelebremos el banquete,\nQue en su amor nos ordenó.'),(962,153,'Estrofa',3,'Recordando las angustias\nque por nos sufrió el Señor\nDividida está nuestra alma\nEntre el gozo y el dolor.'),(963,153,'Estrofa',4,'Invoquemos la presencia,\nDel Divino Redentor;\nQue nos mire con clemencia,\nY nos llene de su amor.'),(964,154,'Estrofa',1,'Despide hoy tu grey.\nEn paz y bendición\nY las palabras de tu ley\nConserve el corazón'),(965,154,'Estrofa',2,'Enséñanos, Señor,\nTu ley a meditar;\nVivir unidos en amor,\nY en él por siempre andar'),(966,154,'Estrofa',3,'Ayúdanos, Señor\nAl ir con firme pie\nCruzando siempre sin temor,\nEl sendero de la fe.'),(967,155,'Estrofa',1,'¡Hosanna! ¡Hosanna! ¡Hosanna!\nEl cielo y tierra es del Señor;\nLa gloria y potestad,\nY nos circunda con su amor,\nLa gloria de Jehová.'),(968,155,'Estrofa',2,'Alzad, pues himnos de loor,\nQue es grato el Sumo Bien,\nY a Dios rindamos todo honor\nAhora y siempre. Amén.'),(969,155,'Estrofa',3,'A Dios rindamos todo honor,\n¡Todo honor, todo honor!\nA Dios rindamos todo honor,\nAhora y siempre. Amén'),(970,156,'Estrofa',1,'Las Sagradas Escrituras nos enseñan a diezmar,\nComo bueno para el hombre fiel;\nPues Jehová se alegra siempre,\nCuando el hombre sabe dar\nY con creces recompensa a él'),(971,156,'Coro',2,'Cuán eterno gozo al hombre da,\nDar su diezmos todos a Jehová:\nPaz habrá en su corazón,\nGrande y fiel satisfacción,\nY abundancia de fidelidad.'),(972,156,'Estrofa',3,'Nuestros diezmos Dios nos pide,\nDe lo que abundante Él da,\nY entregarlo para su obra aquí;\nEl os manda que a la Iglesia,\nLos debemos de llevar\nPara su distribución allí.'),(973,156,'Coro',4,'Cuán eterno gozo al hombre da,\nDar su diezmos todos a Jehová:\nPaz habrá en su corazón,\nGrande y fiel satisfacción,\nY abundancia de fidelidad.'),(974,156,'Estrofa',5,'Nuestra plata, nuestro tiempo\nNuestro amor, nuestro vivir\nDios anhela le ofrendemos hoy,\nEl promete por los diezmos\nBendiciones dar sin fin\nSi leales somos al Señor.'),(975,156,'Coro',6,'Cuán eterno gozo al hombre da,\nDar su diezmos todos a Jehová:\nPaz habrá en su corazón,\nGrande y fiel satisfacción,\nY abundancia de fidelidad.'),(976,157,'Estrofa',1,'Jubilosas nuestras voces,\nelevemos con fervor;\nPara dar la bienvenida,\nA los siervos del Señor'),(977,157,'Coro',2,'Bienvenidos, bienvenidos,\nAdalides de Jehová\nParabienes no fingidos,\nLa congregación os da.'),(978,157,'Estrofa',3,'Bienvenidos los heraldos\nDe la fe y de la verdad\nA quien nuestros corazones\nHoy les brindan amistad'),(979,157,'Coro',4,'Bienvenidos, bienvenidos,\nAdalides de Jehová\nParabienes no fingidos,\nLa congregación os da.'),(980,157,'Estrofa',5,'Bienvenidos los soldados,\nDe las huestes de Jesús\nLos que luchan denodados\nPor el triunfo de su Luz'),(981,157,'Coro',6,'Bienvenidos, bienvenidos,\nAdalides de Jehová\nParabienes no fingidos,\nLa congregación os da.'),(982,157,'Estrofa',7,'Uno solo es nuestro anhelo\nTrabajemos con tesón\nPor hacer que al Rey del cielo\nReine en cada corazón'),(983,157,'Coro',8,'Bienvenidos, bienvenidos,\nAdalides de Jehová\nParabienes no fingidos,\nLa congregación os da.'),(984,158,'Estrofa',1,'Más Santidad dame,\nMás odio al mal\nMás calma en las penas\nMás alto ideal\nMás fe en mi Maestro,\nMás consagración\nMás celo en servirle\nMás grata oración'),(985,158,'Estrofa',2,'Más prudente hazme\nMás sabio en Él\nMás firme en su causa\nMás fuerte y más fiel\nMás recto en la vida,\nMás triste al pecar\nMás humilde hijo\nMás pronto en amar.'),(986,158,'Estrofa',3,'Más pureza dame\nMás fuerza en Jesús\nMás de su dominio,\nMás paz en la cruz\nMás rica esperanza\nMás obrar aquí\nMás ansia del Reino\nMás gozo allí'),(987,159,'Estrofa',1,'Los niños son de Cristo,\nÉl es su Salvador;\nSon joyas muy preciosas,\nComprólas por su amor'),(988,159,'Coro',2,'Joyas, joyas, joyas\nJoyas de el Salvador;\nEstán en esta tierra\nCual luz y dulce amor'),(989,159,'Estrofa',3,'Los niños son tesoros.\nPues que de Cristo son;\nLuz refulgente esparcen.\nEn horas de aflicción'),(990,159,'Coro',4,'Joyas, joyas, joyas\nJoyas de el Salvador;\nEstán en esta tierra\nCual luz y dulce amor'),(991,159,'Estrofa',5,'Los niños son estrellas\nDe grata claridad\nQuiere Jesús que anuncien.\nAl mundo su verdad.'),(992,159,'Coro',6,'Joyas, joyas, joyas\nJoyas de el Salvador;\nEstán en esta tierra\nCual luz y dulce amor'),(993,159,'Estrofa',7,'Los niños son de Cristo.\nCon ellos reinará\nY con Él para siempre\nDichosos vivirán'),(994,159,'Coro',8,'Joyas, joyas, joyas\nJoyas de el Salvador;\nEstán en esta tierra\nCual luz y dulce amor'),(995,160,'Estrofa',1,'Tu dejaste tu trono y corona por mí,\nAl venir a Belén a nacer;\nMas a Ti no fue dado el entrar al mesón,\nY en pesebre te hicieron nacer.'),(996,160,'Coro',2,'Ven a mi corazón, ¡Oh Cristo!\nPues en el hay lugar para Ti;\nVen a mi corazón. ¡Oh. Cristo! ven,\nPues en el hay lugar para Ti;'),(997,160,'Estrofa',3,'Alabanzas celestes los Ángeles dan.\nEn que rinden al Verbo loor;\nMas humilde viniste a la tierra. Señor.\nA dar vida al mas vil pecador.'),(998,160,'Coro',4,'Ven a mi corazón, ¡Oh Cristo!\nPues en el hay lugar para Ti;\nVen a mi corazón. ¡Oh. Cristo! ven,\nPues en el hay lugar para Ti;'),(999,160,'Estrofa',5,'Siempre pueden las zorras sus cuevas tener,\nY las aves sus nidos también;\nMas el Hijo del Hombre no tuvo lugar,\nEn el cual reclinara su sien.'),(1000,160,'Coro',6,'Ven a mi corazón, ¡Oh Cristo!\nPues en el hay lugar para Ti;\nVen a mi corazón. ¡Oh. Cristo! ven,\nPues en el hay lugar para Ti;'),(1001,160,'Estrofa',7,'Tu viniste, Señor, con tu gran bendición,\npara dar libertad y salud;\nMas con odio y desprecio te hicieron morir,\nAunque vieron tu amor y virtud.'),(1002,160,'Coro',8,'Ven a mi corazón, ¡Oh Cristo!\nPues en el hay lugar para Ti;\nVen a mi corazón. ¡Oh. Cristo! ven,\nPues en el hay lugar para Ti;'),(1003,161,'Estrofa',1,'Cuando estoy triste con gran terror,\nCuando me abate cruel el dolor,\nViene a mi lado mi buen Señor,\nCuando lo anhelo más.'),(1004,161,'Coro',2,'Cuando lo anhelo más,\nCuando lo anhelo más;\nViene Jesús a darme su luz,\nCuando lo anhelo más.'),(1005,161,'Estrofa',3,'Cuando a mi lado veo falsedad\nCristo me brinda fiel su amistad\nLas aflicciones torna en bondad\nCuando lo anhelo más'),(1006,161,'Coro',4,'Cuando lo anhelo más,\nCuando lo anhelo más;\nViene Jesús a darme su luz,\nCuando lo anhelo más.'),(1007,161,'Estrofa',5,'Si en el camino débil estoy\n“Ten fe” -me dice- “gracia te doy”,\nFuerzas me infunde doquier yo voy,\nCuando lo anhelo más.'),(1008,161,'Coro',6,'Cuando lo anhelo más,\nCuando lo anhelo más;\nViene Jesús a darme su luz,\nCuando lo anhelo más.'),(1009,162,'Estrofa',1,'Cansado y triste vine al Salvador,\nMi culpa É1 llevó, mi culpa Él llevó;\nMi eterna dicha hallé en su amor,\nMi culpa Él llevó.'),(1010,162,'Coro',2,'Mi culpa Él llevó, mi culpa Él llevó,\nAlegre siempre cantaré,\nal Señor, gozoso alabaré;\nPorque Él me salvó.'),(1011,162,'Estrofa',3,'Borrados todos mis pecados son,\nMi culpa Él llevó, Mi culpa Él llevó;\nA Él feliz, elevo mi canción,\nmi culpa Él llevó.'),(1012,162,'Coro',4,'Mi culpa Él llevó, mi culpa Él llevó,\nAlegre siempre cantaré,\nal Señor, gozoso alabaré;\nPorque Él me salvó.'),(1013,162,'Estrofa',5,'Ya vivo libre de condenación,\nMi culpa Él llevó, mi culpa Él llevó;\nSu dulce paz tengo en mi corazón,\nmi culpa el llevó.'),(1014,162,'Coro',6,'Mi culpa Él llevó, mi culpa Él llevó,\nAlegre siempre cantaré,\nal Señor, gozoso alabaré;\nPorque Él me salvó.'),(1015,162,'Estrofa',7,'Si vienes hoy a Cristo, pecador,\nTu culpa llevará, tu culpa llevará;\nPerdón tendrás si acudes al Señor,\ntu culpa llevará.'),(1016,162,'Coro',8,'Tu culpa llevará, tu culpa llevará,\nY limpiará tu corazón;\ny dirás feliz en tu canción:\nMi culpa Él llevó.'),(1017,163,'Estrofa',1,'El Rey que viene cerca está,\nEl mismo que en la cruz murió;\nMas solo viene a establecer.\nSu Reino eternal.'),(1018,163,'Coro',2,'Cerca está, cerca está,\nA las puertas mismas llama ya;\nViene presto, viene presto,\nA las puertas llega ya.'),(1019,163,'Estrofa',3,'De su venida vemos ya,\nSeñales muchas por doquier;\nY pronto el alba eternal,\nPodrán los pueblos ver.'),(1020,163,'Coro',4,'Cerca está, cerca está,\nA las puertas mismas llama ya;\nViene presto, viene presto,\nA las puertas llega ya.'),(1021,163,'Estrofa',5,'Después de atar a Satanás,\nDe Cristo el Reino empezará;\nSerá el gran Reino de paz.\nCon Cristo nuestro Rey'),(1022,163,'Coro',6,'Cerca está, cerca está,\nA las puertas mismas llama ya;\nViene presto, viene presto,\nA las puertas llega ya.'),(1023,163,'Estrofa',7,'Después del Reino Milenial,\nEl Hijo a Dios entregará;\nSu reino sin la muerte atroz,\nLo cual quitado habrá'),(1024,163,'Coro',8,'Cerca está, cerca está,\nA las puertas mismas llama ya;\nViene presto, viene presto,\nA las puertas llega ya.'),(1025,164,'Estrofa',1,'Bajo sus alas seguro descanso,\nAunque anochece y amaga el turbión,\nEn Él confío, su abrazo me guarda,\nHijo soy de su eternal redención'),(1026,164,'Coro',2,'Salvo en Jesús, Salvo en Jesús,\n¿Quien de Él podrá apartarme?;\nBajo sus alas mi alma estará,\nSalva y segura por siempre.'),(1027,164,'Estrofa',3,'Bajo sus alas eterno refugio,\nTanto lo anhela este leal corazón:\nSi por mi herida no hay cura en la tierra,\nCristo me alivia y me da bendición.'),(1028,164,'Coro',4,'Salvo en Jesús, Salvo en Jesús,\n¿Quien de Él podrá apartarme?;\nBajo sus alas mi alma estará,\nSalva y segura por siempre.'),(1029,164,'Estrofa',5,'Bajo sus alas, placer indecible,\nMe escondo aquí mientras pase mi afán;\nFiel protección de mi fiel enemigo,\nPaz y salud me proporcionarán.'),(1030,164,'Coro',6,'Salvo en Jesús, Salvo en Jesús,\n¿Quien de Él podrá apartarme?;\nBajo sus alas mi alma estará,\nSalva y segura por siempre.'),(1031,165,'Estrofa',1,'Por mi integridad, Tu me juzgarás,\nEres mi justiciero fiel;\nTu mi corazón examinarás,\nBondadoso Dios de Israel,'),(1032,165,'Coro',2,'Escudriña mi corazón,\nExamina mi corazón,\nManos limpias yo alzaré a Ti,\nEscudriña mi corazón'),(1033,165,'Estrofa',3,'Escogí, Señor, Tu verdad sin par,\nLa maldad siempre aborrecí;\nY mi corazón Tu podrás guardar,\nEn feliz comunión en Ti.'),(1034,165,'Coro',4,'Escudriña mi corazón,\nExamina mi corazón,\nManos limpias yo alzaré a Ti,\nEscudriña mi corazón'),(1035,165,'Estrofa',5,'Yo de Ti jamás me podré ocultar,\nDonde voy estarás doquier;\nVes en sombras como en la claridad,\nDonde esté, tu me puedes ver.'),(1036,165,'Coro',6,'Escudriña mi corazón,\nExamina mi corazón,\nManos limpias yo alzaré a Ti,\nEscudriña mi corazón'),(1037,165,'Estrofa',7,'Cristo escudriña mi corazón,\nMis ideas así probar;\nTu me librarás de la trasgresión,\nY tu luz me podrá salvar .'),(1038,165,'Coro',8,'Escudriña mi corazón,\nExamina mi corazón,\nManos limpias yo alzaré a Ti,\nEscudriña mi corazón'),(1039,165,'Estrofa',9,'¡Oh! Señor Jesús con sinceridad,\nQuiero ir yo en pos de Ti;\nQuiero yo tu luz, quiero tu verdad,\nRedentor eres para mi.'),(1040,165,'Coro',10,'Escudriña mi corazón,\nExamina mi corazón,\nManos limpias yo alzaré a Ti,\nEscudriña mi corazón'),(1041,166,'Estrofa',1,'Me guía Él, con cuanto amor,\nMe guía Siempre mi Señor;\nAl ver mi esfuerzo en serle fiel,\nCon cuanto amor me Guía Él.'),(1042,166,'Coro',2,'Me Guía Él me guía Él,\nCon cuanto amor me guía Él;\nNo abrigo dudas ni temor,\nPues me conduce el buen pastor.'),(1043,166,'Estrofa',3,'En el abismo del dolor,\nO en donde brille el sol mejor;\nEn dulce paz o en lucha cruel,\nCon gran bondad me guía Él.'),(1044,166,'Coro',4,'Me Guía Él me guía Él,\nCon cuanto amor me guía Él;\nNo abrigo dudas ni temor,\nPues me conduce el buen pastor.'),(1045,166,'Estrofa',5,'Tu mano quiero yo tomar,\nJesús, y nunca vacilar;\nPues sólo a quien te sigue fiel,\nSe oyó decir me guía Él.'),(1046,166,'Coro',6,'Me Guía Él me guía Él,\nCon cuanto amor me guía Él;\nNo abrigo dudas ni temor,\nPues me conduce el buen pastor.'),(1047,166,'Estrofa',7,'Y mi carrera al terminar,\nY así mi triunfo al realizar;\nNo habrá ni dudas ni temor,\nPues me guiará mi Buen Pastor.'),(1048,166,'Coro',8,'Me Guía Él me guía Él,\nCon cuanto amor me guía Él;\nNo abrigo dudas ni temor,\nPues me conduce el buen pastor.'),(1049,167,'Estrofa',1,'Soy feliz en el servicio del Señor,\nMuy alegre, tan alegre,\nTengo paz, contentamiento y amor,\nEn servir al Salvador.'),(1050,167,'Coro',2,'En servir al Salvador,\nEn servirle con amor;\n¡Cuán alegre yo me siento,\nEn servir a mi Señor!'),(1051,167,'Estrofa',3,'Soy feliz en el servicio del Señor,\nMuy alegre, tan alegre;\nHoy dedico mis talentos al Señor,\nServiré al Salvador.'),(1052,167,'Coro',4,'En servir al Salvador,\nEn servirle con amor;\n¡Cuán alegre yo me siento,\nEn servir a mi Señor!'),(1053,167,'Estrofa',5,'Soy feliz en el servicio del Señor,\nMuy alegre, tan alegre;\nEn la lucha nunca faltará el valor\nQue me da el Salvador.'),(1054,167,'Coro',6,'En servir al Salvador,\nEn servirle con amor;\n¡Cuán alegre yo me siento,\nEn servir a mi Señor!'),(1055,167,'Estrofa',7,'Soy feliz en el servicio del Señor,\nMuy alegre, tan alegre;\nEn la noche va conmigo el buen Pastor,\nCuando sirvo al Salvador.'),(1056,167,'Coro',8,'En servir al Salvador,\nEn servirle con amor;\n¡Cuán alegre yo me siento,\nEn servir a mi Señor!'),(1057,168,'Estrofa',1,'Estando Jesús en Bethania,\nAllá con Simón el leproso,\nLlegó una mujer humillada,\nlevando un ungüento precioso;\nRompiendo aquel fino alabastro,\nAquella mujer dulcemente,\nDerrama el ungüento preciado,\nEn la cabeza del Señor.'),(1058,168,'Estrofa',2,'Los hombres ingratos murmuran,\nLlevando tristeza aquella alma;\nPero es el Señor compasivo,\nY pronto le vuelve la calma,\nY dice con voz cariñosa:\n“Vosotros tendréis a los pobres,\nMas ella mi cuerpo ha ungido,\nSabiendo que voy a morir.”'),(1059,168,'Estrofa',3,'Entonces aquel Iscariote,\nOyendo la voz del maligno;\nA los sacerdotes llegando,\nOfrece entregar al Señor,\nAquellos se holgaron de gozo y\nJudas entrego al Maestro,\nLe dice Jesús dulcemente:\n“¿Con beso me vas a entregar?”.'),(1060,169,'Estrofa',1,'La segunda venida de Cristo,\nUn evento sublime será;\nTan grandioso cual nunca fue visto,\nMás glorioso jamás se verá.\nDe los cielos el Hijo del Hombre,\nEn la gloria del Padre vendrá;\n“Verdadero y Fiel” es su nombre,\nY el cetro del Reino tendrá.'),(1061,169,'Estrofa',2,'Cual relámpago luce del este.\nUna nube con luz de crisol;\nCuyo brillo, que alcanza al oeste,\nSobrepuja los rayos del sol.\nEs la hueste de ángeles santos,\nRefulgentes de gloria y de luz;\nLos que escoltan y loan con cantos,\nAl invicto y glorioso Jesús.'),(1062,169,'Estrofa',3,'Los impíos de miedo se espantan,\nY perecen al ver al Señor;\nMas los justos las manos levantan,\nHacia Cristo, su buen Redentor.\nContemplando sus gratos fulgores,\nLe aclaman con férvida voz:\n“Rey de Reyes, Señor de Señores”\n¡Mil hosannas al Hijo de Dios!.'),(1063,170,'Estrofa',1,'Habló Dios estas palabras,\nEn el monte Sinaí:\n“No tendrás dioses ajenos,\nNi imagen te harás de mi”'),(1064,170,'Coro',2,'Estos son diez mandamientos,\nEternos como su Autor;\nQue recomienda su Hijo,\n//Cristo nuestro Redentor//.'),(1065,170,'Estrofa',3,'El nombre de Dios en vano,\nNunca lo mencionaras;\nY descansará tu mano,\nEl sábado de Jehová'),(1066,170,'Coro',4,'Estos son diez mandamientos,\nEternos como su Autor;\nQue recomienda su Hijo,\n//Cristo nuestro Redentor//.'),(1067,170,'Estrofa',5,'A tu padre y a tu madre,\nDebida honra les darás;\nNo mates ni adulteres,\nTambién te prohíbe hurtar.'),(1068,170,'Coro',6,'Estos son diez mandamientos,\nEternos como su Autor;\nQue recomienda su Hijo,\n//Cristo nuestro Redentor//.'),(1069,170,'Estrofa',7,'Testigo falso no es bueno,\nNi debes nunca tu ser;\nNo codiciarás lo ajeno,\nNi casa ni la mujer.'),(1070,170,'Coro',8,'Estos son diez mandamientos,\nEternos como su Autor;\nQue recomienda su Hijo,\n//Cristo nuestro Redentor//.'),(1071,171,'Estrofa',1,'Perdóname, Señor, a Ti sólo pequé,\nRecíbeme por Tu amor, perdóname, Señor,\nA ti solo pequé y de Ti me aparté,\nMucho he pecado Santo Dios.\nPerdóname Señor.'),(1072,171,'Estrofa',2,'Perdóname Señor, escucha mi oración,\nEn ti !Oh Dios!\nDescansa aquel que gime por perdón,\nJesús, oh Salvador, inútil es mentir,\nPues todo Tu lo sabes bien,\nPerdóname, Señor.'),(1073,171,'Estrofa',3,'Perdóname, Señor, pues vengo a tus pies,\nTe ruego laves hoy mi ser, perdóname Señor;\nJesús mi Salvador, me diste salvación,\nAsí en los brazos de tu amor,\nHalle consolación.'),(1074,172,'Estrofa',1,'Ya el fin se acerca de tu día santo,\nBenigno acoge la oración, Señor,\nQue te ofrecemos en humilde canto,\nCual sacrificio de agradable olor.'),(1075,172,'Estrofa',2,'Por las mercedes de tu amor debidas,\nPor el descanso y plácido solaz;\nMil gracias sean solo a Ti rendidas,\nRey de los reyes, Príncipe de Paz.'),(1076,172,'Estrofa',3,'De nuestro culto borra los defectos,\nDa a nuestras preces eficaz virtud;\nTu amor tan solo nos hará perfectos,\nSólo tu gracia nos dará salud.'),(1077,172,'Estrofa',4,'Haz que del mundo la escabrosa senda,\nCorrer podamos con seguro pie;\nY en los conflictos que la duda tienda,\nTu luz alumbra nuestra débil fe.'),(1078,172,'Estrofa',5,'Este descanso de sagrada holgura,\nEs de las almas celestial festín;\nNos anticipa la sin par ventura,\nDe aquel reposo que será sin fin'),(1079,173,'Estrofa',1,'Te loamos, ¡oh, Dios!\nCon unánime voz,\nQue en Cristo tu Hijo\nNos diste perdón.'),(1080,173,'Coro',2,'Aleluya, te alabamos,\nCuán grande es tu amor,\nAleluya, te adoramos,\nBendito Señor.'),(1081,173,'Estrofa',3,'Te loamos, Jesús,\nQuien tu trono de luz,\nHas dejado por darnos,\nSalud en la cruz.'),(1082,173,'Coro',4,'Aleluya, te alabamos,\nCuán grande es tu amor,\nAleluya, te adoramos,\nBendito Señor.'),(1083,173,'Estrofa',5,'Unidos load,\nAl gran Dios de verdad,\nQue es la fuente de gracia,\nVirtud y piedad.'),(1084,173,'Coro',6,'Aleluya, te alabamos,\nCuán grande es tu amor,\nAleluya, te adoramos,\nBendito Señor.'),(1085,174,'Estrofa',1,'Mi Salvador en su bondad,\nAl mundo malo descendió,\nY de hondo abismo de maldad,\nÉl mi alma levantó.'),(1086,174,'Coro',2,'Seguridad me dio Jesús,\nCuando su mano me tendió;\nEstando en sombra, a plena luz,\nEn su bondad me levantó.'),(1087,174,'Estrofa',3,'Su voz constante resistí,\nAunque Él amante me llamó;\nMas su palabra recibí,\nY fiel me levantó.'),(1088,174,'Coro',4,'Seguridad me dio Jesús,\nCuando su mano me tendió;\nEstando en sombra, a plena luz,\nEn su bondad me levantó.'),(1089,174,'Estrofa',5,'Tortura cruel sufrió por mí,\nCuando la cruz Él escaló.\nTan sólo así salvado fui.\nY así me levantó.'),(1090,174,'Coro',6,'Seguridad me dio Jesús,\nCuando su mano me tendió;\nEstando en sombra, a plena luz,\nEn su bondad me levantó.'),(1091,174,'Estrofa',7,'Que soy feliz, yo bien lo sé,\nCon esta vida que Él me dió;\nMas no comprendo aún, por qué,\nJesús me levantó.'),(1092,174,'Coro',8,'Seguridad me dio Jesús,\nCuando su mano me tendió;\nEstando en sombra, a plena luz,\nEn su bondad me levantó.'),(1093,175,'Estrofa',1,'Cuando me desalientan, las sombras del terror,\nY mi alma está angustiada, y llena de dolor,\nMi Salvador promete, siempre a mi lado estar,\nEn Él seguro asilo, bien sé que puedo hallar.'),(1094,175,'Coro',2,'Por gracia Jesús me sostendrá,\nPor gracia me sostendrá;\nEn prueba y dolor mi Salvador,\nPor gracia me sostendrá'),(1095,175,'Estrofa',3,'Cuando en mis tristes horas, contemplo el mundo cruel,\nY cuando aquí no encuentro, ningún amigo fiel;\nTan sólo sé que Cristo, conmigo siempre está,\nSu amor bendito calma, de mi alma la ansiedad.'),(1096,175,'Coro',4,'Por gracia Jesús me sostendrá,\nPor gracia me sostendrá;\nEn prueba y dolor mi Salvador,\nPor gracia me sostendrá'),(1097,175,'Estrofa',5,'Cuando la tentación, no puedo yo vencer,\nY las tribulaciones, cercan mi frágil ser;\nEntonces me sostiene, el brazo del Señor,\nY por fuerza y gracia, soy más que vencedor.'),(1098,175,'Coro',6,'Por gracia Jesús me sostendrá,\nPor gracia me sostendrá;\nEn prueba y dolor mi Salvador,\nPor gracia me sostendrá'),(1099,176,'Estrofa',1,'Bendice, ¡oh, alma! a tu Creador, con férvida canción,\nEnsalce y cante su loor, tu ardiente Corazón;\nNo olvides nunca su bondad, con negra ingratitud,\nPues Él perdona tu maldad, te Salva y da Salud.'),(1100,176,'Coro',2,'Cantad, Cantad, dulcísima canción,\nCantad, cantad, al Rey de la creación;\nVosotros ángeles que Él crió, y hacéis su voluntad,\nVosotros, obras que Él formó, su Nombre celebrad.'),(1101,176,'Estrofa',3,'De bien tu boca llena está, y nueva juventud,\nA tu alma siempre le dará, calmando tu inquietud;\nEn ira es lento para arder, mas pronto es en su amor,\nNo quiere siempre contender, ni dura su furor.'),(1102,176,'Coro',4,'Cantad, Cantad, dulcísima canción,\nCantad, cantad, al Rey de la creación;\nVosotros ángeles que Él crió, y hacéis su voluntad,\nVosotros, obras que Él formó, su Nombre celebrad.'),(1103,176,'Estrofa',5,'Tan alto cual el cielo creó, sobre este mundo cruel,\nAsí su amor engrandeció, al darlo al hombre fiel.\nY tan lejanos cual están, oeste y este, así;\nMis rebeliones estarán, muy lejos, sí, de mi.'),(1104,176,'Coro',6,'Cantad, Cantad, dulcísima canción,\nCantad, cantad, al Rey de la creación;\nVosotros ángeles que Él crió, y hacéis su voluntad,\nVosotros, obras que Él formó, su Nombre celebrad.'),(1105,176,'Estrofa',7,'Se acuerda que del polvo soy, formado en su poder,\nQue el hombre es flor tan sólo de hoy,\nQue al sol va a perecer, mas Él de siglo en Siglo da,\nSu amor sin limitar, a todo aquel que listo esta,\nSus leyes a guardar.'),(1106,176,'Coro',8,'Cantad, Cantad, dulcísima canción,\nCantad, cantad, al Rey de la creación;\nVosotros ángeles que Él crió, y hacéis su voluntad,\nVosotros, obras que Él formó, su Nombre celebrad.'),(1107,177,'Estrofa',1,'Una noche con la luna, Cristo lloraba,\nY contemplaba, la ciudad Santa.'),(1108,177,'Coro',2,'“¡Oh, Jerusalem, Jerusalem, Ciudad de Dios!\nLlora hoy por ti mi corazón, como el ave a su hijo,\nLe da siempre protección, quise a tus hijos recoger”'),(1109,177,'Estrofa',3,'¡Oh, Jerusalem, hermosa, tu que has matado,\nCuántos te ha enviado, El Dios de Abraham!'),(1110,177,'Coro',4,'“¡Oh, Jerusalem, Jerusalem, Ciudad de Dios!\nLlora hoy por ti mi corazón, como el ave a su hijo,\nLe da siempre protección, quise a tus hijos recoger”'),(1111,177,'Estrofa',5,'¡Oh, ciudad de mil ensueños,\nque has despreciado,\nLo que te ha dado, El Dios de Amor...!'),(1112,177,'Coro',6,'“¡Oh, Jerusalem, Jerusalem, Ciudad de Dios!\nLlora hoy por ti mi corazón, como el ave a su hijo,\nLe da siempre protección, quise a tus hijos recoger”'),(1113,177,'Estrofa',7,'Lloro de dolor al verla, cuán olvidada,\nYace alejada, la gran Ciudad.'),(1114,177,'Coro',8,'“¡Oh, Jerusalem, Jerusalem, Ciudad de Dios!\nLlora hoy por ti mi corazón, como el ave a su hijo,\nLe da siempre protección, quise a tus hijos recoger”'),(1115,177,'Estrofa',9,'Aunque tú le has despreciado, Dios aún promete\nUn día volverte, tu majestad.'),(1116,177,'Coro',10,'“¡Oh, Jerusalem, Jerusalem, Ciudad de Dios!\nLlora hoy por ti mi corazón, como el ave a su hijo,\nLe da siempre protección, quise a tus hijos recoger”'),(1117,178,'Estrofa',1,'Soldados del Señor, luchemos con valor,\nMostremos lealtad, firmeza y verdad;\nOímos la llamada, “traed hoy la espada”,\nLa lid comienza contra el mal, es guerra inmortal.'),(1118,178,'Coro',2,'Firmes por Cristo todos, sólo así ganareis,\nFe en el Rey de reyes, con Él todos venceréis;\nCon firme pie marchamos, Jesús no nos faltará,\nSin temor, con valor, con la fe en Dios,\nLa lucha se ganará.'),(1119,178,'Estrofa',3,'Ya suena el clarín, sed fieles hasta el fin,\nUnidos avanzad, velad, orad, Marchad;\nEl Jefe tan glorioso, se verá hoy victorioso,\nSu santidad y gran verdad, por siempre proclamad.'),(1120,178,'Coro',4,'Firmes por Cristo todos, sólo así ganareis,\nFe en el Rey de reyes, con Él todos venceréis;\nCon firme pie marchamos, Jesús no nos faltará,\nSin temor, con valor, con la fe en Dios,\nLa lucha se ganará.'),(1121,178,'Estrofa',5,'Es recia esta lid, mas Cristo es adalid,\nGuiando Él está, victoria nos dará;\nLuego en todo el mundo, con gran amor profundo,\nLos hombres gozaran su luz, que emana de la cruz.'),(1122,178,'Coro',6,'Firmes por Cristo todos, sólo así ganareis,\nFe en el Rey de reyes, con Él todos venceréis;\nCon firme pie marchamos, Jesús no nos faltará,\nSin temor, con valor, con la fe en Dios,\nLa lucha se ganará.'),(1123,179,'Estrofa',1,'Para la causa de mi Señor\nPara su Iglesia salva por Él:\nPara su viña cristiana y fiel.\nDaré mis diezmos con gran amor.'),(1124,179,'Coro',2,'Mis diezmos todos yo doy,\nY mis ofrendas de gratitud;\nPor su potencia y su virtud,\nMi Dios harálos multiplicar.'),(1125,179,'Estrofa',3,'En mis pobrezas y en mi aflicción.\nEn mi abundancia y prosperidad.\nSolemne, con gran lealtad,\nDaré mis diezmos con devoción.'),(1126,179,'Coro',4,'Mis diezmos todos yo doy,\nY mis ofrendas de gratitud;\nPor su potencia y su virtud,\nMi Dios harálos multiplicar.'),(1127,179,'Estrofa',5,'Soy responsable de cooperar,\nPara la causa de mi Señor;\nY por lo mismo con gran amor,\nDiezmos y ofrendas prometo dar.'),(1128,179,'Coro',6,'Mis diezmos todos yo doy,\nY mis ofrendas de gratitud;\nPor su potencia y su virtud,\nMi Dios harálos multiplicar.'),(1129,179,'Estrofa',7,'A contribuir me invita el Señor,\nSegún mis fuerzas según mi fe;\nMis diezmos a Cristo yo le daré,\nEl ama a todo feliz dador.'),(1130,179,'Coro',8,'Mis diezmos todos yo doy,\nY mis ofrendas de gratitud;\nPor su potencia y su virtud,\nMi Dios harálos multiplicar.'),(1131,180,'Estrofa',1,'Cristo siempre está conmigo\nYa no quiero mas vagar\nSiento siempre su presencia\nHallo en Él mi dulce hogar.'),(1132,180,'Coro',2,'Dice Cristo: “No te dejo solo,\nSiempre a tu lado estoy;\nAunque lejos tus pisadas vaguen,\nSiempre contigo estoy,\nY no temo nunca, pues mío es.'),(1133,180,'Estrofa',3,'Al cruzar el valle oscuro,\nYo seguro estaré;\nPorque juntos caminamos.\nY con Él yo reinaré.'),(1134,180,'Coro',4,'Dice Cristo: “No te dejo solo,\nSiempre a tu lado estoy;\nAunque lejos tus pisadas vaguen,\nSiempre contigo estoy,\nY no temo nunca, pues mío es.'),(1135,181,'Estrofa',1,'Mi Dios y yo peregrinamos juntos,\nA cada instante siento su bondad;\n//Confío siempre en su perfecta guianza,\nDe día y noche mi alma guardará.//'),(1136,181,'Estrofa',2,'Mi Dios y yo, como fieles amigos,\nAndamos siempre en dulce comunión;\n//Mi devoción completa en Él he puesto,\nQuitó mi mal y dióme su perdón.//'),(1137,181,'Estrofa',3,'Mi Dios y yo caminaremos juntos,\nYa nada aquí nos podrá separar;\n//Su mano en mí daráme fortaleza,\nY no caeré en garras del pecar.//'),(1138,181,'Estrofa',4,'Mi Dios y yo sonreímos siempre juntos,\nY juntos disipamos el dolor;\n//Logré pasar la noche tenebrosa,\nVoy a la tierra de paz y de amor.//'),(1139,182,'Estrofa',1,'Hay un mundo feliz más allá,\nDonde cantan los santos en luz;\nTributando eterno loor,\nAl invicto, Glorioso Jesús.'),(1140,182,'Coro',2,'En el mundo feliz,\nReinaremos con nuestro Señor;\nEn el mundo feliz,\nReinaremos con nuestro Señor.'),(1141,182,'Estrofa',3,'Cantaremos con gozo a Jesús,\nAl cordero que nos rescató;\nQue con sangre vertida en la cruz,\nLos pecados del mundo quitó.'),(1142,182,'Coro',4,'En el mundo feliz,\nReinaremos con nuestro Señor;\nEn el mundo feliz,\nReinaremos con nuestro Señor.'),(1143,182,'Estrofa',5,'Para siempre en el mundo feliz,\nCon los santos daremos honor;\nAl invicto, glorioso Jesús,\nA Jesús, nuestro Rey y Señor.'),(1144,182,'Coro',6,'En el mundo feliz,\nReinaremos con nuestro Señor;\nEn el mundo feliz,\nReinaremos con nuestro Señor.'),(1145,183,'Estrofa',1,'Servir a Jesús, proclamar su verdad,\nEs grande placer y felicidad;\nEn Cristo y la Biblia, glorioso es confiar,\n¡Qué bueno es servir a Jesús!'),(1146,183,'Coro',2,'¡Qué bueno es servir, si servir a Jesús!\n¡Qué bueno es servir, a Jesús!\nAunque aquí nos perezca el camino muy cruel\nSiempre en Cristo hay paz y solaz.'),(1147,183,'Estrofa',3,'¡Qué bueno es servir a Jesús siempre aquí!,\nSer siempre veraz, luchando feliz,\nRiquezas de gloria en Él hay, ¡oh!, sí,\n¡Qué bueno es servir a Jesús!'),(1148,183,'Coro',4,'¡Qué bueno es servir, si servir a Jesús!\n¡Qué bueno es servir, a Jesús!\nAunque aquí nos perezca el camino muy cruel\nSiempre en Cristo hay paz y solaz.'),(1149,183,'Estrofa',5,'Si pena y tristeza te quieren cercar,\nY triste tu ser, desea el dulce hogar;\nNo temas tus luchas, Jesús premiará\n¡Qué bueno es servir a Jesús!'),(1150,183,'Coro',6,'¡Qué bueno es servir, si servir a Jesús!\n¡Qué bueno es servir, a Jesús!\nAunque aquí nos perezca el camino muy cruel\nSiempre en Cristo hay paz y solaz.'),(1151,184,'Estrofa',1,'Ved a Cristo, Rey de gloria,\nEs del mundo vencedor;\nDe la guerra vuelve invicto,\nTodos démosle loor.'),(1152,184,'Coro',2,'Coronadle Santos todos,\nCoronadle Rey de reyes;\nCoronadle Santos todos,\nCoronad al Salvador.'),(1153,184,'Estrofa',3,'Exaltadle, si, exaltadle,\nRicos frutos trae Jesús;\nEntronadlo do su padre,\nEl Rey David también reinó.'),(1154,184,'Coro',4,'Coronadle Santos todos,\nCoronadle Rey de reyes;\nCoronadle Santos todos,\nCoronad al Salvador.'),(1155,184,'Estrofa',5,'Si los malos se burlaron,\nCoronando al Salvador;\nHoy los ángeles y santos,\nLo proclaman su Señor.'),(1156,184,'Coro',6,'Coronadle Santos todos,\nCoronadle Rey de reyes;\nCoronadle Santos todos,\nCoronad al Salvador.'),(1157,184,'Estrofa',7,'Escuchad las alabanzas,\nQue se elevan hacia Él;\nVictorioso Reina Cristo,\nAdorad a Emmanuel.'),(1158,184,'Coro',8,'Coronadle Santos todos,\nCoronadle Rey de reyes;\nCoronadle Santos todos,\nCoronad al Salvador.'),(1159,185,'Estrofa',1,'Yo hallé un fiel amigo para siempre,\nMas que hermano, padre o madre es Él;\nMás que plata o que oro, o que cobre,\nEs de todos Jesucristo el más fiel.'),(1160,185,'Coro',2,'Sólo Cristo, Sólo Cristo\nEs el lirio de los valles, mi Jesús.\nSólo Cristo, Sólo Cristo,\nEs el lirio de los Valles, mi Jesús.'),(1161,185,'Estrofa',3,'De Sarón Él es la rosa tan fragante,\nY del valle el lirio puro es Él;\nEn el alma quebrantada y tan triste,\nSus olores de amor exhala Él.'),(1162,185,'Coro',4,'Sólo Cristo, Sólo Cristo\nEs el lirio de los valles, mi Jesús.\nSólo Cristo, Sólo Cristo,\nEs el lirio de los Valles, mi Jesús.'),(1163,185,'Estrofa',5,'Es Jesús benigno, tierno, compasivo,\nLento en ira, grande en perdonar,\nÉl levanta con amor al abatido,\nSólo sabe Jesucristo como amar.'),(1164,185,'Coro',6,'Sólo Cristo, Sólo Cristo\nEs el lirio de los valles, mi Jesús.\nSólo Cristo, Sólo Cristo,\nEs el lirio de los Valles, mi Jesús.'),(1165,186,'Estrofa',1,'Ahora si pueblo querido, pueblo amado del Señor,\nDios nos ha dado el reposo, un emblema de su amor'),(1166,186,'Coro',2,'Gloria a Dios, gloria a Él, gloria a Cristo,\nGloria a Cristo, Él es el Rey de Israel.'),(1167,186,'Estrofa',3,'Ahora pueblo de Israel, ya es tiempo de despertar\nRecibe el día del reposo, como sábado eternal.'),(1168,186,'Coro',4,'Gloria a Dios, gloria a Él, gloria a Cristo,\nGloria a Cristo, Él es el Rey de Israel.'),(1169,186,'Estrofa',5,'El sábado es del Señor, por tanto lo has de guardar;\nEs el que Dios ha ofrecido, símbolo espiritual.'),(1170,186,'Coro',6,'Gloria a Dios, gloria a Él, gloria a Cristo,\nGloria a Cristo, Él es el Rey de Israel.'),(1171,186,'Estrofa',7,'Este es el día del reposo, el de toda bendición;\nApartado para el hombre, desde el fin de la creación'),(1172,186,'Coro',8,'Gloria a Dios, gloria a Él, gloria a Cristo,\nGloria a Cristo, Él es el Rey de Israel.'),(1173,186,'Estrofa',9,'Este sábado es de Cristo, descanso para Israel;\nAsí el que quiera salvarse, debe reposar en él.'),(1174,186,'Coro',10,'Gloria a Dios, gloria a Él, gloria a Cristo,\nGloria a Cristo, Él es el Rey de Israel.'),(1175,187,'Estrofa',1,'Tus preceptos y ley de amor,\nSon dulces a mi corazón,\nLa delicia sin par Señor,\nEs ella mi meditación.\nHalló dulce calma, en tu ley mi alma.'),(1176,187,'Coro',2,'Es para mi, dulce tu ley,\nDulce tu ley de amor;\nEs para mi, dulce tu ley\nDulce tu ley de amor.'),(1177,187,'Estrofa',3,'En tus sendas yo quiero andar,\nCon santa sumisión;\nY de gozo podrás llenar,\nSiempre mi corazón;\nPara mi son gratos,\nSantos tus mandamientos.'),(1178,187,'Coro',4,'Es para mi, dulce tu ley,\nDulce tu ley de amor;\nEs para mi, dulce tu ley\nDulce tu ley de amor.'),(1179,187,'Estrofa',5,'Los mandatos de mi Señor,\nGozo y paz me dan;\nLos acato yo con temor,\nSiempre me librarán;\nEllos son mi guía,\nSantos cada día.'),(1180,187,'Coro',6,'Es para mi, dulce tu ley,\nDulce tu ley de amor;\nEs para mi, dulce tu ley\nDulce tu ley de amor.'),(1181,188,'Estrofa',1,'Lo que Cristo manda siempre es lo mejor,\nAunque no comprenda pruebas y dolor;\nÉl siempre procura mi oro refinar,\nEn Él, pues, confío, Él me ha de cuidar.'),(1182,188,'Coro',2,'Me guarda y me guía, de día en día\nSu senda es la mía, Él sabe mejor.'),(1183,188,'Estrofa',3,'Mis pasos van siempre por donde escogió,\nCon Él por mi guía, seguro estoy yo;\nEn lazo o en sombra, cerca lo tendré,\nConoce el camino, nunca temeré.'),(1184,188,'Coro',4,'Me guarda y me guía, de día en día\nSu senda es la mía, Él sabe mejor.'),(1185,188,'Estrofa',5,'Su senda es la mía, Él sabe mejor,\nMi alma en Él confía, en su dulce amor;\nMe brinda el descanso con su protección,\nSeguirle es mi encanto, dulce comunión.'),(1186,188,'Coro',6,'Me guarda y me guía, de día en día\nSu senda es la mía, Él sabe mejor.'),(1187,189,'Estrofa',1,'Despliegue el cristiano su santa bandera\nY muéstrela ufano del mundo a la faz\nSoldados valientes, el triunfo os espera,\nSeguid vuestra lucha constante y tenaz'),(1188,189,'Coro',2,'Cristo nos guía, es nuestro Jefe,\nY con nosotros siempre estará,\nNada temamos, Él nos alienta,\nY a la victoria llevarnos podrá.'),(1189,189,'Estrofa',3,'Despliegue el cristiano su santa bandera,\nDomine baluartes y almenas a mil,\nLa Biblia bendita conquiste doquiera,\nY ante ella se incline la turba gentil.'),(1190,189,'Coro',4,'Cristo nos guía, es nuestro Jefe,\nY con nosotros siempre estará,\nNada temamos, Él nos alienta,\nY a la victoria llevarnos podrá.'),(1191,189,'Estrofa',5,'Despliegue el cristiano su santa bandera,\nPredique a los pueblos el libro inmortal,\nPresente a los hombres la luz verdadera,\nQue vierte ese claro, luciente fanal.'),(1192,189,'Coro',6,'Cristo nos guía, es nuestro Jefe,\nY con nosotros siempre estará,\nNada temamos, Él nos alienta,\nY a la victoria llevarnos podrá.'),(1193,190,'Estrofa',1,'Mas cual mi Cristo siempre anhelo ser,\nMas mansedumbre, más benignidad;\nCelo en servirle, fidelidad mostrar,\nMas consagrado a la obra que me da.'),(1194,190,'Coro',2,'Toma mi ser, tan sólo tuyo es,\nToma mi ser, lo doy Señor a Ti;\nMi corazón, imploro limpies Tú,\nTenme, soy tuyo por la eternidad.'),(1195,190,'Estrofa',3,'Mas cual mi Cristo es mi oración,\nMas fuerza tenga, mas resignación;\nMas serio siempre, y mas espiritual,\nY al que vaga traer al altar.'),(1196,190,'Coro',4,'Toma mi ser, tan sólo tuyo es,\nToma mi ser, lo doy Señor a Ti;\nMi corazón, imploro limpies Tú,\nTenme, soy tuyo por la eternidad.'),(1197,190,'Estrofa',5,'Mas cual mi Cristo, más profunda fe,\nDe su cariño, grande compasión;\nCual Él paciente, humilde y veraz\nEs mi anhelo cual Cristo aquí andar'),(1198,190,'Coro',6,'Toma mi ser, tan sólo tuyo es,\nToma mi ser, lo doy Señor a Ti;\nMi corazón, imploro limpies Tú,\nTenme, soy tuyo por la eternidad.'),(1199,191,'Estrofa',1,'Habla, Señor a mi alma, hable tu dulce voz,\nHáblame en tiernas notas, “tu no estás solo, no”;\nMi corazón prepara, presto a escuchar tu ley,\nLoores mi alma llenen, de contrición y fe.'),(1200,191,'Coro',2,'Háblame en dulces notas, háblame con amor,\n“Ya la victoria es tuya, no tengas mas temor”;\nHáblame cada día, hable tu tierna voz,\nQue escuchen mis oídos, “Tu no estás solo, no”'),(1201,191,'Estrofa',3,'Habla a tus hijos siempre, dales tu santidad,\nLlénales de tu gozo, enséñales a orar;\nA ti consagren todo, vivan tan solo en ti,\nTraigan tu Reino pronto, vean tu rostro aquí.'),(1202,191,'Coro',4,'Háblame en dulces notas, háblame con amor,\n“Ya la victoria es tuya, no tengas mas temor”;\nHáblame cada día, hable tu tierna voz,\nQue escuchen mis oídos, “Tu no estás solo, no”'),(1203,191,'Estrofa',5,'Habla cual en lo antiguo, diste tu santa ley,\nTus testimonios siempre, quiero guardar por fe;\nQuiero magnificarte, quiero tu gloria dar,\nEl grato testimonio, de obedecer y amar.'),(1204,191,'Coro',6,'Háblame en dulces notas, háblame con amor,\n“Ya la victoria es tuya, no tengas mas temor”;\nHáblame cada día, hable tu tierna voz,\nQue escuchen mis oídos, “Tu no estás solo, no”'),(1205,192,'Estrofa',1,'Dejo el mundo y sigo a Cristo,\nPues el mundo pasará;\nMas el tiempo amor divino,\nPor los siglos durará.'),(1206,192,'Coro',2,'¡Oh, que amor inmensurable!\n¡Que clemencia, que bondad!\n¡Oh, la plenitud de gracia,\nPrenda de inmortalidad!.'),(1207,192,'Estrofa',3,'Dejo el mundo y sigo a Cristo,\nMi alma en ÉL consolaré;\nYa que ÉL vela mis pisadas,\nSu bondad ensalzaré.'),(1208,192,'Coro',4,'¡Oh, que amor inmensurable!\n¡Que clemencia, que bondad!\n¡Oh, la plenitud de gracia,\nPrenda de inmortalidad!.'),(1209,192,'Estrofa',5,'Dejo el mundo y sigo a Cristo,\nMi benigno Salvador;\nEn mis peregrinaciones,\nBrille en mi su resplandor.'),(1210,192,'Coro',6,'¡Oh, que amor inmensurable!\n¡Que clemencia, que bondad!\n¡Oh, la plenitud de gracia,\nPrenda de inmortalidad!.'),(1211,192,'Estrofa',7,'Dejo el mundo y sigo a Cristo,\nConfiaré yo en su luz;\nHasta que sin velo mire,\nCara a cara a mi Jesús.'),(1212,192,'Coro',8,'¡Oh, que amor inmensurable!\n¡Que clemencia, que bondad!\n¡Oh, la plenitud de gracia,\nPrenda de inmortalidad!.'),(1213,193,'Estrofa',1,'Tuyo soy, Jesús ya escuché la voz,\nDe tu amor hablándome aquí;\nMas anhelo siempre servirte oh Dios,\nY más cerca estar de Ti.'),(1214,193,'Coro',2,'Aún más cerca, cerca de tu cruz,\nLlévame, ¡oh, Salvador!;\nAún mas cerca, cerca, cerca de tu cruz,\nLlévame, ¡oh, buen Pastor!.'),(1215,193,'Estrofa',3,'A seguirte a Ti me consagro hoy,\nConstreñido por tu amor;\nY mi espíritu, alma y cuerpo doy,\nPor servirte, mi Señor.'),(1216,193,'Coro',4,'Aún más cerca, cerca de tu cruz,\nLlévame, ¡oh, Salvador!;\nAún mas cerca, cerca, cerca de tu cruz,\nLlévame, ¡oh, buen Pastor!.'),(1217,193,'Estrofa',5,'¡Oh, cuán pura y santa delicia es,\nDe tu comunión gozar;\nY contigo hablar, y tu dulce voz,\nCada día escuchar!.'),(1218,193,'Coro',6,'Aún más cerca, cerca de tu cruz,\nLlévame, ¡oh, Salvador!;\nAún mas cerca, cerca, cerca de tu cruz,\nLlévame, ¡oh, buen Pastor!.'),(1219,194,'Estrofa',1,'En el monte calvario estaba una cruz\nEmblema de afrenta y dolor\nMas yo amo a Jesús, pues murió en dicha cruz\nPor salvar al más vil pecador.'),(1220,194,'Coro',2,'¡Oh, yo siempre amaré a mi Jesús!,\nGloria y triunfo su sangre será;\nY algún día al contemplar su faz,\nMi corona Jesús me dará.'),(1221,194,'Estrofa',3,'En la cruz de Jesús, do su sangre vertió,\nHermosura contemplo sin par;\nPues en ella triunfante la muerte venció,\nY mi ser puede santificar.'),(1222,194,'Coro',4,'¡Oh, yo siempre amaré a mi Jesús!,\nGloria y triunfo su sangre será;\nY algún día al contemplar su faz,\nMi corona Jesús me dará.'),(1223,194,'Estrofa',5,'Yo seré siempre fiel a la voz de Jesús,\nSus desprecios con ÉL sufriré\nY algún día feliz con los santos en luz,\nPara siempre su gloria veré.'),(1224,194,'Coro',6,'¡Oh, yo siempre amaré a mi Jesús!,\nGloria y triunfo su sangre será;\nY algún día al contemplar su faz,\nMi corona Jesús me dará.'),(1225,195,'Estrofa',1,'Fiel huésped a tu puerta está, anhela luego entrar,\nTu nombre sabe y tu morar, ¡escucha su llamar!;\nSu mano traspasada está, su rostro con sudor,\nEs el Señor, Rey Celestial, atiende su clamor.'),(1226,195,'Coro',2,'He aquí a tu puerta llama,\nEl Divino Redentor;\nQuiere hacer hoy en ti morada,\n¿Le abrirás tu corazón?.'),(1227,195,'Estrofa',3,'Agónico en Gethsemaní, vergüenza cruel sufrió,\nSu pura sangre carmesí, con gozo derramó;\nSalvarte quiso, pecador de negra inquietud,\n¿Despreciarás a tu Señor que quiere en ti morar?'),(1228,195,'Coro',4,'He aquí a tu puerta llama,\nEl Divino Redentor;\nQuiere hacer hoy en ti morada,\n¿Le abrirás tu corazón?.'),(1229,195,'Estrofa',5,'El caro huésped hoy está su voz dejando oír,\nY llama tierno, sin cesar. ¿Le quieres recibir?;\n¡Despierta, oh, alma, pues se va! ¿Entrar le dejarás?\nEl rostro triste volverá, no llamará jamás'),(1230,195,'Coro',6,'He aquí a tu puerta llama,\nEl Divino Redentor;\nQuiere hacer hoy en ti morada,\n¿Le abrirás tu corazón?.'),(1231,196,'Estrofa',1,'Si solo y triste te sientes tú,\nPor los cuidados y el mal;\nTus cargas aliviara Jesús,\nSi oras a Él sin cesar.'),(1232,196,'Coro',2,'Ora con fe, ora con fe,\n¿Triunfo deseas tener?\nOra con fe, ora con fe, ora con fe\n¿Triunfo deseas tener? Ora con fe'),(1233,196,'Estrofa',3,'Si estas tentado a volver atrás,\nTentado a desesperar\nCorre a los brazos de el Salvador,\nDile todo en oración'),(1234,196,'Coro',4,'Ora con fe, ora con fe,\n¿Triunfo deseas tener?\nOra con fe, ora con fe, ora con fe\n¿Triunfo deseas tener? Ora con fe'),(1235,196,'Estrofa',5,'Si por problemas perplejo estás,\nOra y solución tendrás;\nSi enfermedades minan tu ser,\nOra hasta el triunfo obtener.'),(1236,196,'Coro',6,'Ora con fe, ora con fe,\n¿Triunfo deseas tener?\nOra con fe, ora con fe, ora con fe\n¿Triunfo deseas tener? Ora con fe'),(1237,197,'Estrofa',1,'Los obreros del Señor\nSe reúnen aquí,\nPara informar\nDe la Obra del Señor.'),(1238,197,'Coro',2,'La Palabra de nuestro Dios,\nNos une en amor,\nComo ejemplo de el Salvador\nPara el siervo fiel.'),(1239,197,'Estrofa',3,'Con mi voz aclamaré\nA Jehová, nuestro Dios,\nDelante de Él presentaré,\nToda mi labor.'),(1240,197,'Coro',4,'La Palabra de nuestro Dios,\nNos une en amor,\nComo ejemplo de el Salvador\nPara el siervo fiel.'),(1241,197,'Estrofa',5,'Nuevas fuerzas y valor\nTe pedimos con fe,\nPara traer más almas\nA tu redil.'),(1242,197,'Coro',6,'La Palabra de nuestro Dios,\nNos une en amor,\nComo ejemplo de el Salvador\nPara el siervo fiel.'),(1243,198,'Estrofa',1,'Jesús es precioso, mi buen Salvador,\nPor siempre le alabo por su gran amor;\nSi débil me encuentro me ayuda el Señor,\nEl es mi precioso Jesús.'),(1244,198,'Coro',2,'Precioso es Jesús, mi Jesús,\nPrecioso es Jesús, mi Jesús;\nMi gloria será su rostro al mirar,\nEl es mi precioso Jesús.'),(1245,198,'Estrofa',3,'Y cuando en pecado y sin Salvación,\nLlamando a las puertas de mi corazón,\nMe dijo: Acepta hoy mi gran perdón,\nÉl es mi precioso Jesús.'),(1246,198,'Coro',4,'Precioso es Jesús, mi Jesús,\nPrecioso es Jesús, mi Jesús;\nMi gloria será su rostro al mirar,\nEl es mi precioso Jesús.'),(1247,198,'Estrofa',5,'Mas ya por su gracia mi alma salvó,\nQuitó mi tristeza, mi llanto enjugó;\nMis dudas y males ya me los quito,\nÉl es mi precioso Jesús.'),(1248,198,'Coro',6,'Precioso es Jesús, mi Jesús,\nPrecioso es Jesús, mi Jesús;\nMi gloria será su rostro al mirar,\nEl es mi precioso Jesús.'),(1249,199,'Estrofa',1,'Hay un canto nuevo en mi ser,\nEs la voz de mi Jesús;\nQue me dice: “Ven a descansar,\nTu paz conquisté en la cruz”.'),(1250,199,'Coro',2,'Cristo, Cristo, Cristo,\nNombre sin igual;\nLlena siempre mi alma,\nDe esa nota celestial.'),(1251,199,'Estrofa',3,'Náufrago en pecado me encontré,\nSin paz en mi corazón;\nMas en Cristo, mi Señor hallé,\nDulce paz y protección.'),(1252,199,'Coro',4,'Cristo, Cristo, Cristo,\nNombre sin igual;\nLlena siempre mi alma,\nDe esa nota celestial.'),(1253,199,'Estrofa',5,'Tengo de su gracia celestial,\nGozo en su santo amor;\nY riquezas fluyen a raudal,\nDesde el trono del Señor.'),(1254,199,'Coro',6,'Cristo, Cristo, Cristo,\nNombre sin igual;\nLlena siempre mi alma,\nDe esa nota celestial.'),(1255,199,'Estrofa',7,'Por las aguas hondas me llevó,\nPruebas en mi senda hallé;\nDo áspero sendero me guió,\nMas sus huellas seguiré.'),(1256,199,'Coro',8,'Cristo, Cristo, Cristo,\nNombre sin igual;\nLlena siempre mi alma,\nDe esa nota celestial.'),(1257,200,'Estrofa',1,'Jehová es mi pastor, me apacienta con amor,\nEn sus pastos delicados paceré;\nDescansando sin temor, al abrigo del Señor,\nDe las aguas de reposo beberé.'),(1258,200,'Coro',2,'El Señor me pastorea, nada ya me faltará,\nJunto a Él caminaré, en sus brazos confiaré;\nNada del amor de Dios me apartará.'),(1259,200,'Estrofa',3,'Mi Pastor me guiará,\nSiempre me confortará,\nPor las sendas de justicia me guiará;\nEn el tiempo del dolor,\nMe será consolador,\nEn mi corazón su paz infundirá.'),(1260,200,'Coro',4,'El Señor me pastorea, nada ya me faltará,\nJunto a Él caminaré, en sus brazos confiaré;\nNada del amor de Dios me apartará.'),(1261,200,'Estrofa',5,'¡Oh, cuán fiel es mi pastor!,\n¡Cuán constante es su amor!;\nQue mi copa rebosando siempre está,\nCuando en valle oscuro esté.\nMal ninguno temeré,\nY en la Iglesia de mi Dios siempre estaré.'),(1262,200,'Coro',6,'El Señor me pastorea, nada ya me faltará,\nJunto a Él caminaré, en sus brazos confiaré;\nNada del amor de Dios me apartará.'),(1263,201,'Estrofa',1,'¿Es pesada la cruz que tu llevas?\n¿Te acosan las luchas doquier?\n¿Te circundan del mundo las pruebas?\n¿Nadie quiérete socorrer?'),(1264,201,'Coro',2,'En las sombras de tu vida se halla,\nCristo es amigo compasivo en verdad;\nEn las luchas de tu vida ven a Cristo,\nSolo en Él encontrarás felicidad.'),(1265,201,'Estrofa',3,'¿Has sufrido fatal desengaño,\nY todos se alejan de ti?;\n¿Las tinieblas de duda y engaño,\nTe acechan con frenesí?.'),(1266,201,'Coro',4,'En las sombras de tu vida se halla,\nCristo es amigo compasivo en verdad;\nEn las luchas de tu vida ven a Cristo,\nSolo en Él encontrarás felicidad.'),(1267,201,'Estrofa',5,'¿Has perdido la dicha y el gozo?,\n¿De pena te sientes morir?;\n¿Has en vano buscado reposo,\nSin saber a quien acudir?.'),(1268,201,'Coro',6,'En las sombras de tu vida se halla,\nCristo es amigo compasivo en verdad;\nEn las luchas de tu vida ven a Cristo,\nSolo en Él encontrarás felicidad.'),(1269,202,'Estrofa',1,'Amigo tengo que me ama,\nMe ama me ama;\nAmigo tengo que me ama,\nY su nombre es Jesús.'),(1270,202,'Coro',2,'Me ama domingo y lunes también,\nMartes y miércoles donde esté;\nJueves y viernes y sábado es de Él,\nAlabad su nombre, es mi buen Jesús.'),(1271,202,'Estrofa',3,'Amigo tengo que me guía,\nMe guía, me guía;\nAmigo tengo que me guía,\nY su nombre es Jesús.'),(1272,202,'Coro',4,'Me ama domingo y lunes también,\nMartes y miércoles donde esté;\nJueves y viernes y sábado es de Él,\nAlabad su nombre, es mi buen Jesús.'),(1273,202,'Estrofa',5,'Amigo tengo que me enseña,\nMe enseña, me enseña;\nAmigo tengo que me enseña,\nY su nombre es Jesús.'),(1274,202,'Coro',6,'Me ama domingo y lunes también,\nMartes y miércoles donde esté;\nJueves y viernes y sábado es de Él,\nAlabad su nombre, es mi buen Jesús.'),(1275,202,'Estrofa',7,'Amigo tengo que me cuida,\nMe cuida, me cuida;\nAmigo tengo que me cuida,\nsu nombre es Jesús.'),(1276,202,'Coro',8,'Me ama domingo y lunes también,\nMartes y miércoles donde esté;\nJueves y viernes y sábado es de Él,\nAlabad su nombre, es mi buen Jesús.'),(1277,203,'Estrofa',1,'Estaremos juntos en ese día glorioso,\nEn la tierra de nuestros mayores;\nEstaremos juntos en ese día glorioso,\nEn la tierra de nuestros mayores.'),(1278,203,'Estrofa',2,'Viva viva Palestina,\nViva viva Palestina;\nTierra que nuestros padres dejaron,\nY que al fin conquistaron.'),(1279,204,'Estrofa',1,'Oh, Cristo mío, Rey de mi alma,\nSalvásteme del mal, lávame en el raudal;\nDe tu preciosa Sangre Purísima,\nNinguna mancha ya me contamina.'),(1280,204,'Coro',2,'Tanto me amaste, pues que te diste,\nSacrificándote sobre una cruz;\nPor mi redención con tanto amor,\nSe que te amo Cristo mi Salvador'),(1281,204,'Estrofa',3,'Cuando iba errante, Tú me buscaste,\nNo me dejaste perder el alma;\nPor plena gracia compraste mi salud,\nImpartiéndome la Santa virtud.'),(1282,204,'Coro',4,'Tanto me amaste, pues que te diste,\nSacrificándote sobre una cruz;\nPor mi redención con tanto amor,\nSe que te amo Cristo mi Salvador'),(1283,205,'Estrofa',1,'Canten del amor de Cristo,\nEnsalzad al Redentor;\nTibutadle santos todos,\nGrande gloria y loor.'),(1284,205,'Coro',2,'Cuando estemos en gloria,\nEn presencia de nuestro Redentor;\nA una voz la historia,\nDiremos del Gran vencedor.'),(1285,205,'Estrofa',3,'La victoria es segura,\nA las huestes del Señor;\n¡Oh, pelead con la mirada,\nPuesta en nuestro protector!.'),(1286,205,'Coro',4,'Cuando estemos en gloria,\nEn presencia de nuestro Redentor;\nA una voz la historia,\nDiremos del Gran vencedor.'),(1287,205,'Estrofa',5,'El pendón alzad cristianos,\nDe la cruz y caminad;\nDe triunfo en triunfo,\nSiempre firmes avanzad.'),(1288,205,'Coro',6,'Cuando estemos en gloria,\nEn presencia de nuestro Redentor;\nA una voz la historia,\nDiremos del Gran vencedor.'),(1289,205,'Estrofa',7,'Adelante en la lucha,\n¡Oh, soldados de la fe!;\nNuestro el triunfo, ¡Oh, escucha!,\nLos clamores, ¡Viva el Rey!.'),(1290,205,'Coro',8,'Cuando estemos en gloria,\nEn presencia de nuestro Redentor;\nA una voz la historia,\nDiremos del Gran vencedor.'),(1291,206,'Estrofa',1,'Siempre el Salvador conmigo,\nNada soy sin su poder;\nSu presencia necesito,\nVoy, sin Él a perecer.'),(1292,206,'Coro',2,'Me guiará mi Salvador,\nMi alma a Él confiaré;\nCon amor donde Él me lleve,\nSus pisadas seguiré.'),(1293,206,'Estrofa',3,'Siempre el Salvador conmigo,\nPuédeme la fe faltar;\nSus palabras me consuelan,\nCual Él nadie puede hablar.'),(1294,206,'Coro',4,'Me guiará mi Salvador,\nMi alma a Él confiaré;\nCon amor donde Él me lleve,\nSus pisadas seguiré.'),(1295,206,'Estrofa',5,'Siempre el Salvador conmigo,\nIlumíneme su faz;\nEn la calma, en la tormenta,\nEn la lucha y en la paz.'),(1296,206,'Coro',6,'Me guiará mi Salvador,\nMi alma a Él confiaré;\nCon amor donde Él me lleve,\nSus pisadas seguiré.'),(1297,206,'Estrofa',7,'Siempre el Salvador conmigo,\nSus consejos me guiarán;\nHasta que me vea en la orilla,\nAnhelada del Jordán.'),(1298,206,'Coro',8,'Me guiará mi Salvador,\nMi alma a Él confiaré;\nCon amor donde Él me lleve,\nSus pisadas seguiré.'),(1299,207,'Estrofa',1,'¡Oh, qué Salvador es mi Cristo Jesús!\n¡Oh, qué Salvador es aquí!,\nEl salva al mas malo de su iniquidad,\nY vida eterna le da.'),(1300,207,'Coro',2,'Me escondo en la Roca, que es Cristo el Señor,\nY allí nada yo temeré;\nMe escondo en la Roca, que es mi Salvador,\nY en Él siempre confiaré, Y siempre con Él viviré.'),(1301,207,'Estrofa',3,'Iré a mirar a los que aquí deje,\nY con ellos yo estaré;\nMas quiero mirar a mi Cristo Jesús,\nEl cual murió en dura cruz.'),(1302,207,'Coro',4,'Me escondo en la Roca, que es Cristo el Señor,\nY allí nada yo temeré;\nMe escondo en la Roca, que es mi Salvador,\nY en Él siempre confiaré, Y siempre con Él viviré.'),(1303,207,'Estrofa',5,'Y cuando esta vida termine aquí,\nLa lucha abandonaré;\nEntonces a Cristo yo voy a mirar,\nLoor a su nombre daré.'),(1304,207,'Coro',6,'Me escondo en la Roca, que es Cristo el Señor,\nY allí nada yo temeré;\nMe escondo en la Roca, que es mi Salvador,\nY en Él siempre confiaré, Y siempre con Él viviré.'),(1305,207,'Estrofa',7,'Y cuando en las nubes descienda Jesús,\nGlorioso al mundo a reinar,\nSu gran salvación y perfecto amor,\nPor siglos yo he de gozar.'),(1306,207,'Coro',8,'Me escondo en la Roca, que es Cristo el Señor,\nY allí nada yo temeré;\nMe escondo en la Roca, que es mi Salvador,\nY en Él siempre confiaré, Y siempre con Él viviré.'),(1307,208,'Estrofa',1,'Mi padre es un Rey muy rico, sin par,\nÉL tiene caudales inmensos doquier;\nSu oro y diamantes no pueden contar,\nTesoro que nadie podrá contener.'),(1308,208,'Coro',2,'¡Soy el hijo de un Rey!, ¡El hijo de un Rey!,\n¡Con Cristo bendito, Soy el hijo de un Rey!\n¡Soy el hijo de un Rey!, ¡El hijo de un Rey!\n¡Con Cristo bendito, Soy el hijo de un Rey!'),(1309,208,'Estrofa',3,'El hijo de Dios, mi buen Salvador,\nAl mundo viniendo muy pobre se vio;\nHoy Reina en la gloria cubierto de honor,\nY un sitio en su Reino con Dios me ofreció.'),(1310,208,'Coro',4,'¡Soy el hijo de un Rey!, ¡El hijo de un Rey!,\n¡Con Cristo bendito, Soy el hijo de un Rey!\n¡Soy el hijo de un Rey!, ¡El hijo de un Rey!\n¡Con Cristo bendito, Soy el hijo de un Rey!'),(1311,208,'Estrofa',5,'Errante viví sin patria ni hogar,\nUn vil extranjero sin Dios y sin fe;\nMas Cristo bendito me quiso adoptar,\nHerencia por siempre con ÉL yo tendré.'),(1312,208,'Coro',6,'¡Soy el hijo de un Rey!, ¡El hijo de un Rey!,\n¡Con Cristo bendito, Soy el hijo de un Rey!\n¡Soy el hijo de un Rey!, ¡El hijo de un Rey!\n¡Con Cristo bendito, Soy el hijo de un Rey!'),(1313,209,'Estrofa',1,'Te loamos, Te glorificamos,\nTe confesamos eterno Dios y Padre;\nToda la tierra con temor sagrado,\nSiempre te adora.'),(1314,209,'Estrofa',2,'Y los cielos y los querubines,\nTodos te ensalzan con voces interminables;\nRey de los cielos, Las eternas huestes,\nSiempre te dicen:'),(1315,209,'Estrofa',3,'Santo, Santo, Santo Señor ensalzado,\nDios fortísimo, tu majestad y gloria;\nLlenan los cielos y te muestran adorado,\nSobre la tierra. Amén.'),(1316,210,'Estrofa',1,'Viene otra vez nuestro Salvador ¡Oh, que si fuera hoy!\npara reinar con poder y amor ¡Oh, que si fuera hoy!\nY con su esposa ÉL estará, purificada en su grande amor\nDel mundo por la redondez ¡Oh, que si fuera hoy!'),(1317,210,'Coro',2,'¡Gloria!, ¡Gloria! Gozo sin fin traerá,\n¡Gloria!, ¡Gloria! Al coronarlo Rey;\n¡Gloria!, ¡Gloria! La senda preparad,\n¡Gloria!, ¡Gloria! Cristo viene otra vez.'),(1318,210,'Estrofa',3,'Terminará el poder de Satán, ¡Ojalá fuera hoy!,\nNo mas tristezas aquí verán, ¡Ojalá fuera hoy!;\nTodos los muertos en Cristo irán a recibir a su Salvador,\n¿Cuándo estas glorias aquí vendrán? ¡Ojalá fuera hoy!'),(1319,210,'Coro',4,'¡Gloria!, ¡Gloria! Gozo sin fin traerá,\n¡Gloria!, ¡Gloria! Al coronarlo Rey;\n¡Gloria!, ¡Gloria! La senda preparad,\n¡Gloria!, ¡Gloria! Cristo viene otra vez.'),(1320,210,'Estrofa',5,'Fieles y leales nos debe hallar, Si ÉL viniera hoy,\nTodos velando con gozo y paz, Si ÉL viniera hoy;\nMultiplicadas señales hay, en el oriente se ve el albor,\nYa más cercano el tiempo está, ¡Ojalá fuera hoy!.'),(1321,210,'Coro',6,'¡Gloria!, ¡Gloria! Gozo sin fin traerá,\n¡Gloria!, ¡Gloria! Al coronarlo Rey;\n¡Gloria!, ¡Gloria! La senda preparad,\n¡Gloria!, ¡Gloria! Cristo viene otra vez.'),(1322,211,'Estrofa',1,'Hay quien vele mis pisadas, en la sombra y en la luz,\nPor la sendas escarpadas, velará por mi Jesús;\nPor los valles, por los montes, do me lleve su bondad,\nMiro yo los horizontes, de una nueva claridad.'),(1323,211,'Coro',2,'Hay quien vele mis pisadas,\nY mi senda trazará\nHasta el fin de la jornada\nEs Jesús quien me guiará'),(1324,211,'Estrofa',3,'Hay contacto que me explica, la presencia del Señor,\nÉL mis penas dulcifica y me libra del temor;\nCristo con su amor herida, protección me puede dar,\nCuando cruzo de la vida el inquieto y fiero mar'),(1325,211,'Coro',4,'Hay quien vele mis pisadas,\nY mi senda trazará\nHasta el fin de la jornada\nEs Jesús quien me guiará'),(1326,211,'Estrofa',5,'Hay un corazón amante, de infinita compasión,\nQue confiere paz constate, al contrito corazón;\nEn su amor hay eficiencia, Cristo es un amigo fiel,\nHay en ÉL verdad y gracia, Suyo soy y mío es ÉL.'),(1327,211,'Coro',6,'Hay quien vele mis pisadas,\nY mi senda trazará\nHasta el fin de la jornada\nEs Jesús quien me guiará'),(1328,212,'Estrofa',1,'Dulces momentos consoladores,\nLos que me paso junto a la cruz;\nAllí sufriendo crueles dolores,\nMiro al Cordero, Cristo Jesús.'),(1329,212,'Estrofa',2,'Miro sus brazos de amor abiertos,\nQue me convidan a ir a ÉL;\nY haciendo suyos mis desaciertos,\nPor mi sus labios gustan de hiel.'),(1330,212,'Estrofa',3,'De sus heridas la viva fuente,\nDe pura sangre veo manar;\nY salpicando mi impura frente,\nLa infame culpa logra borrar.'),(1331,212,'Estrofa',4,'Miro su angustia ya terminada,\nHecha la ofrenda de la expiación;\nSu noble frente, mustia, inclinada,\nY consumada mi redención.'),(1332,212,'Estrofa',5,'Dulces momentos, ricos en dones,\nDe paz y gracia, de vida y luz;\nSólo hay consuelos y bendiciones,\nCerca de Cristo, junto a la cruz.'),(1333,213,'Estrofa',1,'Encontré refugio donde descansar,\nEn la eterna roca de salud;\nCuando en mis temores quiero yo flaquear,\nMe fortalece fiel mi Jesús.'),(1334,213,'Coro',2,'Roca de los siglos, Rosa de Sarón,\nTu me das refugio en la tentación;\nLirio de los valles, Astro matinal,\nPaz encuentra en Ti mi Corazón.'),(1335,213,'Estrofa',3,'Es Jesús la tierna Rosa de Sarón,\nPlena de pureza y verdad;\nMi deleite santo, mi consolación,\nLa fuente de mi felicidad.'),(1336,213,'Coro',4,'Roca de los siglos, Rosa de Sarón,\nTu me das refugio en la tentación;\nLirio de los valles, Astro matinal,\nPaz encuentra en Ti mi Corazón.'),(1337,213,'Estrofa',5,'ÉL es para mi la estrella matinal,\nQue disipa toda oscuridad;\nAunque me circule por doquiera el mal,\nEn Cristo tengo seguridad.'),(1338,213,'Coro',6,'Roca de los siglos, Rosa de Sarón,\nTu me das refugio en la tentación;\nLirio de los valles, Astro matinal,\nPaz encuentra en Ti mi Corazón.'),(1339,214,'Estrofa',1,'Hay corazones a tu alrededor,\nTristes, cansados, sin paz;\nDales consuelo que alivie el dolor,\nTorna su llanto en solaz.'),(1340,214,'Coro',2,'Hazme una fuente de bendiciones,\nY que fulgure Cristo en mi;\nHazme un testigo, te ruego Señor,\nY un fiel obrero de mi Salvador.'),(1341,214,'Estrofa',3,'Cuenta la historia que Cristo y su amor,\nY de su luz poder;\nMuestra en tu vida que tu Redentor,\nHa trasformado tu ser.'),(1342,214,'Coro',4,'Hazme una fuente de bendiciones,\nY que fulgure Cristo en mi;\nHazme un testigo, te ruego Señor,\nY un fiel obrero de mi Salvador.'),(1343,214,'Estrofa',5,'Por de tu fe la virtud en acción,\nAma cual Cristo amó;\nSe fiel y emplea en tu santa misión,\nEl don que Cristo te dio.'),(1344,214,'Coro',6,'Hazme una fuente de bendiciones,\nY que fulgure Cristo en mi;\nHazme un testigo, te ruego Señor,\nY un fiel obrero de mi Salvador.'),(1345,215,'Estrofa',1,'Una voz resuena de ansia y de fervor\n¡Dadnos luz!, ¡Dadnos luz!,\nMiles en tinieblas, llenos de pavor,\nPiden luz, piden luz.'),(1346,215,'Coro',2,'¡Dadnos Luz, la gloriosa luz!\nDel perdón de paz y amor;\n¡Dadnos Luz, la preciosa luz!\nDe Jesús, el Salvador.'),(1347,215,'Estrofa',3,'Oh en toda tierra haced resplandecer,\nEsa luz de Jesús;\nLuz que ilumine nuestra senda aquí,\n¡Dadnos luz! ¡Dadnos luz!.'),(1348,215,'Coro',4,'¡Dadnos Luz, la gloriosa luz!\nDel perdón de paz y amor;\n¡Dadnos Luz, la preciosa luz!\nDe Jesús, el Salvador.'),(1349,215,'Estrofa',5,'En Jesús hay vida, paz, consolación,\n¡Dadnos luz! ¡Dadnos luz!;\nSu amor, su gracia afirma el corazón,\n¡Dadnos luz! ¡Dadnos luz!.'),(1350,215,'Coro',6,'¡Dadnos Luz, la gloriosa luz!\nDel perdón de paz y amor;\n¡Dadnos Luz, la preciosa luz!\nDe Jesús, el Salvador.'),(1351,215,'Estrofa',7,'Oh creyentes fieles, todo el mundo henchid,\nDe esa luz de Jesús;\nA salvar millares sin tardar, salid,\n¡Con la luz de Jesús!.'),(1352,215,'Coro',8,'¡Dadnos Luz, la gloriosa luz!\nDel perdón de paz y amor;\n¡Dadnos Luz, la preciosa luz!\nDe Jesús, el Salvador.'),(1353,216,'Estrofa',1,'Quiero seguir las pisadas de Cristo,\nQuiero ir en pos de mi Rey y Señor;\nY modelando por Él mi carácter,\nCanto con gozo a mi Redentor'),(1354,216,'Coro',2,'¡Qué hermoso es seguir, las pisadas de Cristo!,\nSiempre en la Luz, cerca de Jesús;\n¡Qué hermoso es seguir, las pisadas de Cristo!,\nEn su santa luz.'),(1355,216,'Estrofa',3,'Ando mas cerca de ÉL que me guía,\nCuando el maligno me quiere tentar;\nSiempre confiando en Cristo mi fuerte,\nDebo con gozo su nombre ensalzar.'),(1356,216,'Coro',4,'¡Qué hermoso es seguir, las pisadas de Cristo!,\nSiempre en la Luz, cerca de Jesús;\n¡Qué hermoso es seguir, las pisadas de Cristo!,\nEn su santa luz.'),(1357,216,'Estrofa',5,'Sigo sus pasos de tierno cariño,\nMisericordia, amor y lealtad;\nViendo hacia ÉL por el don de su gracia,\nVoy al descanso, gloriosa ciudad.'),(1358,216,'Coro',6,'¡Qué hermoso es seguir, las pisadas de Cristo!,\nSiempre en la Luz, cerca de Jesús;\n¡Qué hermoso es seguir, las pisadas de Cristo!,\nEn su santa luz.'),(1359,216,'Estrofa',7,'Quiero seguir las pisadas de Cristo,\nPor donde vaya con ÉL quiero andar;\nViendo a mi Rey en gloriosa hermosura,\nCon ÉL en gloria, podré descansar.'),(1360,216,'Coro',8,'¡Qué hermoso es seguir, las pisadas de Cristo!,\nSiempre en la Luz, cerca de Jesús;\n¡Qué hermoso es seguir, las pisadas de Cristo!,\nEn su santa luz.'),(1361,217,'Estrofa',1,'Grato es contar la historia, del celestial favor,\nDe Cristo y de su gloria, de Cristo y de su amor;\nMe agrada referirla, pues sé que es la verdad,\ny nada satisface, cual ella mi ansiedad.'),(1362,217,'Coro',2,'¡Cuán bella es esa historia!, mi tema ya en gloria,\nSerá ensalzar la historia, de Cristo y de su amor.'),(1363,217,'Estrofa',3,'Grato es contar la historia, más bella que escuché,\nMas áurea, mas hermosa, que cuanto yo soñé;\nContarla siempre anhelo, pues hay quien nunca oyó,\nQue para hacerle salvo, Cristo en la Cruz murió.'),(1364,217,'Coro',4,'¡Cuán bella es esa historia!, mi tema ya en gloria,\nSerá ensalzar la historia, de Cristo y de su amor.'),(1365,217,'Estrofa',5,'Grato es contar la historia, qué placentera es,\nY es más, al repetirla, preciosa cada vez;\nLa historia, pues que canto, oíd con atención,\nPorque es mensaje santo, de eterna salvación.'),(1366,217,'Coro',6,'¡Cuán bella es esa historia!, mi tema ya en gloria,\nSerá ensalzar la historia, de Cristo y de su amor.'),(1367,217,'Estrofa',7,'Grato es contar la historia, de todas la mejor,\nQue cuanto más escuche, me infunde más amor;\nY cuando ya en gloria, entone mi cantar,\nSerá la misma historia, que tanto supe amar.'),(1368,217,'Coro',8,'¡Cuán bella es esa historia!, mi tema ya en gloria,\nSerá ensalzar la historia, de Cristo y de su amor.'),(1369,218,'Estrofa',1,'No hay cual Jesús otro fiel amigo\nNo lo hay, no lo hay;\nOtro que pueda salvar las almas,\nNo lo hay, no lo hay.'),(1370,218,'Coro',2,'Conoce todas nuestras luchas\nY solo Él nos sostendrá;\nNo hay cual Jesús otro fiel amigo,\nNo lo hay, no lo hay.'),(1371,218,'Estrofa',3,'No hay otro amigo tan santo y digno,\nNo lo hay, no lo hay\nPero a la vez es humilde y tierno,\nNo lo hay, no lo hay'),(1372,218,'Coro',4,'Conoce todas nuestras luchas\nY solo Él nos sostendrá;\nNo hay cual Jesús otro fiel amigo,\nNo lo hay, no lo hay.'),(1373,218,'Estrofa',5,'No hay un instante que nos olvide,\nNo lo hay, no lo hay;\nNo hay noche oscura\nQue no nos cuide,\nNo lo hay, no lo hay'),(1374,218,'Coro',6,'Conoce todas nuestras luchas\nY solo Él nos sostendrá;\nNo hay cual Jesús otro fiel amigo,\nNo lo hay, no lo hay.'),(1375,219,'Estrofa',1,'Tierra bendita y divina, es la de Palestina,\nDonde nació Jesús;\nEres de las naciones cumbre,\nBañada con la lumbre que derramó su luz.'),(1376,219,'Coro',2,'Eres la historia inolvidable,\nPorque en tu seno se derramó,\n//La sangre, preciosa sangre, del\nUnigénito Hijo de Dios.//'),(1377,219,'Estrofa',3,'Cuenta la historia del pasado,\nQue en su seno sagrado vivió El Salvador;\ny en sus hermosos Olivares,\nHabló a los millares la Palabra de amor.'),(1378,219,'Coro',4,'Eres la historia inolvidable,\nPorque en tu seno se derramó,\n//La sangre, preciosa sangre, del\nUnigénito Hijo de Dios.//'),(1379,219,'Estrofa',5,'Quedan en ti testigos mudos,\nQue son los viejos muros de la Jerusalén;\nViejas paredes destruidas,\nQue si tuvieran vida nos hablarían también.'),(1380,219,'Coro',6,'Eres la historia inolvidable,\nPorque en tu seno se derramó,\n//La sangre, preciosa sangre, del\nUnigénito Hijo de Dios.//'),(1381,220,'Estrofa',1,'Tu corazón pide el Dios de bondad,\nQuiere llenarlo de paz y de amor;\nPonlo a sus plantas con fe y humildad,\n“Toma, Señor”, Dile, “mi corazón”.'),(1382,220,'Coro',2,'“Tu corazón, tu corazón”,\nOye la voz que te sigue doquier;\nLibre del mundo te quiere tener,\n“Dime”, te dice hoy “tu corazón”'),(1383,220,'Estrofa',3,'Tu corazón busca el buen Salvador,\nDon más precioso no quiero tener;\nPaso tras paso te sigue su amor,\n“Dame”, diciéndote, “Tu corazón”.'),(1384,220,'Coro',4,'“Tu corazón, tu corazón”,\nOye la voz que te sigue doquier;\nLibre del mundo te quiere tener,\n“Dime”, te dice hoy “tu corazón”'),(1385,220,'Estrofa',5,'Tu corazón busca el Consolador,\nPara llenarlo de gracia y poder;\nÉl es del Padre el enviado de amor,\nRinde al Padre tu corazón.'),(1386,220,'Coro',6,'“Tu corazón, tu corazón”,\nOye la voz que te sigue doquier;\nLibre del mundo te quiere tener,\n“Dime”, te dice hoy “tu corazón”'),(1387,221,'Estrofa',1,'Ignoro yo por que será,\nMis planes veo fracasar;\nMas cuando llegue a ver al Rey,\nEntonces yo comprenderé.'),(1388,221,'Coro',2,'Un día yo comprenderé,\nUn día, cuando le veré;\nDe lágrimas libre seré,\nYo sé que lo entenderé.'),(1389,221,'Estrofa',3,'En mi carrera hay gran dolor,\nAfán, pesar, o cruel temor;\nMas cuando en Sión con ÉL esté,\nEntonces yo comprenderé.'),(1390,221,'Coro',4,'Un día yo comprenderé,\nUn día, cuando le veré;\nDe lágrimas libre seré,\nYo sé que lo entenderé.'),(1391,221,'Estrofa',5,'En medio de tribulación,\nEn tentación o aflicción;\nDescansaré en el amor,\nDe Jesús, mi Salvador.'),(1392,221,'Coro',6,'Un día yo comprenderé,\nUn día, cuando le veré;\nDe lágrimas libre seré,\nYo sé que lo entenderé.'),(1393,222,'Estrofa',1,'Quiero que habléis de aquel grande amor,\nQue en el Calvario Dios nos mostró;\nQuiero que habléis del buen Salvador,\n¡Habladme más de Cristo!.'),(1394,222,'Coro',2,'Quiero escuchar la historia fiel,\nDe Jesús, mi Salvador;\nQuiero vivir tan solo por ÉL,\n¡Habladme más de Cristo!.'),(1395,222,'Estrofa',3,'Cuando me asalte la tentación,\nY que sus redes tienda a mi pie;\nQuiero tener en ÉL protección,\n¡Habladme más de Cristo!.'),(1396,222,'Coro',4,'Quiero escuchar la historia fiel,\nDe Jesús, mi Salvador;\nQuiero vivir tan solo por ÉL,\n¡Habladme más de Cristo!.'),(1397,222,'Estrofa',5,'Cuando en la lucha falte la fe,\nY el alma sienta desfallecer;\nQuiero saber que ayuda tendré,\n¡Habladme más de Cristo!.'),(1398,222,'Coro',6,'Quiero escuchar la historia fiel,\nDe Jesús, mi Salvador;\nQuiero vivir tan solo por ÉL,\n¡Habladme más de Cristo!.'),(1399,223,'Estrofa',1,'El oro y la plata no me han redimido,\nMi ser del pecado no pueden librar;\nLa sangre de Cristo es mi sola esperanza,\nSu muerte tan solo me puede salvar.'),(1400,223,'Coro',2,'Me redimió, mas no con plata,\nMe compró mi Salvador;\nCon oro, no, mas con su sangre,\n¡Gran precio de su amor!.'),(1401,223,'Estrofa',3,'El oro y la plata no me han redimido,\nLa pena terrible no pueden quitar;\nLa Sangre de Cristo es mi sola esperanza,\nMi culpa su muerte la alcanza a borrar.'),(1402,223,'Coro',4,'Me redimió, mas no con plata,\nMe compró mi Salvador;\nCon oro, no, mas con su sangre,\n¡Gran precio de su amor!.'),(1403,224,'Estrofa',1,'En tu cena nos juntamos,\nSeñor, para celebrar,\nTu pasión y cruel muerte,\nY en tu grande amor pensar;\nGrande amor, grande amor,\nY en tu grande amor pensar.'),(1404,224,'Estrofa',2,'Redimidos ya tenemos,\nPor tu muerte comunión;\nEn el pan te recordamos,\nDios de nuestra salvación;\nSalvación, salvación,\nDios de nuestra salvación.'),(1405,224,'Estrofa',3,'En la copa confesamos,\nQue tu sangre es eficaz;\nPor tu salvación perfecta,\nEsperamos ver tu faz;\nVer tu faz Ver tu faz,\nEsperamos ver tu faz.'),(1406,224,'Estrofa',4,'Por tu gracia congregados,\nEn tu paz y con amor;\nEn espíritu cantamos,\nA Ti nuestro Redentor;\nRedentor, Redentor ,\nA Ti nuestro Redentor'),(1407,225,'Estrofa',1,'El Señor Jesús está llamando,\n¿Quién al campo a trabajar irá?\n¿Quién ira buscando a los perdidos?\n¿Quién la senda les enseñara?'),(1408,225,'Coro',2,'Háblame, Oh, háblame,\nY heme aquí responderé Señor;\nHáblame, te diré;\n“Heme aquí, Oh, envíame Señor”'),(1409,225,'Estrofa',3,'Cuando el trozo de carbón ardiente,\nAl profeta fiel purificó;\nAl oír la voz que le llamaba,\nMándame, Señor, él respondió.'),(1410,225,'Coro',4,'Háblame, Oh, háblame,\nY heme aquí responderé Señor;\nHáblame, te diré;\n“Heme aquí, Oh, envíame Señor”'),(1411,225,'Estrofa',5,'Hay millones que en pecado mueren,\nEscuchad su llanto de dolor;\nAcudid con tiempo a rescatarles,\n¿Quién dirá: Oh, envíame, Señor?'),(1412,225,'Coro',6,'Háblame, Oh, háblame,\nY heme aquí responderé Señor;\nHáblame, te diré;\n“Heme aquí, Oh, envíame Señor”'),(1413,225,'Estrofa',7,'Pronto el tiempo de la siega pasa,\nPronto iremos al deseado Edén;\nOjalá que aquel solemne día,\nCristo allí nos diga: “Hiciste bien”.'),(1414,225,'Coro',8,'Háblame, Oh, háblame,\nY heme aquí responderé Señor;\nHáblame, te diré;\n“Heme aquí, Oh, envíame Señor”'),(1415,226,'Estrofa',1,'Cuando junte Jesús las naciones,\nQue ante Él han de comparecer,\n!Oh! ¿Cómo hemos de estar en el juicio,\nel fallo del juez al saber?'),(1416,226,'Coro',2,'Juntará todo el trigo en su troje,\nmas al viento el tamo esparcirá;\nPues, ¿Cómo hemos de estar en el juicio,\nDel gran día que pronto vendrá?'),(1417,226,'Estrofa',3,'¿Del Señor las palabras oiremos:\n“Bien hecho, mi buen siervo fiel”*;\n¿O temblando de espanto seremos,\nQuitados del trono por Él?.'),(1418,226,'Coro',4,'Juntará todo el trigo en su troje,\nmas al viento el tamo esparcirá;\nPues, ¿Cómo hemos de estar en el juicio,\nDel gran día que pronto vendrá?'),(1419,226,'Estrofa',5,'Mirará complacido a sus hijos,\nSu sello en sus frentes verá;\nMientras ellos de hinojos le adoren,\nCoronas de luz les pondrá.'),(1420,226,'Coro',6,'Juntará todo el trigo en su troje,\nmas al viento el tamo esparcirá;\nPues, ¿Cómo hemos de estar en el juicio,\nDel gran día que pronto vendrá?'),(1421,226,'Estrofa',7,'Esperemos, velemos y hagamos,\nLas lámparas todas brillar;\nY al venir el Esposo a las bodas,\nGozosos podremos entrar.'),(1422,226,'Coro',8,'Juntará todo el trigo en su troje,\nmas al viento el tamo esparcirá;\nPues, ¿Cómo hemos de estar en el juicio,\nDel gran día que pronto vendrá?'),(1423,227,'Estrofa',1,'¡Santo! ¡Santo! Grande, Eterno Dios,\ncon alegría, Hoy te alabamos,\nRey de Reyes, Grande Capitán,\nTodopoderoso Guerrero,\nhonor y gloria, Luz y dominio\ntributaremos todos a Ti'),(1424,227,'Coro',2,'¡Santo! ¡Santo! Eres Tú, Señor,\n¡Dios de las batallas Glorioso!'),(1425,227,'Estrofa',3,'Alabadle, cielos tierra y mar,\nToda su Iglesia, Sus mensajeros;\nAlabanzas, cantos de loor;\nHoy unidos celebraremos,\nJuez Majestuoso y Reverendo\nFuego y vida eres Señor.'),(1426,227,'Coro',4,'¡Santo! ¡Santo! Eres Tú, Señor,\n¡Dios de las batallas Glorioso!'),(1427,227,'Estrofa',5,'Rey de siglos, solo eterno Dios,\nVeraz y Justo, Incomparable;\nInmortal, autor de todo bien,\nEres el autor de la vida,\nY para siempre, entonaremos\nEl canto eterno de redención.'),(1428,227,'Coro',6,'¡Santo! ¡Santo! Eres Tú, Señor,\n¡Dios de las batallas Glorioso!'),(1429,228,'Estrofa',1,'Tengo un amigo Cristo el Señor,\nYo le bendigo con mi loor;\nPorque en el mundo nadie como Él,\nEs en mi vida paciente y fiel.'),(1430,228,'Coro',2,'Cristo mi amigo, ya tuyo soy,\n¡Todo, rendido, contigo voy!'),(1431,228,'Estrofa',3,'Tengo un refugio que en el turbión,\nDel alma es siempre fiel protección;\nCon el seguro yo viviré,\nPorque a su amparo caminaré.'),(1432,228,'Coro',4,'Cristo mi amigo, ya tuyo soy,\n¡Todo, rendido, contigo voy!'),(1433,228,'Estrofa',5,'Tengo un maestro doquier yo voy,\nY sus senderos siguiendo estoy;\nEn las tinieblas jamás iré,\nPorque sus luces y amor tendré.'),(1434,228,'Coro',6,'Cristo mi amigo, ya tuyo soy,\n¡Todo, rendido, contigo voy!'),(1435,228,'Estrofa',7,'¡Oh, dulce amigo! tu compasión,\nHa subyugado mi corazón;\n¿Cómo rebelde pudiera ser,\nY tanta gracia desconocer?.'),(1436,228,'Coro',8,'Cristo mi amigo, ya tuyo soy,\n¡Todo, rendido, contigo voy!'),(1437,229,'Estrofa',1,'Haz lo que quieras de mi Señor,\nTú el alfarero, yo el barro soy;\nDócil y humilde anhelo ser,\nCúmplase siempre en mi tu querer.'),(1438,229,'Estrofa',2,'Haz lo que quieras de mi Señor,\nMírame y prueba mi corazón;\nLávame, y quita toda maldad,\nPara que pueda contigo estar.'),(1439,229,'Estrofa',3,'Haz lo que quieras de mí, Señor,\nCura mis llagas y mi dolor;\nTuyo es oh, Cristo todo poder,\nTu mano extiende y sanaré.'),(1440,229,'Estrofa',4,'Haz lo que quieras de mi Señor,\nDueño absoluto de mí Tú sé;\nDame la unción del consolador,\nY el mundo a Cristo pueda en mi ver.'),(1441,230,'Estrofa',1,'Al andar con Jesús en su fúlgida luz;\nEn mi senda su gloria veré,\nY su voz he de oír, pues promete vivir,\nCon aquel que obedezca por fe.'),(1442,230,'Coro',2,'Su santa ley obedezco por fe,\nY feliz en mi maestro,\nYo por siempre seré.'),(1443,230,'Estrofa',3,'No habrá nubes jamás, ni una sombra pues las,\nQuitará la sonrisa del Rey, llanto no hay ni dolor,\nNi le espanta el temor,\nAl que Dios obedezca por fe.'),(1444,230,'Coro',4,'Su santa ley obedezco por fe,\nY feliz en mi maestro,\nYo por siempre seré.'),(1445,230,'Estrofa',5,'Si trabajo y penar, tengo yo que cargar;\nRico pago en Jesús obtendré;\nPues alivia su amor, mi afán mi dolor,\nCuando ve que obedezco por fe.'),(1446,230,'Coro',6,'Su santa ley obedezco por fe,\nY feliz en mi maestro,\nYo por siempre seré.'),(1447,230,'Estrofa',7,'Nunca pude saber de su amor y placer,\nHasta que todo a Cristo entregue;\nSu bondad su favor, su poder redentor,\nGoza aquel que obedezca por fe.'),(1448,230,'Coro',8,'Su santa ley obedezco por fe,\nY feliz en mi maestro,\nYo por siempre seré.'),(1449,231,'Estrofa',1,'En Jesucristo confía no más,\nPon tu carga en Jesús;\nPaz y socorro de el obtendrás,\nPon tu carga en Jesús.'),(1450,231,'Coro',2,'Pon tu carga en Jesús y dile tu cruel dolor,\nEn Cristo tu amigo tendrás un abrigo;\n¡Oh, Pon tu carga en Jesús!'),(1451,231,'Estrofa',3,'Paz redentora tu alma tendrá,\nPon tu carga en Jesús;\nDe inquietudes te libertará,\nPon tu carga en Jesús.'),(1452,231,'Coro',4,'Pon tu carga en Jesús y dile tu cruel dolor,\nEn Cristo tu amigo tendrás un abrigo;\n¡Oh, Pon tu carga en Jesús!'),(1453,231,'Estrofa',5,'De los conflictos no huyas jamás,\nPon tu carga en Jesús;\nEn el desierto no busques la paz,\nPon tu carga en Jesús.'),(1454,231,'Coro',6,'Pon tu carga en Jesús y dile tu cruel dolor,\nEn Cristo tu amigo tendrás un abrigo;\n¡Oh, Pon tu carga en Jesús!'),(1455,231,'Estrofa',7,'¿Males te asaltan doquier pecador?\nPon tu carga en Jesús;\n¿Vas ya cansado de pena y dolor?\nPon tu carga en Jesús.'),(1456,231,'Coro',8,'Pon tu carga en Jesús y dile tu cruel dolor,\nEn Cristo tu amigo tendrás un abrigo;\n¡Oh, Pon tu carga en Jesús!'),(1457,231,'Estrofa',9,'Cristo podrá disipar tu temor,\nPon tu carga en Jesús;\nA los devotos les da gran valor,\nPon tu carga en Jesús.'),(1458,231,'Coro',10,'Pon tu carga en Jesús y dile tu cruel dolor,\nEn Cristo tu amigo tendrás un abrigo;\n¡Oh, Pon tu carga en Jesús!'),(1459,232,'Estrofa',1,'¡Oh, Cristo, nuestra Roca aquí!,\nY abrigo de la tempestad;\nDichoso el que se esconda en ti,\nAbrigo de la tempestad.'),(1460,232,'Coro',2,'En tierra de cansancio, Jesús Roca es,\nJesús Roca es, Jesús Roca es;\nEn tierra de cansancio, Jesús Roca es,\nY abrigo de la tempestad.'),(1461,232,'Estrofa',3,'Sombra eres Tú y escudo fiel,\nY abrigo de la tempestad;\n¿Por que temer con tal broquel,\ny abrigo de la tempestad?'),(1462,232,'Coro',4,'En tierra de cansancio, Jesús Roca es,\nJesús Roca es, Jesús Roca es;\nEn tierra de cansancio, Jesús Roca es,\nY abrigo de la tempestad.'),(1463,232,'Estrofa',5,'En Ti encontramos del turbión,\nAbrigo de la tempestad;\nEn Ti halla siempre el corazón,\nAbrigo de la tempestad.'),(1464,232,'Coro',6,'En tierra de cansancio, Jesús Roca es,\nJesús Roca es, Jesús Roca es;\nEn tierra de cansancio, Jesús Roca es,\nY abrigo de la tempestad.'),(1465,232,'Estrofa',7,'Refugio Tú eres, Salvador,\nY abrigo de la tempestad;\nSí, nuestro gran auxiliar,\nY abrigo de la tempestad.'),(1466,232,'Coro',8,'En tierra de cansancio, Jesús Roca es,\nJesús Roca es, Jesús Roca es;\nEn tierra de cansancio, Jesús Roca es,\nY abrigo de la tempestad.'),(1467,233,'Estrofa',1,'El sábado glorioso feliz nos cubre ya,\nYa van a ser las ocho las diez pronto serán;\nDel sueño despertemos, a tiempo hay que llegar,\nNo demos mal ejemplo la clase va a empezar.'),(1468,233,'Estrofa',2,'¡ Mi Biblia y mi cuaderno! me quiero alistar,\nDespués del desayuno a la Iglesia marchar;\nEl texto de memoria me van a preguntar,\n¡Que bella es la historia que hoy vamos a estudiar!'),(1469,233,'Estrofa',3,'Al dividir las clases contento marcharé,\nMi Biblia y mi lápiz conmigo llevaré;\nPrometo a mi maestro con atención oír,\n“De tu doctrina, oh Cristo, en pos anhelo ir”.'),(1470,233,'Estrofa',4,'Prometo quietecito la clase estudiar,\nOyendo calladito lo que se va a enseñar;\nY al terminar la clase y de otros ir en pos,\n¡Ni un grito ni una frase! Pues es casa de Dios.'),(1471,234,'Estrofa',1,'Dad a Dios inmortal alabanza,\nSu merced, su bondad nos inunda;\nEn su gracia prodigios fecunda,\nSus mercedes humildes cantad.\nAl Señor de señores dad gloria,\nRey de reyes, poder sin segundo;\nMorirán los señores del mundo,\nMas su Reino no acaba jamás.'),(1472,234,'Estrofa',2,'Las naciones vio en vicio sumidas,\nY sintió compasión en su seno;\nDe prodigios de gracia está lleno,\nSus mercedes humildes cantad.\nA su pueblo llevó por la mano,\nA la tierra por Él prometida,\nPor los siglos sin fin le da vida,\nY el pecado y la muerte caerán.'),(1473,234,'Estrofa',3,'A su Hijo envío por salvarnos,\nDel pecado y la muerte inherente;\nDe prodigio de gracia es torrente,\nSus mercedes humildes cantad.\nPor el mundo su mano nos lleva,\nY al eterno descanso nos guía;\nSu bondad vivirá eterno día,\nCuando el mal no ha de hallarse jamás.'),(1474,235,'Estrofa',1,'La tierna voz de el Salvador,\nNos habla conmovida;\nOíd al Médico de Amor,\nQue da a los muertos vida.'),(1475,235,'Coro',2,'Nunca los hombres cantarán,\nNunca los ángeles en luz;\nNota mas dulce entonarán,\nQue el nombre de Jesús.'),(1476,235,'Estrofa',3,'Cordero manso ¡Gloria a Ti!,\nPor Salvador te aclamo;\nTu dulce nombre es para mí,\nLa joya que mas amo.'),(1477,235,'Coro',4,'Nunca los hombres cantarán,\nNunca los ángeles en luz;\nNota mas dulce entonarán,\nQue el nombre de Jesús.'),(1478,235,'Estrofa',5,'La amarga copa de dolor,\nJesús, fue tu bebida;\nEn cambio das al pecador,\nEl agua de la vida.'),(1479,235,'Coro',6,'Nunca los hombres cantarán,\nNunca los ángeles en luz;\nNota mas dulce entonarán,\nQue el nombre de Jesús.'),(1480,235,'Estrofa',7,'“Borradas ya tus culpas son”,\nSu voz hoy te pregona;\nAcepta, pues la salvación,\nY espera la corona.'),(1481,235,'Coro',8,'Nunca los hombres cantarán,\nNunca los ángeles en luz;\nNota mas dulce entonarán,\nQue el nombre de Jesús.'),(1482,236,'Estrofa',1,'Mi espíritu, alma y cuerpo,\nMi ser, mi vida eterna;\nCual viva santa ofrenda,\nEntrego a Ti mi Dios.'),(1483,236,'Coro',2,'Mi todo a Dios consagro,\nEn Cristo el vivo altar.\n¡Descienda el fuego santo,\nSu sello celestial!.'),(1484,236,'Estrofa',3,'Soy tuyo, Jesucristo,\nComprando con tu sangre;\nHaz que Contigo ande,\nEn plena comunión.'),(1485,236,'Coro',4,'Mi todo a Dios consagro,\nEn Cristo el vivo altar.\n¡Descienda el fuego santo,\nSu sello celestial!.'),(1486,236,'Estrofa',5,'Espíritu Divino,\nDel Padre la promesa;\nSedienta, mi alma anhela,\nCon Él, Santa Unción.'),(1487,236,'Coro',6,'Mi todo a Dios consagro,\nEn Cristo el vivo altar.\n¡Descienda el fuego santo,\nSu sello celestial!.'),(1488,237,'Estrofa',1,'Lugar hay donde descansar,\nCerca al corazón de Dios;\nDo nada puede molestar,\nCerca al corazón de Dios.'),(1489,237,'Coro',2,'Jesús, del cielo enviado,\nDel corazón de Dios;\n¡Oh siempre cerca tennos,\nAl corazón de Dios!.'),(1490,237,'Estrofa',3,'Lugar hay de consuelo y luz,\nCerca al corazón de Dios;\nDo nos juntamos con Jesús,\nCerca al corazón de Dios.'),(1491,237,'Coro',4,'Jesús, del cielo enviado,\nDel corazón de Dios;\n¡Oh siempre cerca tennos,\nAl corazón de Dios!.'),(1492,237,'Estrofa',5,'Lugar hay de eternal solaz,\nCerca al corazón de Dios;\nDo Cristo otorga gozo y paz,\nCerca al corazón de Dios.'),(1493,237,'Coro',6,'Jesús, del cielo enviado,\nDel corazón de Dios;\n¡Oh siempre cerca tennos,\nAl corazón de Dios!.'),(1494,238,'Estrofa',1,'Día santo del Señor,\n¡Oh cuán pronto en pasar!;\nSólo vino poco ha,\nYa lo vemos terminar.\n//Y volando al cielo va,\nFiel testigo allí será;//'),(1495,238,'Estrofa',2,'¿Cual informe llevará,\nAl celeste tribunal?;\n¿De maldades hablará,\nO cuidado mundanal?;\n//¿O de santa adoración,\nCon Jesús en comunión?//.'),(1496,238,'Estrofa',3,'¡Oh perdónanos, Señor,\nEl mal uso de tu don!;\nLos preceptos de tu ley,\nGraba en nuestro corazón;\n//Es tu sábado Señor,\nDía santo de tu amor//.'),(1497,239,'Estrofa',1,'A lugares obscuros, por Cristo el Señor,\nPronto iré porque Él vino a morir;\nPor aquellos que viven sin Dios y su amor,\nY les quiero las nuevas decir.'),(1498,239,'Coro',2,'Do me envíes , Señor,\nPronto iré por doquier;\nPara que de tu amor,\nPueda oír todo ser.'),(1499,239,'Estrofa',3,'Aunque duro el lugar do me llame que esté,\nListo estoy por Él sacrificar;\nAunque el mundo me tenga por fatuo, yo sé,\nQue al maestro yo debo agradar.'),(1500,239,'Coro',4,'Do me envíes , Señor,\nPronto iré por doquier;\nPara que de tu amor,\nPueda oír todo ser.'),(1501,239,'Estrofa',5,'Vuestros bienes y vida ¿Por que malgastar,\nEn placeres del mundo fugaz?;\nDe este sueño y sopor pronto hay que despertar,\nPara andar con las nuevas de paz.'),(1502,239,'Coro',6,'Do me envíes , Señor,\nPronto iré por doquier;\nPara que de tu amor,\nPueda oír todo ser.'),(1503,239,'Estrofa',7,'Las ovejas pedidas que busca el Pastor,\nNo han podido su voz escuchar;\nDel peligro Él las busca, salvar en su amor,\nY al aprisco las quiere llevar.'),(1504,239,'Coro',8,'Do me envíes , Señor,\nPronto iré por doquier;\nPara que de tu amor,\nPueda oír todo ser.'),(1505,240,'Estrofa',1,'Hay un lugar do quiero estar,\nMuy cerca de mi Redentor;\nAllí podré yo descansar,\nAl fiel amparo de su amor.'),(1506,240,'Coro',2,'Muy cerca de mi Redentor,\nSeguro asilo encontraré;\nMe guardara del tentador,\nY ya de nada temeré.'),(1507,240,'Estrofa',3,'Quitarme el mundo no podrá,\nLa paz que halló mi corazón;\nJesús amante me dará,\nLa mas segura protección.'),(1508,240,'Coro',4,'Muy cerca de mi Redentor,\nSeguro asilo encontraré;\nMe guardara del tentador,\nY ya de nada temeré.'),(1509,240,'Estrofa',5,'Ni dudas ni temor tendré,\nEstando cerca de Jesús;\nRodeado siempre me veré,\nCon los fulgores de su luz.'),(1510,240,'Coro',6,'Muy cerca de mi Redentor,\nSeguro asilo encontraré;\nMe guardara del tentador,\nY ya de nada temeré.'),(1511,241,'Estrofa',1,'Si en tu senda las nubes agolparse ves,\nNo vaciles por ello, ni flaqueen tus pies;\nCada nube que venga, no podrá traer,\nMas que pruebas que pasan, si hay y valor y fe.'),(1512,241,'Coro',2,'Si hay valor y fe, si hay valor y fe\nEn la mas obscura noche, siempre hay luz\nSi hay valor y fe, si hay valor y fe\nGozo y paz traerá la lucha, si hay valor y fe'),(1513,241,'Estrofa',3,'Si es tu vida una carga de cuidados mil,\nOlvidado de todos, te podrás sentir;\nSi una ayuda acudieres, a llevar doquier,\nEsto endulza la vida, ¡Si hay valor y fe!.'),(1514,241,'Coro',4,'Si hay valor y fe, si hay valor y fe\nEn la mas obscura noche, siempre hay luz\nSi hay valor y fe, si hay valor y fe\nGozo y paz traerá la lucha, si hay valor y fe'),(1515,241,'Estrofa',5,'Pon en alto los ojos sin dudar jamás,\nQue en las lides del mundo vencedor saldrás;\nQue si ha flores y encantos tras invierno cruel,\nTrae encantos la vida , ¡Si hay valor y fe!'),(1516,241,'Coro',6,'Si hay valor y fe, si hay valor y fe\nEn la mas obscura noche, siempre hay luz\nSi hay valor y fe, si hay valor y fe\nGozo y paz traerá la lucha, si hay valor y fe'),(1517,242,'Estrofa',1,'Yo soy peregrino,\ncaminando voy,\nSurcando el camino,\ncamino de Sión;'),(1518,242,'Estrofa',2,'Habito en cabañas,\nno es aquí mi país,\nY aunque habite en cabañas,\nEn Jesús soy feliz.'),(1519,243,'Estrofa',1,'Salvador, oh dicha eterna,\nMás que vida eres aquí,\nEn la tenebrosa senda,\nLleva mi alma junto a Ti;\nJunto a Ti, Junto a Ti,\nJunto a Ti, Junto a Ti,\nEn la tenebrosa senda,\nLleva mi alma junto a Ti.'),(1520,243,'Estrofa',2,'No ansío mas placeres\nNi renombre busco aquí,\nSufriré si Tú lo quieres,\nPero tenme junto a Ti;\nJunto a Ti, Junto a Ti,\nJunto a Ti, Junto a Ti,\nSufriré si tu lo quieres,\nPero tenme junto a Ti.'),(1521,243,'Estrofa',3,'No me dejes en el valle,\nDde la muerte sucumbir,\nHaz que auxilio presto halle,\nYyendo siempre junto a Ti.\nJunto a Ti, Junto a Ti,\nJunto a Ti, Junto a Ti,\nHaz que auxilio presto halle,\nYendo siempre junto a Ti.'),(1522,244,'Estrofa',1,'Otro amigo como Cristo no hay,\nQue a las almas de salud no lo hay;\nNo hay palacio igual también,\nComo el de mi eterno Rey;\nDo con Él yo reinaré, no lo hay.'),(1523,244,'Coro',2,'No lo hay, no lo hay, no lo hay, no lo hay,\nEn el palacio del Rey;\nDo estará toda su grey,\nEs un sitio que otro igual, no lo hay.'),(1524,244,'Estrofa',3,'Otro Rey como mi Cristo no hay,\nQue de mar a mar domine no hay;\nNo hay corona igual yo sé\ncomo la que ostentaré\nY triunfante cantaré, no lo hay.'),(1525,244,'Coro',4,'No lo hay, no lo hay, no lo hay, no lo hay,\nEn el palacio del Rey;\nDo estará toda su grey,\nEs un sitio que otro igual, no lo hay.'),(1526,244,'Estrofa',5,'Níveas ropas como aquellas no hay,\nLas que luciré en el Reino, no hay;\nEntre los santos allí, yo siempre me hallaré,\nOtra dicha como aquella no hay.'),(1527,244,'Coro',6,'No lo hay, no lo hay, no lo hay, no lo hay,\nEn el palacio del Rey;\nDo estará toda su grey,\nEs un sitio que otro igual, no lo hay.'),(1528,244,'Estrofa',7,'Otra reunión como esta no hay,\nDo contemple a los profetas, no hay;\nLos apóstoles también,\nJunto a Cristo allí veré;\nY con ellos cantaré, no lo hay.'),(1529,244,'Coro',8,'No lo hay, no lo hay, no lo hay, no lo hay,\nEn el palacio del Rey;\nDo estará toda su grey,\nEs un sitio que otro igual, no lo hay.'),(1530,245,'Estrofa',1,'De Jesús bella historia anhelo contar,\nMi alma, estando perdida, vino a rescatar;\nEs la historia que habla de cuanto me amó,\nPor gracia me levantó.'),(1531,245,'Coro',2,'El me levantó ¡Oh gloria de Dios!,\nMi senda trazó, voy de Él en pos;\nSiento su perdón, mi alma salvo,\nPor gracia me levantó.'),(1532,245,'Estrofa',3,'Cuando en tétrico océano iba a sucumbir,\nMi Señor presto vino mi alma a redimir;\nComo puedo pagarle este inmenso amor,\nPor gracia me levantó.'),(1533,245,'Coro',4,'El me levantó ¡Oh gloria de Dios!,\nMi senda trazó, voy de Él en pos;\nSiento su perdón, mi alma salvo,\nPor gracia me levantó.'),(1534,245,'Estrofa',5,'Ya no siento temores, ya no hay más pesar,\nEl Señor de señores me cuida del mal;\nDel poder de la muerte ya me rescató,\nPor gracia me levantó.'),(1535,245,'Coro',6,'El me levantó ¡Oh gloria de Dios!,\nMi senda trazó, voy de Él en pos;\nSiento su perdón, mi alma salvo,\nPor gracia me levantó.'),(1536,246,'Estrofa',1,'Dime la historia de Cristo, grábala en mi corazón,\nEsta historia tan dulce, que no la puedo olvidar;\nDi como el coro celeste, su dulce canto entonó,\n“Gloria a Dios en lo alto, y aquí paz, que el Rey ya\nnació'),(1537,246,'Coro',2,'Dime la historia de Cristo, grábala en mi corazón,\nEsta historia tan dulce, que no la puedo olvidar.'),(1538,246,'Estrofa',3,'Cuéntame como mi culpa su existencia abrumó,\nY pruebas mil le acosaron pero de todas triunfo;\nHáblame de los tormentos y del dolor que sufrió,\nCuando se vio abandonado y en cruz atroz,\nÉl falleció.'),(1539,246,'Coro',4,'Dime la historia de Cristo, grábala en mi corazón,\nEsta historia tan dulce, que no la puedo olvidar.'),(1540,246,'Estrofa',5,'Y sobre todo habladme de como resucitó,\nY al ascender a su Padre nuestro rescate selló;\nDi cómo desde su Trono nos manda todo el poder,\nQue aquí necesitamos para el pecado vencer.'),(1541,246,'Coro',6,'Dime la historia de Cristo, grábala en mi corazón,\nEsta historia tan dulce, que no la puedo olvidar.'),(1542,247,'Estrofa',1,'Gozo da servir a Cristo,\nEn la vida diaria aquí;\nGozo, que con alegría,\nSiempre Él me da a mí.'),(1543,247,'Coro',2,'Gozo hay, si en servir a Cristo,\nGozo en el corazón;\nCada día Él da poder,\nMe ayuda a vencer;\nY da gozo, gozo en el corazón.'),(1544,247,'Estrofa',3,'Gozo da servir a Cristo,\nGozo que triunfante está;\nEn la pena o tristeza,\nCristo en todo vence ya.'),(1545,247,'Coro',4,'Gozo hay, si en servir a Cristo,\nGozo en el corazón;\nCada día Él da poder,\nMe ayuda a vencer;\nY da gozo, gozo en el corazón.'),(1546,247,'Estrofa',5,'Gozo da servir a Cristo,\nAunque solo ande yo;\nEs el gozo permanente,\nQue el Calvario nos logró.'),(1547,247,'Coro',6,'Gozo hay, si en servir a Cristo,\nGozo en el corazón;\nCada día Él da poder,\nMe ayuda a vencer;\nY da gozo, gozo en el corazón.'),(1548,247,'Estrofa',7,'Gozo da servir a Cristo,\nGozo en la oscuridad;\nPorque tengo el secreto,\nDe la luz de la verdad.'),(1549,247,'Coro',8,'Gozo hay, si en servir a Cristo,\nGozo en el corazón;\nCada día Él da poder,\nMe ayuda a vencer;\nY da gozo, gozo en el corazón.'),(1550,248,'Estrofa',1,'Estad por Cristo firmes,\nSoldados del Señor;\nAlzad hoy la bandera,\nEn nombre de Jesús.\nEs vuestra la victoria,\nCon Él por Capitán;\nPor Él será vencidas,\nLas huestes de Satán.'),(1551,248,'Estrofa',2,'Estad por Cristo firmes,\nOs llama Él a la lid;\nCon Él, pues, a la lucha,\nSoldados todos id.\nProbad que sois valientes,\nLuchando contra el mal;\nEs fuerte el enemigo,\nMas Cristo es sin igual.'),(1552,248,'Estrofa',3,'Estad por Cristo firmes,\nLas fuerzas vienen de Él;\nEl brazo de los hombres,\nEs débil y es infiel.\nVestios la armadura,\nVelad en oración;\nDeberes y peligros,\nDemandan gran tesón.'),(1553,249,'Estrofa',1,'Jesús, yo te amo y tuyo seré,\nPor ti los placeres del mundo dejé;\nPues Tú me redimes, me das salvación,\nBorrando mis culpas me diste perdón.'),(1554,249,'Estrofa',2,'Primero me amaste y diste por mí,\nDe sangre precioso raudal carmesí;\nCon ella pagaste mi gran trasgresión,\nBorrando mis culpas me diste perdón.'),(1555,250,'Estrofa',1,'Cristo, fiel te quiero ser,\nDame el poder, dame el poder;\nYo contigo quiero andar,\nSin vacilar, sin vacilar.'),(1556,250,'Coro',2,'En tus pasos quiero seguir,\nCerca de Ti, cerca de Ti;\nY si encuentro pruebas aquí,\nDame confianza en Ti.'),(1557,250,'Estrofa',3,'Con Jesús, yo quiero hablar,\nSolo con Él, Sólo con Él;\nPaz y gozo yo tendré,\nAl serle fiel, al serle fiel.'),(1558,250,'Coro',4,'En tus pasos quiero seguir,\nCerca de Ti, cerca de Ti;\nY si encuentro pruebas aquí,\nDame confianza en Ti.'),(1559,250,'Estrofa',5,'Dame ardiente corazón,\nLleno de amor, lleno de amor;\nY tu Espíritu, Señor,\nComo guiador, como guiador.'),(1560,250,'Coro',6,'En tus pasos quiero seguir,\nCerca de Ti, cerca de Ti;\nY si encuentro pruebas aquí,\nDame confianza en Ti.'),(1561,250,'Estrofa',7,'Cada día quiero cumplir,\nTu voluntad, tu voluntad;\nY servirte a Ti, Señor,\nEn humildad, en humildad.'),(1562,250,'Coro',8,'En tus pasos quiero seguir,\nCerca de Ti, cerca de Ti;\nY si encuentro pruebas aquí,\nDame confianza en Ti.'),(1563,251,'Estrofa',1,'Vanidad de vanidades, todo, todo vanidad,\nEl mal reina y falsedades, predomina la impiedad.'),(1564,251,'Coro',2,'Si oro, plata y tesoro preciado, Algún día lograres tener,\nVanidad te habrá rodeado, ten cuidado, no te vayas a perder.'),(1565,251,'Estrofa',3,'No trabajes por ser rico, ni famoso anheles ser,\nSi esto buscas con ahínco, inocente no has de ser.'),(1566,251,'Coro',4,'Si oro, plata y tesoro preciado, Algún día lograres tener,\nVanidad te habrá rodeado, ten cuidado, no te vayas a perder.'),(1567,251,'Estrofa',5,'Este mundo es engañoso, nada eterno encontrarás,\nLo fragante y muy hermoso, pronto ya no lo hallarás.'),(1568,251,'Coro',6,'Si oro, plata y tesoro preciado, Algún día lograres tener,\nVanidad te habrá rodeado, ten cuidado, no te vayas a perder.'),(1569,251,'Estrofa',7,'Dijo al hombre el Poderoso, dijo Dios con rectitud,\n“Si eres vano y orgulloso, no has de ser eterno Tu”.'),(1570,251,'Coro',8,'Si oro, plata y tesoro preciado, Algún día lograres tener,\nVanidad te habrá rodeado, ten cuidado, no te vayas a perder.'),(1571,251,'Estrofa',9,'No te engañes a ti mismo, no confíes en vanidad,\nQuita de ti el egoísmo, y del pobre ten piedad.'),(1572,251,'Coro',10,'Si oro, plata y tesoro preciado, Algún día lograres tener,\nVanidad te habrá rodeado, ten cuidado, no te vayas a perder.'),(1573,251,'Estrofa',11,'Pronto el Rey de reyes viene, el camino y la verdad,\nQuien la vida solo tiene, por toda la eternidad.'),(1574,251,'Coro',12,'Si oro, plata y tesoro preciado, Algún día lograres tener,\nVanidad te habrá rodeado, ten cuidado, no te vayas a perder.'),(1575,252,'Estrofa',1,'No tengo cuidados ni tengo temor,\nDe lo que me espera aquí;\nConfío tan solo en mi buen Salvador,\nEl cual cuida siempre de mi'),(1576,252,'Coro',2,'Vivo por fe...en mi Salvador,\nNo temeré... es fiel mi Señor;\nEn dura lid... nunca me dejará,\nYo vivo por fe... Él me sostendrá.'),(1577,252,'Estrofa',3,'Vendrán tempestades lo sé yo muy bien,\nLa fuerza del sol faltará;\nAmigos dejarme lo pueden también,\nJesús siempre me sostendrá.'),(1578,252,'Coro',4,'Vivo por fe...en mi Salvador,\nNo temeré... es fiel mi Señor;\nEn dura lid... nunca me dejará,\nYo vivo por fe... Él me sostendrá.'),(1579,252,'Estrofa',5,'Un día vendrá otra vez el Señor,\nEn su Reino nos congregará;\nAllí cesarán mi afán y dolor,\nPor siempre Jesús reinará.'),(1580,252,'Coro',6,'Vivo por fe...en mi Salvador,\nNo temeré... es fiel mi Señor;\nEn dura lid... nunca me dejará,\nYo vivo por fe... Él me sostendrá.'),(1581,253,'Estrofa',1,'En su profundo amor, por nos, el Salvador,\nVino del cielo y obró redención;\nTu vida de pecar debes abandonar,\nConfiando en Cristo por tu salvación.'),(1582,253,'Coro',2,'¡Oh, sin igual amor de Cristo, el Salvador,\nNuestra salud compró cuando en la cruz murió;\nPues tanto fue el amor de nuestro Redentor,\nQue nosotros su vida entregó!.'),(1583,253,'Estrofa',3,'Perdidos y sin luz nos encontró Jesús,\nY en el Calvario su vida entregó;\nVio nuestra perdición, mostró su compasión,\nCuando en la cruz nuestros males llevó.'),(1584,253,'Coro',4,'¡Oh, sin igual amor de Cristo, el Salvador,\nNuestra salud compró cuando en la cruz murió;\nPues tanto fue el amor de nuestro Redentor,\nQue nosotros su vida entregó!.'),(1585,253,'Estrofa',5,'Hijo del Padre Dios es Cristo, cuya voz,\nHoy tiernamente llamándote está;\nÉl te perdonará, tus males borrará,\nConfía en Él, pues te quiere librar.'),(1586,253,'Coro',6,'¡Oh, sin igual amor de Cristo, el Salvador,\nNuestra salud compró cuando en la cruz murió;\nPues tanto fue el amor de nuestro Redentor,\nQue nosotros su vida entregó!.'),(1587,254,'Estrofa',1,'Si la luz del sol se oculta,\nY vacila en mi la fe;\nMi plegaria elevo y clamo,\nCristo mi Piloto sé.'),(1588,254,'Coro',2,'Mi Piloto irá conmigo,\nY de nada temeré, no;\nNo me espanta el mar furioso,\nSolo en Él yo confiaré.'),(1589,254,'Estrofa',3,'Siempre que mi barca boga,\nEn la tempestuosa mar:\nPuedo fiar en mi Piloto,\nY en su seno reposar.'),(1590,254,'Coro',4,'Mi Piloto irá conmigo,\nY de nada temeré, no;\nNo me espanta el mar furioso,\nSolo en Él yo confiaré.'),(1591,254,'Estrofa',5,'Por la ruta que ha marcado,\nMi piloto me guiará;\nEn mis luchas y conflictos,\nGracia y triunfo me dará.'),(1592,254,'Coro',6,'Mi Piloto irá conmigo,\nY de nada temeré, no;\nNo me espanta el mar furioso,\nSolo en Él yo confiaré.'),(1593,254,'Estrofa',7,'Cuando llegue a la ribera,\nDe la Patria milenial;\nMe dará la bienvenida,\nMi piloto sin igual.'),(1594,254,'Coro',8,'Mi Piloto irá conmigo,\nY de nada temeré, no;\nNo me espanta el mar furioso,\nSolo en Él yo confiaré.'),(1595,255,'Estrofa',1,'Yo anduve sin fe como vil pecador,\nuchos años vagué en mal y temor;\nMas un día feliz a Cristo busqué,\nMe sacó de las dudas y paz encontré.'),(1596,255,'Coro',2,'El camino de fe es siempre mejor,\nPues voy con mi Rey, el buen Salvador;\nConsuelo me da, paz, vida y luz,\nSoy siempre feliz, en Cristo Jesús.'),(1597,255,'Estrofa',3,'¡Oh, amigos aquí este canto Oíd,\nEl gran Hijo de Dios invita a venir;\nPues de toda maldad Él os salvará,\nY un hogar en el Reino os preparará!.'),(1598,255,'Coro',4,'El camino de fe es siempre mejor,\nPues voy con mi Rey, el buen Salvador;\nConsuelo me da, paz, vida y luz,\nSoy siempre feliz, en Cristo Jesús.'),(1599,256,'Estrofa',1,'Ya la gracia de mi Señor y Rey,\nMe compró y libertó;\nEn mi corazón hay alegre son,\nDe loor al Redentor.'),(1600,256,'Coro',2,'Todo en todo es Jesucristo,\nMás que el mundo para mi;\nEs más bello que los lirios,\nO que una rosa carmesí.'),(1601,256,'Estrofa',3,'El desierto en huerto Jesús tornó,\nY lo hace florecer;\nCual rubí precioso es para mi,\nEl divino Salvador.'),(1602,256,'Coro',4,'Todo en todo es Jesucristo,\nMás que el mundo para mi;\nEs más bello que los lirios,\nO que una rosa carmesí.'),(1603,256,'Estrofa',5,'El me da solaz y descanso y paz,\nEn la dulce comunión;\nEn mi ser vive Él, soy feliz doquier,\nLlena Él mi corazón.'),(1604,256,'Coro',6,'Todo en todo es Jesucristo,\nMás que el mundo para mi;\nEs más bello que los lirios,\nO que una rosa carmesí.'),(1605,256,'Estrofa',7,'Al venir desdén, Él es mi sostén,\nSustentado de Él yo soy;\nNo me encanta más el poder falaz,\nCon Jesús yo siempre voy.'),(1606,256,'Coro',8,'Todo en todo es Jesucristo,\nMás que el mundo para mi;\nEs más bello que los lirios,\nO que una rosa carmesí.'),(1607,257,'Estrofa',1,'Sagrado es el amor,\nQue nos ha unido aquí;\nA los que creemos del Señor,\nLa voz que llama así.'),(1608,257,'Estrofa',2,'A nuestro Padre Dios,\nRoguemos con fervor;\nAlúmbrenos la misma luz,\nNos una el mismo amor.'),(1609,257,'Estrofa',3,'Nos vamos a ausentar,\nMas nuestra firme unión;\nJamás podráse quebrantar,\nPor la separación.'),(1610,257,'Estrofa',4,'Un día en la eternidad,\nNos hemos de reunir;\nQue Dios nos lo conceda hará,\nEl férvido pedir.'),(1611,258,'Estrofa',1,'La Ley, La Ley, de Jehová es perfecta,\nLa Ley, de Jehová es perfecta,\nQue vuelve el alma, el alma;\nEl testimonio de Jehová fiel,\nque hace sabio al pequeño.'),(1612,258,'Coro',2,'Los mandamientos de Jehová,\nSon rectos, que alegran el corazón;\nEl precepto de Jehová puro,\nQue alumbra los ojos.\nLa Ley, La Ley, de Jehová es perfecta.'),(1613,258,'Estrofa',3,'El temor de Jehová limpio, limpio,\nQue permanece para siempre;\nLos juicios de Jehová son verdad,\nTodos justos, todos justos.'),(1614,258,'Coro',4,'Los mandamientos de Jehová,\nSon rectos, que alegran el corazón;\nEl precepto de Jehová puro,\nQue alumbra los ojos.\nLa Ley, La Ley, de Jehová es perfecta.'),(1615,258,'Estrofa',5,'Deseables son más que el oro,\nY mas que mucho oro afinado;\nY dulce más que miel y que la,\nLa que destila del panal.'),(1616,258,'Coro',6,'Los mandamientos de Jehová,\nSon rectos, que alegran el corazón;\nEl precepto de Jehová puro,\nQue alumbra los ojos.\nLa Ley, La Ley, de Jehová es perfecta.'),(1617,258,'Estrofa',7,'Tu siervo es además,\nAmonestado con ellos;\nEn guardarlos, en guardarlos, hay,\nHay grande, grande galardón.'),(1618,258,'Coro',8,'Los mandamientos de Jehová,\nSon rectos, que alegran el corazón;\nEl precepto de Jehová puro,\nQue alumbra los ojos.\nLa Ley, La Ley, de Jehová es perfecta.'),(1619,259,'Estrofa',1,'¿Hasta cuándo, Jehová,\nme olvidarás para siempre?\n¿Hasta cuándo esconderás, tu rostro de mí?'),(1620,259,'Estrofa',2,'¿Hasta cuándo pondré consejos en mi alma,\ncon ansiedad en mi corazón cada día?\n¿Hasta cuándo será enaltecido,\nMi enemigo sobre mí?'),(1621,259,'Estrofa',3,'Mira, óyeme, Jehová Dios mío,\nalumbra mis ojos,\nporque no duerma en muerte.'),(1622,259,'Estrofa',4,'Porque no diga mi enemigo vencilo;\nmis enemigos se alegrarán, si yo resbalare.'),(1623,259,'Estrofa',5,'Mas yo en tu misericordia, he confiado,\nalegrarase mi corazón, en tu salud'),(1624,259,'Estrofa',6,'Cantaré a Jehová,\nporque me ha hecho bien'),(1625,260,'Estrofa',1,'Cantad alegres a Dios,\nhabitantes de toda la tierra.'),(1626,260,'Estrofa',2,'Servid a Jehová con alegría,\nvenid ante su acatamiento con regocijo.'),(1627,260,'Estrofa',3,'Reconoced que Jehová, Él es Dios,\nEl nos hizo, y no nosotros a nosotros mismos.\nPueblo suyo somos y ovejas de su prado'),(1628,260,'Estrofa',4,'Entrad por sus puertas, con reconocimiento,\npor sus atrios con alabanza.\n// Alabadle, bendecid su nombre. //'),(1629,260,'Estrofa',5,'Porque Jehová es bueno,\nPara siempre es su misericordia,\ny su verdad, por todas las generaciones.\nAmén.'),(1630,261,'Estrofa',1,'Alabad a Jehová, naciones todas,\nAlabad a Jehová, naciones todas;\nPueblos todos alabadle,\nPueblos todos alabadle.'),(1631,261,'Estrofa',2,'Porque ha engrandecido,\nsobre nosotros su misericordia;\ny la verdad de Jehová,\nes para siempre;\nAleluya, Aleluya, Aleluya.'),(1632,262,'Estrofa',1,'Mirad, bendecid a Jehová,\nvosotros todos los siervos de Jehová;\nlos que en la casa de Jehová,\nestáis por las noches.'),(1633,262,'Estrofa',2,'Alzad vuestras manos\nal santuario,\ny bendecid a Jehová.'),(1634,262,'Estrofa',3,'Bendígate Jehová desde Sión,\nel cual ha hecho,\nlos cielos y la tierra.'),(1635,263,'Estrofa',1,'Alzaré mis ojos a los montes,\n¿de dónde vendrá mi socorro?'),(1636,263,'Estrofa',2,'Mi socorro viene de Jehová,\nque hizo los cielos y la tierra.'),(1637,263,'Estrofa',3,'No dará tu pie al resbaladero,\nni se dormirá el que te guarda.'),(1638,263,'Estrofa',4,'He aquí no se adormecerá, ni dormirá,\nel que guarda a Israel.'),(1639,263,'Estrofa',5,'Jehová es tu guardador,\nJehová es tu sombra,\na tu mano derecha.'),(1640,263,'Estrofa',6,'El sol no te fatigará de día,\nni la luna de noche.'),(1641,263,'Estrofa',7,'Jehová te guardará de todo mal,\nEl guardará tu alma'),(1642,263,'Estrofa',8,'Jehová guardará tu salida y tu entrada,\ndesde ahora y para siempre. Amén.'),(1643,264,'Estrofa',1,'A ti que habitas en los cielos,\nalcé mis ojos.'),(1644,264,'Estrofa',2,'He aquí como los ojos de los siervos,\nmiran a la mano de sus Señores;\nY como los ojos de la sierva,\na la mano de su señora;\nasí nuestros ojos miran a Jehová,\nnuestro Dios\nHasta que hará misericordia\nde nosotros.'),(1645,264,'Estrofa',3,'Ten misericordia de nosotros,\nOh Jehová,\nten misericordia de nosotros;\nporque estamos muy hartos\nde menosprecio.'),(1646,264,'Estrofa',4,'Muy harta está nuestra alma,\nde escarnio de los holgados,\ny del menosprecio de los\nsoberbios.'),(1647,265,'Estrofa',1,'Cuando Jehová hiciere tornar,\nLa cautividad de Sión,\n// Seremos como los que sueñan.//'),(1648,265,'Estrofa',2,'Entonces nuestra boca se henchirá de risa,\nY nuestra lengua de alabanza,\nEntonces dirán entre las gentes:\n“Grandes cosas ha hecho Jehová con éstos”.'),(1649,265,'Estrofa',3,'Grandes cosas ha hecho Jehová\nCon nosotros, Estaremos alegres.\nEstaremos alegres.'),(1650,265,'Estrofa',4,'Haz volver nuestra cautividad, oh, Jehová,\nComo los arroyos en el austro.\n//Los que sembraron con lágrimas,\nCon regocijo segarán.//'),(1651,265,'Estrofa',5,'Irá andando y llorando,\nEl que lleva la preciosa simiente;\n//Mas volverá a venir con regocijo,\nTrayendo sus gavillas.//'),(1652,266,'Estrofa',1,'Alabad a Dios en su santuario,\nalabadle en la extensión de su fortaleza.'),(1653,266,'Estrofa',2,'Alabadle por sus proezas,\nalabadle conforme a la muchedumbre\nde su grandeza.'),(1654,266,'Estrofa',3,'Alabadle a son de bocina,\nalabadle con salterio y arpa.'),(1655,266,'Estrofa',4,'Alabadle con adufe y flauta,\nalabadle con cuerdas y órgano'),(1656,266,'Estrofa',5,'Alabadle con címbalos resonantes,\nalabadle con címbalos de júbilo'),(1657,266,'Estrofa',6,'Todo lo que respira alabe a\nJehová. ¡Aleluya!'),(1658,267,'Estrofa',1,'Alabad a Jehová, porque es bueno,'),(1659,267,'Coro',2,'Porque para siempre es su misericordia.\nSu misericordia es para siempre.'),(1660,267,'Estrofa',3,'Alabad al Dios de los dioses,'),(1661,267,'Coro',4,'Porque para siempre es su misericordia.\nSu misericordia es para siempre.'),(1662,267,'Estrofa',5,'Alabad al Señor de los señores,'),(1663,267,'Coro',6,'Porque para siempre es su misericordia.\nSu misericordia es para siempre.'),(1664,267,'Estrofa',7,'Al solo que hace grandes maravillas,'),(1665,267,'Coro',8,'Porque para siempre es su misericordia.\nSu misericordia es para siempre.'),(1666,267,'Estrofa',9,'Al que hizo los cielos con entendimiento,'),(1667,267,'Coro',10,'Porque para siempre es su misericordia.\nSu misericordia es para siempre.'),(1668,267,'Estrofa',11,'Al que tendió la tierra sobre las aguas,'),(1669,267,'Coro',12,'Porque para siempre es su misericordia.\nSu misericordia es para siempre.'),(1670,267,'Estrofa',13,'Al que hizo las grandes luminarias,'),(1671,267,'Coro',14,'Porque para siempre es su misericordia.\nSu misericordia es para siempre.'),(1672,267,'Estrofa',15,'El sol para que dominase en el día,'),(1673,267,'Coro',16,'Porque para siempre es su misericordia.\nSu misericordia es para siempre.'),(1674,267,'Estrofa',17,'La luna y las estrellas, para que dominasen en la noche,'),(1675,267,'Coro',18,'Porque para siempre es su misericordia.\nSu misericordia es para siempre.'),(1676,267,'Estrofa',19,'Alabad al Dios de los cielos.'),(1677,267,'Coro',20,'Porque para siempre es su misericordia.\nSu misericordia es para siempre.'),(1678,268,'Estrofa',1,'Jehová es mi pastor, nada me faltará.'),(1679,268,'Estrofa',2,'En lugares de delicados pastos, me hará yacer,\nJunto a aguas de reposo me pastoreará.'),(1680,268,'Estrofa',3,'Confortará mi alma,\nGuiaráme por sendas de justicia,\nPor amor de su nombre.'),(1681,268,'Estrofa',4,'Aunque ande en valle de sombra de muerte;\nNo temeré mal alguno,\nPorque Tú estarás conmigo;\nTu vara y tu callado me infundirán aliento.'),(1682,268,'Estrofa',5,'Aderezarás mesa delante de mi,\nEn presencia de mis angustiadores;\nUngiste mi cabeza con aceite,\nMi copa está rebosando.'),(1683,268,'Estrofa',6,'Ciertamente el bien y la misericordia,\nMe seguirán todos los días de mi vida,\nY en la casa de Jehová moraré, por largos días.'),(1684,269,'Estrofa',1,'Si mi fe disminuyere, Él me sostendrá,\nY si el mal mi amenazare, Él me sostendrá.'),(1685,269,'Coro',2,'Él me sostendrá, Él me sostendrá,\nMi Jesús que tanto me ama, Él me sostendrá.'),(1686,269,'Estrofa',3,'Nunca yo podré ser firme, con tan débil fe,\nMas Él puede dirigirme y Él me sostendrá.'),(1687,269,'Coro',4,'Él me sostendrá, Él me sostendrá,\nMi Jesús que tanto me ama, Él me sostendrá.'),(1688,269,'Estrofa',5,'Son su gozo y complacencia, cuantos Él salvo,\nY al salvarme su clemencia, Él me sostendrá.'),(1689,269,'Coro',6,'Él me sostendrá, Él me sostendrá,\nMi Jesús que tanto me ama, Él me sostendrá.'),(1690,269,'Estrofa',7,'El no quiere ver perdida mi alma en la maldad,\nDio su sangre por mi vida y Él me sostendrá.'),(1691,269,'Coro',8,'Él me sostendrá, Él me sostendrá,\nMi Jesús que tanto me ama, Él me sostendrá.'),(1692,270,'Estrofa',1,'Con voz benigna te llama Jesús,\nInvitación de puro amor;\n¿Por qué le dejas en vano llamar?,\n¿Sordo serás pecador?.'),(1693,270,'Coro',2,'Hoy te convida, hoy te convida,\nVoz bendecida,\nBenigna, convídate hoy.'),(1694,270,'Estrofa',3,'A los cansados convida Jesús,\nCon compasión mira el dolor,\nTráele tu carga, te bendecirá,\nayudaráte el Señor.'),(1695,270,'Coro',4,'Hoy te convida, hoy te convida,\nVoz bendecida,\nBenigna, convídate hoy.'),(1696,270,'Estrofa',5,'Siempre aguardando contempla a Jesús,\n¡Tanto esperar! ¡ Con tanto amor!\nHasta sus plantas ven, mísero y trae,\nTu tentación, tu dolor.'),(1697,270,'Coro',6,'Hoy te convida, hoy te convida,\nVoz bendecida,\nBenigna, convídate hoy.'),(1698,271,'Estrofa',1,'¿Has oído la historia de Cristo,\nDulce historia de gracia y amor?\nCuando débil y pobre caído,\nRedimido me vi del dolor.'),(1699,271,'Coro',2,'Su inmenso amor, yo cierto estoy,\nJamás su igual tener podrá;\nA su fulgor en la vida voy,\nY al Reino así en mi alma va!.'),(1700,271,'Estrofa',3,'¿Has oído del mar tempestuoso,\nQue el Señor con su voz aquietó?;\n¡Tu sabrás que las rudas tormentas,\nDe mi vida el Señor yo calmó!.'),(1701,271,'Coro',4,'Su inmenso amor, yo cierto estoy,\nJamás su igual tener podrá;\nA su fulgor en la vida voy,\nY al Reino así en mi alma va!.'),(1702,271,'Estrofa',5,'¿ Has oído que dijo a los gentes,\n“Los cansados venid hasta mi”;\nVine a Él y sentí que al instante,\nDe su amor el objeto yo fui.'),(1703,271,'Coro',6,'Su inmenso amor, yo cierto estoy,\nJamás su igual tener podrá;\nA su fulgor en la vida voy,\nY al Reino así en mi alma va!.'),(1704,271,'Estrofa',7,'¿Has oído de aquellos que ciegos,\nA sus ojos Él dióles la luz?;\n¡Yo también cuando estaba en las sombras,\nA la luz me llevó mi Jesús!.'),(1705,271,'Coro',8,'Su inmenso amor, yo cierto estoy,\nJamás su igual tener podrá;\nA su fulgor en la vida voy,\nY al Reino así en mi alma va!.'),(1706,272,'Estrofa',1,'¡Oíd! ¡Oíd! Lo que nos manda el Señor,\n“¡Marchad! ¡Marchad! hablad de mi amor;\nY he aquí yo con vosotros estaré,\nLos días todos, hasta el fin os guardaré”'),(1707,272,'Coro',2,'Id, Id por el mundo,\nId, Id y predicad el Evangelio;\nId, Id, va adelante,\nEl Todopoderoso Salvador;\n¡Gloria! ¡Gloria! Aleluya a Jesús,\n¡Gloria! ¡Gloria! Aleluya a Jesús,\nNuestras almas Él salvó,\nNuestras manchas Él lavó,\nProclamemos, pues, a todos su amor.'),(1708,272,'Estrofa',3,'¡Pensad! ¡Pensad! La condición del pecador,\n¡Que triste es! ¡Que llena de dolor!;\nSin luz, sin paz, camina a la eternidad,\nY no conoce el peligro en que está.'),(1709,272,'Coro',4,'Id, Id por el mundo,\nId, Id y predicad el Evangelio;\nId, Id, va adelante,\nEl Todopoderoso Salvador;\n¡Gloria! ¡Gloria! Aleluya a Jesús,\n¡Gloria! ¡Gloria! Aleluya a Jesús,\nNuestras almas Él salvó,\nNuestras manchas Él lavó,\nProclamemos, pues, a todos su amor.'),(1710,272,'Estrofa',5,'¡Salid, salid, embajadores del Señor!\n¡Buscad, buscad, al pobre pecador!\nAprovechad el tiempo que el Señor os da,\nEl día de salud pronto acabará.'),(1711,272,'Coro',6,'Id, Id por el mundo,\nId, Id y predicad el Evangelio;\nId, Id, va adelante,\nEl Todopoderoso Salvador;\n¡Gloria! ¡Gloria! Aleluya a Jesús,\n¡Gloria! ¡Gloria! Aleluya a Jesús,\nNuestras almas Él salvó,\nNuestras manchas Él lavó,\nProclamemos, pues, a todos su amor.'),(1712,273,'Estrofa',1,'Abre mis ojos a la luz,\nTu rostro quiero ver Jesús;\nPon en mi corazón tu bondad,\nY dame paz y santidad.\nHumildemente acudo a Ti,\nPorque tu tierna voz oí;\nGuíame con tu Espíritu consolador.'),(1713,273,'Estrofa',2,'Abre mi oído a tu verdad,\nYo quiero oír con claridad;\nBellas palabras de dulce amor,\nDe Ti, bendito Salvador.\nConsagro a Ti mi frágil ser,\nTu voluntad yo quiero hacer;\nLléname con tu Espíritu Consolador.'),(1714,273,'Estrofa',3,'Abre mis labios para hablar,\nY a todo el mundo proclamar;\nQue Tú viniste a rescatar,\nAl más perdido pecador.\nLa mies es mucha ¡Oh Señor!\nObreros faltan de valor;\nLléname con tu Espíritu consolador.'),(1715,274,'Estrofa',1,'Sálvame, oh Dios, de toda tentación,\nPorque en la muerte, no te alabaré;\nPronto mis días se acaban,\nY al polvo tornaré.'),(1716,274,'Coro',2,'Soy arcilla, soy lodo en tus manos,\nMiserable de mi sin tu amor;\nNo, no se acorte tu mano,\nCristo, Cristo mi salvador.'),(1717,274,'Estrofa',3,'Ciertamente el bien y la bondad,\nMe seguirán los días que more aquí;\nConfortarás mi alma,\nY yo te alabaré.'),(1718,274,'Coro',4,'Soy arcilla, soy lodo en tus manos,\nMiserable de mi sin tu amor;\nNo, no se acorte tu mano,\nCristo, Cristo mi salvador.'),(1719,274,'Estrofa',5,'Tú eres fiel, inmenso tu amor,\nPerdonarás del hombre la maldad;\nAnhelas verlo salvo,\nCuán grande es tu bondad.'),(1720,274,'Coro',6,'Soy arcilla, soy lodo en tus manos,\nMiserable de mi sin tu amor;\nNo, no se acorte tu mano,\nCristo, Cristo mi salvador.'),(1721,274,'Estrofa',7,'Te alabaré por siempre mi Jesús,\nPorque tu gracia ya me perdonó;\nY con tu sacrificio,\nMe has dado salvación.'),(1722,274,'Coro',8,'Soy arcilla, soy lodo en tus manos,\nMiserable de mi sin tu amor;\nNo, no se acorte tu mano,\nCristo, Cristo mi salvador.'),(1723,275,'Estrofa',1,'Huye cual ave a tu monte,\nAlma abrumada del mal;\nAllí en Jesús, la gran fuente,\nLava tu lepra mortal.'),(1724,275,'Estrofa',2,'Huye del mal vergonzoso,\nCalma ya tu ser medroso;\nCristo dará su reposo,\n¡Oh! Alma abruma del mal,\n¡Oh! Alma abruma del mal.'),(1725,275,'Estrofa',3,'Quiere Jesús hoy salvarte,\nTu llanto Él enjugará;\nPromete nunca dejarte,\nDefensa eterna será.'),(1726,275,'Estrofa',4,'Ven, pues, va el día volando,\nYa no andes más suspirando;\nNi te detengas llorando,\nTus males Jesús quitará,\nTus males Jesús quitará.'),(1727,276,'Estrofa',1,'Indigno soy de su gracia infinita,\nMas Cristo por mi padeció;\nDejó Él su Trono y bajó a la tierra,\nLa forma de siervo tomó.'),(1728,276,'Coro',2,'Yo soy indigno, mi lengua lo dice,\nYo soy indigno, mi alma repite;\nMas Jesucristo mi culpa llevó\n¡Que gracia y amor sin igual!.'),(1729,276,'Estrofa',3,'Indigno soy de su gracia infinita,\nMas Él me prepara un hogar;\nAllí viviré con Jesús, el Bendito,\nDo siempre le pueda adorar.'),(1730,276,'Coro',4,'Yo soy indigno, mi lengua lo dice,\nYo soy indigno, mi alma repite;\nMas Jesucristo mi culpa llevó\n¡Que gracia y amor sin igual!.'),(1731,277,'Estrofa',1,'La tumba le encerró,\nCristo, mi Cristo;\nTres días esperó,\nCristo el Señor.'),(1732,277,'Coro',2,'Cristo la tumba venció,\nÉl con gran poder resucitó;\nDe sepulcro y muerte,\nCristo es vencedor,\nVive para siempre nuestro Salvador,\n¡Gloria a Dios! ¡Gloria a Dios!\nEl Señor resucitó.'),(1733,277,'Estrofa',3,'De guardas escapó,\nCristo, mi Cristo;\nEl sello destruyó,\nCristo el Señor.'),(1734,277,'Coro',4,'Cristo la tumba venció,\nÉl con gran poder resucitó;\nDe sepulcro y muerte,\nCristo es vencedor,\nVive para siempre nuestro Salvador,\n¡Gloria a Dios! ¡Gloria a Dios!\nEl Señor resucitó.'),(1735,277,'Estrofa',5,'La muerte dominó,\nCristo mi Cristo;\nY su poder venció,\nCristo el Señor.'),(1736,277,'Coro',6,'Cristo la tumba venció,\nÉl con gran poder resucitó;\nDe sepulcro y muerte,\nCristo es vencedor,\nVive para siempre nuestro Salvador,\n¡Gloria a Dios! ¡Gloria a Dios!\nEl Señor resucitó.'),(1737,278,'Estrofa',1,'De mi tristeza y esclavitud, vengo Jesús, vengo Jesús,\nA tu alegría y a tu virtud, vengo Jesús, a Ti.\nDe mi pobreza y enfermedad, a tu salud y rica bondad\nA tu presencia, de mi maldad, vengo Jesús a Ti.'),(1738,278,'Estrofa',2,'De mi flaqueza y falta de luz, vengo Jesús, vengo Jesús,\nAl eminente bien de tu cruz, vengo Jesús, a Ti.\nDel sufrimiento que es terrenal, a ti mi médico celestial,\nPara ser libre de todo mal, vengo Jesús a Ti.'),(1739,278,'Estrofa',3,'De mi soberbia y ansiedad, vengo Jesús, vengo Jesús,\nPara morar en tu voluntad, vengo Jesús, a Ti.\nDe mi tristeza a tu gran amor a lo del cielo consolador,\nPara por siempre darte loor, vengo Jesús a Ti.'),(1740,278,'Estrofa',4,'De ese terror que la tumba da, vengo Jesús, vengo Jesús,\nA la alegría y luz de tu hogar vengo Jesús, a Ti.\nDe la indecible profundidad, a tu redil de tranquilidad,\nA ver tu faz por la eternidad, vengo Jesús, a Ti.'),(1741,279,'Estrofa',1,'¡Oh, Señor! Procuro en vano,\nMi conducta reformar;\nPues ningún poder humano,\nSantidad me puede dar.\nEs mi vida de pecado,\nDiaria ofensa para Ti;\nPero mi alma ha confiado,\nEn tu sangre carmesí.'),(1742,279,'Estrofa',2,'En tu Reino está el contento,\nNada impuro allí entrará;\nSin el nuevo nacimiento,\nNinguna alma lo verá.\nMira, pues, mi insuficiencia,\nMuestra en mi tu gran poder;\nManifiesta tu clemencia,\nY de nuevo hazme nacer.'),(1743,279,'Estrofa',3,'Oh, Eterno Ser Divino,\nVen y escucha mi oración;\nAnte Ti mi frente inclino,\nPor mi regeneración.\nDe este modo mi esperanza,\nNo vacila y llego a creer;\nQue la bienaventuranza,\nEn el Reino he de tener.'),(1744,280,'Estrofa',1,'Nunca esperes el momento de una grande acción,\nNi que pueda lejos ir tu luz;\nDe la vida a los pequeños actos da atención,\nBrilla en el sitio donde estés.'),(1745,280,'Coro',2,'Brilla en el sitio donde estés,\nBrilla en el sitio donde estés;\nPuedes con tu luz algún perdido rescatar,\nBrilla en el sitio donde estés.'),(1746,280,'Estrofa',3,'Puedes en tu cielo alguno nube disipar,\nHaz a un lado tu egoísmo cruel;\nAunque solo un corazón pudieres consolar,\nBrilla en el sitio donde estés.'),(1747,280,'Coro',4,'Brilla en el sitio donde estés,\nBrilla en el sitio donde estés;\nPuedes con tu luz algún perdido rescatar,\nBrilla en el sitio donde estés.'),(1748,280,'Estrofa',5,'Puede tu talento alguna cosa descubrir,\nDe tu luz podrá resplandecer;\nDe tu mano el pan de vida puede aquí venir,\nBrilla en el sitio donde estés.'),(1749,280,'Coro',6,'Brilla en el sitio donde estés,\nBrilla en el sitio donde estés;\nPuedes con tu luz algún perdido rescatar,\nBrilla en el sitio donde estés.'),(1750,281,'Estrofa',1,'Al Cristo vivo sirvo y Él en el mundo está,\nAunque otros lo negaren yo sé que Él vive ya;\nSu mano tierna veo, su voz consuelo da,\nY cuando yo le llamo muy cerca está.'),(1751,281,'Coro',2,'Él vive, Él vive, hoy vive el salvador,\nConmigo está y me guardará;\nMi amante Redentor;\nÉl vive, Él vive, imparte salvación,\nSé que Él viviendo está,\nPorque vive en mi corazón.'),(1752,281,'Estrofa',3,'En todo el mundo entero contemplo yo su amor,\nY al sentirme triste consuélame Señor;\nSeguro estoy que Cristo,\nMi vida guiando está,\nY que otra vez al mundo regresará.'),(1753,281,'Coro',4,'Él vive, Él vive, hoy vive el salvador,\nConmigo está y me guardará;\nMi amante Redentor;\nÉl vive, Él vive, imparte salvación,\nSé que Él viviendo está,\nPorque vive en mi corazón.'),(1754,281,'Estrofa',5,'Regocijad Cristianos, hoy himnos entonad,\nEternas aleluyas a Cristo Rey, cantad;\nAyuda y esperanza es del mundo pecador,\nNo hay otro tan amante como el Señor.'),(1755,281,'Coro',6,'Él vive, Él vive, hoy vive el salvador,\nConmigo está y me guardará;\nMi amante Redentor;\nÉl vive, Él vive, imparte salvación,\nSé que Él viviendo está,\nPorque vive en mi corazón.'),(1756,282,'Estrofa',1,'Años mi alma en vanidad vivió,\nIgnorando a quien por mi sufrió;\nO que en el Calvario sucumbió,\nEl Salvador.'),(1757,282,'Coro',2,'Mi alma allí divina gracia halló,\nDios allí perdón y paz me dio;\nDel pecado allí me libertó,\nEl Salvador.'),(1758,282,'Estrofa',3,'Por la Biblia miro que pequé,\nY su ley divina quebranté;\nMi alma entonces contempló con fe,\nAl Salvador.'),(1759,282,'Coro',4,'Mi alma allí divina gracia halló,\nDios allí perdón y paz me dio;\nDel pecado allí me libertó,\nEl Salvador.'),(1760,282,'Estrofa',5,'Toda mi alma a Cristo ya entregué,\nHoy le quiero y sirvo como a Rey;\nPor los siglos siempre cantaré,\nAl Salvador.'),(1761,282,'Coro',6,'Mi alma allí divina gracia halló,\nDios allí perdón y paz me dio;\nDel pecado allí me libertó,\nEl Salvador.'),(1762,282,'Estrofa',7,'En la cruz su amor Dios demostró,\nY de gracia al hombre revistió;\nCuando por nosotros se entregó,\nEl Salvador.'),(1763,282,'Coro',8,'Mi alma allí divina gracia halló,\nDios allí perdón y paz me dio;\nDel pecado allí me libertó,\nEl Salvador.'),(1764,283,'Estrofa',1,'Si fui motivo de dolor, Señor,\nSi por mi causa el débil tropezó;\nSi en tus caminos yo no quiero andar,\nPerdón te ruego mi Señor y Dios.'),(1765,283,'Coro',2,'Escucha, oh Dios mi confesión humilde,\nY líbrame de tentación sutil;\nPreserva siempre mi alma en tu redil,\nPerdón te ruego mi Señor y Dios.'),(1766,283,'Estrofa',3,'Si vana y fútil mi palabra fue,\nSi al que sufría en su dolor dejé;\nNo me condenes, Tú por mi maldad,\nPerdón te ruego mi Señor y Dios.'),(1767,283,'Coro',4,'Escucha, oh Dios mi confesión humilde,\nY líbrame de tentación sutil;\nPreserva siempre mi alma en tu redil,\nPerdón te ruego mi Señor y Dios.'),(1768,283,'Estrofa',5,'Si por la vida quise andar en paz,\nTranquilo, libre y sin luchar por Ti;\nCuando anhelabas verme en la lid,\nPerdón te ruego mi Señor y Dios.'),(1769,283,'Coro',6,'Escucha, oh Dios mi confesión humilde,\nY líbrame de tentación sutil;\nPreserva siempre mi alma en tu redil,\nPerdón te ruego mi Señor y Dios.'),(1770,284,'Estrofa',1,'Tentado, no cedas, ceder es pecar,\nMás fácil sería luchando triunfar;\n¡Valor!, pues, resuelto, domina tu mal,\nDios puede librarte de asalto mortal.'),(1771,284,'Coro',2,'En Jesús, pues, confía,\nEn sus brazos tu alma;\nHallará dulce calma,\nÉl te hará vendedor.'),(1772,284,'Estrofa',3,'Evita el pecado, procura agradar,\nA Dios a quien debes por siempre ensalzar;\nNo manche tus labios impúdica voz,\nPreserva tu vida de ofensas a Dios.'),(1773,284,'Coro',4,'En Jesús, pues, confía,\nEn sus brazos tu alma;\nHallará dulce calma,\nÉl te hará vendedor.'),(1774,284,'Estrofa',5,'Amante, benigno y enérgico sé,\nEn Cristo tu Amigo pon toda tu fe;\nVeraz sea tu dicho, de Dios es tu ser,\nCorona te espera, y vas a vencer.'),(1775,284,'Coro',6,'En Jesús, pues, confía,\nEn sus brazos tu alma;\nHallará dulce calma,\nÉl te hará vendedor.'),(1776,285,'Estrofa',1,'Obrero en la mies de Cristo,\nEl campo blanco está;\nY para la cosecha listos,\nTomad aliento ya.'),(1777,285,'Coro',2,'Aquellos que esperan al Señor,\nNuevas fuerzas tendrán;\nSe levantarán con alas,\nCon alas cual las águilas;\n///Correrán y no se cansarán,\nSin fatiga han de andar;///'),(1778,285,'Estrofa',3,'Orando siempre y trabajando,\nY con creciente ardor;\nSeguid sembrando y esperando,\nNo en vano en el Señor.'),(1779,285,'Coro',4,'Aquellos que esperan al Señor,\nNuevas fuerzas tendrán;\nSe levantarán con alas,\nCon alas cual las águilas;\n///Correrán y no se cansarán,\nSin fatiga han de andar;///'),(1780,285,'Estrofa',5,'Los que con lágrimas sembraron,\nCon gozo segarán;\nSemilla de valor llevaron,\nSus frutos traerán'),(1781,285,'Coro',6,'Aquellos que esperan al Señor,\nNuevas fuerzas tendrán;\nSe levantarán con alas,\nCon alas cual las águilas;\n///Correrán y no se cansarán,\nSin fatiga han de andar;///'),(1782,286,'Estrofa',1,'Digno es el Cordero que inmolando fue,\nDe tomar el Reino, honra gloria y prez;\nPara abrir el libro nadie se encontró,\nÉl fue solo digno ¡Cante nuestra voz!.'),(1783,286,'Coro',2,'A Jesús loor, a Jesús loor,\nA Jesús loor, porque Él es digno;\nA Jesús loor, a Jesús loor,\nA Jesús loor, porque Él es digno.'),(1784,286,'Estrofa',3,'Digno es el Cordero que en la cruz murió,\nPor llevar el mundo cerca de su Dios;\nY donde reinaba densa oscuridad,\nÉl la luz del cielo vino a derramar.'),(1785,286,'Coro',4,'A Jesús loor, a Jesús loor,\nA Jesús loor, porque Él es digno;\nA Jesús loor, a Jesús loor,\nA Jesús loor, porque Él es digno.'),(1786,286,'Estrofa',5,'Digno es el Cordero, canten voces mil,\nQue la humana raza vino a redimir;\nDigno es el cordero ¡Salvación a Él!,\nY al que está en el trono, hoy y siempre,\n¡Amen!.'),(1787,286,'Coro',6,'A Jesús loor, a Jesús loor,\nA Jesús loor, porque Él es digno;\nA Jesús loor, a Jesús loor,\nA Jesús loor, porque Él es digno.'),(1788,287,'Estrofa',1,'Junto a mi Dios deseo siempre morar,\nAunque jamás el mundo me quiera amar;\nQue del mundo no soy, que del mundo no soy,\nSolo por él transito, al Reino voy.'),(1789,287,'Estrofa',2,'Sólo a mi Dios el alma sabe querer,\nPorque de amor Él llena todo mi ser;\nVeraz es mi Señor, veraz es mi Señor,\nQue dice en su palabra: ”Dios es amor”'),(1790,287,'Estrofa',3,'Mi Dios, mi bien, mi todo, llégate a mí,\nNo permitas que more lejos de Tí.\nTú me recibirás, Tú me recibirás,\nQue estar sin Ti no puedo nunca jamás.'),(1791,288,'Estrofa',1,'¿Quieres sobre el mundo ser un vencedor?\n¿Quieres tú cantar aun cuando hay dolor?\n¿Quieres ser alegre cual fiel luchador?\nGuarda el contacto con el Salvador.'),(1792,288,'Coro',2,'Guarda el contacto con el Salvador,\nLuego las tinieblas no te cubrirán;\nPor la senda alegre tú caminarás,\nSi el contacto guardas con el Salvador.'),(1793,288,'Estrofa',3,'En el mundo hay muchos, tristes en pecar,\nCuyos corazones lloran del pesar;\nDales el mensaje, no hay que callar,\nCon Dios el contacto debes de guardar.'),(1794,288,'Coro',4,'Guarda el contacto con el Salvador,\nLuego las tinieblas no te cubrirán;\nPor la senda alegre tú caminarás,\nSi el contacto guardas con el Salvador.'),(1795,288,'Estrofa',5,'¿Quieres tú con Dios la comunión tener?,\n¿Y su gloria siempre en ti permanecer?\n¿Que el mundo a Cristo pueda en ti hoy ver?,\nGuarda el contacto con el Salvador.'),(1796,288,'Coro',6,'Guarda el contacto con el Salvador,\nLuego las tinieblas no te cubrirán;\nPor la senda alegre tú caminarás,\nSi el contacto guardas con el Salvador.'),(1797,288,'Estrofa',7,'Deja que el Espíritu implante en ti,\nLa humildad de Cristo y su santo amor;\nOra siempre y vela, que Jesús vendrá,\nGuarda el contacto con el Salvador.'),(1798,288,'Coro',8,'Guarda el contacto con el Salvador,\nLuego las tinieblas no te cubrirán;\nPor la senda alegre tú caminarás,\nSi el contacto guardas con el Salvador.'),(1799,289,'Estrofa',1,'Comprado con sangre por Cristo,\nCon gozo al reino yo voy;\nLibrado por gracia infinita,\nYa sé que su hijo yo soy.'),(1800,289,'Coro',2,'Lo sé, lo sé, comprado con sangre yo soy\nLo sé, lo sé, con Cristo al Reino yo voy'),(1801,289,'Estrofa',3,'Soy libre de pena y culpa,\nSu gozo Él me hace sentir;\nÉl llena de gracia mi alma,\nCon Él es tan dulce vivir.'),(1802,289,'Coro',4,'Lo sé, lo sé, comprado con sangre yo soy\nLo sé, lo sé, con Cristo al Reino yo voy'),(1803,289,'Estrofa',5,'En Cristo yo siempre medito,\nY nunca le puedo olvidar;\nCallar sus favores no quiero,\nVoy siempre a Jesús alabar.'),(1804,289,'Coro',6,'Lo sé, lo sé, comprado con sangre yo soy\nLo sé, lo sé, con Cristo al Reino yo voy'),(1805,289,'Estrofa',7,'Seguro sé que la belleza,\nDel gran Rey yo voy a mirar;\nAhora me guarda y me guía,\nY siempre me quiere ayudar.'),(1806,289,'Coro',8,'Lo sé, lo sé, comprado con sangre yo soy\nLo sé, lo sé, con Cristo al Reino yo voy'),(1807,290,'Estrofa',1,'Noche de gran, gran libertad,\nSe proclama en Israel;\nDía en que el caudillo de la libertad,\nDiera su vida por la humanidad;\nMuriendo en una cruz,\nCristo Jesús el Señor.'),(1808,290,'Estrofa',2,'Y desde allí al pecador,\nSe proclama libertad,\nTodos venid a los pies del Señor,\nÉl es del mundo la gran salvación,\nEs nuestra Estrella de Paz,\nCristo Jesús el Señor.'),(1809,290,'Estrofa',3,'No quieres hoy, oír su voz,\nY venir al Salvador;\nQue en el catorce del mes de Nisán,\nHaremos Cena todos al Señor;\nPor estatuto perpetuo,\nHasta que venga el Señor.'),(1810,291,'Estrofa',1,'No habrá sombras en el valle de la muerte,\nCuando cese de la vida el batallar;\nY escuchemos del Señor el llamamiento,\nYa llevándonos a Sión a descansar.'),(1811,291,'Coro',2,'Sombras, nada de sombras,\nAl dejar el mundo de dolor;\nSombras, nada de sombras,\nCuando al Reino llegue vencedor.'),(1812,291,'Estrofa',3,'Al dejarnos los que amamos no habrá sombras,\nSi su fe depositaron en Jesús;\nPorque irán para vivir por las edades,\nCon quien quiso redimirlos en la cruz.'),(1813,291,'Coro',4,'Sombras, nada de sombras,\nAl dejar el mundo de dolor;\nSombras, nada de sombras,\nCuando al Reino llegue vencedor.'),(1814,292,'Estrofa',1,'Si yo gano al mundo y pierdo a Cristo,\n¿Que provecho para mi será?\nSi en traje mundanal me visto,\n¿Cuál premio el mundo me dará?;\nY si yo granjeare sus riquezas,\nAhorrando su tesoro aquí;\nPerdiendo el Reino y su grandeza,\n¡Que gran pérdida sería a mi!'),(1815,292,'Estrofa',2,'¡Sin Jesús, cuán triste vive el alma,\nCuán vacío el corazón sin Él!;\nEl que torna tempestad en calma,\nEl desierto seco en un vergel.\nSin Jesús hay sólo noche obscura,\nY la vida es triste soledad;\n¿Que sería morar en la negrura,\nY sin Él por la eternidad?'),(1816,293,'Estrofa',1,'Señor, mi Dios, al contemplar los cielos,\nEl firmamento y las estrellas mil:\nAl oir tu voz en los potentes truenos,\nY ver brillar al sol en su cenit.'),(1817,293,'Coro',2,'Mi corazón entona esta canción,\n¡Cuán grande es Él! ¡Cuán grande es Él!\nMi corazón entona esta canción,\n¡Cuán grande es Él! ¡Cuán grande es Él!'),(1818,293,'Estrofa',3,'Al recorrer los montes y los valles,\nY ver las bellas flores al pasar:\nAl escuchar el canto de las aves,\nY el murmurar del claro manantial.'),(1819,293,'Coro',4,'Mi corazón entona esta canción,\n¡Cuán grande es Él! ¡Cuán grande es Él!\nMi corazón entona esta canción,\n¡Cuán grande es Él! ¡Cuán grande es Él!'),(1820,293,'Estrofa',5,'Cuando recuerdo del amor Divino,\nQue desde el cielo al Salvador envió:\nAquél Jesús que por salvarme vino,\nY en una cruz sufrió y por mí murió.'),(1821,293,'Coro',6,'Mi corazón entona esta canción,\n¡Cuán grande es Él! ¡Cuán grande es Él!\nMi corazón entona esta canción,\n¡Cuán grande es Él! ¡Cuán grande es Él!'),(1822,293,'Estrofa',7,'Cuando el Señor me llame a su presencia,\nAl dulce hogar, al reino de esplendor;\nLe adoraré cantando la grandeza,\nDe su poder y su infinito amor.'),(1823,293,'Coro',8,'Mi corazón entona esta canción,\n¡Cuán grande es Él! ¡Cuán grande es Él!\nMi corazón entona esta canción,\n¡Cuán grande es Él! ¡Cuán grande es Él!'),(1824,294,'Estrofa',1,'Un ancla tenemos en temido mar\nPor mucho que ruja no puede quebrar,\nLa dulce esperanza que infunde Jesús,\nLegado en su muerte angustia en la cruz.'),(1825,294,'Estrofa',2,'Allá en las alturas do Reina el Señor,\nRodeado de seres que ensalzan su amor;\nEsta ancla tenemos que fija estará,\nPues Dios a su dicho jamás faltara.'),(1826,294,'Estrofa',3,'Y cuando mas bravo el piélago esté,\nMas firme cojamos el cable de fe;\nQue furias de vientos, embates de mar,\nNo pueden del puerto la entrada vedar.'),(1827,295,'Estrofa',1,'Un día que el cielo sus glorias cantaba,\nUn día que el mal imperaba mas cruel,\nJesús descendió y al nacer de una virgen,\nMorando en el mundo nos dio ejemplo fiel.'),(1828,295,'Coro',2,'Vivo me amaba muerto salvome,\nY en el sepulcro mi mal enterró;\nResucitado me dio justicia,\nUn día el viene pues lo prometió.'),(1829,295,'Estrofa',3,'Un día lleváronle al monte calvario,\nUn día claváronle sobre una cruz;\nSufriendo dolores y pena de muerte,\nSe dio por mi eterno rescate Jesús.'),(1830,295,'Coro',4,'Vivo me amaba muerto salvome,\nY en el sepulcro mi mal enterró;\nResucitado me dio justicia,\nUn día el viene pues lo prometió.'),(1831,295,'Estrofa',5,'Un día dejáronle solo en el huerto,\nUn día la tumba su cuerpo encerró;\nLos ángeles sobre Él guardaban vigilia,\nAsí fue que el dueño del mundo durmió.'),(1832,295,'Coro',6,'Vivo me amaba muerto salvome,\nY en el sepulcro mi mal enterró;\nResucitado me dio justicia,\nUn día el viene pues lo prometió.'),(1833,295,'Estrofa',7,'Un día el sepulcro ocultarlo no pudo,\nUn día a su espiritual cuerpo volvió;\nHabiendo a la muerte por siempre vencido,\nA la diestra del Padre, Jesús se sentó.'),(1834,295,'Coro',8,'Vivo me amaba muerto salvome,\nY en el sepulcro mi mal enterró;\nResucitado me dio justicia,\nUn día el viene pues lo prometió.'),(1835,296,'Estrofa',1,'De celeste país he leído,\ndo se encuentra una hermosa ciudad,\nCuyas calles benditas son de oro,\ny de jaspe su muro eternal;\nA través de sus calles deslumbra\nde sus aguas de vida y cristal,\nY aunque se hable de tanta excelencia,\nNo se ha dicho aun la mitad.'),(1836,296,'Coro',2,'No se ha dicho aun la mitad, no se ha dicho aun la mitad,De aquella ciudad tan gloriosa, no se ha dicho aun la mitad.'),(1837,296,'Estrofa',3,'He leído de aquellas mansiones,\nDonde iremos con Cristo a morar;\nY los santos que aquí le han servido,\nVan con el para siempre a gozar;\nY ni muerte, dolor o pecado\nafligirnos jamás no podrá;\nY aunque se hable de tanta belleza,\nNo se ha dicho aun la mitad'),(1838,296,'Coro',4,'No se ha dicho aun la mitad, no se ha dicho aun la mitad,De aquella ciudad tan gloriosa, no se ha dicho aun la mitad.'),(1839,296,'Estrofa',5,'He leído de níveos vestidos,\ny coronas que irán a ostentar,\nLos que han sido llamados del Padre;\nA gozar de su gloria sin par,\nY los justos por siempre benditos,\nreinarán en aquella ciudad,\nDe esta historia gloriosa y sublime,\nNo se ha dicho aun la mitad.'),(1840,296,'Coro',6,'No se ha dicho aun la mitad, no se ha dicho aun la mitad,De aquella ciudad tan gloriosa, no se ha dicho aun la mitad.'),(1841,296,'Estrofa',7,'He leído de un Cristo benigno,\nQue al mas vil pecador cambiará\nY que paz y perdón le confiere,\nAl que humilde y sincero a Él va;\nHe leído que Dios nos protege,\nSi a su amparo queremos estar\nY aunque tanta bondad se pregona\nNo se ha dicho ni aun la mitad.'),(1842,296,'Coro',8,'No se ha dicho aun la mitad, no se ha dicho aun la mitad,De aquella ciudad tan gloriosa, no se ha dicho aun la mitad.'),(1843,297,'Estrofa',1,'Me hirió el pecado, fui a Jesús,\nMostréle mi dolor;\nPerdido, errante, vi su luz,\nBendíjome en su amor'),(1844,297,'Coro',2,'En la cruz, en la cruz do primero vi la luz,\nY las manchas de mi alma yo lavé;\nFue allí por fe do vi a Jesús,\nY siempre feliz con el seré'),(1845,297,'Estrofa',3,'Sobre una cruz, mi buen Señor,\nSu sangre derramó;\nPor este pobre pecador,\nA quien así salvo.'),(1846,297,'Coro',4,'En la cruz, en la cruz do primero vi la luz,\nY las manchas de mi alma yo lavé;\nFue allí por fe do vi a Jesús,\nY siempre feliz con el seré'),(1847,297,'Estrofa',5,'Venció la muerte con poder ,\nY al cielo se exaltó;\nConfiar en Él es mi placer,\nMorir no temo yo.'),(1848,297,'Coro',6,'En la cruz, en la cruz do primero vi la luz,\nY las manchas de mi alma yo lavé;\nFue allí por fe do vi a Jesús,\nY siempre feliz con el seré'),(1849,297,'Estrofa',7,'Aunque el se fue solo no estoy,\nMando al consolador;\nDivino espíritu que hoy,\nMe da perfecto amor.'),(1850,297,'Coro',8,'En la cruz, en la cruz do primero vi la luz,\nY las manchas de mi alma yo lavé;\nFue allí por fe do vi a Jesús,\nY siempre feliz con el seré'),(1851,298,'Estrofa',1,'En mis angustias me ayuda Jesús,\nSobre mi alma derrama su luz;\nTodos los días consuelo me da,\nCada momento conmigo el está.'),(1852,298,'Coro',2,'Cada momento me guarda Señor,\nCada momento en gracia y amor;\nVida abundante yo tengo en Ti,\nCada momento Tu vienes a mi.'),(1853,298,'Estrofa',3,'Yo acudo al trono de gracia con fe,\nOye mi voz y mis lagrimas ve;\nCristo Jesús en el cielo, y allí,\nCada momento se acuerda de mi.'),(1854,298,'Coro',4,'Cada momento me guarda Señor,\nCada momento en gracia y amor;\nVida abundante yo tengo en Ti,\nCada momento Tu vienes a mi.'),(1855,298,'Estrofa',5,'Cristo es mi Roca, mi libertador,\nEl es mi escudo, mi gran defensor;\nEn día de lucha a Él mirare,\nCada momento y salvo seré.'),(1856,298,'Coro',6,'Cada momento me guarda Señor,\nCada momento en gracia y amor;\nVida abundante yo tengo en Ti,\nCada momento Tu vienes a mi.'),(1857,299,'Estrofa',1,'Señor Jesús tu eres mi pastor,\nY a tu cuidado yo vivo tan feliz;\nYo te conozco pues tu voz oí,\nPacientemente llamándome al redil.'),(1858,299,'Coro',2,'Mi pastor es Jesús, mi buen Pastor es Jesús,\nMi pastor es Jesús, mi buen Pastor es Jesús\nEn sus hombros el me lleva,\nCuando yo cansado estoy;\nMi pastor es Jesús, mi buen Pastor.'),(1859,299,'Estrofa',3,'La senda está colmada de abundancia,\nEl pasto delicioso para mí;\nSediento no he de estar, pues tu Palabra,\nMuestra la fuente de salvación aquí.'),(1860,299,'Coro',4,'Mi pastor es Jesús, mi buen Pastor es Jesús,\nMi pastor es Jesús, mi buen Pastor es Jesús\nEn sus hombros el me lleva,\nCuando yo cansado estoy;\nMi pastor es Jesús, mi buen Pastor.'),(1861,300,'Estrofa',1,'¿Respuesta no hay al ruego que en tu pecho,\nCon ansiedad alzaste en tu dolor?...\n¿Tu fe vacila ya y tu esperanza,\nCreyendo vano el ruego a tu Señor?...\nNo digas nunca que Él no oyó tu voz,\nTu anhelo cumplirá después tu Dios,\nTu anhelo cumplirá después tu Dios.'),(1862,300,'Estrofa',2,'¿Respuesta no hay? Quizá cuando elevaste,\nTu ansiosa voz al trono celestial;\nTemiste no sufrir tan larga espera,\n¡Tan dura fue tu lucha con el mal!\nMas tu verás que el tiempo irá veloz,\nY te responderá después tu Dios,\nY te responderá después tu Dios.'),(1863,300,'Estrofa',3,'¿Respuesta no hay? No digas que te olvida,\nQuizá tu parte no cumplida vio;\nCuando tu ansioso ruego a Dios alzaste\nDe fe la lucha en tu alma comenzó;\nSi de su ley tan sólo vas en pos,\nRespuesta te dará después tu Dios,\nRespuesta te dará después tu Dios.'),(1864,300,'Estrofa',4,'¿Respuesta no hay? La fe tenerla debe,\nSi en Cristo, Roca eterna firme está;\nSegura siempre queda en la tormenta,\nNi a los rayos, ni a los vientos temerá;\nPues sabe bien que Dios oirá su voz,\nExclama: ¡Lo ha de hacer después mi Dios!\nExclama: ¡Lo ha de hacer después mi Dios!'),(1865,301,'Estrofa',1,'No me pases, no me olvides,\nTierno Salvador;\nMuchos gozan tus mercedes,\nOye mi clamor.'),(1866,301,'Coro',2,'Cristo, Cristo,\nOye Tú mi voz;\nSalvador tu gracia dame,\nOye mi clamor.'),(1867,301,'Estrofa',3,'Ante el Trono de tu gracia,\nHallo dulce paz;\nNada aquí mi alma sacia,\nTú eres mi solaz.'),(1868,301,'Coro',4,'Cristo, Cristo,\nOye Tú mi voz;\nSalvador tu gracia dame,\nOye mi clamor.'),(1869,301,'Estrofa',5,'Sólo fío en tus bondades,\nGuíame en tu luz;\nY mi alma no deseches,\nSálvame, Jesús.'),(1870,301,'Coro',6,'Cristo, Cristo,\nOye Tú mi voz;\nSalvador tu gracia dame,\nOye mi clamor.'),(1871,301,'Estrofa',7,'Fuente viva de consuelo,\nTú eres para mí;\n¿A quién tengo en este suelo,\nSi no sólo a Ti?'),(1872,301,'Coro',8,'Cristo, Cristo,\nOye Tú mi voz;\nSalvador tu gracia dame,\nOye mi clamor.'),(1873,302,'Estrofa',1,'¿Quién a Cristo quiere, de hoy en más seguir;\nSu pendón alzando, yendo a combatir?\n¿Quién le quiere humilde, siempre aquí servir;\nSiempre obedecerle, darle su existir?'),(1874,302,'Coro',2,'¿Quién seguirle quiere? ¿Quién responderá,\nAl buen redentor: Heme aquí “Yo iré‚”?\n¿Quién doquier que fuere, tras su huella irá?\n¿Quién dirá al Señor: “Yo te seguiré”?'),(1875,302,'Estrofa',3,'¿Quién seguirle quiere, con profundo amor;\nDándole la gloria, dándole el honor.\nDe su noble causa, siendo defensor;\nY en su santa viña, fiel trabajador?'),(1876,302,'Coro',4,'¿Quién seguirle quiere? ¿Quién responderá,\nAl buen redentor: Heme aquí “Yo iré‚”?\n¿Quién doquier que fuere, tras su huella irá?\n¿Quién dirá al Señor: “Yo te seguiré”?'),(1877,302,'Estrofa',5,'¿Quién seguirle quiere, sin vacilación;\nA su seno huyendo, de la tentación,\nSin dudar confiando en su protección,\nY gozando siempre de su bendición?'),(1878,302,'Coro',6,'¿Quién seguirle quiere? ¿Quién responderá,\nAl buen redentor: Heme aquí “Yo iré‚”?\n¿Quién doquier que fuere, tras su huella irá?\n¿Quién dirá al Señor: “Yo te seguiré”?'),(1879,303,'Estrofa',1,'Del amor divino, ¿Quién me apartará?\nEscondido en Cristo, ¿Quién me tocará?\nSi Dios justifica. ¿Quién condenará?\nCristo por mí aboga, ¿Quién me acusará?'),(1880,303,'Coro',2,'A los que a Dios aman,\nTodo ayuda a bien;\nEsto es mi consuelo,\nEsto es mi sostén.'),(1881,303,'Estrofa',3,'Todo lo que pasa en mi vida aquí,\nDios me lo prepara para bien de mí;\nEn mis pruebas duras,\nDios me es siempre fiel.\n¿Por qué, pues, las dudas?\nYo descanso en Él.'),(1882,303,'Coro',4,'A los que a Dios aman,\nTodo ayuda a bien;\nEsto es mi consuelo,\nEsto es mi sostén.'),(1883,303,'Estrofa',5,'Plagas hay y muerte en mi alrededor,\nordenó mi suerte el que es Dios de amor,\nNi una sola flecha me podrá dañar,\nMientras no permita, no me alcanzará.'),(1884,303,'Coro',6,'A los que a Dios aman,\nTodo ayuda a bien;\nEsto es mi consuelo,\nEsto es mi sostén.'),(1885,304,'Estrofa',1,'Maravillosa gracia, vino Jesús a dar;\nMás alta que los cielos,\nMás honda que la mar,\nMás grande que mis culpas,\nClavadas en la cruz,\nEs la maravillosa gracia de Jesús.'),(1886,304,'Coro',2,'Inefable es la divina gracia,\nEs inmensurable cual la mar;\nComo clara fuente siempre suficiente,\nPara pecadores rescatar,\nPerdonando todos mis errores,\nCristo me limpió de mi maldad,\nAlabaré su dulce nombre por la eternidad.'),(1887,304,'Estrofa',3,'Maravillosa gracia, gracia de compasión;\nGracia que sacia el alma, con plena salvación;\nGracia que lleva al Reino, gracia de paz y luz,\nEs la maravillosa gracia de Jesús.'),(1888,304,'Coro',4,'Inefable es la divina gracia,\nEs inmensurable cual la mar;\nComo clara fuente siempre suficiente,\nPara pecadores rescatar,\nPerdonando todos mis errores,\nCristo me limpió de mi maldad,\nAlabaré su dulce nombre por la eternidad.'),(1889,304,'Estrofa',5,'Maravillosa gracia, llama con dulce voz;\nLlámanos a ser hechos, hijos de nuestro Dios;\nColma de su consuelo, nos llena de virtud,\nEsta maravillosa gracia de Jesús.'),(1890,304,'Coro',6,'Inefable es la divina gracia,\nEs inmensurable cual la mar;\nComo clara fuente siempre suficiente,\nPara pecadores rescatar,\nPerdonando todos mis errores,\nCristo me limpió de mi maldad,\nAlabaré su dulce nombre por la eternidad.'),(1891,305,'Estrofa',1,'Yo sólo espero ese día,\nCuando Cristo volverá;\nYo sólo espero ese día,\nCuando Cristo volverá.\nAfán y todo trabajo,\nPara mí terminarán;\n//Cuando Cristo venga,\nY en su Reino Él me tendrá.//'),(1892,305,'Estrofa',2,'Ya no me importa que el mundo,\nMe desprecie por doquier;\nYa no soy más de este mundo,\nSoy del Reino espiritual.\nYo sólo espero ese día,\nCuando me levantaré,\n//De la tumba fría con un cuerpo,\nYa inmortal.//'),(1893,305,'Estrofa',3,'Entonces allí triunfante\ny victorioso estaré,\nA mi Señor Jesucristo\ncara a cara le veré;\nAllí no habrá más tristezas,\nNi trabajos para mí,\n//Con los redimidos\nal Cordero alabaré.//'),(1894,306,'Estrofa',1,'Soy peregrino aquí, mi hogar lejano está,\nEn la Mansión de Luz, eterna paz y amor;\nEmbajador yo soy del Reino Celestial,\nEn los negocios de mi Rey.'),(1895,306,'Coro',2,'Este mensaje fiel oíd, que dijo ya celeste voz;\n“Reconciliados ya, dice el Señor y Rey,\n¡Reconciliados hoy con Dios!'),(1896,306,'Estrofa',3,'Que del pecado vil arrepentidos ya,\nHan de reinar con Él, los que obedientes son,\nEs el mensaje fiel que debo proclamar,\nEn los negocios de mi Rey.'),(1897,306,'Coro',4,'Este mensaje fiel oíd, que dijo ya celeste voz;\n“Reconciliados ya, dice el Señor y Rey,\n¡Reconciliados hoy con Dios!'),(1898,306,'Estrofa',5,'Mi hogar más bello es que el valle de Sarón,\nEterno gozo y paz reinan por siempre en ÉL,\nY allí Jesús dará eterna habitación,\nEs el mensaje de mi Rey'),(1899,306,'Coro',6,'Este mensaje fiel oíd, que dijo ya celeste voz;\n“Reconciliados ya, dice el Señor y Rey,\n¡Reconciliados hoy con Dios!'),(1900,307,'Estrofa',1,'¿Quién podrá con su presencia\nImpartirme bendición?\nSólo Cristo y su clemencia,\nPueden dar consolación.'),(1901,307,'Coro',2,'Sólo Cristo satisface,\nMi transido corazón;\nEs el Lirio de los valles,\nY la Rosa de Sarón.'),(1902,307,'Estrofa',3,'Su amor no se limita,\nEn su gracia, sin igual;\nSu merced es infinita,\nMás profunda que mi mal.'),(1903,307,'Coro',4,'Sólo Cristo satisface,\nMi transido corazón;\nEs el Lirio de los valles,\nY la Rosa de Sarón.'),(1904,307,'Estrofa',5,'Redención sublime y santa,\nImposible de explicar;\nQue su sangre sacrosanta,\nMi alma pudo rescatar.'),(1905,307,'Coro',6,'Sólo Cristo satisface,\nMi transido corazón;\nEs el Lirio de los valles,\nY la Rosa de Sarón.'),(1906,307,'Estrofa',7,'Cristo suple en abundancia,\nToda mi necesidad;\nSer de Él, es mi ganancia,\nInefable es su bondad.'),(1907,307,'Coro',8,'Sólo Cristo satisface,\nMi transido corazón;\nEs el Lirio de los valles,\nY la Rosa de Sarón.'),(1908,308,'Estrofa',1,'Cristo guarda siempre, puedo en Él confiar,\nNo me deja nunca, puedo en Él confiar,\nPues, cual la Roca eterna de los siglos, firme estaré.'),(1909,308,'Coro',2,'¡Nada, no, nada, me ha de mover!\n¡Nada, no, nada, me ha de mover!\nPues, cual la Roca eterna de los siglos, firme estaré.'),(1910,308,'Estrofa',3,'Fuerte es Jesucristo, puedo en Él confiar,\nTodo me ha provisto, puedo en Él confiar,\nPues, cual la Roca eterna de los siglos, firme estaré.'),(1911,308,'Coro',4,'¡Nada, no, nada, me ha de mover!\n¡Nada, no, nada, me ha de mover!\nPues, cual la Roca eterna de los siglos, firme estaré.'),(1912,308,'Estrofa',5,'En la noche obscura, puedo en Él confiar,\nMi alma está segura, puedo en Él confiar,\nPues, cual la Roca eterna de los siglos, firme estaré.'),(1913,308,'Coro',6,'¡Nada, no, nada, me ha de mover!\n¡Nada, no, nada, me ha de mover!\nPues, cual la Roca eterna de los siglos, firme estaré.'),(1914,308,'Estrofa',7,'Muchos me abandonan, puedo en Él confiar,\nOtros me engañan, puedo en Él confiar,\nPues, cual la Roca eterna de los siglos, firme estaré'),(1915,308,'Coro',8,'¡Nada, no, nada, me ha de mover!\n¡Nada, no, nada, me ha de mover!\nPues, cual la Roca eterna de los siglos, firme estaré.'),(1916,309,'Estrofa',1,'Mi voluntad la he rendido,\nY pertenezco sólo a Ti;\nHumildemente yo te pido:\n“Tu voluntad se haga en mí”.'),(1917,309,'Coro',2,'Oh, dulce bien, a Ti me entrego,\nTu voluntad hoy haz en mí;\nOh, Dios bendito, mi ser contrito,\nConsagro solamente a Ti.'),(1918,309,'Estrofa',3,'Estoy hastiado de mi culpa,\nY sólo Tú perdonarás;\nNo puedo darte otra disculpa,\nA Ti me acerco nada más.'),(1919,309,'Coro',4,'Oh, dulce bien, a Ti me entrego,\nTu voluntad hoy haz en mí;\nOh, Dios bendito, mi ser contrito,\nConsagro solamente a Ti.'),(1920,309,'Estrofa',5,'Tu voluntad, oh Rey precioso,\nRendido quiero aceptar;\nDel Santo Espíritu gozoso,\nMi alma quiero inundar.'),(1921,309,'Coro',6,'Oh, dulce bien, a Ti me entrego,\nTu voluntad hoy haz en mí;\nOh, Dios bendito, mi ser contrito,\nConsagro solamente a Ti.'),(1922,309,'Estrofa',7,'Contigo siempre, Dios amado,\nMi pie seguro estará;\n¿Quién de tu amor ilimitado,\nPodrá mi vida separar?'),(1923,309,'Coro',8,'Oh, dulce bien, a Ti me entrego,\nTu voluntad hoy haz en mí;\nOh, Dios bendito, mi ser contrito,\nConsagro solamente a Ti.'),(1924,310,'Estrofa',1,'Yo soy la vid y mi Padre el Labrador,\nVosotros pámpanos, dice el Salvador;\nEstad en mí y Yo en ti, y fruto llevaréis.\nPorque sin Mí, nada podéis hacer jamás;\nDios nos ha puesto los frutos a llevar,\nQue permanezcan como un testimonio a Él.'),(1925,310,'Estrofa',2,'El que estuviere en la vid le limpiará,\nPara que frutos abunden más y más;\nLuego pedid, Sin desmayar, lo que deseas tú.\nEl Dios de amor, que te ama a ti, te lo dará;\nGlorificado así mi Padre es,\nEn que llevéis mucho fruto,\nY seáis siempre fiel.'),(1926,310,'Estrofa',3,'Por mis palabras vosotros limpios sois,\nCon el amor de mi Padre amo Yo;\nDejar mi amor, siempre brillar,\nCon todo su fulgor;\nFácil será, obedecer, mi voluntad;\nTodo mi gozo en vosotros estará.\nY vuestro gozo con fruto cumplido será.'),(1927,311,'Estrofa',1,'Más profundo llévame, oh, Cristo,\nEn tu santo amor;\nAunque sufra duras aflicciones,\nNo tendré temor.'),(1928,311,'Coro',2,'¡Oh! más profundo amor,\nDeseo, oh, Señor;\nTu santa voluntad\nQuiero hacer, en humildad.'),(1929,311,'Estrofa',3,'Más profunda santificación,\nQuiero hoy tener;\nY crecer en gracia es mi anhelo,\nDame, oh Dios, poder.'),(1930,311,'Coro',4,'¡Oh! más profundo amor,\nDeseo, oh, Señor;\nTu santa voluntad\nQuiero hacer, en humildad.'),(1931,311,'Estrofa',5,'Más profunda devoción a Cristo,\nYo necesito, oh Dios,\nPara ser un atalaya tuyo,\nY seguirte en pos.'),(1932,311,'Coro',6,'¡Oh! más profundo amor,\nDeseo, oh, Señor;\nTu santa voluntad\nQuiero hacer, en humildad.'),(1933,312,'Estrofa',1,'Confío en Dios, no importa dónde esté,\nEn alta mar o en tierra, tengo fe;\nSi vienen pruebas y dolor,\nMi amante Dios me cuida con su amor.'),(1934,312,'Coro',2,'Confío en Dios, yo sé que me ama Él,\nEn la furiosa lid es mi broquel;\nSi olas rugen con furor,\nMi amante Dios me cuida con su amor.'),(1935,312,'Estrofa',3,'Confío en Dios, Él siempre paz me da,\nEn las tinieblas a mi lado está;\nConforta el alma y da valor,\nMi amante Dios me cuida con su amor.'),(1936,312,'Coro',4,'Confío en Dios, yo sé que me ama Él,\nEn la furiosa lid es mi broquel;\nSi olas rugen con furor,\nMi amante Dios me cuida con su amor.'),(1937,312,'Estrofa',5,'Confío en Dios, nada me faltará,\nEn su bondad me pastoreará;\nEl quitará todo temor,\nMi amante Dios me cuida con su amor.'),(1938,312,'Coro',6,'Confío en Dios, yo sé que me ama Él,\nEn la furiosa lid es mi broquel;\nSi olas rugen con furor,\nMi amante Dios me cuida con su amor.'),(1939,313,'Estrofa',1,'Es mi vida cual el mar,\nPero voy sin titubear;\nLos escollos al cruzar,\nEl piloto es mi Jesús.'),(1940,313,'Coro',2,'Voy hacia la eternidad,\nEl piloto es mi Jesús;\nPor la fe en Él, llegaré,\nHasta el puerto de salud;\nÉl me da seguridad,\nSanto gozo, bella luz.'),(1941,313,'Estrofa',3,'Oigo fiero al mar rugir,\nA mis pies el agua hervir;\nMas yo puedo aún decir:\nEl piloto es mi Jesús.'),(1942,313,'Coro',4,'Voy hacia la eternidad,\nEl piloto es mi Jesús;\nPor la fe en Él, llegaré,\nHasta el puerto de salud;\nÉl me da seguridad,\nSanto gozo, bella luz.'),(1943,313,'Estrofa',5,'Vendaval hay por doquier\nMas no tengo qué temer;\nNada me podrá vencer,\nEl piloto es mi Jesús.'),(1944,313,'Coro',6,'Voy hacia la eternidad,\nEl piloto es mi Jesús;\nPor la fe en Él, llegaré,\nHasta el puerto de salud;\nÉl me da seguridad,\nSanto gozo, bella luz.'),(1945,313,'Estrofa',7,'La tormenta al arreciar,\nMi bajel hace temblar;\nPuedo aún así cantar:\nEl piloto es mi Jesús.'),(1946,313,'Coro',8,'Voy hacia la eternidad,\nEl piloto es mi Jesús;\nPor la fe en Él, llegaré,\nHasta el puerto de salud;\nÉl me da seguridad,\nSanto gozo, bella luz.'),(1947,314,'Estrofa',1,'Pertenezco a mi Rey,\nHijo soy de su amor;\nY sus regias moradas veré,\nSus delicias sin fin, revelóme el Señor,\nY un lugar con sus hijos tendré.'),(1948,314,'Coro',2,'Pertenezco a mi Rey,\nHijo soy de su amor;\nY a los suyos jamás olvidó;\nEn su Reino de amor, he de ver al Señor,\nY a su lado feliz viviré.'),(1949,314,'Estrofa',3,'Pertenezco a mi Rey,\nY que me ama lo sé;\nY a sus dones de amor celestial,\nPor doquiera que voy, sin cesar hallaré,\nComo pruebas de amor sin igual.'),(1950,314,'Coro',4,'Pertenezco a mi Rey,\nHijo soy de su amor;\nY a los suyos jamás olvidó;\nEn su Reino de amor, he de ver al Señor,\nY a su lado feliz viviré.'),(1951,314,'Estrofa',5,'Pertenezco a mi Rey,\nY no dudo jamás,\nQue reunidos los suyos serán,\nEn la Sión milenial, la morada de paz,\nDo pesares jamás se hallarán'),(1952,314,'Coro',6,'Pertenezco a mi Rey,\nHijo soy de su amor;\nY a los suyos jamás olvidó;\nEn su Reino de amor, he de ver al Señor,\nY a su lado feliz viviré.'),(1953,315,'Estrofa',1,'Soy yo soldado de Jesús,\nY siervo del Señor;\nNo temeré llevar su cruz,\nSufriendo por su amor.'),(1954,315,'Coro',2,'Después de la batalla nos coronará,\nDios nos coronará,\nDios nos coronará;\nDespués de la batalla nos coronará,\nEn aquella Santa Sión,\nMás allá, más allá, en aquella Santa Sión.\nDespués de la batalla nos coronará,\nEn aquella santa Sión.'),(1955,315,'Estrofa',3,'Lucharon otros por la fe,\n¿Cobarde habré de ser?\nPor mi Señor yo pelearé,\nConfiando en su poder.'),(1956,315,'Coro',4,'Después de la batalla nos coronará,\nDios nos coronará,\nDios nos coronará;\nDespués de la batalla nos coronará,\nEn aquella Santa Sión,\nMás allá, más allá, en aquella Santa Sión.\nDespués de la batalla nos coronará,\nEn aquella santa Sión.'),(1957,315,'Estrofa',5,'Es menester que sea fiel,\nQue nunca vuelva atrás;\nQue siga siempre en pos de Él,\nY me guiará en paz.'),(1958,315,'Coro',6,'Después de la batalla nos coronará,\nDios nos coronará,\nDios nos coronará;\nDespués de la batalla nos coronará,\nEn aquella Santa Sión,\nMás allá, más allá, en aquella Santa Sión.\nDespués de la batalla nos coronará,\nEn aquella santa Sión.'),(1959,316,'Estrofa',1,'Débil soy, tu fuerza es tal,\nQue me guardarás del mal;\nSatisfecho estoy, oh sí,\nAl andar, oh Señor, junto a Ti.'),(1960,316,'Coro',2,'A tu lado andar, Señor,\nEstá es mi oración;\nCada día en tu amor,\nSiempre guárdame, Salvador.'),(1961,316,'Estrofa',3,'En la prueba y dolor,\nCuídame, oh buen Señor;\nY al fin en tu ciudad,\nGozaré de tu comunión.'),(1962,316,'Coro',4,'A tu lado andar, Señor,\nEstá es mi oración;\nCada día en tu amor,\nSiempre guárdame, Salvador.'),(1963,317,'Estrofa',1,'Ojos divinos de mi Jesús,\nQue derramaron su hermosa luz;\nSiempre apacibles ante el dolor,\nManifestaron sublime amor.'),(1964,317,'Estrofa',2,'Ante una sierva, Pedro negó,\nA su Maestro y Él le miró;\nY sus miradas, al penetrar,\nLe condujeron pronto a llorar.'),(1965,317,'Estrofa',3,'Cuando Zaqueo al árbol subió,\nEl Cristo amado pronto le vio;\nY aquel pequeño, sin vacilar,\nAl Nazareno lleva a su hogar.'),(1966,317,'Estrofa',4,'Ojos divinos, llenos de amor,\nFueron los ojos de mi Señor;\nMiran mi vida, tu vida, ven,\nQuieren que hagamos tan sólo el bien.'),(1967,317,'Estrofa',5,'Vedles mirando a Jerusalem,\nA quien deseaban tan sólo el bien;\nY con profundo, sin par dolor,\nAquellos ojos lloran de amor.'),(1968,317,'Estrofa',6,'Ante los ojos de mi Jesús,\nNadie se esconde, pues son la luz;\nEscudriñando tu vida están,\nY dondequiera te seguirán.'),(1969,318,'Estrofa',1,'De tu Espíritu Divino,\nQuiero mi alma rebosar;\nA la luz de tu camino,\nOh, Señor, prefiero andar.'),(1970,318,'Estrofa',2,'Oh, verdad maravillosa,\nQue nos libras de pecar;\nDe tu gloria portentosa,\nQuiero fiel participar.'),(1971,318,'Estrofa',3,'Santo Dios del cielo,\nLlena mi alma de tu amor;\nTu presencia de consuelo,\nLlena del perfecto amor.'),(1972,319,'Estrofa',1,'Nos veremos en el río, cuyas aguas argentinas, nacen, puras, cristalinas, bajo el trono del Señor.'),(1973,319,'Coro',2,'Oh, sí, nos congregaremos,\nEn célica hermosísima ribera,\nDel río de la vida verdadera,\nQue nace del trono de Dios.'),(1974,319,'Estrofa',3,'En las márgenes del río, que frecuentan serafines;\nY embellecen querubines, da la dicha eterna Dios.'),(1975,319,'Coro',4,'Oh, sí, nos congregaremos,\nEn célica hermosísima ribera,\nDel río de la vida verdadera,\nQue nace del trono de Dios.'),(1976,319,'Estrofa',5,'El vergel que riega el río, de Jesús es la morada;\nEl mal nunca tiene entrada, allí sólo reina Dios.'),(1977,319,'Coro',6,'Oh, sí, nos congregaremos,\nEn célica hermosísima ribera,\nDel río de la vida verdadera,\nQue nace del trono de Dios.'),(1978,319,'Estrofa',7,'Antes de llegar al río, nuestra carga dejaremos;\nLibres todos estaremos, por la gracia del Señor.'),(1979,319,'Coro',8,'Oh, sí, nos congregaremos,\nEn célica hermosísima ribera,\nDel río de la vida verdadera,\nQue nace del trono de Dios.'),(1980,319,'Estrofa',9,'En la margen de aquel río, crece el árbol de la vida;\nY a toda alma dolorida, dan sus hojas la salud.'),(1981,319,'Coro',10,'Oh, sí, nos congregaremos,\nEn célica hermosísima ribera,\nDel río de la vida verdadera,\nQue nace del trono de Dios.'),(1982,319,'Estrofa',11,'Tiene faz risueña el río, pues la de Jesús refleja;\nLa que de su grey aleja, todo mal, todo dolor.'),(1983,319,'Coro',12,'Oh, sí, nos congregaremos,\nEn célica hermosísima ribera,\nDel río de la vida verdadera,\nQue nace del trono de Dios.'),(1984,320,'Estrofa',1,'Aviva tu obra, oh Dios,\nEjerce tu poder;\nLos muertos han de oír la voz,\nQue hoy hemos menester.'),(1985,320,'Estrofa',2,'A tu obra vida da,\nLas almas tienen sed:\nHambrientas de tu buen maná,\nAguardan tu merced.'),(1986,320,'Estrofa',3,'Aviva tu labor,\nGlorioso fruto dé;\nMediante el gran Consolador,\nAbunde nuestra fe.'),(1987,320,'Estrofa',4,'La fuente espiritual,\nAvive nuestro amor;\nSerá tu gloria sin igual,\nY nuestro el bien, Señor.'),(1988,321,'Estrofa',1,'Un mensaje del Señor, ¡Aleluya!\nAnuncio yo que da la paz;\nEs de Dios el santo amor, ¡Aleluya!\n“Ve tan sólo a Cristo y vivirás”.'),(1989,321,'Coro',2,'Ve a Cristo y vivirás,\nVe a Cristo y vivirás;\nEs de Dios el santo amor, ¡Aleluya!\n“Ve tan sólo a Cristo y vivirás”.'),(1990,321,'Estrofa',3,'El mensaje del amor, ¡Aleluya!\nInfundirá la fe en ti;\nQue Jesús, mi Salvador, ¡Aleluya!\nDio por ti su sangre carmesí.'),(1991,321,'Coro',4,'Ve a Cristo y vivirás,\nVe a Cristo y vivirás;\nEs de Dios el santo amor, ¡Aleluya!\n“Ve tan sólo a Cristo y vivirás”.'),(1992,321,'Estrofa',5,'Vida puedes obtener, ¡Aleluya!\nQue tu Señor te quiere dar;\nSi tan sólo quieres ver, ¡Aleluya!\nPor fe a quien podrá salvar.'),(1993,321,'Coro',6,'Ve a Cristo y vivirás,\nVe a Cristo y vivirás;\nEs de Dios el santo amor, ¡Aleluya!\n“Ve tan sólo a Cristo y vivirás”.'),(1994,321,'Estrofa',7,'Cómo vine, te diré, ¡Aleluya!\nA mi Jesús que me salvó;\nFui tan sólo por la fe, ¡Aleluya!\nY Jesús mi alma redimió.'),(1995,321,'Coro',8,'Ve a Cristo y vivirás,\nVe a Cristo y vivirás;\nEs de Dios el santo amor, ¡Aleluya!\n“Ve tan sólo a Cristo y vivirás”.'),(1996,322,'Estrofa',1,'Mi Redentor, el Rey de gloria,\nQue vive, yo seguro estoy;\nY da coronas de victoria,\nA recibir la mía voy.'),(1997,322,'Coro',2,'Que permanezca no pidáis,\nEntre el bullicio y el vaivén;\nEl mundo alegre hoy dejaré,\nAún cuando fuese algún Edén.\nLa cita nada más aguardo,\nQue el Rey me diga: Hijo, ven.'),(1998,322,'Estrofa',3,'En mi Señor Jesús confío,\nSu sangre clama a mi favor;\nEs dueño Él de mi albedrío,\nEstar con Él es lo mejor.'),(1999,322,'Coro',4,'Que permanezca no pidáis,\nEntre el bullicio y el vaivén;\nEl mundo alegre hoy dejaré,\nAún cuando fuese algún Edén.\nLa cita nada más aguardo,\nQue el Rey me diga: Hijo, ven.'),(2000,322,'Estrofa',5,'De tanto amor me maravillo,\nY no me canso de admirar;\nMe libertó de mi peligro,\nSufriendo todo en mi lugar.'),(2001,322,'Coro',6,'Que permanezca no pidáis,\nEntre el bullicio y el vaivén;\nEl mundo alegre hoy dejaré,\nAún cuando fuese algún Edén.\nLa cita nada más aguardo,\nQue el Rey me diga: Hijo, ven.'),(2002,322,'Estrofa',7,'Consuélome en su larga ausencia,\nPensando: Pronto volverá;\nEntonces su gloriosa herencia,\nA cada fiel, Jesús, dará.'),(2003,322,'Coro',8,'Que permanezca no pidáis,\nEntre el bullicio y el vaivén;\nEl mundo alegre hoy dejaré,\nAún cuando fuese algún Edén.\nLa cita nada más aguardo,\nQue el Rey me diga: Hijo, ven.'),(2004,323,'Estrofa',1,'A los pies de Jesucristo,\nSiempre quiero hallarme yo;\nEscuchando cual María,\nLas palabras de su amor.\nA los pies de Jesucristo,\nMi pasado olvidaré;\nPues su mano fiel y tierna,\nMe ha librado de caer.'),(2005,323,'Estrofa',2,'A los pies de Jesucristo\nHallo tierna compasión;\nPara todos mis afanes,\nMis conflictos y dolor.\nPuedo yo decirle a Cristo,\nMis cuidados y temor;\nY con Él tendrá mi alma,\nGozo, paz, tranquilidad.'),(2006,323,'Estrofa',3,'A los pies de Jesucristo,\nYo tendré‚ su bendición;\nEn sus ojos hay dulzura,\nY en su seno protección,\n//Y que el mundo sepa al verme,\nQue Jesús es mi Señor.//'),(2007,324,'Estrofa',1,'Cuando mis luchas terminen aquí,\nY ya seguro en el Reino esté;\nCuando al Señor mire cerca de mí,\nPor las edades mi gloria será.'),(2008,324,'Coro',2,'Esa será gloria sin fin, gloria sin fin,\nGloria sin fin,\ncuando por gracia, su faz pueda ver,\nEsa mi gloria sin fin ha de ser.'),(2009,324,'Estrofa',3,'Gozo infinito será contemplar,\nTodos los seres que salvos serán;\nMas la presencia de Cristo gozar,\nPor las edades mi gloria será.'),(2010,324,'Coro',4,'Esa será gloria sin fin, gloria sin fin,\nGloria sin fin,\ncuando por gracia, su faz pueda ver,\nEsa mi gloria sin fin ha de ser.'),(2011,324,'Estrofa',5,'Cuando por gracia yo pueda tener,\nEn su reinado morada de paz;\nY que allí siempre su faz pueda ver,\nPor las edades mi gloria será.'),(2012,324,'Coro',6,'Esa será gloria sin fin, gloria sin fin,\nGloria sin fin,\ncuando por gracia, su faz pueda ver,\nEsa mi gloria sin fin ha de ser.'),(2013,325,'Estrofa',1,'¡Oh!, no rechaces la verdad,\nTus ojos hoy abre a la luz;\nRenuncia a toda la maldad,\nY ven a Jesús.'),(2014,325,'Coro',2,'¡Oh, ven sin tardar! ¡Oh, ven sin tardar!\n¡Acepta a Jesús y salvo serás!'),(2015,325,'Estrofa',3,'Tus ojos ya tal vez el sol,\nNo más aquí contemplarán;\nHoy es el día de salvación,\n¡Oh, ven a Jesús!'),(2016,325,'Coro',4,'¡Oh, ven sin tardar! ¡Oh, ven sin tardar!\n¡Acepta a Jesús y salvo serás!'),(2017,325,'Estrofa',5,'Jesús te tiene compasión,\n¿Con qué su amor le pagarás?\nHoy trae a Él tu corazón,\nY salvo serás.'),(2018,325,'Coro',6,'¡Oh, ven sin tardar! ¡Oh, ven sin tardar!\n¡Acepta a Jesús y salvo serás!'),(2019,325,'Estrofa',7,'Jesús recibe al pecador,\nQue quiera a Él su alma unir;\nYa no desprecies más su amor,\n¡Oh, ven a Jesús!'),(2020,325,'Coro',8,'¡Oh, ven sin tardar! ¡Oh, ven sin tardar!\n¡Acepta a Jesús y salvo serás!'),(2021,326,'Estrofa',1,'Cuán felices fuimos desde que creímos,\nEn el Cristo amado, que fuera inmolado;\nFue la tumba fría y resucitado,\nUn hermoso día fue glorificado.'),(2022,326,'Estrofa',2,'En la hora postrera, cuando Cristo fuera,\nEn la cruz clavado por nuestro pecado,\nTiernamente dijo a Juan y a su Madre:\n“He aquí tu hijo, he aquí tu madre”'),(2023,326,'Estrofa',3,'Cuando le clavaban y le denostaban,\nImploró clemencia, perdón y paciencia.\nEn favor de aquellos que en tinieblas yacen,\n“Pues ignoran ellos”, dijo, “lo que hacen”'),(2024,326,'Estrofa',4,'En su angustia llama, “Sed yo tengo”, exclama,\n¿Y sabéis qué hicieron? Vinagre le dieron;\nY aquel penitente que buscarle quiso,\nLe ofreció la fuente de su paraíso.'),(2025,326,'Estrofa',5,'Con solemne calma encomienda su alma,\nA su Padre amado que ya le ha dejado,\nPor el vil pecado de un mundo soez,\nY clama angustiado. “Consumado es”.'),(2026,327,'Estrofa',1,'De Jesús el nombre guarda,\nHeredero de afán;\nDulce hará tu boca amarga,\nTus afanes cesarán.'),(2027,327,'Coro',2,'Suave luz, manantial,\nDe esperanza, fe y amor;\nSumo bien celestial,\nEs Jesús el Salvador.'),(2028,327,'Estrofa',3,'De Jesús el nombre estima,\nQue te sirva de broquel;\nAlma débil, combatida,\nHallarás asilo en Él.'),(2029,327,'Coro',4,'Suave luz, manantial,\nDe esperanza, fe y amor;\nSumo bien celestial,\nEs Jesús el Salvador.'),(2030,327,'Estrofa',5,'De Jesús el nombre ensalza,\nCuyo sin igual poder;\nDel sepulcro nos levanta,\nRenovando nuestro ser.'),(2031,327,'Coro',6,'Suave luz, manantial,\nDe esperanza, fe y amor;\nSumo bien celestial,\nEs Jesús el Salvador.'),(2032,328,'Estrofa',1,'Cristianos todos ya prepararse,\nVed el esposo, vuestro Señor;\nLlenas tened las lámparas siempre\nA su encuentro id con amor.'),(2033,328,'Coro',2,'Cristo ya viene, pronto, si, viene,\nSin tardanza aparecerá;\nCon Él cantemos !Aleluya!\nQue vida eterna Él nos dará.'),(2034,328,'Estrofa',3,'Ya las señales cúmplanse todas,\nYa la higuera quiere brotar;\nFieles venid, el Salvador llama,\nNadie en sus bodas debe faltar.'),(2035,328,'Coro',4,'Cristo ya viene, pronto, si, viene,\nSin tardanza aparecerá;\nCon Él cantemos !Aleluya!\nQue vida eterna Él nos dará.'),(2036,328,'Estrofa',5,'Presto acude, alma acepta,\nEste convite de tu Señor;\nEl te dará su gozo y gloria,\nVen y recibe hoy su amor.'),(2037,328,'Coro',6,'Cristo ya viene, pronto, si, viene,\nSin tardanza aparecerá;\nCon Él cantemos !Aleluya!\nQue vida eterna Él nos dará.'),(2038,329,'Estrofa',1,'¿Has hallado en Cristo plena salvación?\nPor la sangre que Cristo vertió;\nToda mancha lava de tu corazón,\nEres limpio en la sangre eficaz.'),(2039,329,'Coro',2,'¿Eres limpio en la sangre,\nEn la sangre de Cristo Jesús?\n¿Es tu corazón más blanco que la nieve?\n¿Eres limpio en la sangre eficaz?'),(2040,329,'Estrofa',3,'¿Vives siempre al lado de tu Salvador?\n¿Por la sangre que el derramó?\n¿Del pecado eres siempre vencedor?\n¿Eres limpio en la sangre eficaz?'),(2041,329,'Coro',4,'¿Eres limpio en la sangre,\nEn la sangre de Cristo Jesús?\n¿Es tu corazón más blanco que la nieve?\n¿Eres limpio en la sangre eficaz?'),(2042,329,'Estrofa',5,'¿Tendrás ropa blanca al venir Jesús?\n¿Eres limpio en la fuente de amor?\n¿Estás listo para la gloria de su luz?\n¿Eres limpio en la sangre eficaz?'),(2043,329,'Coro',6,'¿Eres limpio en la sangre,\nEn la sangre de Cristo Jesús?\n¿Es tu corazón más blanco que la nieve?\n¿Eres limpio en la sangre eficaz?'),(2044,329,'Estrofa',7,'Cristo ofrece hoy pureza y poder,\n¡Oh, acude a la cruz del Señor!\nÉl la fuente es, que limpiará tu ser,\n¡Oh, acude a su sangre eficaz!'),(2045,329,'Coro',8,'¿Eres limpio en la sangre,\nEn la sangre de Cristo Jesús?\n¿Es tu corazón más blanco que la nieve?\n¿Eres limpio en la sangre eficaz?'),(2046,330,'Estrofa',1,'Cuando desalentado me siento desmayar,\nA murmurar tentado, con ganas de quejar;\nMas al pensar en Cristo no puedo olvidar,\nY clamo a la Roca Eterna: Escóndeme.'),(2047,330,'Coro',2,'Oh, Roca Eterna, ¡escóndeme!\nNo hay otro refugio, yo vengo a Ti con fe;\nLa noche me rodea, la luz también se fue,\nHoy clamo a la Roca Eterna: Escóndeme.'),(2048,330,'Estrofa',3,'A veces combatido, ni un paso puedo dar,\nCansado y tentado mi fe para negar;\nMas al pensar en Cristo y en su gran amor,\nMe siento muy animado y con valor.'),(2049,330,'Coro',4,'Oh, Roca Eterna, ¡escóndeme!\nNo hay otro refugio, yo vengo a Ti con fe;\nLa noche me rodea, la luz también se fue,\nHoy clamo a la Roca Eterna: Escóndeme.'),(2050,330,'Estrofa',5,'Hallé la paz en Cristo, escondedero fiel,\nEs mi amigo eterno, divino Emmanuel;\nNo más a tientas ando, en su camino voy,\nEn Cristo la Roca Eterna, seguro estoy.'),(2051,330,'Coro',6,'Oh, Roca Eterna, ¡escóndeme!\nNo hay otro refugio, yo vengo a Ti con fe;\nLa noche me rodea, la luz también se fue,\nHoy clamo a la Roca Eterna: Escóndeme.'),(2052,330,'Estrofa',7,'Oh, pecador perdido acepta a Jesús,\nTe colmará de bienes y andarás en su luz;\nPues cuando ya del mundo perdiste toda fe,\nA la Roca Eterna clama: Escóndeme.'),(2053,330,'Coro',8,'Oh, Roca Eterna, ¡escóndeme!\nNo hay otro refugio, yo vengo a Ti con fe;\nLa noche me rodea, la luz también se fue,\nHoy clamo a la Roca Eterna: Escóndeme.'),(2054,331,'Estrofa',1,'Salvador mío, como Tú eres,\nPuro y santo, quiero vivir;\nDejando atrás los vanos placeres,\nEn tus pisadas quiero seguir.'),(2055,331,'Coro',2,'Hazme, oh Cristo, como Tú eres,\nMi ser inunda con tu poder;\nVen en tu gloria, Padre bendito,\nTu semejanza quiero tener.'),(2056,331,'Estrofa',3,'Hazme valiente, fiel y benigno,\nDispuesto siempre a perdonar;\nQuiero en mi vida ser compasivo,\nFiel proclamando tu voluntad.'),(2057,331,'Coro',4,'Hazme, oh Cristo, como Tú eres,\nMi ser inunda con tu poder;\nVen en tu gloria, Padre bendito,\nTu semejanza quiero tener.'),(2058,331,'Estrofa',5,'Quiero ser dócil, manso y humilde,\nSiempre sumiso, siempre leal;\nMi ser entero gloria te rinde,\nBusca anhelante tu santidad.'),(2059,331,'Coro',6,'Hazme, oh Cristo, como Tú eres,\nMi ser inunda con tu poder;\nVen en tu gloria, Padre bendito,\nTu semejanza quiero tener.'),(2060,331,'Estrofa',7,'Hoy purifica toda mi alma\nCon fuego santo de tu altar;\nQue desarraigue todo lo malo,\nPara que Tú la puedas usar.'),(2061,331,'Coro',8,'Hazme, oh Cristo, como Tú eres,\nMi ser inunda con tu poder;\nVen en tu gloria, Padre bendito,\nTu semejanza quiero tener.'),(2062,332,'Estrofa',1,'Siervos de Jesús, hombres de verdad;\nGuardas del deber somos, sí;\nLibres de maldad, ricos en bondad;\nFieles en la lid seremos, sí;'),(2063,332,'Coro',2,'¡Firmes! ¡fuertes! alcen la bandera,\nGrande, noble emblema del deber,\n¡Pronto! ¡Bravos! pasen la consigna:\nMarchen, todos, vamos a vencer.'),(2064,332,'Estrofa',3,'¡Cuán hermosos son los que sin temor,\nListos al llamar del clarín;\nLuchan con valor, sufren sin cesar,\n¡Guardas del deber hasta el fin!.'),(2065,332,'Coro',4,'¡Firmes! ¡fuertes! alcen la bandera,\nGrande, noble emblema del deber,\n¡Pronto! ¡Bravos! pasen la consigna:\nMarchen, todos, vamos a vencer.'),(2066,332,'Estrofa',5,'Nuestro capitán es ya vencedor,\nÉl nos redimió por su cruz;\nGuardas del deber, Él nos da poder,\nÉl nos guiará hasta la luz.'),(2067,332,'Coro',6,'¡Firmes! ¡fuertes! alcen la bandera,\nGrande, noble emblema del deber,\n¡Pronto! ¡Bravos! pasen la consigna:\nMarchen, todos, vamos a vencer.'),(2068,332,'Estrofa',7,'Invencibles son los que con afán,\nCada día van al deber,\nGrande luz tendrán y recibirán,\nMagno galardón del Redentor.'),(2069,332,'Coro',8,'¡Firmes! ¡fuertes! alcen la bandera,\nGrande, noble emblema del deber,\n¡Pronto! ¡Bravos! pasen la consigna:\nMarchen, todos, vamos a vencer.'),(2070,333,'Estrofa',1,'La peña fuerte, el Santo Dios,\nNos guarda de la tempestad;\nBusquemos, pues, su protección,\nNos guarda de la tempestad.'),(2071,333,'Coro',2,'En tierra calurosa Jesús nos da,\nSu sombra, sí, su sombra, sí;\nJesús es el Peñasco que sombra da,\nNos guarda de la tempestad.'),(2072,333,'Estrofa',3,'De día templa el gran calor,\nNos guarda de la tempestad;\nDe paz, de noche en derredor,\nNos guarda de la tempestad.'),(2073,333,'Coro',4,'En tierra calurosa Jesús nos da,\nSu sombra, sí, su sombra, sí;\nJesús es el Peñasco que sombra da,\nNos guarda de la tempestad.'),(2074,333,'Estrofa',5,'Procelas surjan con furor,\nNos guarda de la tempestad;\nAlbergue ofrécenos su amor,\nNos guarda de la tempestad.'),(2075,333,'Coro',6,'En tierra calurosa Jesús nos da,\nSu sombra, sí, su sombra, sí;\nJesús es el Peñasco que sombra da,\nNos guarda de la tempestad.'),(2076,333,'Estrofa',7,'La Peña de mi corazón,\nNos guarda de la tempestad;\nEn cada amarga tentación,\nNos guarda de la tempestad.'),(2077,333,'Coro',8,'En tierra calurosa Jesús nos da,\nSu sombra, sí, su sombra, sí;\nJesús es el Peñasco que sombra da,\nNos guarda de la tempestad.'),(2078,334,'Estrofa',1,'De Cristo cada día quiero yo más cerca estar,\nEl es mi Rey amable, mi precioso Salvador;\nNo puedo en todo el mundo amigo cual Jesús hallar\nQuien maravillas hace y prodigios sin cesar.'),(2079,334,'Coro',2,'Jamás podrán contarme,\nDe Cristo la mitad;\nDe su amor divino, su poder y majestad.'),(2080,334,'Estrofa',3,'Ya miro cerca el día del regreso del Señor,\nY yo con muchos santos al encuentro sin igual;\nIremos a las nubes alabando con fervor,\nA Cristo el Rey glorioso, cuyo Reino es eternal.'),(2081,334,'Coro',4,'Jamás podrán contarme,\nDe Cristo la mitad;\nDe su amor divino, su poder y majestad.'),(2082,334,'Estrofa',5,'Y cuando estemos salvos en su Reino espiritual,\nJamás nos cansaremos de servir al Salvador;\nGozosos alzaremos nuestro cántico triunfal,\nY de arpas mil los ecos subirán en su loor.'),(2083,334,'Coro',6,'Jamás podrán contarme,\nDe Cristo la mitad;\nDe su amor divino, su poder y majestad.'),(2084,335,'Estrofa',1,'En el mundo la Iglesia,\nPeregrina ha de estar;\nAnhelante ella espera,\nSu feliz, eterno hogar.'),(2085,335,'Coro',2,'Nos veremos, nos veremos,\nNos veremos en la tierra más allá ;\nNos veremos, nos veremos,\nJunto al río cristalino más allá.'),(2086,335,'Estrofa',3,'Nada aquí es permanente,\nTodo ha de terminar;\nMas miramos adelante,\nEn el Reino nuestro hogar.'),(2087,335,'Coro',4,'Nos veremos, nos veremos,\nNos veremos en la tierra más allá ;\nNos veremos, nos veremos,\nJunto al río cristalino más allá.'),(2088,335,'Estrofa',5,'Las familias en la tierra,\nSe desunen al morir;\nMas esperan la mañana,\nEn que se han de reunir.'),(2089,335,'Coro',6,'Nos veremos, nos veremos,\nNos veremos en la tierra más allá ;\nNos veremos, nos veremos,\nJunto al río cristalino más allá.'),(2090,335,'Estrofa',7,'Con Jesús cual unos reyes,\nPronto habremos de estar;\nJuntos, miles de millares,\nCon Jesús para reinar.'),(2091,335,'Coro',8,'Nos veremos, nos veremos,\nNos veremos en la tierra más allá ;\nNos veremos, nos veremos,\nJunto al río cristalino más allá.'),(2092,336,'Estrofa',1,'Podrá no ser allí do peligros hay que hallar,\nPodrá feliz estar y en la calma aquí morar;\nMas una cosa sé, que en sombras o en placer,\nSi Él va conmigo, ¡Iré por doquier!'),(2093,336,'Coro',2,'Si Él va conmigo, yo iré por doquier,\nEl Reino estará doquiera yo esté con mi Jesús;\nEs un privilegio poder llevar su cruz,\nIré si Jesús va conmigo por doquier.'),(2094,336,'Estrofa',3,'Acaso he de llevar la palabra de salud,\nA todos los que luchan en medio de inquietud;\nMas si esto es mi deber, gozoso lo he de hacer,\nY si Él va conmigo, ¡Iré por doquier!'),(2095,336,'Coro',4,'Si Él va conmigo, yo iré por doquier,\nEl Reino estará doquiera yo esté con mi Jesús;\nEs un privilegio poder llevar su cruz,\nIré si Jesús va conmigo por doquier.'),(2096,336,'Estrofa',5,'Mas si es mi parte aquí dentro del hogar llevar\nLa cruz que muchos llevan aún más allá del mar;\nMi fe podré probar y siempre haré saber,\nQue si el va conmigo, ¡Iré por doquier!'),(2097,336,'Coro',6,'Si Él va conmigo, yo iré por doquier,\nEl Reino estará doquiera yo esté con mi Jesús;\nEs un privilegio poder llevar su cruz,\nIré si Jesús va conmigo por doquier.'),(2098,336,'Estrofa',7,'Los juicios del Señor no me toca discutir,\nMi parte es su camino constante aquí seguir;\nMas ir o aquí quedar lo puedo todo hacer,\nY si Él va conmigo, ¡Iré por doquier!'),(2099,336,'Coro',8,'Si Él va conmigo, yo iré por doquier,\nEl Reino estará doquiera yo esté con mi Jesús;\nEs un privilegio poder llevar su cruz,\nIré si Jesús va conmigo por doquier.'),(2100,337,'Estrofa',1,'Muy cercano está el día, cuando volverá Jesús,\nCon la majestad y gloria, que le dio su Padre Dios.\nDe sus santos rodeado, en la nube bajará;\nYa de Cristo es el reinado, y el pecado quitará.'),(2101,337,'Coro',2,'Ven, Señor Jesús, ven pronto,\nClaman todos con ardor;\nHe aquí yo vengo presto,\nPresto dice el Salvador.'),(2102,337,'Estrofa',3,'Su venida, Jesucristo, librará la humanidad;\nDe Satán, autor inicuo, de su gran calamidad.\nCesarán todos los males, por el Reino de Jesús;\nAlegraos, oh mortales, ¡Ved el triunfo de su cruz!'),(2103,337,'Coro',4,'Ven, Señor Jesús, ven pronto,\nClaman todos con ardor;\nHe aquí yo vengo presto,\nPresto dice el Salvador.'),(2104,337,'Estrofa',5,'Cuanto anhelan y desean, la venida de Jesús;\nLos creyentes ya salvados, por la obra de su cruz.\n“Ven y siéntate conmigo, en mi trono”, el Rey dirá:\n“Has sufrido y has vencido, de mi gloria goza ya”.'),(2105,337,'Coro',6,'Ven, Señor Jesús, ven pronto,\nClaman todos con ardor;\nHe aquí yo vengo presto,\nPresto dice el Salvador.'),(2106,338,'Estrofa',1,'Junto a la cruz do Jesús murió,\nJunto a la cruz do salud pedí;\nYa mis maldades Él perdonó,\n¡A su nombre gloria!'),(2107,338,'Coro',2,'¡A su nombre gloria!\n¡A su nombre gloria!\nYa mis maldades Él perdonó,\n¡A su nombre gloria!'),(2108,338,'Estrofa',3,'Junto a la cruz donde le busqué,\nCuán admirable perdón me dio;\nYa con Jesús siempre viviré,\n¡A su nombre gloria!'),(2109,338,'Coro',4,'¡A su nombre gloria!\n¡A su nombre gloria!\nYa mis maldades Él perdonó,\n¡A su nombre gloria!'),(2110,338,'Estrofa',5,'Fuente preciosa de salvación,\nQué grande gozo yo pude hallar;\nAl encontrar en Jesús perdón,\n¡A su nombre gloria!'),(2111,338,'Coro',6,'¡A su nombre gloria!\n¡A su nombre gloria!\nYa mis maldades Él perdonó,\n¡A su nombre gloria!'),(2112,338,'Estrofa',7,'Tú, pecador, que perdido estás,\nHoy esta fuente ven a buscar;\nPaz y perdón encontrar podrás,\n¡A su nombre gloria!'),(2113,338,'Coro',8,'¡A su nombre gloria!\n¡A su nombre gloria!\nYa mis maldades Él perdonó,\n¡A su nombre gloria!'),(2114,339,'Estrofa',1,'Canta, oh buen cristiano,\nDulce será cantar;\nHace el camino llano,\nLibra el pesar.\nCanta en las noches tristes,\nCanta en la alegre luz;\nEl mal así resistes,\nCanta de Jesús.'),(2115,339,'Estrofa',2,'Canta, oh buen cristiano,\nTempla tu corazón;\nAlza a tu Soberano,\nTu feliz canción.\nSiempre está lleno el mundo,\nDe endechas y dolor;\nCanta el amor profundo,\nDe tu Salvador.'),(2116,339,'Estrofa',3,'Canta, oh buen cristiano,\nDios tu socorro es;\nEl sostendrá tu mano,\nHasta la vejez.\n¿Sabes que el diablo invitas,\nCuando medroso estás?\nDios quitará tus cuitas,\nSi cantando vas.'),(2117,340,'Estrofa',1,'¿Has buscado la paz, sin hallarla jamás?\n¿Es intenso tu ruego al clamar?\nPaz no puedes sentir, ni por mucho gemir,\nHasta que pongas todo en su altar.'),(2118,340,'Coro',2,'¿Está tu alma completa en célico altar?\n¿Ya vives entregado a Él...?\nSólo así tú podrás disfrutar de la paz,\nEn su altar deposita tu ser.'),(2119,340,'Estrofa',3,'¿Cómo puedes vivir en maldad y sentir\nQue Jesús ha aprobado tu acción...?\nCumple su voluntad, deja toda maldad,\nEn su altar pon hoy tu corazón.'),(2120,340,'Coro',4,'¿Está tu alma completa en célico altar?\n¿Ya vives entregado a Él...?\nSólo así tú podrás disfrutar de la paz,\nEn su altar deposita tu ser.'),(2121,340,'Estrofa',5,'Tú no sabes por qué, Dios detiene el bien aún,\nAunque eleves tu ferviente prez\nHasta que en humildad, fe y sinceridad,\nTu alma toda en su altar hoy le des.'),(2122,340,'Coro',6,'¿Está tu alma completa en célico altar?\n¿Ya vives entregado a Él...?\nSólo así tú podrás disfrutar de la paz,\nEn su altar deposita tu ser.'),(2123,340,'Estrofa',7,'Disfrutar de su amor, no podrás pecador,\nNi gozar su divina amistad\nSólo que desde hoy digas: “Mi alma te doy,\nDeposito mi vida en tu altar...'),(2124,340,'Coro',8,'¿Está tu alma completa en célico altar?\n¿Ya vives entregado a Él...?\nSólo así tú podrás disfrutar de la paz,\nEn su altar deposita tu ser.'),(2125,341,'Estrofa',1,'En la cruenta cruz el Señor Jesús,\nPor mí en el Calvario se entregó;\nTanto fue el amor del buen Salvador,\nQue del alto cielo descendió.'),(2126,341,'Coro',2,'Cristo, Príncipe de gloria,\nEn la cruz por mí su vida dio;\nCristo, despreciado, herido,\nAgonía aguda soportó.\nCristo, quien fue sin pecado,\nMis pecados en la cruz llevó;\nFue por mí que el Salvador allí,\nEn la cruz me redimió.'),(2127,341,'Estrofa',3,'Cerca de la cruz del Señor Jesús,\nEl gentío le vituperó;\nPor mi salvación en su compasión,\nEl gran precio de ella allí pagó.'),(2128,341,'Coro',4,'Cristo, Príncipe de gloria,\nEn la cruz por mí su vida dio;\nCristo, despreciado, herido,\nAgonía aguda soportó.\nCristo, quien fue sin pecado,\nMis pecados en la cruz llevó;\nFue por mí que el Salvador allí,\nEn la cruz me redimió.'),(2129,342,'Estrofa',1,'Ven amigo a Jesús, pues Él murió por ti,\nRecibirás la luz que quiere dar a ti;\nMi buen Jesús murió para darte perdón,\nAbre tu corazón y dulce paz tendrás.'),(2130,342,'Coro',2,'Día fatal vendrá cuando no habrá lugar,\nLa puerta se abre hoy y tú podrás entrar;\nMas gracia ya no habrá, pues despreciaste hoy,\nAcepta, pecador, la salvación de Dios.'),(2131,342,'Estrofa',3,'Las manos del Señor se abren hoy para ti,\nVen y confía en Él y serás muy feliz;\nTus cuitas pon en Dios, pues Él las llevará,\nQuitará tu pesar por su consolación.'),(2132,342,'Coro',4,'Día fatal vendrá cuando no habrá lugar,\nLa puerta se abre hoy y tú podrás entrar;\nMas gracia ya no habrá, pues despreciaste hoy,\nAcepta, pecador, la salvación de Dios.'),(2133,343,'Estrofa',1,'Soy la triste oveja que dejó al pastor,\nYo andaba perdido cuando Él me encontró;\nCon un silbo suave, luego me llamó,\nY en sus brazos al dulce hogar me llevó.\nLas noventa y nueve dejó en el redil,\nY se fue al desierto a buscarme a mí;\nCon afán inmenso luego me llamó,\nY hallóme gimiendo de acerbo dolor,\nSe sentó a mi lado y al verme lloró.'),(2134,343,'Estrofa',2,'Ven mi triste oveja, escucha mi voz,\nNo me desconozcas, soy el buen pastor;\nVamos al rebaño do reina la paz,\nAllí donde mora mi Rey Eternal.\nSi por la fatiga no puedes andar,\nVen que entre mis brazos te puedo llevar;\nVen mi triste oveja, vamos al redil;\nQue muy tiernos pastos tengo para ti;\nConmigo por siempre tú vas a vivir.'),(2135,344,'Estrofa',1,'Vagué sediento en el pecado abrumador,\nY nada a mi alma dio satisfacción;\nMas cuando fui a la cruz de Cristo, el Salvador,\nAgua abundante halló mi corazón.'),(2136,344,'Coro',2,'Toma de la fuente de agua viva,\nFuente eternal, agua del raudal;\nToma de la fuente de agua viva,\nFuente de agua viva celestial.'),(2137,344,'Estrofa',3,'¡Oh, cuán dulce raudal de Dios brotando está!\nFelicidad y gozo me brindó;\nEn gloria, gracia y bendición mi vida irá,\nPor eso ¡Aleluya! canto yo.'),(2138,344,'Coro',4,'Toma de la fuente de agua viva,\nFuente eternal, agua del raudal;\nToma de la fuente de agua viva,\nFuente de agua viva celestial.'),(2139,344,'Estrofa',5,'¡Oh, pecador! ¿Por qué a Jesús no vienes hoy,\nY así su agua de vida aceptar?\nEl dice: “Fuente de agua eterna y libre soy,\nLa sed de tu alma puedo aplacar”.'),(2140,344,'Coro',6,'Toma de la fuente de agua viva,\nFuente eternal, agua del raudal;\nToma de la fuente de agua viva,\nFuente de agua viva celestial.'),(2141,345,'Estrofa',1,'Caminando estoy con rumbo a Sión,\nElevando a Cristo mi canción,\nYa no soy esclavo, Cristo me ha librado,\nCanto aleluya, gloria a Dios.'),(2142,345,'Coro',2,'Canto aleluya, gloria a Dios;\nCanto aleluya; gloria a Dios\nTodos mis pecados, ya son perdonados,\nCanto aleluya, gloria a Dios.'),(2143,345,'Estrofa',3,'Satanás me tienta con tesón,\nPero le resisto en oración,\nNo seré vencido por el enemigo,\nCanto aleluya, gloria a Dios.'),(2144,345,'Coro',4,'Canto aleluya, gloria a Dios;\nCanto aleluya; gloria a Dios\nTodos mis pecados, ya son perdonados,\nCanto aleluya, gloria a Dios.'),(2145,345,'Estrofa',5,'Cuando viene obscura tempestad,\nCristo pone en mi alma claridad,\nEl es mi consuelo, sigo rumbo al Reino,\nCanto aleluya, Gloria a Dios.'),(2146,345,'Coro',6,'Canto aleluya, gloria a Dios;\nCanto aleluya; gloria a Dios\nTodos mis pecados, ya son perdonados,\nCanto aleluya, gloria a Dios.'),(2147,346,'Estrofa',1,'Sólo en Jesús hay vida eterna,\nEs Él quien me da salvación;\nCristo liberta del pecado,\nY limpia mi corazón.'),(2148,346,'Coro',2,'Yo soy feliz pues de su amor disfruto,\nSeguro estoy que Él me cuidará;\nEs mi Jesús incomparable,\nCerca de Él siempre yo quiero andar.'),(2149,346,'Estrofa',3,'El me buscó con gran ternura,\nY me libertó del pecar,\nCon su paciencia y su dulzura;\nCambió el llanto por cantar.'),(2150,346,'Coro',4,'Yo soy feliz pues de su amor disfruto,\nSeguro estoy que Él me cuidará;\nEs mi Jesús incomparable,\nCerca de Él siempre yo quiero andar.'),(2151,346,'Estrofa',5,'Cristo es mi vida y mi esperanza,\nEn Él tengo felicidad;\nÉl es mi buena venturanza,\nMe rindo a su voluntad.'),(2152,346,'Coro',6,'Yo soy feliz pues de su amor disfruto,\nSeguro estoy que Él me cuidará;\nEs mi Jesús incomparable,\nCerca de Él siempre yo quiero andar.'),(2153,347,'Estrofa',1,'Mansión gloriosa tendré en el Reino,\nDo las maldades nunca entrarán:\nToda tristeza cambiará en consuelo,\nY en dulce canto el dolor y afán.'),(2154,347,'Coro',2,'Bellas mansiones habrá en la gloria,\nTendré en la mía el gozo sin par;\nSuenan las notas de la grata victoria,\nVoy, pues, con gozo a mi dulce hogar.'),(2155,347,'Estrofa',3,'En este mundo predomina el llanto,\nSomos sujetos al dolor fatal;\nMas en el Reino cesará el quebranto,\nY por los siglos nunca habrá más mal.'),(2156,347,'Coro',4,'Bellas mansiones habrá en la gloria,\nTendré en la mía el gozo sin par;\nSuenan las notas de la grata victoria,\nVoy, pues, con gozo a mi dulce hogar.'),(2157,347,'Estrofa',5,'Amigo mío, cuanto anhelo yo verte,\nLibre de penas y de turbación;\nA Jesucristo debes ya entregarte,\nTendrás también una bella mansión.'),(2158,347,'Coro',6,'Bellas mansiones habrá en la gloria,\nTendré en la mía el gozo sin par;\nSuenan las notas de la grata victoria,\nVoy, pues, con gozo a mi dulce hogar.'),(2159,348,'Estrofa',1,'El día perfecto pronto llegará,\nEl día de paz, sin penas ni dolor,\nTraerá el gozo que deseamos hoy,\nNingún dolor podrá allí entrar.'),(2160,348,'Coro',2,'Adiós a pruebas al rayar el alba,\nAdiós a toda aflicción aquí;\nNo habrá dolor, ni muerte en ese día,\nSombras desaparecerán allí.'),(2161,348,'Estrofa',3,'Confía en Dios, Él siempre te guiará,\nHacia el día que aclarando está;\nSíguele fiel que pronto Él vendrá,\nY a su imagen Él nos cambiará'),(2162,348,'Coro',4,'Adiós a pruebas al rayar el alba,\nAdiós a toda aflicción aquí;\nNo habrá dolor, ni muerte en ese día,\nSombras desaparecerán allí.'),(2163,349,'Estrofa',1,'Nuestras plegarias a Ti elevamos,\nOh, Dios del cielo, nuestro Hacedor.'),(2164,349,'Coro',2,'Oye, oh Padre oye a tu guardia;\nHoy de rodillas, en oración.'),(2165,349,'Estrofa',3,'En este día por Ti bendito,\nTe lo pedimos todos tus hijos.'),(2166,349,'Coro',4,'Oye, oh Padre oye a tu guardia;\nHoy de rodillas, en oración.'),(2167,349,'Estrofa',5,'Te lo rogamos en ese nombre,\nPerfecto y bello de Jesucristo.'),(2168,349,'Coro',6,'Oye, oh Padre oye a tu guardia;\nHoy de rodillas, en oración.'),(2169,349,'Estrofa',7,'Tú hoy nos oyes, así confiamos,\nClemente y bueno Dios de Israel.'),(2170,349,'Coro',8,'Oye, oh Padre oye a tu guardia;\nHoy de rodillas, en oración.'),(2171,350,'Estrofa',1,'¡Oh, valientes ingresad! a las filas del Señor,\nPara ir a combatir, Apollyón, Abaddón.\nAirado él estará, como un león te rugirá;\nMas confía en esto tú... Dios te guiará.'),(2172,350,'Estrofa',2,'Con honor, obreros sed, portavoces del Señor,\nY con gozo pregonad la salud de Israel;\nBella y dura es la misión, Satanás te tentará,\nPero si en Cristo estás, nada temerás.'),(2173,350,'Estrofa',3,'Alma y mente tú pondrás al servicio del Señor,\nY todo tu corazón, a servir a Jesús.\nHermosos serán tus pies, cuando lleves el maná,\nDel pasado que hoy es nuestro buen Jesús.'),(2174,350,'Estrofa',4,'Con integridad servid, al que ha sido y que será,\nPor los siglos Gran Señor, desde allá de la Creación.\nAl final oirás su voz, que con gozo te dirá:\n“En lo poco fuiste fiel, entra al gozo hoy”.'),(2175,351,'Estrofa',1,'¡Oh, mi Señor!, a Ti que tanto amo,\nElevo hoy, mi alma y corazón;\nMira mi aflicción y congoja,\nTennos piedad, clamamos hoy a Ti.\nConfiamos en lo que dijera ayer,\nTu Hijo, nuestro amante Salvador:\n“En mi nombre pedid, todo a mi Padre,\nSeguridad tened, que os lo dará”.'),(2176,351,'Estrofa',2,'Yo sé que Tú a cada uno oyes,\nY nos darás según tu voluntad,\nLo que en secreto está, Tú ya lo sabes,\nEn público, Tú recompensarás,\nA todo aquel que listo esté a guardar\nTus Mandamientos, la Ley Eterna,\nLey que grabada fue, en unas tablas,\nY ahora está en nuestro corazón.'),(2177,351,'Estrofa',3,'¡Oh, mi Señor!, a Ti, que tanto amo,\nMi alma toda en tu altar pondré;\nYo sé que Tú verás todas mis faltas,\nY por tu amor, me las perdonarás.\nPostrados ante el trono de tu amor,\nTocamos hoy con todo el corazón,\nCreyendo que oirás, ¡Oh!, para darnos,\nA cada uno de tu gran bondad.'),(2178,351,'Estrofa',4,'Sentir queremos, ese grande gozo,\nQue oirás y así contestarás;\nSostén tu Iglesia, si, firme y segura,\nEn contra de los dardos del pecar.\nAfirma a tu pequeña juventud,\nY a los hijos de toda la Grey,\nPara poder gozar de aquel Reino,\nQue en esta tierra, tu Hijo fundará.'),(2179,352,'Estrofa',1,'Eran cien ovejas que había en el rebaño;\nEran cien ovejas que amante cuidó,\nPero en una tarde, al contarlas todas,\nLe faltaba una, le faltaba una\nY se entristeció.'),(2180,352,'Coro',2,'Las noventa y nueve dejó en el desierto,\nY por la montaña a buscarla fue,\nLa encontró gimiendo, temblando de frío,\nUngió sus heridas, y con ella en hombros,\nGozoso volvió.'),(2181,352,'Estrofa',3,'Esta misma historia, vuelve a repetirse:\nTodavía hay ovejas que errabundas van\nVagando en el mundo, sin Dios, sin consuelo,\nSin Dios, sin consuelo, sin Dios, sin consuelo,\nY sin su perdón.'),(2182,352,'Coro',4,'Las noventa y nueve dejó en el desierto,\nY por la montaña a buscarla fue,\nLa encontró gimiendo, temblando de frío,\nUngió sus heridas, y con ella en hombros,\nGozoso volvió.'),(2183,353,'Estrofa',1,'Como el siervo brama junto al agua\nAsí clamaré por Ti, oh mi Dios;\nPorque en Ti sacio mi sed,\nY de Ti marcharé siempre en pos.'),(2184,353,'Coro',2,'Clamo yo, Señor, en mis temores,\nClamo yo siempre saliendo estoy;\nY Señor, en oración he de pedirte,\nMe ayudes para no caer.'),(2185,353,'Estrofa',3,'Y si el mundo me rechaza por seguirte,\nEntonces con más fuerzas clamaré:\nDame paz, dame amor, dame consuelo,\nDame fe y también tu bendición.'),(2186,353,'Coro',4,'Clamo yo, Señor, en mis temores,\nClamo yo siempre saliendo estoy;\nY Señor, en oración he de pedirte,\nMe ayudes para no caer.'),(2187,354,'Estrofa',1,'Oye Israel,, Dios te dice así:\n“Por ser tan rebelde, Yo te esparcí”.\nDios te habló a ti, Profetas envió,\nQue también dijeron:,”A Jehová oíd”.'),(2188,354,'Estrofa',2,'Como los polluelos, te quiso juntar,\nEl varón perfecto, y digno de amar.\nMas con grande saña, uniste tu voz,\nDiciendo a Pilato:, “Crucifica a Jesús”.'),(2189,354,'Estrofa',3,'Mas un pacto hay, promesa a David,\nY Dios, que no es hombre, no puede mentir.\nSu nombre selló, el Pacto de ayer,\nY cumplido el tiempo, te va recoger.'),(2190,354,'Estrofa',4,'Mas en ese día, te convertirás,\nCuando a Jesucristo, enfrente tendrás.\nY verán tus ojos, que aquel Emmanuel,\nEs el Hijo amado, del Dios de Israel.'),(2191,354,'Estrofa',5,'Verán en sus pies, y en sus manos también,\nLa huella innegable de crucifixión;\nEse día habrá, llanto sobre Él,\nQuitaraste el velo, oh, pueblo de Israel.'),(2192,354,'Estrofa',6,'Le dirás, entonces: “¿Por qué herido estás?”\n“Son por mis amigos que vine a salvar”.\nY en su regazo feliz estarás,\nCuando allí su Reino fundado será.'),(2193,355,'Estrofa',1,'Yo soy obrero de mi Cristo, y listo debo estar,\nPara cumplir las misiones a que se me ha de enviar.\nYo soy obrero de mi Cristo, de la Iglesia de Dios;\nYo iré, iré predicando las nuevas de Israel.\nYo iré, yo iré, y así esparciré,\nDe Dios la salvación que en Cristo Él dejó.'),(2194,355,'Estrofa',2,'Yo espero que con la ayuda, y el gran poder de Dios,\nPoder sembrar su palabra en tierra buena y fértil.\nY que lleven mucho fruto, a uno, ciento y mil,\nPara que puedan gozarse con Cristo en el redil.\nYo iré, yo ire al campo a predicar,\nNarrando a la nación, el plan de salvación.'),(2195,355,'Estrofa',3,'Iré cumpliendo el mandato de nuestro Dios Jesús,\nDe ir, de ir predicando como lo hiciera Él.\nIré, ¡oh, sí, muy gozoso! y así espero venir.\nJehová verá por mis pasos, mi entrada y mi salir.\nYo voy, yo iré confiando en Ti, Señor;\nLa obra es de Ti, en Cristo, mi Señor.'),(2196,356,'Estrofa',1,'Divino compañero del camino,\nTu presencia siento yo, al transitar,\nHe ya disipado de las sombras,\nYa tengo luz, la luz bendita\nDe tu amor.'),(2197,356,'Coro',2,'Quédate Señor, ya se hace tarde,\nTe ofrezco el corazón para posar;\nHazlo tu morada permanente,\nAcéptalo, acéptalo, mi Salvador.'),(2198,356,'Estrofa',3,'La sombra de la noche se aproxima\nY en ella el tentador acechará;\nNo, no me dejes solo en el camino,\nAyúdame, ayúdame hasta el llegar.'),(2199,356,'Coro',4,'Quédate Señor, ya se hace tarde,\nTe ofrezco el corazón para posar;\nHazlo tu morada permanente,\nAcéptalo, acéptalo, mi Salvador.'),(2200,357,'Estrofa',1,'Venid, cristianos muy alegres,\nEl culto empieza ya;\nPensad que muchos son los campos,\n¡Oh!, ídlos a sembrar.'),(2201,357,'Coro',2,'Aquellos que han dicho: “Heme aquí”,\nAl Señor servirán;\nSe irán, ¡oh, si!, ungidos,\nUngidos del Espíritu.\nHablarán y nada temerán,\nBuenas nuevas llevarán;\n//Hablarán con toda gran verdad,\nEl Evangelio de Dios//'),(2202,357,'Estrofa',3,'Predicando a todo abatido,\nA quebrantados a vendar;\nLibrando a todo abatido,\nY al preso libertad.'),(2203,357,'Coro',4,'Aquellos que han dicho: “Heme aquí”,\nAl Señor servirán;\nSe irán, ¡oh, si!, ungidos,\nUngidos del Espíritu.\nHablarán y nada temerán,\nBuenas nuevas llevarán;\n//Hablarán con toda gran verdad,\nEl Evangelio de Dios//'),(2204,357,'Estrofa',5,'Predicando el año de la buena\nVoluntad del Señor,\nDía de grande venganza,\nDe nuestro Dios Jehová.'),(2205,357,'Coro',6,'Aquellos que han dicho: “Heme aquí”,\nAl Señor servirán;\nSe irán, ¡oh, si!, ungidos,\nUngidos del Espíritu.\nHablarán y nada temerán,\nBuenas nuevas llevarán;\n//Hablarán con toda gran verdad,\nEl Evangelio de Dios//'),(2206,357,'Estrofa',7,'A consolar todos con gozo,\nEn donde luto habrá;\nSabiendo que en aquel Reino,\nTu premio Él te dará.'),(2207,357,'Coro',8,'Aquellos que han dicho: “Heme aquí”,\nAl Señor servirán;\nSe irán, ¡oh, si!, ungidos,\nUngidos del Espíritu.\nHablarán y nada temerán,\nBuenas nuevas llevarán;\n//Hablarán con toda gran verdad,\nEl Evangelio de Dios//'),(2208,358,'Estrofa',1,'Gloria a Dios, Gloria a Dios,\nGloria al Hijo,\nGloria al Hijo, amén,\nAmén, amén.'),(2209,358,'Estrofa',2,'Nuestras voces al cantar,\nElevamos a tu altar;\n//Como el cántico de Moisés,\nPara el que vive y por siempre es.//'),(2210,358,'Estrofa',3,'Es tu pueblo de Israel,\nQue Tú amaste, oh Jehová.\n//El Israel espiritual,\nHoy reunido en la fe de Emmanuel.//'),(2211,358,'Estrofa',4,'Promesas diste a Abraham,\nA Jacob e Isaac.\n//Promesas que cumplirás,\nAl que te busca con integridad.//'),(2212,358,'Estrofa',5,'Digno eres, oh Señor,\nDe todo honor, honra y gloria,\n//Ahora y siempre y por los siglos,\nDe los siglos, amén.//'),(2213,359,'Estrofa',1,'Cristo es la Peña de Horeb, que está brotando,\nAgua de vida saludable para Ti.\nCristo es la Peña de Horeb, que está brotando,\nAgua de vida saludable para Ti.\nVen, a tomarla que es más dulce que la miel;\nRefresca el alma, refresca todo tu ser.\nCristo es la Peña de Horeb, que está brotando,\nAgua de vida saludable para Ti.'),(2214,359,'Estrofa',2,'Cristo es el lirio del valle de las flores,\nÉl es la Rosa blanca y pura de Sarón.\nCristo es la vida y amor de los amores,\nÉl es la eterna fuente de la salvación.\nVen a buscarla en tu triste condición.\nRefresca el alma, refresca todo tu ser.\nCristo es el lirio del valle de las flores,\nÉl es la Rosa blanca y pura de Sarón.'),(2215,360,'Estrofa',1,'Nuevamente tu bondad, nos une, Señor, aquí;\nTodos llenos de emoción y una sola comunión.\nDeseamos que Tú estés, del principio hasta el final,\nY esperamos recibir una rica bendición.'),(2216,360,'Estrofa',2,'Señor, si es tu bondad, líbranos de todo mal\nY aquí reine tu paz en esta tu reunión.\nVelaremos por cumplir, aunque dura es esta lid,\nPues las obras de Satán trataremos de abolir.'),(2217,360,'Estrofa',3,'Como un león camina él, tras tu obra y de tu grey;\nCúbrenos, oh gran Señor, con tus alas de bondad.\nGrande es la necesidad de ver juntos y hacer\nGrandes cosas, oh Jehová, para salvar a tu grey.'),(2218,360,'Estrofa',4,'Tú muy pronto ya vendrás, las señales claras son,\nY cuentas Tú nos pedirás de tus hijos, oh Señor.\nPoco tiempo queda ya y mucho lo que hay que hacer,\nPuesta en Ti toda fe, guíanos para vencer.'),(2219,361,'Estrofa',1,'¡Oh, Jerusalem!, a Egipto serviste,\nAdoraste tú a un falso dios;\nSaliste de allí con grande victoria,\nCuando al Dios Jehová tú reconociste.'),(2220,361,'Coro',2,'Jerusalem, ciudad del Rey,\nOye la voz de tu Creador;\nÉl te ama, sí, y te reunirá,\nPues sólo el Señor es tu Salvador.'),(2221,361,'Estrofa',3,'Pudiste observar las profecías,\nLástima por ti, no confiaste en Él;\nLe viste crecer y no lo creíste,\nQue el que te habló era el Mesías.'),(2222,361,'Coro',4,'Jerusalem, ciudad del Rey,\nOye la voz de tu Creador;\nÉl te ama, sí, y te reunirá,\nPues sólo el Señor es tu Salvador.'),(2223,361,'Estrofa',5,'¡Oh, Jerusalem!, que destruida fuiste,\nNo quisiste oír cuando Él te avisó;\nTe profetizó en sus lamentos,\nY aún así la muerte le diste.'),(2224,361,'Coro',6,'Jerusalem, ciudad del Rey,\nOye la voz de tu Creador;\nÉl te ama, sí, y te reunirá,\nPues sólo el Señor es tu Salvador.'),(2225,361,'Estrofa',7,'¡Oh, Jerusalem!, fuiste esparcida,\nY pagar así la incredulidad;\nPero el tiempo ya casi es cumplido\nY Jehová dice: “Serás reunida”.'),(2226,361,'Coro',8,'Jerusalem, ciudad del Rey,\nOye la voz de tu Creador;\nÉl te ama, sí, y te reunirá,\nPues sólo el Señor es tu Salvador.'),(2227,362,'Estrofa',1,'Cristo me halló errante y peregrino,\nEl me encontró hundido en el error;\nEl transformó mi vida y mi destino,\nGloría a su nombre por ese sublime amor.'),(2228,362,'Coro',2,'Yo quiero amarle porque Él salvó mi alma,\nQuiero entregarle todo mi corazón;\nEl me guiará con tierna y dulce calma,\nY para siempre me dará su protección.'),(2229,362,'Estrofa',3,'Vagaba yo por sendas peligrosas\nY sin saber que ofendí a Dios,\nEl extendió su mano milagrosa,\nMe dio su gracia cuando oí su tierna voz.'),(2230,362,'Coro',4,'Yo quiero amarle porque Él salvó mi alma,\nQuiero entregarle todo mi corazón;\nEl me guiará con tierna y dulce calma,\nY para siempre me dará su protección.'),(2231,363,'Estrofa',1,'Cuando tentado yo he deseado\nSaber por qué hay muchos aquí,\nQue andan sin pruebas y sin cuidados,\nMientras el mal me hace luchar aquí,\nEntenderemos nuestras angustias,\nEntenderemos nuestro pesar;\nHermano mío, nunca desmayes,\nTodo en el Reino se ha de aclarar.'),(2232,363,'Estrofa',2,'Hasta la muerte, dijo el Maestro,\nSerás tú fiel y trabajarás;\nHermano mío, nunca desmayes,\nTodo en el Reino se ha de aclarar;\nEntenderemos nuestras angustias,\nEntenderemos nuestro pesar;\nHermano mío, nunca desmayes,\nTodo en el Reino se ha de aclarar.'),(2233,364,'Estrofa',1,'Dios de los cielos, Mi Dios Jehová;\nEl sol se oculta, Tu día se va;\nNuestras angustias y todo pesar,\nDepositamos en Ti, Señor;\nOye, te ruego, oye Señor,\nY no dilates tu contestar.'),(2234,364,'Estrofa',2,'Benditos son tus hijos que\nTú sábado pueden guardar,\nY darte honra, gloria y loor,\nDesde el principio hasta el final;\nRecuerda aquellos que aún están\nBajo las manos de faraón;\nY en sus luchas mira, Señor,\nTu día guardan en su corazón.'),(2235,364,'Estrofa',3,'Otra semana empieza hoy,\nPara vivirla o para morir;\nSólo Tú sabes que pasará,\nSi es por tu causa gozo será.\nMuchos enfermos y viudas hay,\nQue reunidos aquí no están;\nY donde quiera que hoy estén;\nTu bendición dales, Señor.'),(2236,364,'Estrofa',4,'Tu Iglesia hoy que cae el sol,\nGracias te da, oh buen Señor;\nTu día santo vemos pasar,\nY si vivimos es por su amor;\nNos retiramos de este lugar,\nPero sí, nunca jamás de Ti,\nY haz que con gozo volvamos a estar,\nEn otro sábado muy junto a Ti.'),(2237,365,'Estrofa',1,'Seis días de trabajo, seis días de labor;\nSeis días en el mundo, Egipto espiritual;\nSeis días en angustias, y uno para Dios;\nTienes que obedecer y amar, el día del Señor.'),(2238,365,'Estrofa',2,'Domingo no lo es, lunes y martes, no;\nMiércoles y jueves, tampoco lo serán;\nEl viernes sí empieza, pero al atardecer;\nTienes que obedecer y amar, el día del Señor.'),(2239,365,'Estrofa',3,'El sábado es emblema, desde la creación;\nGrabado en unas tablas, allá en el Sinaí.\nSeñal eterna y santa, para el pueblo de Dios;\nTienes que obedecer y amar, el día del Señor.'),(2240,365,'Estrofa',4,'El cuarto mandamiento, no debes evadir;\nSeñal y ejemplo tienes, pues Dios lo descansó,\nDespués de los seis días, de bella creación;\nTienes que obedecer y amar, el día del Señor.'),(2241,365,'Estrofa',5,'También te dijo así: “Guardadlo si me amáis”;\nFue hecho por tu causa, para tu salvación;\nJehová lo descansó, Cristo no lo abolió;\nSí, Cristo lo guardaba, sí... También lo guardo yo.'),(2242,366,'Estrofa',1,'Verso 7 Alzad, oh puertas, vuestras cabezas,\ny alzaos vosotras, puertas eternas,\ny entrará el Rey de gloria,\ny entrará el Rey de gloria.'),(2243,366,'Estrofa',2,'Verso 8 ¿Quién es este Rey de gloria?\n¿Quién es este Rey de gloria?\nJehová, el fuerte y valiente,\nJehová , el fuerte y valiente,\nEl poderoso en batalla.'),(2244,366,'Estrofa',3,'Verso 9 Alzad, oh puertas, vuestras cabezas,\nY alzaos vosotras, puertas eternas,\nY entrará el Rey de gloria,\nY entrará el Rey de gloria.'),(2245,366,'Estrofa',4,'Verso 10 ¿Quién es este Rey de gloria?\n¿Quién es este Rey de gloria?\nJehová de los ejércitos,\nJehová de los ejércitos,\nÉl es el Rey de la gloria.'),(2246,367,'Estrofa',1,'Los obreros del Señor,\nSe reúnen hoy aquí;\nPara ir a esparcir,\nEl evangelio de Dios.'),(2247,367,'Coro',2,'Obreros, sí, obreros,\nEn la viña del Señor;\nObreros todos digan:\n“Heme aquí yo iré Señor,\n//A salvar, a salvar,\nLas almas que engañó Satán”//'),(2248,367,'Estrofa',3,'Santidad hay que tener\nEn la obra del Señor,\nY verás, al predicar,\nSus bendiciones y amor.'),(2249,367,'Coro',4,'Obreros, sí, obreros,\nEn la viña del Señor;\nObreros todos digan:\n“Heme aquí yo iré Señor,\n//A salvar, a salvar,\nLas almas que engañó Satán”//'),(2250,367,'Estrofa',5,'Él tus labios usará,\nY tu mente guiará,\nCuando con integridad,\nLe digas: “Tuyo soy”.'),(2251,367,'Coro',6,'Obreros, sí, obreros,\nEn la viña del Señor;\nObreros todos digan:\n“Heme aquí yo iré Señor,\n//A salvar, a salvar,\nLas almas que engañó Satán”//'),(2252,368,'Estrofa',1,'En Jesús mi Señor encontré dulce paz,\nEn Jesús, quien por mí se entregó;\nSi acudieres a Él, este don tú tendrás,\nVe que a nadie jamás rechazó.'),(2253,368,'Coro',2,'Sublime don, don sin igual,\nSolamente Él podrá conceder;\nEs un rayo de luz, de su luz celestial,\nQue en nosotros Él quiere encender.'),(2254,368,'Estrofa',3,'En Jesús encontré inefable perdón,\nCuando a Él suplicante acudí;\nEn amor encendió mi falaz corazón,\nY por Él nueva fe recibí.'),(2255,368,'Coro',4,'Sublime don, don sin igual,\nSolamente Él podrá conceder;\nEs un rayo de luz, de su luz celestial,\nQue en nosotros Él quiere encender.'),(2256,368,'Estrofa',5,'En Jesús nueva vida tendrás, pecador,\nSin tardanza dirígete a Él;\nEn tu pecho pondrá nueva fe, nuevo amor,\nY después siempre sírvele fiel.'),(2257,368,'Coro',6,'Sublime don, don sin igual,\nSolamente Él podrá conceder;\nEs un rayo de luz, de su luz celestial,\nQue en nosotros Él quiere encender.'),(2258,369,'Estrofa',1,'Por la mañana yo dirijo mi alabanza\nA Dios, que ha sido y es mi única esperanza.\nPor la mañana yo le invoco con el alma,\nY le suplico que me dé su dulce calma.\nY Él nos escucha, pues nos ama tanto,\nY nos alivia de cualquier quebranto.\nNos da su mano, poderosa y fuerte,\nPara librarnos de la misma muerte.'),(2259,369,'Estrofa',2,'Cuando la noche se aproxima, tenebrosa,\nEn elevar mi oración mi alma se goza;\nSiento su paz inagotable, dulce y grata,\nPorque temor y ansiedad, Cristo los mata.\nTambién elevo mi cantar al cielo,\nCuando a la tierra baja negro velo.\nEl sol se oculta, pero queda Cristo,\nA quien mis ojos por la fe han visto.'),(2260,369,'Estrofa',3,'Brilla su lumbre bienhechora mientras duermo;\nPone su mano sobre mí si estoy enfermo.\nMe fortalece, me alienta con el sueño,\nPues es mi Dios, mi Redentor y Él es mi dueño.\nY al despertar por la mañana siento\nQue Dios invade mi alma y pensamiento;\nVeo a Jesús, mi redentor amado,\nPor mi pecado en una cruz clavado.'),(2261,369,'Estrofa',4,'Veo la sangre de sus manos que ha brotado;\nVeo la sangre borbotando en su costado;\nUna corona con espinas en su frente,\nLa multitud escarneciéndole insolente.\n//Pero, ¡Qué dicha cuando al Cielo sube,\nLleno de gloria en majestuosa nube!//'),(2262,370,'Estrofa',1,'¡Oh!, Santa Cena que Cristo hiciera,\nCon sus discípulos Él celebró,\nDando su Cuerpo por pan divino,\nTambién su sangre cual puro vino.'),(2263,370,'Estrofa',2,'El que tomare la Santa Cena\nIndignamente, culpable es,\nY juicio come y para siempre,\nNo discerniendo el Cuerpo del Señor.'),(2264,370,'Estrofa',3,'Así, cada uno examinándose,\nComan y beban de este manjar;\nY toda vez que hicieres esto\nLa muerte de Cristo anunciarás.'),(2265,370,'Estrofa',4,'Todos sentados junto a la mesa,\nCristo bendijo, partiendo el pan:\n“Coman de esto que es mi cuerpo,\nQue por vosotros partido es”.'),(2266,370,'Estrofa',5,'Así también hay bendiciones,\nTomando el vaso les enseño:\n“Beban de esto que es mi sangre,\nLa cual por muchos derramaré”.'),(2267,371,'Estrofa',1,'Nada sé sobre el futuro,\nDesconozco lo que habrá;\nEs probable que las nubes\nMi luz vengan a opacar.\nNada temo del futuro,\nPues Jesús conmigo va,\nY hoy le pido decidido,\nPues Él sabe lo que habrá.'),(2268,371,'Coro',2,'Muchas cosas no comprendo,\nEl mañana con su afán;\nMas un dulce amigo tengo,\nQue mi mano sostendrá.'),(2269,371,'Estrofa',3,'Nada sé sobre el futuro,\nDesconozco lo que habrá;\nMas Él cuida de las aves,\nÉl también me cuidará.\nY al andar por mi camino,\nEn la prueba tempestad,\nSé que Cristo irá conmigo,\nSé que guarda su bondad.'),(2270,371,'Coro',4,'Muchas cosas no comprendo,\nEl mañana con su afán;\nMas un dulce amigo tengo,\nQue mi mano sostendrá.'),(2271,372,'Estrofa',1,'Has llegado a la Iglesia de Dios,\nte diré lo que debes saber;\nOtra igual en el mundo no hay.\nno la busques, no la encontrarás.\n¡Oh!,escucha y ponme cuidado,\nporque fue especial su comienzo;\nFue Jesús quien la inició\ncuando llamó a su apostolado.'),(2272,372,'Estrofa',2,'Caminando Jesús junto al mar,\nencontró y vio a dos hermanos;\nLa Iglesia así comenzó cuando\nÉl les extendió la mano.\nSimón Pedro y Andrés son sus nombres,\nque aquel llamado obedecen\nDe “Venid en pos de mí,\nY os haré pescadores de hombres”.'),(2273,372,'Estrofa',3,'Tú bien sabes que a doce llamó,\nY entre ellos uno era traidor,\nQue vendiendo al Señor Jesús\nConvirtióse en un vil pecador;\nPero debes sentirte dichoso,\nPues la sangre de Cristo nos salva;\nAsí fue el amor de Jehová,\nComo todo, un Padre amoroso.'),(2274,372,'Estrofa',4,'La Iglesia nació en Israel,\nUn principio que debe alegrarte,\nY lo debes de agradecer\nA su fundador, Emmanuel.\nEs la Iglesia pura y sincera,\nQue cual novia en promesa se encuentra,\nPorque sabe que bodas tendrá,\nCuando venga por ella el cordero.'),(2275,373,'Estrofa',1,'Gozo hay en el cielo, gozo hay hoy aquí;\nTus pecados lavados son, pues al mundo dices adiós,\nPor seguir a Cristo Jesús.'),(2276,373,'Coro',2,'Gozo, gozo, gozo da; el pecador\nque se arrepiente, en el cielo gozo da,\nGozo, gozo, gozo da.'),(2277,373,'Estrofa',3,'Gozo hay en el cielo, el Señor feliz te verá,\nÉl ha visto tu decisión de entregarle todo tu ser\nY sus leyes a obedecer.'),(2278,373,'Coro',4,'Gozo, gozo, gozo da; el pecador\nque se arrepiente, en el cielo gozo da,\nGozo, gozo, gozo da.'),(2279,373,'Estrofa',5,'Gozo hay en el cielo, gozo hay hoy aquí;\nAl desierto tú entrarás, la serpiente te morderá,\nMas con Cristo tú vencerás.'),(2280,373,'Coro',6,'Gozo, gozo, gozo da; el pecador\nque se arrepiente, en el cielo gozo da,\nGozo, gozo, gozo da.'),(2281,373,'Estrofa',7,'Gozo hay en el cielo, gozo hay hoy aquí;\nEn el Reino tú lo tendrás, cuando Cristo te diga así:\n“De mi Padre bendito ven”.'),(2282,373,'Coro',8,'Gozo, gozo, en el cielo hay,\nY nosotros nos gozamos;\nToda la Iglesia de Dios,\nCielos y Tierra, gozosos están.'),(2283,374,'Estrofa',1,'Meditar en Jesús ha de ser mi afán,\nSu bondad hacia el pobre pecador;\nÉl ganó para mí un Reino eternal,\nEn la cruz, do mostróme su amor.'),(2284,374,'Coro',2,'Ven, ven, buen Jesús;\nMora en mi corazón,\nLléname de santidad;\nJesús, contigo deseo andar.'),(2285,374,'Estrofa',3,'Consultar a Jesús ha de ser mi afán,\nY Jesús me dará fuerza y poder;\nSin Jesús, y por mí nada quiero practicar,\nMis acciones inspire Jesús.'),(2286,374,'Coro',4,'Ven, ven, buen Jesús;\nMora en mi corazón,\nLléname de santidad;\nJesús, contigo deseo andar.'),(2287,374,'Estrofa',5,'Predicar a Jesús ha de ser mi afán,\nY Jesús me dará fuerza y poder;\nSin Jesús y su amor es vano trabajar,\nDe Jesús en la cruz hablaré.'),(2288,374,'Coro',6,'Ven, ven, buen Jesús;\nMora en mi corazón,\nLléname de santidad;\nJesús, contigo deseo andar.'),(2289,374,'Estrofa',7,'Imitar a Jesús ha de ser mi afán,\nEn Jesús quiero mi dechado ver.\nSin mirar a Jesús nada bueno puedo hacer,\nY mirando a Jesús todo es bien.'),(2290,374,'Coro',8,'Ven, ven, buen Jesús;\nMora en mi corazón,\nLléname de santidad;\nJesús, contigo deseo andar.'),(2291,375,'Estrofa',1,'Cuando yo me torne otra vez al polvo\nDonde fui tomado por nuestro Señor,\nQuedará mi cuerpo en una porción,\nEsperando el día de la resurrección.'),(2292,375,'Estrofa',2,'Ya mi cuerpo muerto, ya no siente nada,\nMis oídos no oyen, ni mis ojos ven;\nNi mis labios hablan, ni mis manos palpan,\nY mis pies no andan sobre la maldad.'),(2293,375,'Estrofa',3,'Tengo la esperanza de ir a gozar\nDe la gran promesa de nuestro Señor;\nLa segunda muerte no la sufriré,\nPorque voy con Cristo, nuestro Salvador.'),(2294,376,'Estrofa',1,'Arrolladas las neblinas, A la vista el esplendor\nDe las sierras y los ríos A la luz y amor del sol;\nDel Señor el arco viendo De promesas la señal,\nCon amigos verdaderos Gozaremos claridad.'),(2295,376,'Coro',2,'Como nos conocerán, Llegaremos a tener\nPleno y recto entendimiento,\nPaz, tranquilidad, y placer;\nJustamente juzgaremos,\nSin las nieblas del ayer.'),(2296,376,'Estrofa',3,'Caminar atribulados contemplando el porvenir,\nEs sombrío, duro y largo, en la soledad sufrir;\nMas la voz “Venid benditos” a las penas fin pondrá,\nY con Cristo reunidos gozaremos claridad.'),(2297,376,'Coro',4,'Como nos conocerán, Llegaremos a tener\nPleno y recto entendimiento,\nPaz, tranquilidad, y placer;\nJustamente juzgaremos,\nSin las nieblas del ayer.'),(2298,376,'Estrofa',5,'Todos dicha rebosando, del gran solio en derredor,\nEntre amantes, entre amados, tendrán santa\ncomprensión.\nDo los redimidos cantan su rescate sin cesar,\nUna vez llegado el Reino, gozaremos claridad.'),(2299,376,'Coro',6,'Como nos conocerán, Llegaremos a tener\nPleno y recto entendimiento,\nPaz, tranquilidad, y placer;\nJustamente juzgaremos,\nSin las nieblas del ayer.'),(2300,377,'Estrofa',1,'Nada puede ya faltarme, porque Dios mis pasos guía\nA la tierra saludable, en diversos frutos rica.\nDulce néctar de reposo son sus aguas cristalinas;\nEllas dan salud al alma y la llenan de delicias.'),(2301,377,'Estrofa',2,'Por la senda me conduce de su ley con mano pía,\nEn amor a su gran nombre, fuente viva de justicia.\nCuando el tenebroso valle cruce de la muerte fría,\nNo tendré temor alguno, siendo Dios el que me guía'),(2302,377,'Estrofa',3,'Con su vara y su callado me dará consuelo y vida,\nY ante los que me persiguen, mesa me pondrá surtida.\nCon el bálsamo divino mi cabeza aromatiza,\nY rebosa ya la copa que me colma de alegría.'),(2303,377,'Estrofa',4,'La misericordia santa seguirá la senda mía,\nY de Dios sus bendiciones gozaré todos los días.\nNada puede ya faltarme, porque Dios mis pasos guía\nA la tierra saludable, en diversos frutos rica.'),(2304,378,'Estrofa',1,'Dios nos ha dado promesa:\n“Lluvias de gracia enviaré,\nDones que os den fortaleza,\nBendición grande os daré”.'),(2305,378,'Coro',2,'Lluvias de gracia,\nLluvias pedimos, Señor;\nMándanos lluvias copiosas,\nLluvias del consolador.'),(2306,378,'Estrofa',3,'Cristo nos dio la promesa\nDel Santo Consolador,\nPaz, perdón y pureza,\nPara su gloria y honor.'),(2307,378,'Coro',4,'Lluvias de gracia,\nLluvias pedimos, Señor;\nMándanos lluvias copiosas,\nLluvias del consolador.'),(2308,378,'Estrofa',5,'Dios nuestro, a todos tus hijos\nMuestra tu amor y poder;\nTú eres de gracia la fuente,\nLlena de paz nuestro ser.'),(2309,378,'Coro',6,'Lluvias de gracia,\nLluvias pedimos, Señor;\nMándanos lluvias copiosas,\nLluvias del consolador.'),(2310,378,'Estrofa',7,'Obra en tus siervos piadosos\nCelo, virtud y valor;\nDel tentador victoriosos\nSalgan contigo, Señor.'),(2311,378,'Coro',8,'Lluvias de gracia,\nLluvias pedimos, Señor;\nMándanos lluvias copiosas,\nLluvias del consolador.'),(2312,379,'Estrofa',1,'Dicha grande es la del hombre cuyas sendas rectas son,\nLejos de los pecadores, lejos de la tentación.\nA los malos consejeros deja, porque teme el mal;\nHuye de la burladora gente, impía e inmoral.'),(2313,379,'Estrofa',2,'Antes en la ley divina cifra su mayor placer,\nMeditando día y noche, en su divinal saber.\nEste, como el árbol verde, Bien regado, y en sazón,\nFrutos abundantes rinde, y hojas que perennes son.'),(2314,379,'Estrofa',3,'Cuando emprende es prosperado, duradero le es el bien;\nMuy diversos resultados sacan los que nada creen,\nPues los lanza como el tamo que el ciclón arrebató,\nDe pasiones remolino que a nublones destruyó.'),(2315,379,'Estrofa',4,'En el Juicio ningún malo, por lo tanto, se alzará;\nEntre justos congregados, insensatos nunca habrá.\nPorque Dios la vía mira, por la cual los suyos van;\nOtra es la de los impíos, a la nada volverán.'),(2316,380,'Estrofa',1,'La cruz no es mayor que la gracia\nQue el señor Jesús me da;\nSu rostro, el nublado más negro,\nEsconder jamás podrá.'),(2317,380,'Coro',2,'La cruz no es mayor que su bondad,\nNo oculta su faz la tempestad;\nSatisfáceme saber,\nQue confiando en el poder\nDe Jesús, podré vencer.'),(2318,380,'Estrofa',3,'Si espinas agudas me hieren,\nDe ellas Él se coronó;\nSi amarga es mi copa, en el huerto\nCáliz peor Él apuró.'),(2319,380,'Coro',4,'La cruz no es mayor que su bondad,\nNo oculta su faz la tempestad;\nSatisfáceme saber,\nQue confiando en el poder\nDe Jesús, podré vencer.'),(2320,380,'Estrofa',5,'La luz de su amor más reluce\nEn la senda de aflicción;\nNo siento el afán cuando llevo\nAl perdido salvación.'),(2321,380,'Coro',6,'La cruz no es mayor que su bondad,\nNo oculta su faz la tempestad;\nSatisfáceme saber,\nQue confiando en el poder\nDe Jesús, podré vencer.'),(2322,380,'Estrofa',7,'Andando a su vista, me gozo\nEn cumplir su voluntad;\nSu sangre mi vida ha limpiado,\nY me guarda en la verdad.'),(2323,380,'Coro',8,'La cruz no es mayor que su bondad,\nNo oculta su faz la tempestad;\nSatisfáceme saber,\nQue confiando en el poder\nDe Jesús, podré vencer.'),(2324,381,'Estrofa',1,'Cristo, mi piloto sé\nEn el tempestuoso mar,\nFieras ondas mi bajel\nVan a hacerlo zozobrar;\nMas si Tú conmigo vas,\nPronto al puerto llegaré;\nCarta y brújula hallo en Ti,\n¡Cristo, mi piloto sé!'),(2325,381,'Estrofa',2,'Todo agita el huracán\nCon indómito furor;\nMas los vientos cesarán\nAl mandato de tu voz.\nY al decir: “Que sea la paz”,\nCeder sumiso el mar.\nDe las aguas, Tú, el Señor,\n¡Guíame, cual piloto fiel!'),(2326,381,'Estrofa',3,'Cuando al fin cercano esté\nDe su Reino eternal;\nSi el abismo ruge aún,\nEntre el puerto y mi bajel,\nEn tu pecho al descansar,\nQuiero oír tu voz decir:\n“Nada temas ya del mar,\nTu piloto siempre soy”.'),(2327,382,'Estrofa',1,'¿Que me puede dar perdón?\nSólo de Jesús la sangre.\n¿Y un nuevo corazón?\nSólo de Jesús la sangre.'),(2328,382,'Coro',2,'Precioso es el raudal\nQue limpia todo mal;\nNo hay otro manantial,\nSólo de Jesús la sangre.'),(2329,382,'Estrofa',3,'Fue el rescate eficaz,\nSólo de Jesús la sangre;\nTrajo santidad y paz,\nSólo de Jesús la sangre.'),(2330,382,'Coro',4,'Precioso es el raudal\nQue limpia todo mal;\nNo hay otro manantial,\nSólo de Jesús la sangre.'),(2331,382,'Estrofa',5,'Veo para mi salud,\nSólo de Jesús la sangre;\nTiene de sanar virtud,\nSólo de Jesús la sangre.'),(2332,382,'Coro',6,'Precioso es el raudal\nQue limpia todo mal;\nNo hay otro manantial,\nSólo de Jesús la sangre.'),(2333,382,'Estrofa',7,'Cantaré junto a sus pies,\nSólo de Jesús la sangre;\nEl cordero digno es,\nSólo de Jesús la sangre'),(2334,382,'Coro',8,'Precioso es el raudal\nQue limpia todo mal;\nNo hay otro manantial,\nSólo de Jesús la sangre.'),(2335,383,'Estrofa',1,'Me dice el Salvador:\n“Es poco tu poder,\nHijo débil, halla en mí\nTodo cuanto has menester”.'),(2336,383,'Coro',2,'Todo debo a Él,\nPues ya lo pagó;\nDe las manchas del pecar,\nCual nieve me lavó.'),(2337,383,'Estrofa',3,'Señor, hallado he\nQue sólo tu poder\nA mi duro corazón\nEs capaz de enternecer.'),(2338,383,'Coro',4,'Todo debo a Él,\nPues ya lo pagó;\nDe las manchas del pecar,\nCual nieve me lavó.'),(2339,383,'Estrofa',5,'Pues nada hay bueno en mí,\nTu gracia buscaré,\nY en la sangre de Jesús\nMi alma lavaré.'),(2340,383,'Coro',6,'Todo debo a Él,\nPues ya lo pagó;\nDe las manchas del pecar,\nCual nieve me lavó.'),(2341,383,'Estrofa',7,'Cuando ante el tribunal,\nEn aquel día yo esté,\nA los pies de mi Jesús,\nAlegre cantaré.'),(2342,383,'Coro',8,'Todo debo a Él,\nPues ya lo pagó;\nDe las manchas del pecar,\nCual nieve me lavó.'),(2343,384,'Estrofa',1,'Da gracia, ¡Oh Dios!, escúchame a mí.\n¡Ven, gran libertador!\nPues agobiado anhelo, ¡Oh Dios!, a Ti.\n¡Ven, gran libertador!'),(2344,384,'Coro',2,'Por frígidas montañas yo vagué\nMuy lejos de mi buen pastor;\n¡Oh, sálvame y llévame al redil,\nVen, gran libertador!'),(2345,384,'Estrofa',3,'No puedo abrigo en noche oscura hallar.\n¡Ven, gran libertador!\nMás luz y vida Tú me puedes dar,\n¡Ven, gran libertador!'),(2346,384,'Coro',4,'Por frígidas montañas yo vagué\nMuy lejos de mi buen pastor;\n¡Oh, sálvame y llévame al redil,\nVen, gran libertador!'),(2347,384,'Estrofa',5,'Asendereado sin descanso y paz,\n¡Ven, gran libertador!\nLos ojos alzo a tu benigna faz,\n¡Ven, gran libertador!'),(2348,384,'Coro',6,'Por frígidas montañas yo vagué\nMuy lejos de mi buen pastor;\n¡Oh, sálvame y llévame al redil,\nVen, gran libertador!'),(2349,384,'Estrofa',7,'Mi voz contrita Tú no desoirás,\n¡Ven, gran libertador!\nMi humilde ruego pronto atenderás,\n¡Ven, gran libertador!'),(2350,384,'Coro',8,'Por frígidas montañas yo vagué\nMuy lejos de mi buen pastor;\n¡Oh, sálvame y llévame al redil,\nVen, gran libertador!'),(2351,385,'Estrofa',1,'Es el amor divino,\nMi gozo y mi placer;\nAllana mi camino\nY me hace obedecer.'),(2352,385,'Coro',2,'Dios es amor, soy su pequeñuelo,\nQuiero ser santo como es Él;\nEs el amor divino,\nMi gozo y mi placer;\nAllana mi camino\nY me hace obedecer.'),(2353,385,'Estrofa',3,'Del triste mundo, lleno\nDe muerte y dolor,\nQuisiera yo llevar a Dios,\nA un pobre pecador.'),(2354,385,'Coro',4,'Dios es amor, soy su pequeñuelo,\nQuiero ser santo como es Él;\nEs el amor divino,\nMi gozo y mi placer;\nAllana mi camino\nY me hace obedecer.'),(2355,385,'Estrofa',5,'Y cuando esté en el Reino,\nCon Cristo mi Señor,\nAllí por siempre cantaré\nDe Dios y de su amor.'),(2356,385,'Coro',6,'Dios es amor, soy su pequeñuelo,\nQuiero ser santo como es Él;\nEs el amor divino,\nMi gozo y mi placer;\nAllana mi camino\nY me hace obedecer.'),(2357,386,'Estrofa',1,'Alabadle, fiel Salvador, compasivo,\nCanta, oh, tierra, canta su magno amor;\nSaludadle ángeles, santos en gloria,\nTributad al nombre de Cristo honor;\nEn sus brazos, Él llevará a sus hijos,\nGuardarálos siempre cual fiel pastor;\nEntonad canción a su excelsa grandeza,\nEnsalzadle en himnos de gran loor.'),(2358,386,'Estrofa',2,'Alabadle, fiel Salvador, compasivo,\nQuien por nuestras faltas su vida dio;\nRoca eterna, nuestra inmortal esperanza,\nRey del cielo, que en Gólgota murió;\nDadle loores, nuestros pesares lleva,\nAlabad tan ancho y profundo amor;\nEntonad canción a su excelsa grandeza,\nEnsalzadle en himnos de gran loor.'),(2359,386,'Estrofa',3,'Alabadle, fiel Salvador, compasivo,\nQuerubines que obedecéis su ley;\nCristo en gloria reina por siglos de siglos,\nNuestro Medianero, Profeta y Rey;\nCristo viene, grande, en poder y gloria;\nViene, sí, del mundo ya vencedor;\nEntonad canción a su excelsa grandeza,\nEnsalzadle en himnos de gran loor'),(2360,387,'Estrofa',1,'¿Quién está por Cristo? ¿Quién le servirá?\nA salvar a otros ¿Quién le ayudará?\n¿Quién, dejando el mundo, contra el error,\nLuchará por siempre al lado del Señor?'),(2361,387,'Coro',2,'Por su magna gracia, su profundo amor,\nYo estoy por Cristo, es mi Rey, Señor.'),(2362,387,'Estrofa',3,'No por la corona y el galardón,\nEntro en esta lucha y alzo el pendón;\nEs por el perdido, por quien Él murió;\nEn llevarlo al Salvador, me gozo yo.'),(2363,387,'Coro',4,'Por su magna gracia, su profundo amor,\nYo estoy por Cristo, es mi Rey, Señor.'),(2364,387,'Estrofa',5,'No con oro o plata, Cristo nos compró,\nSino con la sangre que en la cruz vertió.\nLos que a Él acuden, bendecidos son,\nLibertad reciben, limpio corazón.'),(2365,387,'Coro',6,'Por su magna gracia, su profundo amor,\nYo estoy por Cristo, es mi Rey, Señor.'),(2366,387,'Estrofa',7,'Rudo el conflicto sigue con Satán;\nMas lo venceremos, Cristo es capitán.\nSu verdad eterna, nuestro pabellón;\nSu presencia aviva a todo corazón.'),(2367,387,'Coro',8,'Por su magna gracia, su profundo amor,\nYo estoy por Cristo, es mi Rey, Señor.'),(2368,388,'Estrofa',1,'Tesoro incomparable, Jesús, amigo fiel,\nRefugio del que huye del adversario cruel;\nSujeta compasivo a Ti mi corazón,\nYa que para salvarme sufriste la pasión.'),(2369,388,'Estrofa',2,'Delicias de mi alma, paz de la eternidad,\nDel cual yo me alimento en mi necesidad;\nEn mi flaqueza extrema se cumple tu virtud,\nY en medio de mis males ser quieres mi salud.'),(2370,388,'Estrofa',3,'Dirige a mí tu rostro, Jesús, lleno de amor,\nSol puro de justicia, grato consolador;\nSin tu influencia santa la vida es un morir,\nGozar de tu presencia, sólo esto es vivir.'),(2371,388,'Estrofa',4,'Jesús, riqueza mía, mi amante Salvador,\nEn mis flaquezas eres mi fuerte protector.\nMi paz el enemigo turbar podrá jamás,\nPor más que lo intentare, no lo permitirás.'),(2372,388,'Estrofa',5,'Al mundo de palacios no pertenezco ya,\nA Cristo pertenezco, en Él mi vida está.\nEn sempiterno gozo quiero con Él vivir,\nConsagro a Él mi vida y todo mi existir.'),(2373,389,'Estrofa',1,'Hay vida en mirar a mi Salvador.\nDice Jesús: “Miradme a mí”.\nHeces el mundo y sus glorias son,\nTesoros brillantes se ven allí.'),(2374,389,'Coro',2,'¡Oh!, mirad, pues hallaréis\nVida eterna en el Señor;\nSalvación recibiréis\nEn el Redentor, Jesús.'),(2375,389,'Estrofa',3,'La vista al poner en mi Salvador,\nDulces sonrisas Él me dio;\nHoy del maligno soy vencedor,\nMirando a Jesús, que por mí murió.'),(2376,389,'Coro',4,'¡Oh!, mirad, pues hallaréis\nVida eterna en el Señor;\nSalvación recibiréis\nEn el Redentor, Jesús.'),(2377,389,'Estrofa',5,'Mirando a Jesús siempre confiaré\nEn sus promesas y poder;\nNunca vencido del mal seré,\nSu gracia me ayuda a obedecer.'),(2378,389,'Coro',6,'¡Oh!, mirad, pues hallaréis\nVida eterna en el Señor;\nSalvación recibiréis\nEn el Redentor, Jesús.'),(2379,390,'Estrofa',1,'Día grande viene, un día grande,\nDía grande viene y cerca está,\nCuando justos y malos separados quedarán;\n¡Oh!, hermano, ¿Apercibido estás?'),(2380,390,'Coro',2,'¿Te hallas listo? ¿Te hallas listo\nPara el último gran tribunal?\n¿Te hallas listo? ¿Te hallas listo\nPara el día final?'),(2381,390,'Estrofa',3,'Día triste viene, un día triste;\nDía triste viene y cerca está,\nCuando: “Id pecadores, no os conozco” el Juez dirá;\n¡Oh!, hermano, ¿apercibido estás?'),(2382,390,'Coro',4,'¿Te hallas listo? ¿Te hallas listo\nPara el último gran tribunal?\n¿Te hallas listo? ¿Te hallas listo\nPara el día final?'),(2383,390,'Estrofa',5,'Día alegre viene, un día alegre;\nDía alegre viene y cerca está;\nMas su luz brilla sólo en los que aman al Señor;\n¡Oh!, hermano, ¿Apercibido estás?'),(2384,390,'Coro',6,'¿Te hallas listo? ¿Te hallas listo\nPara el último gran tribunal?\n¿Te hallas listo? ¿Te hallas listo\nPara el día final?'),(2385,391,'Estrofa',1,'¡Oh!, cuán gratas las nuevas al peregrino aquí,\nEn desierto obligado a vagar:\n“He aquí, pronto en gloria tu Salvador vendrá,\nY podrás en su Reino entrar”.'),(2386,391,'Coro',2,'Sí, viene, viene, viene, esto sé;\nA la tierra Jesús vendrá,\nY los peregrinos a su Reino irán,\nA su Reino el Señor los guiará.'),(2387,391,'Estrofa',3,'Los sepulcros de cuantos en Cristo duermen ya,\nA su voz, todos se han de abrir;\nLos millones también que en el mar profundo están,\nVolverán otra vez a vivir.'),(2388,391,'Coro',4,'Sí, viene, viene, viene, esto sé;\nA la tierra Jesús vendrá,\nY los peregrinos a su Reino irán,\nA su Reino el Señor los guiará.'),(2389,391,'Estrofa',5,'Nos veremos allá en el nuevo Edén feliz,\nEl adiós no diremos jamás;\nPues del norte y del sur los salvados llegarán\nA morar en el Reino de paz.'),(2390,391,'Coro',6,'Sí, viene, viene, viene, esto sé;\nA la tierra Jesús vendrá,\nY los peregrinos a su Reino irán,\nA su Reino el Señor los guiará.'),(2391,392,'Estrofa',1,'Amanece ya la mañana de oro,\nPronto el Rey vendrá;\nY su pueblo a su Reino,\nCristo llevará.'),(2392,392,'Coro',2,'Amanece ya la mañana de oro,\nTras la noche terrenal,\nCuando surgirá del sepulcro abierto,\nVida inmortal.'),(2393,392,'Estrofa',3,'En aquel gran día los separados,\nSe encontrarán;\nY las lágrimas de los afligidos,\nSe enjugarán.'),(2394,392,'Coro',4,'Amanece ya la mañana de oro,\nTras la noche terrenal,\nCuando surgirá del sepulcro abierto,\nVida inmortal.'),(2395,392,'Estrofa',5,'Con sus ángeles del ardiente cielo,\nCristo, el juez, vendrá,\nA la tierra a establecer su Reino,\nCon su Iglesia morará.'),(2396,392,'Coro',6,'Amanece ya la mañana de oro,\nTras la noche terrenal,\nCuando surgirá del sepulcro abierto,\nVida inmortal.'),(2397,392,'Estrofa',7,'Cuando llegue a todos el Evangelio,\nAnunciando el fin,\nCesará el tardar del Esposo, entonces\nSonará el clarín.'),(2398,392,'Coro',8,'Amanece ya la mañana de oro,\nTras la noche terrenal,\nCuando surgirá del sepulcro abierto,\nVida inmortal.'),(2399,393,'Estrofa',1,'Mientras en el corazón, un alma judía palpite;\nY rumbo al Oriente, la mirada a Sión se dirija.\nNo está perdida aún nuestra esperanza;\nEsa esperanza bimilenaria;\nDe ser pueblo libre en nuestra tierra,\nLa tierra de Sión y Jerusalem.'),(2400,393,'Estrofa',2,'Mientras nuestros ojos viertan lágrimas,\nY, cual lluvias, afluyan las ofrendas;\nY las multitudes de nuestro pueblo,\nAún las tumbas de los Padres visiten.'),(2401,393,'Estrofa',3,'Mientras el ardor de nuestro ideal,\nEn nuestros ojos aparezca;\nY por la destrucción de nuestro santuario,\nOjo alguno lágrima vierta.'),(2402,393,'Estrofa',4,'Mientras lágrimas puras,\nDel ojo de la hija de mi pueblo corran;\nY para los lamentos por Sión en las vigilias,\nAún a medianoche se levantan.'),(2403,393,'Estrofa',5,'Mientras el amor nacional,\nEn el corazón judío palpite,\nAún cabe confiar,\nQue Dios, el iracundo, nos prodigue misericordia.'),(2404,393,'Estrofa',6,'Escuchad mis hermanos, en los países de mis andanzas,\nLa voz de uno de nuestros profetas:\n“Que tan sólo con el último judío,\nAcabará también nuestra esperanza”.'),(2405,394,'Estrofa',1,'Anoche tuve un sueño, sublime, arrobador:\nMiraba a Jerusalén y al templo en su esplendor,\nOí cantar a niños un coro celestial.\nEn tanto que escuchaba un antema angelical,\nEn tanto que escuchaba un antema angelical.'),(2406,394,'Coro',2,'¡Jerusalén! ¡Jerusalén! prorrumpe en voz triunfal!\n¡Hosanna en las alturas! ¡Hosanna al Señor tu Rey!'),(2407,394,'Estrofa',3,'Mi sueño luego se cambió y una quietud reinó;\nCesaron las hosannas y el infantil clamor,\nTras misterioso manto el sol veló su esplendor\nY la sombra de una cruz en el cielo apareció.\nY la sombra de una cruz en el cielo apareció.'),(2408,394,'Coro',4,'¡Jerusalén! ¡Jerusalén! prorrumpe en voz triunfal!\n¡Hosanna en las alturas! ¡Hosanna al Señor tu Rey!'),(2409,394,'Estrofa',5,'Un nuevo cuadro contemplé: prodigio fue sin par.\nY vi la Ciudad Santa junto al sereno mar.\nDios la alumbraba con su luz, sus calles de oro vi,\nY quien deseaba en ella entrar, cabida hallaba allí.\nEstrellas, luna y astro rey perdieron su fulgor.\n//Al descender Jerusalén la Nueva en su esplendor,//'),(2410,394,'Coro',6,'¡Jerusalén! ¡Jerusalén! Prorrumpe en voz triunfal:\n¡Hosanna en las alturas! ¡Hosanna al Señor tu Rey!\n¡Hosanna en las alturas! ¡Hosanna al Señor tu Rey!'),(2411,395,'Estrofa',1,'Solemnes resuenen las voces de amor,\nCon gran regocijo tributen loor;\nAl Rey soberano, el buen Salvador,\nDignísimo es del más alto honor.'),(2412,395,'Coro',2,'Alabad, alabad, alabad al gran rey,\nAdorad, adorad, adoradle su grey;\nEs nuestro escudo, baluarte y sostén,\nEl Omnipotente por siglos amén.'),(2413,395,'Estrofa',3,'Su amor infinito. ¿Qué lengua dirá?,\nY ¿Quién sus bondades jamás sondeará?\nSu misericordia no puede faltar,\nMil himnos alaben su nombre sin par.'),(2414,395,'Coro',4,'Alabad, alabad, alabad al gran rey,\nAdorad, adorad, adoradle su grey;\nEs nuestro escudo, baluarte y sostén,\nEl Omnipotente por siglos amén.'),(2415,395,'Estrofa',5,'Inmensa la obra de Cristo en la Cruz,\nEnorme la culpa se ve por su luz;\nAl mundo Él vino, nos iluminó,\nY por nuestras culpas el Justo murió.'),(2416,395,'Coro',6,'Alabad, alabad, alabad al gran rey,\nAdorad, adorad, adoradle su grey;\nEs nuestro escudo, baluarte y sostén,\nEl Omnipotente por siglos amén.'),(2417,395,'Estrofa',7,'Velad fieles todos, velad con fervor,\nQue viene muy pronto Jesús el Señor;\nCon notas alegres vendrá a reinar,\nA su eterna gloria os ha de llevar.'),(2418,395,'Coro',8,'Alabad, alabad, alabad al gran rey,\nAdorad, adorad, adoradle su grey;\nEs nuestro escudo, baluarte y sostén,\nEl Omnipotente por siglos amén.'),(2419,396,'Estrofa',1,'Ante el trono de tu gracia, hoy venimos, Oh, Señor;\nA pedirte corrobores, estos votos del amor.\nImploramos tu presencia, e infinita protección;\nPor tus hijos que celebran, en tu altar su santa unión.'),(2420,396,'Coro',2,'Sí, desciende, Dios Eterno,\nSantifica Tú la unión;\nY derrama ahora en ellos,\nTu divina bendición.'),(2421,396,'Estrofa',3,'Oh, Señor, derrama en ellos, los raudales de tu luz;\nQue reciban en sus almas, la visita de Jesús.\nQue tu mano cariñosa, cubra aquí su nuevo hogar;\nY los libre de aflicciones, de dolor y de pesar.'),(2422,396,'Coro',4,'Sí, desciende, Dios Eterno,\nSantifica Tú la unión;\nY derrama ahora en ellos,\nTu divina bendición.'),(2423,396,'Estrofa',5,'Oh, Señor, escucha atento, de tus hijos la oración;\nPorque vienen implorando, Tu divina protección.\nFunde aquí sus corazones, con el fuego conyugal;\nY que unidos peregrinen, a tu Reino Eternal.'),(2424,396,'Coro',6,'Sí, desciende, Dios Eterno,\nSantifica Tú la unión;\nY derrama ahora en ellos,\nTu divina bendición.'),(2425,397,'Estrofa',1,'//Bienaventurado aquel,\ncuyas iniquidades son perdonadas//;\n//Y borrados sus pecados,//\nBienaventurado el hombre a quien,\nNo imputa Jehová la iniquidad,\nY en cuyo espíritu no hay superchería.'),(2426,397,'Coro',2,'Mientras callé, envejeciéronse mis huesos,\nEn mi gemir todo el día;\nPorque de día y de noche\nSe agravó sobre mi tu mano.'),(2427,397,'Estrofa',3,'//Volvióse, volvióse mi verdor, en sequedades de estío//\nMi pecado, mi pecado te declaré\nY no encubrí mi iniquidad.\nConfesaré dije contra mi, mis rebeliones a Jehová.\nY Tú perdonaste la maldad de mi pecado.'),(2428,397,'Coro',4,'Mientras callé, envejeciéronse mis huesos,\nEn mi gemir todo el día;\nPorque de día y de noche\nSe agravó sobre mi tu mano.'),(2429,397,'Estrofa',5,'//Por esto orará, a ti todo santo, en el Tiempo de poder hallarte//.\nCiertamente en la inundación de muchas aguas\nno llegarán estas a él.\nTú eres mi refugio, tú eres mi refugio\nme guardarás de angustias\nCon cánticos de Liberación me rodearás.'),(2430,397,'Coro',6,'Mientras callé, envejeciéronse mis huesos,\nEn mi gemir todo el día;\nPorque de día y de noche\nSe agravó sobre mi tu mano.'),(2431,398,'Estrofa',1,'Jehová reina, Jehová reina,\nVistióse de magnificencia\nVistióse Jehová, ciñose de fortaleza\nAfirmó también el mundo, que no se moverá.\nFirme es tu trono desde entonces,\nTú eres eternalmente.'),(2432,398,'Estrofa',2,'Alzaron los ríos oh Jehová,\nAlzaron los ríos su sonido,\nAlzaron los ríos sus ondas.\nJehová en las alturas es más Poderoso;\nQue el estruendo de las muchas aguas,\nMás que las recias ondas del mar.\nTus testimonios son muy firmes;\nLa santidad conviene a tu casa,\nOh Jehová, por los siglos y para siempre.'),(2433,398,'Estrofa',3,'Alzaron los ríos oh Jehová,\nAlzaron los ríos su sonido,\nAlzaron los ríos sus ondas.\nJehová en las alturas es más Poderoso;\nQue el estruendo de las muchas aguas,\nMás que las recias ondas del mar.\nTus testimonios son muy firmes;\nLa santidad conviene a tu casa,\nOh Jehová, por los siglos y para siempre. AMÉN'),(2434,399,'Estrofa',1,'Bienaventurado, Bienaventurado,\nTodo aquel que teme a Jehová;\nQue anda en sus caminos,\nCuando comieres, cuando comieres.\nEl trabajo de tus manos,\nBienaventurado, Bienaventurado, tú;\nY tendrás bien.'),(2435,399,'Coro',2,'Tu mujer será como parra que lleva frutos,\nA los lados de tu casa;\nTus hijos como plantas de oliva,\nAlrededor de tu mesa.\nTus hijos como plantas de oliva,\nAlrededor de tu mesa.\nHe aquí que así será bendito el hombre,\nQue teme, que teme a Jehová;\nBendígate Jehová desde Sión,\nY veas el bien de Jerusalem.\nTodos los días de tu vida,\nY veas los hijos de tus hijos;\nY la paz sobre Israel.'),(2436,400,'Estrofa',1,'Blancos vestidos bañados de luz;\nRica diadema de gran esplendor;\nBella ciudad de sublime quietud,\nDonde la noche jamás existió\nEsa ciudad admirable de Dios\nDonde estaremos reunidos con el;\nPadre, permite que no falte yo,\nEs mi oración'),(2437,400,'Coro',2,'Bellos ropajes, hermoso hogar\nTierra preciosa, dulce cantar;\nBella corona, de estrellas mil;\nRica mansión de luz, do viviré.'),(2438,400,'Estrofa',3,'¡oh cuan preciosa! Es la meditación de vivir siempre por la eternidad\nEstando libre de preocupación\nLibre de afanes y de toda ansiedad.\nTendremos parte en el júbilo aquel,\nDonde voces alaban a Dios;\nTodo lo que ha preparado Jesús,\nEs para mí'),(2439,400,'Coro',4,'Bellos ropajes, hermoso hogar\nTierra preciosa, dulce cantar;\nBella corona, de estrellas mil;\nRica mansión de luz, do viviré.'),(2440,400,'Estrofa',5,'Cosas hermosas tenemos que ver\nEn las regiones de Reino de Dios\nCuando con Cristo yo vaya a gozar;\nY mi corona reciba de Dios.\nBello lugar donde muerte no habrá\nDulce refugio de santo calor;\nBello país donde muerte no habrá,\nDo gozare.'),(2441,400,'Coro',6,'Bellos ropajes, hermoso hogar\nTierra preciosa, dulce cantar;\nBella corona, de estrellas mil;\nRica mansión de luz, do viviré.'),(2442,401,'Estrofa',0,'Cristo me ayuda por Él a vivir, \nCristo me ayuda por Él a morir; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2443,401,'Coro',1,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2444,401,'Estrofa',2,'Siento pesares, muy cerca Él está, \nSiento dolores, alivio me da; \nTengo aflicciones, me muestra su amor, \nCada momento, me cuidas Señor.'),(2445,401,'Coro',3,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2446,401,'Estrofa',4,'Tengo amarguras o tengo temor, \nTengo tristezas, me inspiras valor; \nTengo conflictos o penas aquí, \nCada momento te acuerdas de mí.'),(2447,401,'Coro',5,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2448,401,'Estrofa',6,'Tengo flaquezas o débil estoy \nCristo me dice: “Tu amparo yo soy”. \nCada momento en tinieblas o en luz, \nSiempre conmigo está mi Jesús.'),(2449,401,'Coro',7,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2450,402,'Estrofa',0,'Cristo me ayuda por Él a vivir, \nCristo me ayuda por Él a morir; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2451,402,'Coro',1,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2452,402,'Estrofa',2,'Siento pesares, muy cerca Él está, \nSiento dolores, alivio me da; \nTengo aflicciones, me muestra su amor, \nCada momento, me cuidas Señor.'),(2453,402,'Coro',3,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2454,402,'Estrofa',4,'Tengo amarguras o tengo temor, \nTengo tristezas, me inspiras valor; \nTengo conflictos o penas aquí, \nCada momento te acuerdas de mí.'),(2455,402,'Coro',5,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2456,402,'Estrofa',6,'Tengo flaquezas o débil estoy \nCristo me dice: “Tu amparo yo soy”. \nCada momento en tinieblas o en luz, \nSiempre conmigo está mi Jesús.'),(2457,402,'Coro',7,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2458,403,'Estrofa',0,'Cristo me ayuda por Él a vivir, \nCristo me ayuda por Él a morir; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2459,403,'Coro',1,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2460,403,'Estrofa',2,'Siento pesares, muy cerca Él está, \nSiento dolores, alivio me da; \nTengo aflicciones, me muestra su amor, \nCada momento, me cuidas Señor.'),(2461,403,'Coro',3,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2462,403,'Estrofa',4,'Tengo amarguras o tengo temor, \nTengo tristezas, me inspiras valor; \nTengo conflictos o penas aquí, \nCada momento te acuerdas de mí.'),(2463,403,'Coro',5,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2464,403,'Estrofa',6,'Tengo flaquezas o débil estoy \nCristo me dice: “Tu amparo yo soy”. \nCada momento en tinieblas o en luz, \nSiempre conmigo está mi Jesús.'),(2465,403,'Coro',7,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2466,404,'Estrofa',0,'Cristo me ayuda por Él a vivir, \nCristo me ayuda por Él a morir; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2467,404,'Coro',1,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2468,404,'Estrofa',2,'Siento pesares, muy cerca Él está, \nSiento dolores, alivio me da; \nTengo aflicciones, me muestra su amor, \nCada momento, me cuidas Señor.'),(2469,404,'Coro',3,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2470,404,'Estrofa',4,'Tengo amarguras o tengo temor, \nTengo tristezas, me inspiras valor; \nTengo conflictos o penas aquí, \nCada momento te acuerdas de mí.'),(2471,404,'Coro',5,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2472,404,'Estrofa',6,'Tengo flaquezas o débil estoy \nCristo me dice: “Tu amparo yo soy”. \nCada momento en tinieblas o en luz, \nSiempre conmigo está mi Jesús.'),(2473,404,'Coro',7,'Cada momento la vida me da, \nCada momento conmigo Él está; \nHasta que llegue su reino a ver, \nCada momento le entrego mi ser.'),(2474,405,'Estrofa',0,'Por fe contemplo redención,\nLa fuente carmesí;\nJesús nos da la salvación,\nSu vida dió por mí.'),(2475,405,'Coro',1,'La fuente sin igual hallé,\nDe vida y luz el manantial;\n¡Oh, gloria a Dios, me limpia a mí,\nMe limpia a mí, me limpia a mí.'),(2476,405,'Estrofa',2,'Mi vida entrego a mi Jesús,\nLas dudas Él quitó;\nMi alma goza de su luz,\nMis deudas Él pagó.'),(2477,405,'Coro',3,'La fuente sin igual hallé,\nDe vida y luz el manantial;\n¡Oh, gloria a Dios, me limpia a mí,\nMe limpia a mí, me limpia a mí.'),(2478,405,'Estrofa',4,'Cuán inefable gozo es,\nSaber que salvo soy;\nMi Rey aquí es mi Jesús,\nAl reino sé que voy.'),(2479,405,'Coro',5,'La fuente sin igual hallé,\nDe vida y luz el manantial;\n¡Oh, gloria a Dios, me limpia a mí,\nMe limpia a mí, me limpia a mí.'),(2480,405,'Estrofa',6,'¡Oh, gracia excelsa de mi Dios,\nProfundo es el amor;\nDe mi Jesús vía de luz,\nCordero redentor.'),(2481,405,'Coro',7,'La fuente sin igual hallé,\nDe vida y luz el manantial;\n¡Oh, gloria a Dios, me limpia a mí,\nMe limpia a mí, me limpia a mí.'),(2482,406,'Estrofa',0,'Nunca desmayes en todo afán,\nTe cuidará el Señor;\nSus fuertes alas te cubrirán,\nTe cuidará el Señor.'),(2483,406,'Coro',1,'Te cuidará el Señor,\nNo te verás solo jamás;\nVelando está su amor;\nTe cuidará el Señor.'),(2484,406,'Estrofa',2,'Cuando flaqueare tu corazón,\nTe cuidará el Señor;\nEn tus conflictos y tentación,\nTe cuidará el Señor.'),(2485,406,'Coro',3,'Te cuidará el Señor,\nNo te verás solo jamás;\nVelando está su amor;\nTe cuidará el Señor.'),(2486,406,'Estrofa',4,'De sus riquezas te proveerá,\nTe cuidará el Señor;\nJamás sus bienes te negará,\nTe cuidará el Señor.'),(2487,406,'Coro',5,'Te cuidará el Señor,\nNo te verás solo jamás;\nVelando está su amor;\nTe cuidará el Señor.'),(2488,406,'Estrofa',6,'Que pruebas vengan no importa, no,\nTe cuidará el Señor;\nTus cargas todas en Cristo pon,\nTe cuidará el Señor.'),(2489,406,'Coro',7,'Te cuidará el Señor,\nNo te verás solo jamás;\nVelando está su amor;\nTe cuidará el Señor.'),(2490,407,'Estrofa',0,'No hay tristeza en el reino, ni llanto ni amargo dolor;\nNo hay corazón angustiado, do reina el Señor de amor;\nLas nubes de nuestro horizonte, jamás aparecen allí;\nEl sol en su gloria esplendente, derrama su luz celestial.'),(2491,407,'Coro',1,'Yo voy a la patria del alma, do Cristo prepara mi hogar;\nDo todos los santificados, irán para siempre a morar;\nEl día feliz ya se acerca, en que el sol para mí se pondrá;\n¡Oh, qué gozo será, cuando mire al Señor,\nen aquella hermosa ciudad!'),(2492,407,'Estrofa',2,'No hay aflicción en el reino, ni pruebas existen allá;\nEl alma que en Cristo reposa, segura en su seno estará.\nNo hay tentación en el reino, ni sombra de muerte atroz;\nEl árbol de vida florece, do fluye el río de Dios.'),(2493,407,'Coro',3,'Yo voy a la patria del alma, do Cristo prepara mi hogar;\nDo todos los santificados, irán para siempre a morar;\nEl día feliz ya se acerca, en que el sol para mí se pondrá;\n¡Oh, qué gozo será, cuando mire al Señor,\nen aquella hermosa ciudad!'),(2494,407,'Estrofa',4,'¡Cuán dulce será en el reino, pasadas las penas aquí;\nVolvernos a ver reunidos, con nuestros amados allí!.\n¡Por todos los siglos eternos, qué dicha inefable ha de ser;\nEstar en presencia de Cristo, gozando de eterno placer!'),(2495,407,'Coro',5,'Yo voy a la patria del alma, do Cristo prepara mi hogar;\nDo todos los santificados, irán para siempre a morar;\nEl día feliz ya se acerca, en que el sol para mí se pondrá;\n¡Oh, qué gozo será, cuando mire al Señor,\nen aquella hermosa ciudad!'),(2496,408,'Estrofa',0,'Hay un jardín memorable y hermoso,\nDonde flores exhalan su olor:\nDonde el Maestro pasaba las horas\nRespirando su dulce oración.'),(2497,408,'Coro',1,'Al hermoso jardín , el jardín de oración\nAl hermoso jardín de oración:\nEl Señor está allí y la puerta abre Él,\nAl hermoso jardín de oración.'),(2498,408,'Estrofa',2,'Aun las aves gorjeaban sus trinos,\nAl compás de tan dulce oración.\nCuando el Maestro imploraba a los cielos,\nPara el mundo la grán salvación.'),(2499,408,'Coro',3,'Al hermoso jardín , el jardín de oración\nAl hermoso jardín de oración:\nEl Señor está allí y la puerta abre Él,\nAl hermoso jardín de oración.'),(2500,408,'Estrofa',4,'La fragancia del óleo Divino,\nSe esparcía por todo el jardín,\nCuando Cristo del cielo fue ungido,\nPorque pronto ya Él iba a morir.'),(2501,408,'Coro',5,'Al hermoso jardín , el jardín de oración\nAl hermoso jardín de oración:\nEl Señor está allí y la puerta abre Él,\nAl hermoso jardín de oración.'),(2502,409,'Estrofa',0,'[D]Cerc[D][F#]a de [G]Ti, Señor, [D][F#]quiero morar;\nTu grande y tierno amor, quiero gozar.\nLlena mi pobre ser, limpia mi corazón;\nHazme tu rostro ver, en comunión.'),(2503,409,'Estrofa',1,'Pasos inciertos doy, el sol se va;\nMas si contigo estoy, no temo ya.\nHimnos de gratitud, ferviente cantaré;\nY fiel a Ti, Jesús, siempre seré.'),(2504,409,'Estrofa',2,'Día feliz veré, creyendo en Ti;\nEn que yo habitaré, cerca de Ti.\nMi voz alabará, tu dulce nombre allí;\nY mi alma gozará, cerca de Ti.'),(2505,410,'Estrofa',0,'[D]Cerc[D][F#]a de [G]Ti, Señor, [D][F#]quiero morar;\nTu grande y tierno amor, quiero gozar.\nLlena mi pobre ser, limpia mi corazón;\nHazme tu rostro ver, en comunión.'),(2506,410,'Estrofa',1,'Pasos inciertos doy, el sol se va;\nMas si contigo estoy, no temo ya.\nHimnos de gratitud, ferviente cantaré;\nY fiel a Ti, Jesús, siempre seré.'),(2507,410,'Estrofa',2,'Día feliz veré, creyendo en Ti;\nEn que yo habitaré, cerca de Ti.\nMi voz alabará, tu dulce nombre allí;\nY mi alma gozará, cerca de Ti.'),(2508,411,'Estrofa',0,'[D]Cerc[D][F#]a de [G]Ti, Señor, [D][F#]quiero morar;\n[Bm]Tu gr[Bm][F#]ande y tie[G]rno amor, [D]quier[A]o goza[D]r.\nLlen[G]a mi p[D]obre ser, limpi[D][B]a mi corazó[A]n;\n[Bm]Hazm[Bm][F#]e tu ro[G]stro ver, e[D]n comunió[D]n.'),(2509,411,'Estrofa',1,'Pasos inciertos doy, el sol se va;\nMas si contigo estoy, no temo ya.\nHimnos de gratitud, ferviente cantaré;\nY fiel a Ti, Jesús, siempre seré.'),(2510,411,'Estrofa',2,'Día feliz veré, creyendo en Ti;\nEn que yo habitaré, cerca de Ti.\nMi voz alabará, tu dulce nombre allí;\nY mi alma gozará, cerca de Ti.'),(2511,412,'Estrofa',0,'[D]Cerc[D][F#]a de [G]Ti, Señor, [D][F#]quiero morar;\n[Bm]Tu gr[Bm][F#]ande y tie[G]rno amor, [D]quier[A]o goza[D]r.\nLlen[G]a mi p[D]obre ser, limpi[D][B]a mi corazó[A]n;\n[Bm]Hazm[Bm][F#]e tu ro[G]stro ver, e[D]n comunió[D]n.'),(2512,412,'Estrofa',1,'[D]Paso[D][F#]s inciertos doy, el sol se va;\nMas si contigo estoy, no temo ya.\nHimnos de gratitud, ferviente cantaré;\nY fiel a Ti, Jesús, siempre seré.'),(2513,412,'Estrofa',2,'Día feliz veré, creyendo en Ti;\nEn que yo habitaré, cerca de Ti.\nMi voz alabará, tu dulce nombre allí;\nY mi alma gozará, cerca de Ti.'),(2514,413,'Estrofa',1,'Unidos, unidos en su nombre unidos\nUnidos, Unidos, en su nombre unidos,\nPues en este mundo paz y amor tenemos\nPues en este mundo paz y amor tenemos'),(2515,413,'Coro',2,'Unidos, siempre unidos\nTomados de las manos\nIremos por el mundo cantándole a Dios\nLa gloria de Jesús, así resplandecerá\nY al mundo llenara de amor y de paz.\nOh, de amor y de paz.'),(2516,413,'Estrofa',3,'Unidos, unidos en su nombre unidos\nUnidos, Unidos, en su nombre unidos,\nPues en este mundo paz y amor tenemos\nPues en este mundo paz y amor tenemos'),(2517,414,'Estrofa',1,'Sé que estas muy triste eso bien lo se\nPorque faltan cosas que no hay en tu ser\nEn el mundo existe la desigualdad\nPues unamos fuerzas para así avanzar.'),(2518,414,'Coro',2,'Pero ven, ven Oh a Cristo a el\nEs la luz el ser, la chispa del saber\nPero ven, ven Oh a Cristo a el\nEs la luz el ser la chispa del saber'),(2519,414,'Estrofa',3,'Comencemos juntos, la nueva misión\nFijemos el blanco que es cristo\nEsfuérzate ahora, nunca faltara\nLa sombra de vida, que en Cristo esta'),(2520,415,'Estrofa',1,'Renuévame señor Jesús\nYa no quiero ser igual\nPruébame señor Jesús\nPon en mi tu corazón'),(2521,415,'Coro',2,'///Porque todo lo que hay\nDentro de mi corazón necesita\nSer cambiado señor///\nNecesita más de ti'),(2522,415,'Estrofa',3,'Renuévame señor Jesús\nYa no quiero ser igual\nPruébame señor Jesús\nPon en mi tu corazón'),(2523,416,'Estrofa',1,'Junto a ti, mi Jesús, quiero siempre caminar\nEstar cerca de tu luz ser reflejo de tu majestad,\nEn conflictos y tristezas me acogiste en tus brazos\nFuiste tú mi amigo sincero y de verdad, cuando todo se volvía contra mi'),(2524,416,'Estrofa',2,'Al recordar pienso yo, todo aquello que viví\nY al pensar siento yo que lo viví junto a ti\nMano a mano voy contigo hacia donde tú me llevas\nTu palabra me ilumina y me hace comprender que tú eres el hijo del gran rey'),(2525,416,'Coro',3,'Si es Jesucristo que dio su vida allá en la cruz,\nJoven nunca desmayes, sigue sus huellas\nHasta el final.'),(2526,416,'Estrofa',4,'En tu vida mi Jesús, me enseñaste a perdonar\nA vencer con valor el pecado y la maldad\nY si en mi la fe desmaya eres tu mi fortaleza\nPor eso con mi canto quiero testificar\nQue solo en tu sendero quiero andar'),(2527,416,'Estrofa',5,'Hoy mi alma se goza pues con mi Cristo he de reinar\nSi con fe y confianza sigo sus huellas\n//Hasta el final//'),(2528,417,'Estrofa',1,'Es el esfuerzo de un joven\nDe la Iglesia de Dios,\nSer valiente y nunca desmayar\nQue el plan es la meta alcanzar…'),(2529,417,'Estrofa',2,'Fuerte ante la adversidad y sencillo\nCon la humanidad, suave como luz\nAl caminar y agradable como el sol al alba dar.'),(2530,417,'Coro',3,'Faro, faro, faro de luz quiero ser\nLuminaria, y al mundo resplandecer\nY con la palabra de Dios vencer,\nLas tinieblas del pecado cruel'),(2531,417,'Estrofa',4,'Suave ciertamente es la luz\nY grato a los ojos ver el sol salir\nSemejante hermano eres tu\nCuando llevas la doctrina a expandir'),(2532,417,'Estrofa',5,'Anda decorosamente\nVistamos armas de luz\nAgradando a Dios omnipotente\nEn el nombre de Jesús'),(2533,418,'Estrofa',1,'Al contemplar tu creación\ninmensa y bella, al ver un amanecer\nla luz de una estrella\nde un ocaso la belleza, el trino\nde las aves al cantar'),(2534,418,'Estrofa',2,'pusiste la sonrisa desde mi infancia,\nla flor de mi juventud\ny ahora que estoy joven mi corazón te canta,\npor las maravillas que has hecho en mi'),(2535,418,'Coro',3,'porque vengo ante ti\nmi corazón gracias te da\npor darme tu amor\ny tu fidelidad gracias mi Dios'),(2536,418,'Estrofa',4,'por estar siempre a mi lado\nen mis tristezas y alegrías porque tu\nconmigo estarás.\nEres la luz que ilumina mi alma\nDas vida a mi existir, por eso\nyo te alabo, por eso yo te exalto\nelevando hacia ti mi gratitud'),(2537,419,'Estrofa',1,'Joven, reconoce al señor\nPorque el es tu creador\nY también tu salvador,\nJoven, no te olvides del señor\nPorque en el esta la vida\nY no hay otro como el.'),(2538,419,'Coro',2,'Hoy te alabo mi Dios\nPor la obra que hiciste en mi\nPorque siempre te acordaste de mi\nY me diste de tu amor\nToma mi vida oh Señor\nte la entrego porque yo quiero ser\nInstrumento de alabanza y loor\nHasta que oscurezca el sol.'),(2539,419,'Estrofa',3,'Joven, la vida es una flor,\nQue un tiempo esta hermosa\nY que se marchitara.\nJoven dale al señor, la gloria de tu vida\nQue después la encontraras.'),(2540,420,'Estrofa',1,'Oh Señor Jesús, nos recordamos hoy\nDe aquel momento tan especial\nque salvarías a la humanidad\nEn aquella ocasión, cuando habías triunfado\nY se te había dado todo el poder'),(2541,420,'Estrofa',2,'Por esa razón ordenaste a tus hijos\nAquellos tus discípulos una gran misión'),(2542,420,'Coro',3,'En esta convención, nos llenamos\nDe emoción, al saber que tu\nEstarás con nosotros\nAyudándonos a realizar\nEsa maravillosa obra señor\nTodos los días hasta el final.'),(2543,420,'Estrofa',4,'Joven participa llevando con afán\nEste hermoso evangelio a la humanidad\nAnuncia esta noticia ya sin vacilar\nMostremos ese amor por todos los demás\nYa que si lo haces tu vida salvaras\nPara que nadie se pierda más tenga vida eterna\nTodos cumplamos esa comisión'),(2544,421,'Estrofa',1,'Cuando puedo contemplar la inmensidad\nEn el firmamento multitud de astros\nTu grandeza oh señor, se deja reflejar\nPara con la humanidad que cree en ti'),(2545,421,'Coro',2,'Creo en Ti, Creo en ti señor,\nque tú eres salvación para la humanidad\ndespojándote tú mismo de tu señorío\nhumillándote, tomaste mi lugar.'),(2546,421,'Estrofa',3,'Tus jóvenes recordamos que en el Sinaí\nDiste mandamientos y decretos,\ntus hijos que confiamos que tú eres veraz\nPorque tu palabra es la verdad'),(2547,422,'Estrofa',1,'Aun no puedo comprender tu amor por mi\nY es que estas conmigo en cada instante\nEn mi vida no hay vacío, si estas siempre conmigo\nY en cualquier dificultad me haces triunfar'),(2548,422,'Coro',2,'Soy, mas vencedor contigo Jesús\nSoy mas que triunfador contigo Jesús\n//Tu me has enseñado, a luchar por la verdad\nGuardar tu palabra\nY tu amor predicar//'),(2549,422,'Estrofa',3,'Quien nos separa de tu amor\nQue nos has permitido estar contigo\nY este día unidos agradezco lo vivido\nY confiando siempre en ti yo estaré'),(2550,423,'Estrofa',1,'Cultivemos juntos ese amor\nQue nos ha dado el creador\nSin egoísmo a los demás, ese amor celestial\nCultivemos la fidelidad, así como la sinceridad\nA nuestro señor Jesús, que por amor murió\nEn la Cruz.'),(2551,423,'Coro',2,'Sembremos, sembremos ese amor\nQue Cristo nos dio\nLa fe que Jesús resucito\nEsa humildad del niño\nCultivemos en el corazón,\nnecesario para nuestra salvación.'),(2552,423,'Estrofa',3,'Cultivemos la justicia, y\nSegaremos misericordia, porque\nLo que cultivemos, eso\nSegaremos.'),(2553,423,'Estrofa',4,'Cultivemos en la humanidad\nSer guía de la eternidad\nPara que nadie se pierda\nMas tenga vida eterna'),(2554,424,'Estrofa',1,'La gloria te damos Oh Dios\nPor hablar a tu hijo Abraham\nEstábamos solos sin esperanza\nVivíamos todos en a oscuridad\nPero Cristo nos dio su vida\nMuriendo en aquella cruz\nLa cual no merecía\nLo hizo por amor'),(2555,424,'Estrofa',2,'Herencia bendita tenemos\nDe esa bella nación'),(2556,424,'Coro',3,'//Y si vosotros sois de cristo\nLinaje de Abraham\nJóvenes luchemos\nEl justo por fe vivirá\nHerederos de la promesa\nVida eterna obtendrás//'),(2557,424,'Estrofa',4,'El señor nos regala la paz\nSi le entregamos el corazón\nSu espíritu dio a la humanidad\nY hoy me guía por un sendero de amor\nPorque el señor compro mi vida\nY me enseño un camino de luz\nLo cual no merecía\nSoy heredero de su amor\nNo ignoremos sus promesas\nSolo en el hay salvación.'),(2558,425,'Estrofa',1,'Recordamos los momentos felices\nQue convivimos con la juventud\nCreo en ti, y soy más que vencedor\nY junto a ti no vacilare…'),(2559,425,'Coro',2,'//Eben ezer, Eben ezer; hasta aquí nos ayudó Jehová\nY no podrá el enemigo ganar mi confianza//'),(2560,425,'Estrofa',3,'Recordamos los momentos felices\nQue convivimos con la juventud\nCreo en ti, y soy más que vencedor\nY junto a ti no vacilare…'),(2561,426,'Estrofa',1,'Hoy vengo a ti y siento tu presencia\nmi vida tú vas a confirmar\nEl que cree en ti, no se avergonzara\nJoven el nunca te dejara.\nPues la fe en mi Cristo es mi salvación,\nMi buen señor te quiero agradar'),(2562,426,'Coro',2,'El joven por fe vivirá\nY se gozara en Jehová\nPor fe también triunfara\nY creerá en lo imposible de lograr'),(2563,426,'Estrofa',3,'En cada paso quiero ver tu rostro\nen toda lucha en ti quiero confiar\nEl que cree en ti, no se avergonzara\nJoven, Dios nunca te abandonara\nPues la fe en Cristo es mi salvación\nMi buen señor te quiero agradar'),(2564,427,'Estrofa',1,'En la inmensidad de tu amor\nOh buen señor\nTu palabra exaltare\nLa esperanza está en ti al sembrar El bien\nY a mí prójimo ayudar\nY tus bendiciones alcanzar'),(2565,427,'Coro',2,'No me cansare de hacer el bien\nSi a su tiempo segare, si no desmayo\nEl trabajo en el señor no es en vano\nLa corona de la vida me dará'),(2566,427,'Estrofa',3,'En tierra desierta donde\nDonde el rocío no cae\nDonde no vuelan las aves\nAllí te exaltare\nPodemos sembrar para cosechar\nEn el amor de nuestro dios\nY así obtener la salvación'),(2567,428,'Estrofa',1,'Dios conmigo está en la batalla\nAyudando a vencer a los gigantes\nAunque millares vengan contra mi\nVencedor de gigantes seré.'),(2568,428,'Coro',2,'//Si Dios conmigo quien contra mi\nNo temeré luchar hasta el fin\nSeré vencedor de gigantes//.'),(2569,428,'Estrofa',3,'Joven si la tentación te rodea\nNo te detengas a mirar sus deleites\nCon la mirada puesta en Jesús\nVencedor de gigantes seré'),(2570,429,'Estrofa',1,'Caminando en integridad,\nobedeciendo su voluntad\nOh mi Dios, tu eres el guía de mi camino\nque me conduce\nA mi destino a ti señor.'),(2571,429,'Coro',2,'Oh juventud, avanza ya,\nen rectitud y santidad\nY caminando en integridad\nLa vida eterna alcanzaras.'),(2572,429,'Estrofa',3,'Tú conoces todo de mí,\nnada puedo ocultarte a ti\nmi creador\ntus mandamientos quiero guardar\ny en tu iglesia perseverar hasta el final'),(2573,430,'Estrofa',1,'Dios dueño del universo\nDueño de mis pensamientos, solo eres tu\nEstoy en el mejor momento\nTu palabra es mi alimento\nTe alabo con mi voz'),(2574,430,'Coro',2,'Conociendo y viviendo la\nDoctrina, es esa luz que\nvino a mí y alumbro mi\nvida, es el mensaje real en\nel que puedo confiar mi\ndelevite está en la ley de Jehová…'),(2575,430,'Estrofa',3,'Tú, la creación de todo a ti\nEs que te alabo con todo el\nCorazón, voy a ti con alegría\nEnseñando la doctrina\nPara la salvación.'),(2576,431,'Estrofa',1,'Señor tú que estas en las alturas,\ny que llenas mi alma de paz y bendición\nTú quien escuchas mis plegarias\nY que sacias mi vida con tu gran amor.\nConfiando en ti estaré'),(2577,431,'Coro',2,'Mi intimidad con Dios,\nEs un regalo que puedo tener\nEl me da su amor y me llena de su poder\nTengo confianza y tengo fe\nEn su palabra yo creeré\nDe su poderosa mano no me soltare'),(2578,431,'Estrofa',3,'Seré fiel a ti en toda mi vida\nY me postrare sincero con mi corazón\nHablare contigo cada día\nEscuchare con calma tu dulce voz\nAdorándote a ti estaré.'),(2579,432,'Estrofa',1,'Oh, que hermoso es compartir\nMomentos como hoy,\nJuntos con tu bella juventud,\nA ti señor mi Dios te queremos adorar\nY decirte en oración esta humilde confesión.'),(2580,432,'Coro',2,'//Y es que: renueves\nNuestra fuerza como el águila\nPon esa fuerza en nuestra juventud\nPara esperar solo en ti//'),(2581,432,'Estrofa',3,'Ser fuertes como Sansón\nValientes como David\nFiel como tu siervo Daniel\nDe ellos aprender a esperar solo en ti\nY decir en esta canción esta humilde confesión.'),(2582,433,'Estrofa',1,'Perdido me encontraba, sin amor y dirección…\nSolo y afligido caminaba, sin hallar solución,\nHasta que un día tu palabra, ilumino mi corazón,'),(2583,433,'Coro',2,'Tu palabra, guía mi camino,\nSiendo yo un peregrino,\nni ando más, en la oscuridad\npracticando la maldad\nayúdame Jesús a ser santo como tu'),(2584,433,'Estrofa',3,'Joven limpia tu camino,\nY guarda su palabra, vida eterna\nSerá tu destino, si amas a Jehová,\nSu palabra es verdad, te guiara a felicidad'),(2585,434,'Estrofa',1,'Hay una luz que guía mi andar,\nQue ilumina mi sendero como faro en el mar\nBienaventurado soy al saber la verdad,\nque combate las tinieblas que me hacen tropezar'),(2586,434,'Coro',2,'Tu palabra guía mi camino, no temeré de las tinieblas, pues tu\nluz me alumbrara, pues ¿con que limpiare yo mi camino? Sino\nguardando tu palabra que me brinda dirección, tu palabra me\nguiara.'),(2587,434,'Estrofa',3,'Meditare en tu palabra mi señor,\nEs una lámpara a mis pasos que\nAlumbra a mi alrededor,\nguardare tus mandamientos y te seguiré.\nDirige tú, mis pasos y hasta ti yo llegare'),(2588,435,'Estrofa',1,'Oh juventud sigue adelante\nAunque la tormenta sea muy fuerte\nNo tengas miedo, confiando en Jehová\nNada podrá ya detenerte\nTuya es mi vida guíala oh Dios\nPor la eternidad'),(2589,435,'Coro',2,'Por siempre fuertes Oh joven de Dios\nCon alma, mente y corazón\nAlabándole con devoción\nPor siempre y llenos de fe\nCon fuerza voluntad y amor\nObtendremos ese galardón\nDe nuestro dios'),(2590,435,'Estrofa',3,'Oh juventud unidos por siempre\nSiguiendo el camino de la eternidad\nSomos la luz en las tinieblas\nPara alumbrar a la humanidad\nTodo lo puedo en Cristo\nque me ayudara'),(2591,436,'Estrofa',1,'Es el poder de Dios En la creación,\nla expresión más sublime Sin comparación,\nque en su perfección alaban al señor\nmi alabanza se unirá, desde el alba al vislumbrar\ny aunque el mundo en ti no crea\nyo en ti puedo confiar'),(2592,436,'Coro',2,'y me basta que sin ver tu rostro\ny no pueda escuchar tu voz\nes la naturaleza que me habla de ti\nmi corazón agradecido esta\npor la azul inmensidad\npor la tierra el mar\ny el viento que en sus alas\nmi canción ha de llevar'),(2593,436,'Estrofa',3,'soy poco menor que los ángeles\nla corona más hermosa de tu creación\ntodo lo pusiste bajo mis pies\nmi deseo es agradarte y\nmi juventud entregarte\ny aunque el mundo en ti no crea\nyo en ti puedo confiar'),(2594,437,'Estrofa',1,'Frente a tu creación\nUnidos estamos señor, Para rendirte honor\nAl único hijo de Dios, Con toda mi alma\nY mi corazón'),(2595,437,'Coro',2,'Te buscamos hoy\nCon todo el alma y corazón\nQue mis actos hoy\nDemuestren mi amor a ti señor\nSolo a ti'),(2596,437,'Estrofa',3,'Juntos te adoramos hoy, En un solo corazón\nEstas en el viento y el sol\nQue alumbra nuestro interior, Venimos hoy unidos\nComo Iglesia de Dios.'),(2597,438,'Estrofa',0,'[D]Cerc[D/F#]a de [G]Ti, Señor, [D/F#]quiero morar;\n[Bm]Tu gr[Bm/F#]ande y tie[G]rno amor, [D]quier[A]o goza[D]r.\nLlen[G]a mi p[D]obre ser, limpi[D/B]a mi corazó[A]n;\n[Bm]Hazm[Bm/F#]e tu ro[G]stro ver, e[D]n comunió[D]n.'),(2598,438,'Estrofa',1,'[D]Paso[D/F#]s inciertos doy, el sol se va;\nMas si contigo estoy, no temo ya.\nHimnos de gratitud, ferviente cantaré;\nY fiel a Ti, Jesús, siempre seré.'),(2599,438,'Estrofa',2,'Día feliz veré, creyendo en Ti;\nEn que yo habitaré, cerca de Ti.\nMi voz alabará, tu dulce nombre allí;\nY mi alma gozará, cerca de Ti.'),(2600,439,'Estrofa',0,'Blancos vestidos bañados de luz;\nRica diadema de gran esplendor;\nBella ciudad de sublime quietud,\nDonde la noche jamás existió\nEsa ciudad admirable de Dios\nDonde estaremos reunidos con el;\nPadre, permite que no falte yo,\nEs mi oración'),(2601,439,'Coro',1,'Bellos ropajes, hermoso hogar\nTierra preciosa, dulce cantar;\nBella corona, de estrellas mil;\nRica mansión de luz, do viviré.'),(2602,439,'Estrofa',2,'¡oh cuan preciosa! Es la meditación de vivir \nsiempre por la eternidad\nEstando libre de preocupación\nLibre de afanes y de toda ansiedad.\nTendremos parte en el júbilo aquel,\nDonde mil voces alaban a Dios;\nTodo lo que ha preparado Jesús,\nEs para mí'),(2603,439,'Coro',3,'Bellos ropajes, hermoso hogar\nTierra preciosa, dulce cantar;\nBella corona, de estrellas mil;\nRica mansión de luz, do viviré.'),(2604,439,'Estrofa',4,'Cosas hermosas tenemos que ver\nEn las regiones del Reino de Dios\nCuando con Cristo yo vaya a gozar;\nY mi corona reciba de Dios.\nBello lugar donde muerte no habrá\nDulce refugio de santo calor;\nBello país donde muerte no habrá,\nDo gozare.'),(2605,439,'Coro',5,'Bellos ropajes, hermoso hogar\nTierra preciosa, dulce cantar;\nBella corona, de estrellas mil;\nRica mansión de luz, do viviré.'),(2606,440,'Estrofa',0,'Tentado, no cedas, ceder es pecar,\nMás fácil sería luchando triunfar;\n¡Valor!, pues, resuelto, domina tu mal,\nDios puede librarte de asalto mortal.'),(2607,440,'Coro',1,'En Jesús, pues, confía,\nEn sus brazos tu alma;\nHallará dulce calma,\nÉl te hará vencedor.'),(2608,440,'Estrofa',2,'Evita el pecado, procura agradar,\nA Dios a quien debes por siempre ensalzar;\nNo manche tus labios impúdica voz,\nPreserva tu vida de ofensas a Dios.'),(2609,440,'Coro',3,'En Jesús, pues, confía,\nEn sus brazos tu alma;\nHallará dulce calma,\nÉl te hará vencedor.'),(2610,440,'Estrofa',4,'Amante, benigno y enérgico sé,\nEn Cristo tu Amigo pon toda tu fe;\nVeraz sea tu dicho, de Dios es tu ser,\nCorona te espera, y vas a vencer.'),(2611,440,'Coro',5,'En Jesús, pues, confía,\nEn sus brazos tu alma;\nHallará dulce calma,\nÉl te hará vencedor.'),(2612,441,'Estrofa',0,'Hay una Iglesia preciosa,\nEsta es la Iglesia de Dios;\nQue esparce su luz por doquiera,\nPara dar al mundo salvación.'),(2613,441,'Coro',1,'¡Oh, ven, ven, ven,\nVen a la Iglesia de Dios;\nDonde podrás descansar;\nOtro sitio igual nunca encuentras,\nCual la Iglesia de Dios sin igual.'),(2614,441,'Estrofa',2,'Ve a la Iglesia de Dios,\nY conocerás verdad;\nY serás para siempre dichoso,\nGozando de libertad.'),(2615,441,'Coro',3,'¡Oh, ven, ven, ven,\nVen a la Iglesia de Dios;\nDonde podrás descansar;\nOtro sitio igual nunca encuentras,\nCual la Iglesia de Dios sin igual.'),(2616,441,'Estrofa',4,'Ven, pecador a Jesús,\nTus pecados lavarás;\nY estando tu alma ya limpia,\nPara siempre con Él estarás.'),(2617,441,'Coro',5,'¡Oh, ven, ven, ven,\nVen a la Iglesia de Dios;\nDonde podrás descansar;\nOtro sitio igual nunca encuentras,\nCual la Iglesia de Dios sin igual.'),(2618,441,'Estrofa',6,'¡Oh, libertad tan preciosa,\nQue en Jesús pude hallar,\nEn su sangre, oh, fuente hermosa,\nQue lavó para siempre mi mal.'),(2619,441,'Coro',7,'¡Oh, ven, ven, ven,\nVen a la Iglesia de Dios;\nDonde podrás descansar;\nOtro sitio igual nunca encuentras,\nCual la Iglesia de Dios sin igual.'),(2620,442,'Estrofa',0,'Obediente a tu mandato,\nParticipa hoy tu grey;\nDe tu cena y con gozo,\nAcercamonos con fé,\nLo que hiciste en el calvario,\nPor el pobre pecador;\nAnunciamos en tu nombre,\nRecordando tu amor.'),(2621,442,'Estrofa',1,'Recordamos tus angustias,\n¡Oh, Divino Redentor!\nY la copa de amargura,\nQue por todo pecador,\nEn el gólgota apuraste,\nDespreciando tu dolor;\nTe pedimos que constantes,\nTe sigamos con valor.'),(2622,442,'Estrofa',2,'Gracias ¡Oh, Jesús te damos,\nLos unidos en tu amor;\nGracias mil, pues disfrutamos\nTu clemencia y tu favor!\nTuya fue la cruz, mas nuestra\nEs la dicha, es la paz;\nTuya sea la gloria toda,\nTuya por siempre jamás.'),(2623,443,'Estrofa',0,'Estando Jesús en Bethania,\nAllá con Simón el leproso,\nLlegó una mujer humillada,\nllevando un ungüento precioso;\nRompiendo aquel fino alabastro,\nAquella mujer dulcemente,\nDerrama el ungüento preciado,\nEn la cabeza del Señor.'),(2624,443,'Estrofa',1,'Los hombres ingratos murmuran,\nLlevando tristeza aquella alma;\nPero es el Señor compasivo,\nY pronto le vuelve la calma,\nY dice con voz cariñosa:\n“Vosotros tendréis a los pobres,\nMas ella mi cuerpo ha ungido,\nSabiendo que voy a morir.”'),(2625,443,'Estrofa',2,'Entonces aquel Iscariote,\nOyendo la voz del maligno;\nA los sacerdotes llegando,\nOfrece entregar al Señor,\nAquellos se holgaron de gozo y\nJudas entrego al Maestro,\nLe dice Jesús dulcemente:\n“¿Con un beso me vas a entregar?”.'),(2626,444,'Estrofa',0,'Anoche tuve un sueño, sublime, arrobador:\nMiraba a Jerusalén y al templo en su esplendor,\nOí cantar a niños un coro celestial.\nEn tanto que escuchaba un antema angelical,\nEn tanto que escuchaba un antema angelical.'),(2627,444,'Coro',1,'¡Jerusalén! ¡Jerusalén! prorrumpe en voz triunfal!\n¡Hosanna en las alturas! ¡Hosanna al Señor tu Rey!'),(2628,444,'Estrofa',2,'Mi sueño luego se cambió y una quietud reinó;\nCesaron las hosannas y el infantil clamor,\nTras misterioso manto el sol veló su esplendor\nY la sombra de una cruz en el cielo apareció.\nY la sombra de una cruz en el cielo apareció.'),(2629,444,'Coro',3,'¡Jerusalén! ¡Jerusalén! prorrumpe en voz triunfal!\n¡Hosanna en las alturas! ¡Hosanna al Señor tu Rey!'),(2630,444,'Estrofa',4,'Un nuevo cuadro contemplé: prodigio fue sin par.\nY vi la Ciudad Santa junto al sereno mar.\nDios la alumbraba con su luz, sus calles de oro vi,\nY quien deseaba en ella entrar, cabida hallaba allí.\nEstrellas, luna y astro rey perdieron su fulgor.\n//Al descender Jerusalén la Nueva en su esplendor,//'),(2631,444,'Coro',5,'¡Jerusalén! ¡Jerusalén! Prorrumpe en voz triunfal:\n¡Hosanna en las alturas! ¡Hosanna al Señor tu Rey!\n¡Hosanna en las alturas! ¡Hosanna al Señor tu Rey!'),(2632,445,'Estrofa',0,'Escogido fui de Dios en el Amado\nEn lugares celestiales\nsu bendición me dio\nAntes de la creación el plan fue hecho\nPor Su santa voluntad'),(2633,445,'Coro',1,'Escogido fui de Dios\nNadie me apartará,\nLas fuerzas de este mundo\nNo me podrán dañar\nVivo y ando en esta vida,\nCon seguridad\nPorque me escogió mi Dios'),(2634,445,'Estrofa',2,'Tengo un sello que el Espirítu me ha dado\nCuando mi confianza puse\nSolo en mi Salvador\nPrenda que el Señor me dio de vida Eterna\nEscogido fui de Dios'),(2635,445,'Coro',3,'Escogido fui de Dios\nNadie me apartará,\nLas fuerzas de este mundo\nNo me podrán dañar\nVivo y ando en esta vida,\nCon seguridad\nPorque me escogió mi Dios'),(2636,445,'Estrofa',4,'Me escogió para alabanza de su gloria\nY sentome en las alturas\nCon Cristo mi Señor\nGrande fue la admiración al ver su gracia\nEscogido fui de Dios'),(2637,445,'Coro',5,'Escogido fui de Dios\nNadie me apartará,\nLas fuerzas de este mundo\nNo me podrán dañar\nVivo y ando en esta vida,\nCon seguridad\nPorque me escogió mi Dios'),(2638,446,'Estrofa',0,'Por fé voy a alcanzar la vida eterna,\nlas más fuertes borrascas venceré,\nal fin que mi Jesús borro mis penas,\npor fé su rostro en gloria yo veré.'),(2639,446,'Coro',1,'Por fe he de mirar\nPor fe he de esperar\nPor fe disfrutaré la vida eterna'),(2640,446,'Estrofa',2,'Señor, perdona mis debilidades,\nque vuelva victorioso por la fé,\nque nunca vuelva a las perversidades,\nlas cosas de la vida que dejé.'),(2641,446,'Coro',3,'Por fe he de mirar\nPor fe he de esperar\nPor fe disfrutaré la vida eterna'),(2642,446,'Estrofa',4,'Señor, que nunca en mi la fé desmaye,\nSeñor, te ruego, aumentes más mi fé,\nque cruce el bravo mar y llegue a tu playa,\nSeñor sé siempre mi piloto fiel.'),(2643,446,'Coro',5,'Por fe he de mirar\nPor fe he de esperar\nPor fe disfrutaré la vida eterna'),(2644,446,'Estrofa',6,'Yo tengo la confianza en Jesucristo,\nDe ser justificado por la fé,\npor fé he de mirar al que no he visto,\npor gracia salvo soy yo por la fé.');
/*!40000 ALTER TABLE `estrofas` ENABLE KEYS */;
UNLOCK TABLES;

